  ["# One thread runs Python bytecode at a time: the ___.\n# Threads overlap I/O and sleep, not CPU work.\n# For CPU-bound work use multiprocessing.\n"] = "# Un hilo ejecuta bytecode de Python a la vez: el ___.\n# Los hilos solapan E/S y sleep, no trabajo de CPU.\n# Para trabajo de CPU usa multiprocessing.\n",
  ["# bisect on an unsorted list returns nonsense.\n# Precondition: a is ___ ascending.\na.sort()\ni = bisect.bisect_left(a, 38)\n"] = "# bisect sobre una lista sin ordenar devuelve tonterías.\n# Condición previa: a está ___ ascendente.\na.sort()\ni = bisect.bisect_left(a, 38)\n",
  ["# level 1: merge 2 halves      -> n items moved\n# level 2: merge 4 quarters    -> n items moved\n# each level: ___ ; levels: log n ; total: n log n\n"] = "# nivel 1: mezclar 2 mitades      -> n elementos movidos\n# nivel 2: mezclar 4 cuartos       -> n elementos movidos\n# cada nivel: ___ ; niveles: log n ; total: n log n\n",
  ["# n = 100\n# pairs = 100 * 99 // 2 = ___\n# still O(n^2): the /2 is a constant\n"] = "# n = 100\n# pares = 100 * 99 // 2 = ___\n# sigue siendo O(n^2): el /2 es una constante\n",
  ["# n = 1000 -> items[3] : 1 step\n# n = 2000 -> items[3] : 1 step\n# the cost stays the ___\n"] = "# n = 1000 -> items[3] : 1 paso\n# n = 2000 -> items[3] : 1 paso\n# el coste se queda the ___\n",
  ["# process 1: python3 -> its own GIL\n# process 2: python3 -> its own ___\n# two cores at 100%\n"] = "# proceso 1: python3 -> su propio GIL\n# proceso 2: python3 -> su propio ___\n# dos núcleos al 100%\n",
  ["# quicksort halves the range each level on average\n# depth ~ log2(n) frames on the stack: O(___) space\n# (naive fib without cache: depth n, RecursionError near 1000)\n"] = "# quicksort parte el rango a la mitad en cada nivel en promedio\n# profundidad ~ log2(n) marcos en la pila: O(___) de espacio\n# (fib ingenuo sin cache: profundidad n, RecursionError cerca de 1000)\n",
  ["# starts a comment. There is no block comment; a triple-quoted string at the top of a def is a docstring."] = "# empieza un comentario. No hay comentario de bloque; una cadena con triple comilla al inicio de un def es un docstring.",
  ["# without cache: 2^n calls\n# with cache: fib(0) .. fib(n), each once -> O(___)\n"] = "# sin cache: 2^n llamadas\n# con cache: fib(0) .. fib(n), cada uno una vez -> O(___)\n",
  ['#[___(Debug)]\nstruct Order { qty: u32 }\n\nlet o = Order { qty: 2 };\nprintln!("{:?}", o);        // Order { qty: 2 }\n'] = '#[___(Debug)]\nstruct Order { qty: u32 }\n\nlet o = Order { qty: 2 };\nprintln!("{:?}", o);        // Order { qty: 2 }\n',
  ["#[derive(Clone, Debug)] generates the impls. Also common: PartialEq, Default, Copy for small types."] = "#[derive(Clone, Debug)] genera las impls. También comunes: PartialEq, Default, Copy para tipos pequeños.",
  ["#[derive(Debug, Clone, PartialEq)] generates common traits. {:?} needs Debug. The till prints the order and the afternoon set is sold."] = "#[derive(Debug, Clone, PartialEq)] genera traits comunes. {:?} necesita Debug. La caja imprime el pedido y la merienda se vende.",
  ['#[derive(Default, Debug)]\nstruct Tray { buns: u32, teas: u32 }\n// An empty tray, all zeros, without typing them.\nlet empty = Tray::___();\nprintln!("{empty:?}");\n'] = '#[derive(Default, Debug)]\nstruct Tray { buns: u32, teas: u32 }\n// Una bandeja vacía, todo ceros, sin escribirlos.\nlet empty = Tray::___();\nprintln!("{empty:?}");\n',
  ['#[derive(Serialize, Deserialize)]\nstruct Order {\n    #[serde(___ = "dish")]\n    name: String,\n    qty: u32,\n}\n// {"dish":"toast","qty":2} now fills name\n'] = '#[derive(Serialize, Deserialize)]\nstruct Order {\n    #[serde(___ = "dish")]\n    name: String,\n    qty: u32,\n}\n// {"dish":"toast","qty":2} ahora rellena name\n',
  ['#[derive(Serialize, Deserialize)]\nstruct Order {\n    name: String,\n    #[serde(___ = "Option::is_none")]\n    note: Option<String>,\n}\n// None -> {"name":"toast"}   Some -> {"name":..,"note":..}\n'] = '#[derive(Serialize, Deserialize)]\nstruct Order {\n    name: String,\n    #[serde(___ = "Option::is_none")]\n    note: Option<String>,\n}\n// None -> {"name":"toast"}   Some -> {"name":..,"note":..}\n',
  ['#[serde(rename = "dish")] is the Go json tag. rename_all = "camelCase" on the struct is common.'] = '#[serde(rename = "dish")] es el tag json de Go. rename_all = "camelCase" en el struct es habitual.',
  ["#[tokio::main] builds the runtime and block_on(main()). Use #[tokio::test] in tests."] = "#[tokio::main] construye el runtime y hace block_on(main()). Usa #[tokio::test] en los tests.",
  ['$ ___ shop.py\nshop.py:12: error: Incompatible return value type\n    (got "None", expected "str")\nFound 1 error in 1 file\n'] = '$ ___ shop.py\nshop.py:12: error: Incompatible return value type\n    (got "None", expected "str")\nFound 1 error in 1 file\n',
  ["$ cargo ___\n   Compiling delivery v0.1.0\nrunning 2 checks\nqty_parses ....... ok\neta_is_positive .. ok\nresult: ok. 2 passed; 0 failed\n"] = "$ cargo ___\n   Compiling delivery v0.1.0\nrunning 2 checks\nqty_parses ....... ok\neta_is_positive .. ok\nresult: ok. 2 passed; 0 failed\n",
  ['$ cargo ___\n$ git diff --stat\n src/main.rs | 14 ++++++-------\n$ cargo ___ --check && echo "clean"\n'] = '$ cargo ___\n$ git diff --stat\n src/main.rs | 14 ++++++-------\n$ cargo ___ --check && echo "clean"\n',
  ["$ cargo ___\nwarning: this `.into_iter()` call is equivalent to `.iter()`\n  --> src/main.rs:12:24\n   = help: consider using `.iter()`\n"] = "$ cargo ___\nwarning: this `.into_iter()` call is equivalent to `.iter()`\n  --> src/main.rs:12:24\n   = help: consider using `.iter()`\n",
  ["$ cargo ___ delivery\n     Created binary (application) `delivery` package\n$ ls delivery\nCargo.toml  src/main.rs\n"] = "$ cargo ___ delivery\n     Created binary (application) `delivery` package\n$ ls delivery\nCargo.toml  src/main.rs\n",
  ["$ cargo ___ reqwest --features json\n    Updating crates.io index\n      Adding reqwest v0.12 to dependencies\n"] = "$ cargo ___ reqwest --features json\n    Updating crates.io index\n      Adding reqwest v0.12 to dependencies\n",
  ["$ cargo build --___\n   Compiling delivery v0.1.0\n    Finished [optimized] target(s) in 41.2s\n"] = "$ cargo build --___\n   Compiling delivery v0.1.0\n    Finished [optimized] target(s) in 41.2s\n",
  ["$ cat go.___\ngithub.com/alex/luckymac v1.2.0 h1:9fK2...Qw=\ngithub.com/alex/luckymac v1.2.0/go.mod h1:Lm0...c8=\n"] = "$ cat go.___\ngithub.com/alex/luckymac v1.2.0 h1:9fK2...Qw=\ngithub.com/alex/luckymac v1.2.0/go.mod h1:Lm0...c8=\n",
  ["$ cd luckymac/menu\n$ go env ___\n/Users/alex/luckymac/go.mod\n"] = "$ cd luckymac/menu\n$ go env ___\n/Users/alex/luckymac/go.mod\n",
  ["$ git ___ v1.0.0\n$ git push origin v1.0.0\n"] = "$ git ___ v1.0.0\n$ git push origin v1.0.0\n",
  ['$ git config --global \\\n    url."git@github.com:".___ "https://github.com/"\n'] = '$ git config --global \\\n    url."git@github.com:".___ "https://github.com/"\n',
  ["$ git remote -v\norigin  git@github.com:alex/luckymac.git (push)\n$ go mod init ___\ngo: creating new go.mod\n"] = "$ git remote -v\norigin  git@github.com:alex/luckymac.git (push)\n$ go mod init ___\ngo: creating new go.mod\n",
  ["$ go ___ -m all\ngithub.com/siuming/cousinshop\ngithub.com/alex/luckymac v1.0.0\ngithub.com/goccy/go-json v0.10.3\n"] = "$ go ___ -m all\ngithub.com/siuming/cousinshop\ngithub.com/alex/luckymac v1.0.0\ngithub.com/goccy/go-json v0.10.3\n",
  ["$ go ___ -o delivery .    # one static file\n$ ./delivery\n"] = "$ go ___ -o delivery .    # one static file\n$ ./delivery\n",
  ["$ go ___ ./...    # static checks, no run\n$ go fmt ./...    # and gofmt every file\n"] = "$ go ___ ./...    # static checks, no run\n$ go fmt ./...    # and gofmt every file\n",
  ["$ go ___ github.com/alex/luckymac@v1.2.0\ngo: downloading github.com/alex/luckymac v1.2.0\ngo: added github.com/alex/luckymac v1.2.0\n"] = "$ go ___ github.com/alex/luckymac@v1.2.0\ngo: downloading github.com/alex/luckymac v1.2.0\ngo: added github.com/alex/luckymac v1.2.0\n",
  ["$ go ___ init luckymac/delivery\ngo: creating new go.mod: module luckymac/delivery\n"] = "$ go ___ init luckymac/delivery\ngo: creating new go.mod: module luckymac/delivery\n",
  ["$ go build ./...\nmain.go:6:2: no required module provides package\n    github.com/alex/luckymac/menu; to add it:\n    go mod ___\n"] = "$ go build ./...\nmain.go:6:2: no required module provides package\n    github.com/alex/luckymac/menu; to add it:\n    go mod ___\n",
  ["$ go clean -___\n$ go build ./...     # everything downloads again, once\n"] = "$ go clean -___\n$ go build ./...     # todo se descarga de nuevo, una vez\n",
  ["$ go env -w ___=github.com/luckymac-hk/*\n$ go get github.com/luckymac-hk/kitchen@latest\n"] = "$ go env -w ___=github.com/luckymac-hk/*\n$ go get github.com/luckymac-hk/kitchen@latest\n",
  ["$ go env GO111MODULE\n___\n# modules everywhere, go.mod or not\n"] = "$ go env GO111MODULE\n___\n# módulos en todas partes, con go.mod o sin él\n",
  ["$ go env GOPROXY\nhttps://proxy.golang.org,___\n"] = "$ go env GOPROXY\nhttps://proxy.golang.org,___\n",
  ["$ go env GOSUMDB\n___.golang.org\n"] = "$ go env GOSUMDB\n___.golang.org\n",
  ["$ go get github.com/alex/luckymac@___\ngo: upgraded github.com/alex/luckymac v0.3.0 => v1.0.0\n"] = "$ go get github.com/alex/luckymac@___\ngo: upgraded github.com/alex/luckymac v0.3.0 => v1.0.0\n",
  ["$ go mod ___\n$ ls\ngo.mod  go.sum  main.go  menu/  ___/\n$ go build ./...      # reads ___/ automatically\n"] = "$ go mod ___\n$ ls\ngo.mod  go.sum  main.go  menu/  ___/\n$ go build ./...      # lee ___/ automáticamente\n",
  ["$ go mod ___    # sync go.mod with the imports\n"] = "$ go mod ___    # sync go.mod with the imports\n",
  ["$ go test -___ ./kitchen\nWARNING: DATA RACE\nWrite at 0x00c0000b4010 by goroutine 8\nPrevious read by goroutine 7\n"] = "$ go test -___ ./kitchen\nWARNING: DATA RACE\nWrite at 0x00c0000b4010 by goroutine 8\nPrevious read by goroutine 7\n",
  ["$ go test ___ ./...\nWARNING: DATA RACE\nWrite at 0x00c0000 by goroutine 7\n"] = "$ go test ___ ./...\nWARNING: DATA RACE\nWrite at 0x00c0000 by goroutine 7\n",
  ["$ ls\ncousinshop/  luckymac/\n$ go ___ init ./cousinshop ./luckymac\n"] = "$ ls\ncousinshop/  luckymac/\n$ go ___ init ./cousinshop ./luckymac\n",
  ["$ ls $(go env GOMODCACHE)\ncache/  github.com/\n$ go env GOMODCACHE\n/Users/siuming/go/pkg/___\n"] = "$ ls $(go env GOMODCACHE)\ncache/  github.com/\n$ go env GOMODCACHE\n/Users/siuming/go/pkg/___\n",
  ['$ python3.13t -c "import sys; print(sys._is_gil_enabled())"\nFalse\n# this is the ___-threaded build (PEP 703)\n'] = '$ python3.13t -c "import sys; print(sys._is_gil_enabled())"\nFalse\n# esta es la compilación ___-threaded (PEP 703)\n',
  ["%d / %d clear"] = "%d / %d listas",
  ["%s  MAP %d/%d  %s"] = "%s  MAPA %d/%d  %s",
  ["%s TRACK"] = "PISTA %s",
  ["%v value, %+v with names, %#v as Go syntax, %T the type."] = "%v valor, %+v con nombres, %#v como sintaxis Go, %T el tipo.",
  ["%v with a plus. %#v adds the type name too; %T prints only the type."] = "%v con un más. %#v añade también el nombre del tipo; %T imprime solo el tipo.",
  ["%w builds a chain. %v would flatten it to text and lose the cause."] = "%w construye una cadena. %v la aplanaría a texto y perdería la causa.",
  ["&'a str: the output lives at least as long as the shorter of a and b. Lifetimes describe; they never extend anything."] = "&'a str: la salida vive al menos tanto como el más corto de a y b. Los lifetimes describen; nunca alargan nada.",
  ["&'static str lives for the whole program. String literals are 'static; a returned reference with no input to borrow from must be too."] = "&'static str vive todo el programa. Los literales de string son 'static; una referencia devuelta sin entrada de la que prestar también debe serlo.",
  ["&String is a shared borrow: read only, any number at once, the owner keeps the value."] = "&String es un préstamo compartido: solo lectura, tantos como quieras a la vez, el dueño conserva el valor.",
  ["&T{} is the usual way to make a pointer to a struct. p.Field works without (*p)."] = "&T{} es la forma habitual de crear un puntero a un struct. p.Field funciona sin (*p).",
  ["&dyn Cook is a trait object: a pointer plus a vtable. Go interfaces work the same way underneath."] = "&dyn Cook es un trait object: un puntero más una vtable. Las interfaces de Go funcionan igual por debajo.",
  ["&mut a. While r lives, no other borrow of a may exist: exactly 1 &mut, or many &, never both."] = "&mut a. Mientras r viva, no puede existir otro préstamo de a: exactamente 1 &mut, o muchos &, nunca ambos.",
  ["&prices[1..3] is a slice of type &[i32]: a borrowed window, no copy. [1..] and [..2] also work."] = "&prices[1..3] es un slice de tipo &[i32]: una ventana prestada, sin copia. [1..] y [..2] también funcionan.",
  ["&str is a view into text; String owns it. Take &str in parameters, return String when you build new text. The receipt prints once."] = "&str es una vista al texto; String es su dueño. Recibe &str en parámetros, devuelve String cuando construyes texto nuevo. El recibo se imprime una vez.",
  ["(hi - lo) / 2. Each pass throws away half the range. usize overflow panics in debug builds, so the subtraction form matters."] = "(hi - lo) / 2. Cada pasada tira la mitad del rango. El desbordamiento de usize hace panic en compilaciones de depuración, así que la forma con resta importa.",
  ["(lo + hi) / 2, or lo + (hi-lo)/2 to dodge overflow. Each pass throws away half the range."] = "(lo + hi) / 2, o lo + (hi-lo)/2 para esquivar el desbordamiento. Cada pasada tira la mitad del rango.",
  ["(lo + hi) // 2. Python ints never overflow, so the plain form is safe. Each pass throws away half the range."] = "(lo + hi) // 2. Los int de Python nunca desbordan, así que la forma simple es segura. Cada pasada tira la mitad del rango.",
  ["(ok, err). Check err before using ok. The gate opens."] = "(ok, err). Comprueba err antes de usar ok. El torniquete se abre.",
  ["**opts packs keyword arguments into a dict. The usual names are *args and **kwargs; any name works."] = "**opts empaqueta los argumentos con nombre en un dict. Los nombres habituales son *args y **kwargs; cualquier nombre sirve.",
  ["*Order is a pointer. Methods that change the struct use a *T receiver."] = "*Order es un puntero. Los métodos que cambian el struct usan un receptor *T.",
  ["*http.Request is everything the client sent. Query().Get reads ?item=."] = "*http.Request es todo lo que envió el cliente. Query().Get lee ?item=.",
  ["*items packs extra positional arguments into a tuple. Go's ...int. Calling total(*prices) unpacks a list the other way."] = "*items empaqueta los argumentos posicionales extra en una tupla. El ...int de Go. Llamar total(*prices) desempaqueta una lista en sentido contrario.",
  ["+%d XP"] = "+%d XP",
  ["--release turns on opt-level 3 and drops debug checks. Plain cargo build is for development."] = "--release activa opt-level 3 y quita las comprobaciones de debug. cargo build a secas es para desarrollo.",
  ["-> None says: no useful result. mypy then complains if you assign the call. Forty bowls saved."] = "-> None dice: sin resultado útil. mypy se queja entonces si asignas la llamada. Cuarenta boles salvados.",
  ["-gcflags=-m says o escapes. Where does a shared reference have to live?"] = "-gcflags=-m dice que o escapa. ¿Dónde tiene que vivir una referencia compartida?",
  ["...int is variadic. Call it with sum(a, b, c) or spread a slice: sum(fares...)."] = "...int es variádico. Llámalo con sum(a, b, c) o expande un slice: sum(fares...).",
  [".await yields to the runtime until the Future is ready. Forget it and nothing runs."] = ".await cede al runtime hasta que el Future está listo. Olvídalo y nada se ejecuta.",
  ['// "abc" is not a number: fall back to zero coins.\nlet coins: u32 = "abc".parse().___(0);\n'] = '// "abc" no es un número: vuelve a cero monedas.\nlet coins: u32 = "abc".parse().___(0);\n',
  ["// &Option<T> to Option<&T>: a borrow, not a move.\nfn root_val(tree: &Link) -> Option<i32> {\n    tree.___().map(|n| n.val)\n}\n"] = "// De &Option<T> a Option<&T>: un préstamo, no un move.\nfn root_val(tree: &Link) -> Option<i32> {\n    tree.___().map(|n| n.val)\n}\n",
  ["// 1 topping: 2 combos   2 toppings: 4   3 toppings: 8\n// n toppings: ___ combos, and listing them all cannot be faster\n"] = "// 1 ingrediente: 2 combos   2 ingredientes: 4   3 ingredientes: 8\n// n ingredientes: ___ combos, y listarlos todos no puede ser más rápido\n",
  ["// 1 topping: 2 combos   2 toppings: 4   3 toppings: 8\n// n toppings: ___ combos; 1u64 << n computes it\n"] = "// 1 ingrediente: 2 combos   2 ingredientes: 4   3 ingredientes: 8\n// n ingredientes: ___ combos; 1u64 << n lo calcula\n",
  ["// 1024 -> 512 -> 256 -> 128 -> 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1\n// ___ halvings: 1024_u32.ilog2()\n"] = "// 1024 -> 512 -> 256 -> 128 -> 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1\n// ___ mitades: 1024_u32.ilog2()\n",
  ["// 1024 -> 512 -> 256 -> 128 -> 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1\n// ___ halvings: log2(1024)\n"] = "// 1024 -> 512 -> 256 -> 128 -> 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1\n// ___ mitades: log2(1024)\n",
  ['// Any cook must give a name; greet comes for free.\n___ Cook {\n    fn name(&self) -> String;\n    fn greet(&self) -> String {\n        format!("{} at the pass", self.name())\n    }\n}\n'] = '// Todo cocinero debe dar un nombre; greet viene gratis.\n___ Cook {\n    fn name(&self) -> String;\n    fn greet(&self) -> String {\n        format!("{} at the pass", self.name())\n    }\n}\n',
  ["// Ask the compiler to write .clone() for Order.\n#[___(Clone, Debug)]\nstruct Order {\n    bun: String,\n    qty: u32,\n}\n"] = "// Pide al compilador que escriba .clone() para Order.\n#[___(Clone, Debug)]\nstruct Order {\n    bun: String,\n    qty: u32,\n}\n",
  ["// BinarySearch on an unsorted slice returns nonsense.\n// Precondition: a is ___ ascending.\nsort.Ints(a)\ni, found := slices.BinarySearch(a, 38)\n"] = "// BinarySearch sobre un slice sin ordenar devuelve tonterías.\n// Condición previa: a está ___ ascendente.\nsort.Ints(a)\ni, found := slices.BinarySearch(a, 38)\n",
  ['// Cargo.toml: [dependencies] has this crate at version 1\nuse ___::Error;\n#[derive(Debug, Error)]\nenum OrderError {\n    #[error("order is empty")]\n    Empty,\n}\n'] = '// Cargo.toml: [dependencies] tiene este crate en la versión 1\nuse ___::Error;\n#[derive(Debug, Error)]\nenum OrderError {\n    #[error("order is empty")]\n    Empty,\n}\n',
  ['// Cargo.toml: tokio = {version="1", features=["full"]}\n#[___]\nasync fn main() {\n    let eta = fetch_eta(7).await;\n    println!("{eta} min");\n}\n'] = '// Cargo.toml: tokio = {version="1", features=["full"]}\n#[___]\nasync fn main() {\n    let eta = fetch_eta(7).await;\n    println!("{eta} min");\n}\n',
  ["// Debug + Display are done, so the body can stay empty\nimpl ___ for OrderError {}\n"] = "// Debug + Display ya están, así que el cuerpo puede quedar vacío\nimpl ___ for OrderError {}\n",
  ["// Do not communicate by sharing memory;\n// share memory by ___.\norders <- Order{id: 7}\n"] = "// No te comuniques compartiendo memoria;\n// comparte memoria ___.\norders <- Order{id: 7}\n",
  ['// Grill and Wok in one Vec: each boxed as a trait object.\nlet crew: Vec<___> = vec![Box::new(Grill), Box::new(Wok)];\nfor c in &crew { println!("{}", c.greet()); }\n'] = '// Grill y Wok en un solo Vec: cada uno en un Box como trait object.\nlet crew: Vec<___> = vec![Box::new(Grill), Box::new(Wok)];\nfor c in &crew { println!("{}", c.greet()); }\n',
  ['// In the terminal, inside the project folder:\n//   $ cargo ___\n// Compiles target/debug/express and starts it.\nfn main() {\n    println!("Lucky Mac Express");\n}\n'] = '// En la terminal, dentro de la carpeta del proyecto:\n//   $ cargo ___\n// Compila target/debug/express y lo arranca.\nfn main() {\n    println!("Lucky Mac Express");\n}\n',
  ['// Keep every handle so the pass can wait for every cook.\nlet mut hs: Vec<___<()>> = Vec::new();\nfor id in 0..3 {\n    hs.push(thread::spawn(move || println!("cook {id}")));\n}\nfor h in hs { h.join().unwrap(); }\n'] = '// Guarda cada handle para que el pase pueda esperar a cada cocinero.\nlet mut hs: Vec<___<()>> = Vec::new();\nfor id in 0..3 {\n    hs.push(thread::spawn(move || println!("cook {id}")));\n}\nfor h in hs { h.join().unwrap(); }\n',
  ["// Not every table has an order yet.\nfn find(orders: &[(u32, &str)], t: u32) -> ___<String> {\n    for (n, item) in orders {\n        if *n == t { return Some(item.to_string()); }\n    }\n    None\n}\n"] = "// No todas las mesas tienen pedido todavía.\nfn find(orders: &[(u32, &str)], t: u32) -> ___<String> {\n    for (n, item) in orders {\n        if *n == t { return Some(item.to_string()); }\n    }\n    None\n}\n",
  ['// Nothing here tells parse which number type to build.\nlet qty = "12".parse___().unwrap();\nlet total = qty * 18;\n'] = '// Nada aquí le dice a parse qué tipo numérico construir.\nlet qty = "12".parse___().unwrap();\nlet total = qty * 18;\n',
  ["// One counter, many cooks: one writer at a time.\nlet sold = Arc::new(___::new(0u32));\n"] = "// Un contador, muchos cocineros: un escritor a la vez.\nlet sold = Arc::new(___::new(0u32));\n",
  ["// Only types with this marker may move to another thread.\nfn ship<T: ___ + 'static>(t: T) {\n    thread::spawn(move || drop(t));\n}\nship(Arc::new(5));    // ok: Arc is thread-safe\n// ship(Rc::new(5));  // error: Rc is not\n"] = "// Solo los tipos con este marcador pueden moverse a otro thread.\nfn ship<T: ___ + 'static>(t: T) {\n    thread::spawn(move || drop(t));\n}\nship(Arc::new(5));    // ok: Arc es thread-safe\n// ship(Rc::new(5));  // error: Rc no lo es\n",
  ['// Peek without waiting: the till must keep beeping.\nmatch rx.___() {\n    Ok(order) => println!("got {order}"),\n    Err(_) => println!("nothing yet"),\n}\n'] = '// Mira sin esperar: la caja debe seguir pitando.\nmatch rx.___() {\n    Ok(order) => println!("got {order}"),\n    Err(_) => println!("nothing yet"),\n}\n',
  ['// Rc counts on one thread only; this one crosses threads.\nlet menu = ___::new(vec!["bun", "egg tart"]);\nlet m2 = menu.clone();\nthread::spawn(move || println!("{}", m2[0]));\n'] = '// Rc cuenta en un solo thread; este cruza threads.\nlet menu = ___::new(vec!["bun", "egg tart"]);\nlet m2 = menu.clone();\nthread::spawn(move || println!("{}", m2[0]));\n',
  ['// Same bound, written under the signature for long lists.\nfn show_all<T>(items: &[T])\n___\n    T: std::fmt::Display,\n{\n    for it in items { println!("{it}"); }\n}\n'] = '// El mismo bound, escrito bajo la firma para listas largas.\nfn show_all<T>(items: &[T])\n___\n    T: std::fmt::Display,\n{\n    for it in items { println!("{it}"); }\n}\n',
  ["// Take any Cook at all; the caller picks the concrete type.\nfn fire(c: ___ Cook) -> String {\n    c.greet()\n}\n"] = "// Acepta cualquier Cook; quien llama elige el tipo concreto.\nfn fire(c: ___ Cook) -> String {\n    c.greet()\n}\n",
  ['// The banner is baked into the binary for the whole run.\nfn banner() -> &___ str {\n    "Lucky Mac Express"\n}\n'] = '// El letrero va grabado en el binario durante toda la ejecución.\nfn banner() -> &___ str {\n    "Lucky Mac Express"\n}\n',
  ["// The child lives on the heap, behind a pointer.\ntype Link = Option<___<Node>>;\nstruct Node {\n    val: i32,\n    left: Link,\n    right: Link,\n}\n"] = "// El hijo vive en el heap, detrás de un puntero.\ntype Link = Option<___<Node>>;\nstruct Node {\n    val: i32,\n    left: Link,\n    right: Link,\n}\n",
  ['// The entry point of a binary crate.\nfn ___() {\n    println!("Lucky Mac Express");\n}\n'] = '// El punto de entrada de un crate binario.\nfn ___() {\n    println!("Lucky Mac Express");\n}\n',
  ["// The first line of a Go file.\npackage ___\nfunc hello() {}\n"] = "// La primera línea de un archivo Go.\npackage ___\nfunc hello() {}\n",
  ['// The pass holds three trays: send blocks when full.\nlet (tx, rx) = mpsc::___(3);\ntx.send("tray").unwrap();\n'] = '// El pase aguanta tres bandejas: send bloquea cuando está lleno.\nlet (tx, rx) = mpsc::___(3);\ntx.send("tray").unwrap();\n',
  ["// The receipt only borrows the name: say so on the struct.\nstruct Receipt___ {\n    name: &'a str,\n    total: u32,\n}\n"] = "// El recibo solo toma prestado el nombre: dilo en el struct.\nstruct Receipt___ {\n    name: &'a str,\n    total: u32,\n}\n",
  ["// The tea thread hands back a number when it is done.\nlet tea = thread::spawn(|| 3 * 60);\n// Wait for it and take the result out of the handle.\nlet secs: u32 = tea.___().unwrap();\n"] = "// El thread del té devuelve un número cuando termina.\nlet tea = thread::spawn(|| 3 * 60);\n// Espéralo y saca el resultado del handle.\nlet secs: u32 = tea.___().unwrap();\n",
  ['// The till gives change back, or a message.\nfn pay(cash: u32, price: u32) -> ___<u32, String> {\n    if cash < price {\n        return Err("not enough cash".to_string());\n    }\n    Ok(cash - price)\n}\n'] = '// La caja devuelve el cambio, o un mensaje.\nfn pay(cash: u32, price: u32) -> ___<u32, String> {\n    if cash < price {\n        return Err("not enough cash".to_string());\n    }\n    Ok(cash - price)\n}\n',
  ["// Two buns from one tray: the winner lives as long as both.\nfn longest<'a>(a: &'a str, b: &'a str) -> &___ str {\n    if a.len() >= b.len() { a } else { b }\n}\n"] = "// Dos bollos de una bandeja: el ganador vive tanto como ambos.\nfn longest<'a>(a: &'a str, b: &'a str) -> &___ str {\n    if a.len() >= b.len() { a } else { b }\n}\n",
  ["// ___ menu prices the morning set and the tea set.\npackage menu\n"] = "// ___ menu prices the morning set and the tea set.\npackage menu\n",
  ['// a literal is a &str; the kiosk needs its own copy\nlet shop = String::___("Lucky Mac Express");\nlet label: &str = &shop;\n'] = '// un literal es un &str; el kiosco necesita su propia copia\nlet shop = String::___("Lucky Mac Express");\nlet label: &str = &shop;\n',
  ['// a max-heap of (count, word), built straight from the map\nlet mut heap: BinaryHeap<(usize, &str)> =\n    cnt.into_iter().map(|(w, c)| (c, w)).___();\n// k pops: most frequent first, tuples compare by count\nfor _ in 0..k {\n    if let Some((c, w)) = heap.pop() { print!("{w} "); }\n}\n'] = '// un max-heap de (count, word), directo desde el map\nlet mut heap: BinaryHeap<(usize, &str)> =\n    cnt.into_iter().map(|(w, c)| (c, w)).___();\n// k pops: el más frecuente primero, las tuplas comparan por count\nfor _ in 0..k {\n    if let Some((c, w)) = heap.pop() { print!("{w} "); }\n}\n',
  ["// a second stack: the smallest so far, at every depth\nfn push(&mut self, x: i32) {\n    let m = *self.low.last().unwrap_or(&x);\n    self.st.push(x);\n    self.low.push(x.___(m));\n}\n// the smallest: *self.low.last().unwrap()   O(1)\n"] = "// una segunda pila: el mínimo hasta ahora, a cada nivel\nfn push(&mut self, x: i32) {\n    let m = *self.low.last().unwrap_or(&x);\n    self.st.push(x);\n    self.low.push(x.___(m));\n}\n// el mínimo: *self.low.last().unwrap()   O(1)\n",
  ["// b'a' is the byte 97. Subtracting it maps a..z onto 0..26.\n// An array index must be the pointer-sized unsigned type.\nlet mut count = [0i32; 26];\nfor c in \"muffin\".bytes() {\n    count[(c - b'a') as ___] += 1;\n}\n"] = "// b'a' es el byte 97. Restarlo mapea a..z sobre 0..26.\n// Un índice de array debe ser el entero sin signo del puntero.\nlet mut count = [0i32; 26];\nfor c in \"muffin\".bytes() {\n    count[(c - b'a') as ___] += 1;\n}\n",
  ["// biggest run of days: extend the run, or start over at x\nlet (mut cur, mut best) = (a[0], a[0]);\nfor &x in &a[1..] {\n    cur = x.___(cur + x);\n    if cur > best { best = cur; }\n}\n"] = "// la mejor racha de días: extenderla, o empezar de nuevo en x\nlet (mut cur, mut best) = (a[0], a[0]);\nfor &x in &a[1..] {\n    cur = x.___(cur + x);\n    if cur > best { best = cur; }\n}\n",
  ["// binary_search on an unsorted slice returns nonsense.\n// Precondition: a is ___ ascending.\na.sort();\nlet i = a.binary_search(&38);\n"] = "// binary_search sobre un slice sin ordenar devuelve tonterías.\n// Condición previa: a está ___ ascendente.\na.sort();\nlet i = a.binary_search(&38);\n",
  ['// both futures make progress on this task at once\nlet (a, b) = tokio::___!(fetch_eta(1), fetch_eta(2));\nprintln!("rider A {a} min, rider B {b} min");\n'] = '// ambos futures avanzan en esta tarea a la vez\nlet (a, b) = tokio::___!(fetch_eta(1), fetch_eta(2));\nprintln!("rider A {a} min, rider B {b} min");\n',
  ["// calling this does nothing yet; it hands back a Future\n___ fn fetch_eta(order_id: u32) -> u32 {\n    tokio::time::sleep(Duration::from_millis(200)).await;\n    order_id % 10 + 5\n}\n"] = "// llamar a esto aún no hace nada; devuelve un Future\n___ fn fetch_eta(order_id: u32) -> u32 {\n    tokio::time::sleep(Duration::from_millis(200)).await;\n    order_id % 10 + 5\n}\n",
  ["// cmd/kiosk/main.go\npackage ___\n\nfunc main() { kiosk.Run() }\n"] = "// cmd/kiosk/main.go\npackage ___\n\nfunc main() { kiosk.Run() }\n",
  ["// count every dish name once per receipt\nlet mut cnt: HashMap<&str, usize> = HashMap::new();\nfor w in words {\n    *cnt.___(w).or_insert(0) += 1;\n}\n"] = "// cuenta cada nombre de plato una vez por recibo\nlet mut cnt: HashMap<&str, usize> = HashMap::new();\nfor w in words {\n    *cnt.___(w).or_insert(0) += 1;\n}\n",
  ["// dp[a] = fewest coins that make amount a\nfor a := range dp {\n    dp[a] = ___             // 'impossible' until proven\n}\ndp[0] = 0\n"] = "// dp[a] = mínimo de monedas para el importe a\nfor a := range dp {\n    dp[a] = ___             // 'imposible' hasta demostrarlo\n}\ndp[0] = 0\n",
  ["// first parameter, never a struct field\nfunc Cook(___ context.Context, o Order) error {\n    return nil\n}\n"] = "// siempre el primer parámetro, nunca en un struct\nfunc Cook(___ context.Context, o Order) error {\n    return nil\n}\n",
  ["// go f() starts a ___\n// thousands of them are cheap\n"] = "// go f() lanza una ___\n// miles de ellas salen baratas\n",
  ["// k items left; the top is the smallest of the k biggest\nlet Reverse(kth) = *heap.___().unwrap();\nkth\n// kth_largest(&[3, 2, 1, 5, 6, 4], 2) == 5\n"] = "// quedan k; la cima es el menor de los k mayores\nlet Reverse(kth) = *heap.___().unwrap();\nkth\n// kth_largest(&[3, 2, 1, 5, 6, 4], 2) == 5\n",
  ["// kth largest: a heap of the k biggest, smallest on top.\n// BinaryHeap is a max-heap; a std::cmp wrapper flips it.\nlet mut heap = BinaryHeap::new();\nfor &x in nums {\n    heap.push(___(x));\n    if heap.len() > k { heap.pop(); }\n}\n"] = "// k-ésimo mayor: un heap con los k mayores, el menor arriba.\n// BinaryHeap es un max-heap; un wrapper de std::cmp lo invierte.\nlet mut heap = BinaryHeap::new();\nfor &x in nums {\n    heap.push(___(x));\n    if heap.len() > k { heap.pop(); }\n}\n",
  ["// level 1: merge 2 halves      -> n items moved\n// level 2: merge 4 quarters    -> n items moved\n// each level: ___ ; levels: log n ; total: n log n\n"] = "// nivel 1: mezclar 2 mitades      -> n elementos movidos\n// nivel 2: mezclar 4 cuartos       -> n elementos movidos\n// cada nivel: ___ ; niveles: log n ; total: n log n\n",
  ['// main.go, module github.com/alex/luckymac\nimport "___"\n\nfmt.Println(menu.Price("set"))\n'] = '// main.go, module github.com/alex/luckymac\nimport "___"\n\nfmt.Println(menu.Price("set"))\n',
  ["// menu/price.go\npackage ___\n\nfunc price(item string) int { return 42 }\n"] = "// menu/price.go\npackage ___\n\nfunc price(item string) int { return 42 }\n",
  ["// menu/price.go\npackage menu\n\nfunc ___(item string) int { return 42 }\n"] = "// menu/price.go\npackage menu\n\nfunc ___(item string) int { return 42 }\n",
  ['// menu/price_test.go\npackage menu___\n\nimport "github.com/alex/luckymac/menu"\n'] = '// menu/price_test.go\npackage menu___\n\nimport "github.com/alex/luckymac/menu"\n',
  ["// merge(l, r): both slices are already sorted\nlet (mut i, mut j, mut out) = (0, 0, Vec::new());\nwhile i < l.len() && j < r.len() {\n    if l[i] ___ r[j] { out.push(l[i]); i += 1; }\n    else { out.push(r[j]); j += 1; }\n}\nout.extend(&l[i..]); out.extend(&r[j..]);\n"] = "// merge(l, r): los dos slices ya están ordenados\nlet (mut i, mut j, mut out) = (0, 0, Vec::new());\nwhile i < l.len() && j < r.len() {\n    if l[i] ___ r[j] { out.push(l[i]); i += 1; }\n    else { out.push(r[j]); j += 1; }\n}\nout.extend(&l[i..]); out.extend(&r[j..]);\n",
  ["// n = 100\n// pairs = 100 * 99 / 2 = ___\n// still O(n^2): the /2 is a constant\n"] = "// n = 100\n// pares = 100 * 99 / 2 = ___\n// sigue siendo O(n^2): el /2 es una constante\n",
  ["// n = 1000 -> items[3] : 1 step\n// n = 2000 -> items[3] : 1 step\n// the cost stays the ___\n"] = "// n = 1000 -> items[3] : 1 paso\n// n = 2000 -> items[3] : 1 paso\n// el coste se queda the ___\n",
  ['// position gives an Option; the till wants a Result.\nfn find(menu: &[&str], w: &str) -> Result<usize, String> {\n    menu.iter()\n        .position(|m| *m == w)\n        .___("not on the menu".to_string())\n}\n'] = '// position da un Option; la caja quiere un Result.\nfn find(menu: &[&str], w: &str) -> Result<usize, String> {\n    menu.iter()\n        .position(|m| *m == w)\n        .___("not on the menu".to_string())\n}\n',
  ["// quicksort halves the range each level on average\n// depth ~ log2(n) frames on the stack: O(___) space\n// (naive fib without memo: depth n)\n"] = "// quicksort parte el rango a la mitad en cada nivel en promedio\n// profundidad ~ log2(n) marcos en la pila: O(___) de espacio\n// (fib ingenuo sin memo: profundidad n)\n",
  ["// returns a JoinHandle; the task runs on the pool now\nlet handle = tokio::___(async { fetch_eta(3).await });\nprint_menu().await;\nlet eta = handle.await?;\n"] = "// devuelve un JoinHandle; la tarea ya corre en el pool\nlet handle = tokio::___(async { fetch_eta(3).await });\nprint_menu().await;\nlet eta = handle.await?;\n",
  ["// starts a line comment. /// is a doc comment that cargo doc turns into pages."] = "// empieza un comentario de línea. /// es un comentario de documentación que cargo doc convierte en páginas.",
  ['// the caller only learns: it is some Iterator of &str\nfn free_riders() -> ___ Iterator<Item = &\'static str> {\n    ["Wing", "Fai"].into_iter().filter(|r| *r != "Fai")\n}\n'] = '// quien llama solo sabe: es algún Iterator de &str\nfn free_riders() -> ___ Iterator<Item = &\'static str> {\n    ["Wing", "Fai"].into_iter().filter(|r| *r != "Fai")\n}\n',
  ['// the mall has five floors of pickup lockers\nfor floor in 1___5 {\n    println!("checking locker on floor {floor}");\n}\n// prints 1, 2, 3, 4, 5\n'] = '// el centro comercial tiene cinco pisos de taquillas de recogida\nfor floor in 1___5 {\n    println!("checking locker on floor {floor}");\n}\n// imprime 1, 2, 3, 4, 5\n',
  ["// the sum of every window of k, without re-adding k items\nlet mut sum: i32 = a[..k].iter().sum();\nlet mut best = sum;\nfor i in k..a.len() {\n    sum += a[i] - a[___];       // one in, one out\n    if sum > best { best = sum; }\n}\n"] = "// la suma de cada ventana de k, sin volver a sumar k elementos\nlet mut sum: i32 = a[..k].iter().sum();\nlet mut best = sum;\nfor i in k..a.len() {\n    sum += a[i] - a[___];       // uno entra, uno sale\n    if sum > best { best = sum; }\n}\n",
  ['// three characters, three bytes each in UTF-8\nlet district = "銅鑼灣";\nlet n = district.___();\nassert_eq!(n, 9);\n'] = '// tres caracteres, tres bytes cada uno en UTF-8\nlet district = "銅鑼灣";\nlet n = district.___();\nassert_eq!(n, 9);\n',
  ["// two_sum: value -> index in a HashMap, one pass, O(n)\nlet mut seen = HashMap::new();\nfor (i, &x) in nums.iter().enumerate() {\n    let want = target - x;\n    if seen.___(&want) { return Some((seen[&want], i)); }\n    seen.insert(x, i);\n}\n"] = "// two_sum: valor -> índice en un HashMap, una pasada, O(n)\nlet mut seen = HashMap::new();\nfor (i, &x) in nums.iter().enumerate() {\n    let want = target - x;\n    if seen.___(&want) { return Some((seen[&want], i)); }\n    seen.insert(x, i);\n}\n",
  ["// without memo: 2^n calls\n// with memo: fib(0) .. fib(n), each once -> O(___)\n"] = "// sin memo: 2^n llamadas\n// con memo: fib(0) .. fib(n), cada uno una vez -> O(___)\n",
  ["// worker(id, rx): the let drops the lock guard at the\n// semicolon, so the job runs with the rail unlocked.\nloop {\n    let msg = rx.lock().unwrap().___();\n    let Ok(job) = msg else { break };  // Err: senders gone\n    job();\n}\n"] = "// worker(id, rx): el let suelta el guard del lock en el\n// punto y coma, así el trabajo corre con el riel libre.\nloop {\n    let msg = rx.lock().unwrap().___();\n    let Ok(job) = msg else { break };  // Err: no hay emisores\n    job();\n}\n",
  ["//go:embed puts files in the binary: string, []byte or embed.FS."] = "//go:embed mete archivos en el binario: string, []byte o embed.FS.",
  ["0  PNG DISK"] = "0  DISCO PNG",
  ["0 is clean, a positive number is sys.exit(n), and a negative one is the signal that killed it: -9 is the out-of-memory killer."] = "0 es limpio, un número positivo es sys.exit(n) y uno negativo es la señal que lo mató: -9 es el asesino por falta de memoria.",
  ["0..3 stops before 3. Which range operator includes the last number?"] = "0..3 se detiene antes del 3. ¿Qué operador de rango incluye el último número?",
  ["00:00. CODE RUSH, the live coding show on the Times Square screen, midnight edition: Python. The night market crowd, a buzzer, seven rounds, Chef Bo at the keyboard. No misses keeps the combo. Round one: recursion, and why fib needs a memo."] = "00:00. CODE RUSH, el show de programación en vivo en la pantalla de Times Square, edición de medianoche: Python. El público del mercado nocturno, un timbre, siete rondas, el chef Bo al teclado. Sin fallos se mantiene el combo. Primera ronda: recursión, y por qué fib necesita un memo.",
  ["01:00. The night market is packing up and the startup's back office is still lit. Siu Ming, host by night, interviewer by later night, hands Chef Bo a marker. The Times Square screen said HIRED; the whiteboard decides the offer. Round one: a receipt full of brackets. Are they balanced?"] = "01:00. El mercado nocturno está recogiendo y la oficina trasera de la startup sigue encendida. Siu Ming, presentador de noche y entrevistador de madrugada, le pasa un rotulador al chef Bo. La pantalla de Times Square dijo HIRED; la pizarra decide la oferta. Ronda uno: un recibo lleno de paréntesis. ¿Están balanceados?",
  ["02:00. The shutters are down and the night batch has forty thousand photos to resize before the morning delivery. Chef Bo threw threads at it and the laptop got hot and no faster. One lock in the interpreter is why, and there is exactly one way around it."] = "02:00. Las persianas están bajadas y el lote nocturno tiene cuarenta mil fotos que reducir antes del reparto de la mañana. El chef Bo le echó hilos y el portátil se calentó sin ir más rápido. La razón es un bloqueo dentro del intérprete, y hay exactamente una manera de rodearlo.",
  ["02:15. The fix looks like one word: Thread becomes Process. Then the terminal fills with the same log line a hundred times over, because a spawned child imports the script it came from and runs everything that is not tucked behind the main guard."] = "02:15. El arreglo parece una sola palabra: Thread se convierte en Process. Entonces la terminal se llena con la misma línea de log cien veces, porque un hijo lanzado con spawn importa el script del que salió y ejecuta todo lo que no esté metido detrás de la guarda de main.",
  ["02:30. Forty thousand photos, eight cores, and one lesson: pay for the interpreters once. A Pool is eight cooks reading the same order book, and the only real decision left is how many photos each of them carries across the kitchen at a time."] = "02:30. Cuarenta mil fotos, ocho núcleos y una lección: los intérpretes se pagan una sola vez. Un Pool son ocho cocineros leyendo la misma comanda, y la única decisión que queda es cuántas fotos lleva cada uno al cruzar la cocina.",
  ["02:45. The receipts worker fills a list and the parent prints nothing, over and over. There is no bug: the child got a copy of the list at start-up and has been filling that. Between processes there is only the dumbwaiter, and everything on it is pickled."] = "02:45. El worker de recibos llena una lista y el padre no imprime nada, una y otra vez. No hay ningún fallo: el hijo recibió una copia de la lista al arrancar y ha estado llenando esa. Entre procesos solo está el montaplatos, y todo lo que sube en él va en pickle.",
  ["03:00. Eight workers, one label printer, and a sticker with two orders printed on top of each other. Separate memory did not make the printer separate. What crosses process lines now is not data but permission: who may write, and when."] = "03:00. Ocho workers, una impresora de etiquetas y una pegatina con dos pedidos impresos uno encima del otro. Separar la memoria no separó la impresora. Lo que ahora cruza la frontera de los procesos no son datos sino permiso: quién puede escribir y cuándo.",
  ["03:20. The month's receipts are two gigabytes and every worker got its own pickled copy of them: eight copies, eight seconds of pickling, one machine on its knees. The cold room is the answer. One block of bytes, everybody walks in, nobody carries it."] = "03:20. Los recibos del mes son dos gigabytes y cada worker recibió su propia copia serializada: ocho copias, ocho segundos de pickle, una máquina de rodillas. La cámara frigorífica es la respuesta. Un bloque de bytes, todos entran y nadie lo carga.",
  ["03:50. The van comes at five. What is left is four hundred HTTP calls to the supplier and four hundred images to resize, and Chef Bo wants one way to write both. concurrent.futures is that way: the same six lines, and one word that decides whether it waits or computes."] = "03:50. La furgoneta llega a las cinco. Quedan cuatrocientas llamadas HTTP al proveedor y cuatrocientas imágenes que reducir, y el chef Bo quiere una sola manera de escribir las dos. concurrent.futures es esa manera: las mismas seis líneas y una palabra que decide si espera o calcula.",
  ["06:40. Causeway Bay. Alex wants a muffin, a hash brown and coffee. The flat's door kiosk will not unlock until the Go file compiles."] = "06:40. Causeway Bay. Alex quiere un muffin, un hash brown y café. El kiosco de la puerta del apartamento no se abre hasta que el archivo Go compile.",
  ["08:10. Breakfast done. The owner wants a delivery app before the lunch rush. First ticket: the signboard shows 銅鑼灣 wrong, because a Go string is bytes, not characters."] = "08:10. Desayuno terminado. El dueño quiere una app de reparto antes del ajetreo del almuerzo. Primer ticket: el letrero muestra 銅鑼灣 mal, porque un string de Go son bytes, no caracteres.",
  ["1  QUESTION"] = "1  PREGUNTA",
  ["1 + max(hl, hr). A balanced tree of n nodes is about log2(n) tall; a sorted insert order makes a list, height n."] = "1 + max(hl, hr). Un árbol equilibrado de n nodos mide unos log2(n); un orden de inserción ya ordenado crea una lista, altura n.",
  ["1-4 copy    5-0 export    A all    S scope    ESC close"] = "1-4 copiar    5-0 exportar    A todo    S alcance    ESC cerrar",
  ["1-7 jump straight in.   Q quest.   TAB Go/Rust.   F3 language.   F4 sound.   ESC quit."] = "1-7 entrar directo.   Q misión.   TAB Go/Rust.   F3 idioma.   F4 sonido.   ESC salir.",
  ["1-7 jump straight in.   Q quest.   TAB Go/Rust/Python.   F3 language.   F4 sound.   ESC quit."] = "1-7 saltar directamente.   Q misión.   TAB Go/Rust/Python.   F3 idioma.   F4 sonido.   ESC salir.",
  ["1..=3 is 1, 2, 3. for in Rust walks anything iterable: ranges, Vec, iterators."] = "1..=3 es 1, 2, 3. En Rust, for recorre cualquier cosa iterable: rangos, Vec, iteradores.",
  ['1..=5 is RangeInclusive; 1..5 stops at 4. Also in patterns: 1..=5 => "low".'] = '1..=5 es RangeInclusive; 1..5 se detiene en 4. También en patrones: 1..=5 => "low".',
  ["10. A million items take 20, a billion 30. That is how slowly log n grows."] = "10. Un millón de elementos lleva 20, mil millones 30. Así de despacio crece log n.",
  ["10. A million items take 20, a billion 30. That is how slowly log n grows: the line almost lies down."] = "10. Un millón de elementos lleva 20, mil millones 30. Así de despacio crece log n: la línea casi se tumba.",
  ["100 RIGHT"] = "100 ACIERTOS",
  ["1024 sorted items. Halving each time, at most how many steps until one is left?"] = "1024 elementos ordenados. Partiendo a la mitad cada vez, ¿como máximo cuántos pasos hasta que queda uno?",
  ["12:00. Both tills are open, the queue is out to Percival Street, and the counter on the wall is wrong by six. Nobody stole anything: sold++ is a read, an add and a write, and two goroutines read the same number before either wrote it back."] = "12:00. Las dos cajas están abiertas, la cola llega hasta Percival Street y el contador de la pared va corto por seis. Nadie robó nada: sold++ es una lectura, una suma y una escritura, y dos goroutines leyeron el mismo número antes de que ninguna lo devolviera.",
  ["12:20. The door sensor, the till and the delivery app all raise one counter. A mutex would work and would also be the slowest thing in the building. The hardware can add without a lock; the sync/atomic package is how Go asks it to."] = "12:20. El sensor de la puerta, la caja y la app de reparto suben el mismo contador. Un mutex funcionaría y sería además lo más lento del edificio. El hardware sabe sumar sin cerrojo; el paquete sync/atomic es como Go se lo pide.",
  ["12:35. The kitchen board is a map[string]int the six wok goroutines all write to, and Go kills the process for it on purpose: a torn map is worse than a stopped one. Alex has three ways out, and only one of them is a lock."] = "12:35. El tablero de la cocina es un map[string]int en el que escriben las seis goroutines de los woks, y Go mata el proceso a propósito: un map roto es peor que un programa parado. Alex tiene tres salidas y solo una es un lock.",
  ["12:50. Forty riders, eight bikes, one printer. Goroutines are cheap enough that Alex made one per order and the queue turned to noise. A pool is the fix: a fixed number of workers, all reading the same channel, all finishing before the shift ends."] = "12:50. Cuarenta repartidores, ocho bicis, una impresora. Las goroutines son tan baratas que Alex creó una por pedido y la cola se volvió ruido. El arreglo es un pool: un número fijo de workers, todos leyendo el mismo channel, todos acabando antes del cierre del turno.",
  ["13:00. CODE RUSH, the live coding show on the Times Square screen. A crowd, a buzzer, seven rounds. Answer without a miss to keep the combo. Round one: recursion, and why fib needs a memo."] = "13:00. CODE RUSH, el programa de coding en vivo en la pantalla de Times Square. Público, un timbre, siete rondas. Responde sin fallar para mantener el combo. Ronda uno: recursión, y por qué fib necesita un memo.",
  ["13:05. The kitchen stopped sending but the counter kept receiving, and every receive came back instantly with an empty Order. A closed channel is not an error: it is a promise that nothing more is coming, and the second value of the receive is where it says so."] = "13:05. La cocina dejó de enviar pero el mostrador siguió recibiendo, y cada recepción volvía al instante con un Order vacío. Un channel cerrado no es un error: es la promesa de que no viene nada más, y el segundo valor de la recepción es donde lo dice.",
  ["13:20. A rider cancels, the customer closes the app, and three goroutines carry on fetching an ETA nobody will read. Go cannot kill a goroutine from outside: cancellation is a value you pass in and a channel the work agrees to watch."] = "13:20. Un repartidor cancela, el cliente cierra la app y tres goroutines siguen buscando un ETA que nadie leerá. Go no puede matar una goroutine desde fuera: la cancelación es un valor que pasas y un channel que el trabajo acepta vigilar.",
  ["13:40. Alex asks the question every newcomer asks: where is async, where is await? Mei draws two lines on the whiteboard. Start it with go. Wait for it with an arrow. Everything async/await gives you, Go gives you without splitting functions into two kinds."] = "13:40. Alex hace la pregunta que hace todo recién llegado: ¿dónde está async, dónde está await? Mei dibuja dos líneas en la pizarra. Arráncalo con go. Espéralo con una flecha. Todo lo que da async/await lo da Go sin partir las funciones en dos clases.",
  ["14:30. The screen at Times Square still says HIRED, but the startup wants a second round in the back office: a whiteboard, a marker, Siu Ming with a list. Round one is the question every callback starts with: does every bracket close in the right order?"] = "14:30. La pantalla de Times Square todavía dice CONTRATADO, pero la startup quiere una segunda ronda en la oficina trasera: una pizarra, un rotulador, Siu Ming con una lista. La primera ronda es la pregunta con la que empieza todo callback: ¿cierra cada paréntesis en el orden correcto?",
  ["15:00. Lunch is done at Lucky Mac. Mei's laptop shows the Times Square branch: every kiosk of Lucky Mac Express is frozen on a Rust file with no main. Alex knows Go. Mei knows Rust. They start walking."] = "15:00. Se acabó el almuerzo en Lucky Mac. El portátil de Mei muestra la sucursal de Times Square: todos los kioscos de Lucky Mac Express están congelados en un archivo Rust sin main. Alex sabe Go. Mei sabe Rust. Empiezan a caminar.",
  ["15:08. The tram stop on Percival Street. The next-tram sign runs a tiny Rust program and it will not compile: someone tried to change a value that was never marked mut. Mei fixes it while Alex reads the error messages out loud."] = "15:08. La parada del tranvía en Percival Street. El letrero del próximo tranvía corre un programa Rust diminuto y no compila: alguien intentó cambiar un valor que nunca se marcó mut. Mei lo arregla mientras Alex lee los errores en voz alta.",
  ["15:15. The underpass at Causeway Bay MTR exit A. The Lucky Mac Express ad gate should show muffin, coffee or set as people walk past, but its match has a hole and the loop never ends. Mei counts the cases on her fingers."] = "15:15. El paso subterráneo de la salida A del MTR de Causeway Bay. La puerta publicitaria de Lucky Mac Express debería mostrar muffin, café o menú al pasar la gente, pero su match tiene un hueco y el bucle nunca termina. Mei cuenta los casos con los dedos.",
  ["15:20. The footbridge over Canal Road, Times Square's clock ahead. The Express delivery board on the bridge shows the price of every set, but the pricing function returns nothing and the seat finder crashes on an empty table. Alex tries the Rust himself for the first time."] = "15:20. La pasarela sobre Canal Road, el reloj de Times Square al frente. El tablero de entregas del Express en el puente muestra el precio de cada menú, pero la función de precios no devuelve nada y el buscador de asientos se cae con una mesa vacía. Alex prueba el Rust por primera vez él mismo.",
  ["15:25. The atrium of Times Square, the crab sticker on the Express order kiosk. The kiosk prints a receipt, then tries to read the same String again and the compiler says: value used after move. Mei explains who owns the tray."] = "15:25. El atrio de Times Square, la pegatina del cangrejo en el kiosco de pedidos del Express. El kiosco imprime un recibo, luego intenta leer el mismo String otra vez y el compilador dice: value used after move. Mei explica quién es el dueño de la bandeja.",
  ["15:30. The delivery app is one file and the Times Square shop wants to import the menu code from GitHub. Before there is a package to import there has to be a module to hold it, and the module's name is not a label: it is the first half of every import path."] = "15:30. La app de reparto es un solo fichero y la tienda de Times Square quiere importar el código del menú desde GitHub. Antes de que haya un paquete que importar tiene que haber un módulo que lo contenga, y el nombre del módulo no es una etiqueta: es la primera mitad de cada ruta de importación.",
  ["15:30. The queue outside Lucky Mac Express, twelve people and a crab sticker on the board. The board should list every order's price and count the muffins per table, but the Vec is never pushed to and the HashMap panics on a missing key. Siu Ming waves them to the front."] = "15:30. La fila frente a Lucky Mac Express, doce personas y una pegatina de cangrejo en el tablero. El tablero debería listar el precio de cada pedido y contar los muffins por mesa, pero nunca se hace push al Vec y el HashMap hace panic con una clave que falta. Siu Ming les hace señas para pasar al frente.",
  ["15:35. The counter of Lucky Mac Express at last, the crab sticker smiling on the till. The till keeps orders as loose tuples and cannot print them, and a size of Medium sneaks in that the kitchen does not know. Siu Ming needs an Order type before the afternoon set can be sold."] = "15:35. Por fin el mostrador de Lucky Mac Express, la pegatina del cangrejo sonriendo en la caja. La caja guarda los pedidos como tuplas sueltas y no puede imprimirlos, y se cuela un tamaño Medium que la cocina no conoce. Siu Ming necesita un tipo Order antes de poder vender la merienda.",
  ["15:45. The menu code moves into its own folder and immediately breaks in three ways: the package is named after nothing, main cannot see the price function, and the import written as ./menu will not build. All three are the same lesson about what a path means."] = "15:45. El código del menú se muda a su propia carpeta y se rompe de tres maneras a la vez: el paquete tiene un nombre que no viene de nada, main no ve la función price, y el import escrito como ./menu no compila. Las tres son la misma lección sobre lo que significa una ruta.",
  ["16:00. Lucky Mac Express, Times Square. The till took a coin it could not parse and froze on a red Err. Siu Ming has a queue; Alex has to learn how Rust hands errors back."] = "16:00. Lucky Mac Express, Times Square. La caja recibió una moneda que no pudo parsear y se congeló en un Err rojo. Siu Ming tiene fila; Alex tiene que aprender cómo Rust devuelve los errores.",
  ["16:00. The cousin's shop imports github.com/alex/luckymac/menu and the go tool fetches it from GitHub without being told where GitHub is: the host is in the path. What it writes down afterwards, in go.mod and go.sum, is what makes next month's build the same build."] = "16:00. La tienda del primo importa github.com/alex/luckymac/menu y la herramienta go lo trae de GitHub sin que nadie le diga dónde está GitHub: el host va en la ruta. Lo que apunta después, en go.mod y go.sum, es lo que hace que la compilación del mes que viene sea la misma compilación.",
  ["16:10. The Express kitchen. Chef Bo's pass runs every station through one Rust program, but the grill and the wok speak different types and the order board shows nothing. A trait gives them one shared voice."] = "16:10. La cocina del Express. El pase de Chef Bo dirige cada estación con un solo programa Rust, pero la parrilla y el wok hablan tipos distintos y el tablero de pedidos no muestra nada. Un trait les da una voz común.",
  ["16:15. Exporting a name is a promise, and the cousin's shop just took Alex up on one he never meant to make. The fix is not a comment asking people to be nice: it is a directory name the compiler enforces, and a layout that says which packages are the API."] = "16:15. Exportar un nombre es una promesa, y la tienda del primo acaba de tomarle la palabra a Alex en una que nunca quiso hacer. El arreglo no es un comentario pidiendo buenos modales: es un nombre de directorio que el compilador impone, y una organización que dice qué paquetes son la API.",
  ["16:20. The kiosk in the mall corridor has one price list in u32 and one weight list in f64, and two copies of every function. The crab on the screen sulks. Generics fold them into one."] = "16:20. El kiosco del pasillo del centro comercial tiene una lista de precios en u32 y una de pesos en f64, y dos copias de cada función. El cangrejo de la pantalla está de morros. Los genéricos las funden en una.",
  ["16:30. The path problem in the flesh: the library on disk is newer than the library in the cache, and the import path points at the cache. Two lines of go.mod, or one go.work file, redirect a path to a folder while you work, and tidy puts go.mod back in step."] = "16:30. El problema de rutas en carne y hueso: la biblioteca del disco es más nueva que la de la caché, y la ruta de importación apunta a la caché. Dos líneas de go.mod, o un fichero go.work, redirigen una ruta a una carpeta mientras trabajas, y tidy vuelve a poner go.mod al día.",
  ["16:30. The set table by the window. The receipt printer holds a reference to a name that was freed one line earlier and Rust refuses to build. Alex learns to say how long a borrow lives."] = "16:30. La mesa del menú junto a la ventana. La impresora de recibos guarda una referencia a un nombre liberado una línea antes y Rust se niega a compilar. Alex aprende a decir cuánto vive un préstamo.",
  ["16:40. Three orders, one cook, one thread: the pineapple buns wait while the kettle boils. Chef Bo wants the grill, the kettle and the pass to run at the same time. Rust threads are real OS threads; no go keyword here."] = "16:40. Tres pedidos, un cocinero, un thread: los bollos de piña esperan mientras hierve el agua. Chef Bo quiere que la parrilla, el hervidor y el pase corran a la vez. Los threads de Rust son threads reales del sistema; aquí no hay palabra go.",
  ["16:45. There is no publish button. A Go module is released by pushing a git tag, and the number on the tag is a contract: patch and minor never break a caller, and a major that does gets a new import path so old and new can live side by side."] = "16:45. No hay botón de publicar. Un módulo Go se publica subiendo una etiqueta git, y el número de la etiqueta es un contrato: patch y minor nunca rompen a quien llama, y un major que sí lo hace recibe una nueva ruta de importación para que lo viejo y lo nuevo convivan.",
  ["16:50. Two tills at Lucky Mac Express and one kitchen. Orders sit in a shared Vec that both tills scribble on and the kitchen never sees. Mei replaces the Vec with a channel: many senders, one receiver."] = "16:50. Dos cajas en Lucky Mac Express y una cocina. Los pedidos están en un Vec compartido en el que garabatean ambas cajas y que la cocina nunca ve. Mei reemplaza el Vec por un channel: muchos emisores, un receptor.",
  ["17:00. Last hour before the tea set. Both tills bump one sold counter from two threads and the total drifts. Rc will not even compile across threads; Mei reaches for Arc, Mutex and one atomic. Get it right and the afternoon tea set is yours."] = "17:00. Última hora antes de la merienda. Las dos cajas suben un mismo contador de ventas desde dos threads y el total se desvía. Rc ni siquiera compila entre threads; Mei recurre a Arc, Mutex y un atómico. Hazlo bien y la merienda es tuya.",
  ["17:00. Lucky Mac Express, Times Square. The receipt printer writes the shop name as 銅鑼 and a broken square. Someone sliced a String by byte count. Mei opens ticket one."] = "17:00. Lucky Mac Express, Times Square. La impresora de recibos escribe el nombre de la tienda como 銅鑼 y un cuadrado roto. Alguien cortó un String por número de bytes. Mei abre el ticket uno.",
  ["17:00. The last path problem is not on disk: it is between the go tool, a public proxy that mirrors the whole ecosystem, and a repo that only Alex's ssh key can open. Two environment variables and one git setting route the private path around the proxy."] = "17:00. El último problema de rutas no está en el disco: está entre la herramienta go, un proxy público que replica todo el ecosistema y un repo que solo abre la clave ssh de Alex. Dos variables de entorno y un ajuste de git desvían la ruta privada alrededor del proxy.",
  ["17:10. The till at Lucky Mac Express unwraps every parse. One bad keypad entry and the drawer prints a stack trace instead of a receipt. Siu Ming wants a real error type."] = "17:10. La caja de Lucky Mac Express hace unwrap de cada parse. Una entrada mala en el teclado y el cajón imprime un stack trace en vez de un recibo. Siu Ming quiere un tipo de error de verdad.",
  ["17:20. The kitchen printer at Lucky Mac Express runs a hand-written index loop. It skips the first dish and prints the last one twice. Chef Bo hands Alex ticket three: iterators."] = "17:20. La impresora de cocina de Lucky Mac Express usa un bucle de índices escrito a mano. Se salta el primer plato e imprime el último dos veces. Chef Bo le pasa a Alex el ticket tres: iteradores.",
  ['17:30. Under the mall atrium screens, the rider app and the kitchen disagree on field names, and every order arrives as "name": null. Ticket four: teach the structs to speak JSON with serde.'] = '17:30. Bajo las pantallas del atrio del centro comercial, la app de repartidores y la cocina no se ponen de acuerdo en los nombres de campo, y cada pedido llega como "name": null. Ticket cuatro: enseña a los structs a hablar JSON con serde.',
  ["17:40. Russell Street. Riders idle by the tram stop while the delivery backend fetches ETAs one by one, blocking on each. Ticket five: make the calls async and run them together on tokio."] = "17:40. Russell Street. Los repartidores esperan junto a la parada del tranvía mientras el backend de reparto pide los ETA uno por uno, bloqueándose en cada uno. Ticket cinco: haz las llamadas async y córrelas juntas en tokio.",
  ["17:50. The pickup queue at Lucky Mac Express is out the door and the new backend is still a folder of .rs files. Alex has go build in his fingers. Mei: in Rust it is all cargo."] = "17:50. La fila de recogida de Lucky Mac Express sale por la puerta y el nuevo backend sigue siendo una carpeta de archivos .rs. Alex tiene go build en los dedos. Mei: en Rust todo es cargo.",
  ["17:55. Lucky Mac Express, the set counter. The backend compiles, but Mei's review has six comments: this is 2015 Rust. Alex rewrites each one the modern way. Then it ships. SHIPPED."] = "17:55. Lucky Mac Express, el mostrador de menús. El backend compila, pero la revisión de Mei tiene seis comentarios: esto es Rust de 2015. Alex reescribe cada uno a la manera moderna. Y sale a producción. ENTREGADO.",
  ["19:00. CODE RUSH, the live coding show on the Times Square screen, evening edition: Rust. A crowd, a buzzer, seven rounds, Mei at the keyboard. No misses keeps the combo. Round one: recursion, and why fib needs a memo."] = "19:00. CODE RUSH, el programa de programación en directo en la pantalla de Times Square, edición de noche: Rust. Público, un pulsador, siete rondas, Mei al teclado. Sin fallos se mantiene el combo. Ronda uno: recursión, y por qué fib necesita un memo.",
  ["19:08. Round two, and the screen shows a tree of order numbers. Insert, walk in order, measure the height. In Rust a tree is a struct with two Option<Box<Node>> fields, and the compiler wants to know its size."] = "19:08. Ronda dos, y la pantalla muestra un árbol de números de pedido. Inserta, recórrelo en orden, mide la altura. En Rust un árbol es un struct con dos campos Option<Box<Node>>, y el compilador quiere saber su tamaño.",
  ["19:17. Round three puts the MTR map on the big screen: stations are nodes, lines are edges. Mei has to reach every station once. Wide first with a queue, then deep with a stack, and a HashSet so nobody loops forever."] = "19:17. La ronda tres pone el mapa del MTR en la pantalla grande: las estaciones son nodos, las líneas son aristas. Mei tiene que llegar a cada estación una vez. Primero a lo ancho con una cola, luego a lo hondo con una pila, y un HashSet para que nadie dé vueltas para siempre.",
  ["19:26. Round four is the chain: a linked list of order tickets, out on the street where the delivery riders queue. Each node owns the next one. Reverse it, walk it, find the middle, and never touch a raw pointer."] = "19:26. La ronda cuatro es la cadena: una lista enlazada de tickets de pedido, en la calle donde hacen cola los repartidores. Cada nodo posee al siguiente. Inviértela, recórrela, encuentra el medio, y sin tocar nunca un puntero crudo.",
  ["19:35. Round five, the shuffle. The screen dumps a hundred order prices in random order. Mei writes merge sort from memory, then the host wants the std spelling: stable, unstable, and a binary search on the result."] = "19:35. Ronda cinco, la barajada. La pantalla suelta cien precios de pedido en orden aleatorio. Mei escribe merge sort de memoria, y luego el presentador quiere la versión de std: estable, inestable, y una búsqueda binaria sobre el resultado.",
  ["19:44. Round six, the classics, back on the mall floor with the crowd pressing in. Two-sum, a palindrome, an anagram, a word count. Every one of them is a hash map or an array of 26, and every one is O(n)."] = "19:44. Ronda seis, los clásicos, de vuelta en la planta del centro comercial con el público apretando. Two-sum, un palíndromo, un anagrama, un conteo de palabras. Todos son un hash map o un array de 26, y todos son O(n).",
  ["19:55. The final, the one they always ask: N worker threads pull jobs from one channel. The Times Square screen shows the Lucky Mac Express kitchen as the diagram. Get the lock, the drop and the join right and the prize is HIRED."] = "19:55. La final, la que siempre preguntan: N threads worker sacan trabajos de un solo channel. La pantalla de Times Square muestra la cocina de Lucky Mac Express como diagrama. Acierta con el lock, el drop y el join y el premio es CONTRATADA.",
  ["2  HINT"] = "2  PISTA",
  ["2 ** 10 is 1024. 2 ** 0.5 is a square root. Ints never overflow in Python; they just grow."] = "2 ** 10 es 1024. 2 ** 0.5 es una raíz cuadrada. Los int nunca desbordan en Python; solo crecen.",
  ["20:30. The Times Square screen is dark; the startup's back office is not. A whiteboard, a marker, Siu Ming with a clipboard. The callback round: the problems the live show never had time for. First, brackets. Every ( wants its ), in order, and a Vec is the stack."] = "20:30. La pantalla de Times Square está apagada; la oficina trasera de la startup, no. Una pizarra, un rotulador, Siu Ming con una carpeta. La ronda CALLBACK: los problemas para los que el programa en vivo no tuvo tiempo. Primero, paréntesis. Cada ( quiere su ), en orden, y un Vec es la pila.",
  ["20:38. Siu Ming draws a staircase. One step or two at a time: how many ways to the top? Mei sees fib, but this time there is no memo: a Vec filled from the bottom. Then the till: the fewest coins for 27 dollars, from 1, 5 and 10. Same table, a min instead of a sum."] = "20:38. Siu Ming dibuja una escalera. Uno o dos escalones por vez: ¿cuántas formas de llegar arriba? Mei ve fib, pero esta vez no hay memo: un Vec rellenado desde abajo. Luego la caja: las menos monedas posibles para 27 dólares, con 1, 5 y 10. La misma tabla, un min en vez de una suma.",
  ["20:45. A week of Lucky Mac Express sales on the whiteboard, some days negative. Which run of days made the most? Mei writes Kadane in four lines. Then windows of k hours, then the longest stretch of dishes with no repeat. Every one of them is one pass and two indices."] = "20:45. Una semana de ventas de Lucky Mac Express en la pizarra, algunos días en negativo. ¿Qué racha de días ganó más? Mei escribe Kadane en cuatro líneas. Luego ventanas de k horas, luego la racha más larga de platos sin repetir. Todos son una pasada y dos índices.",
  ["20:52. Siu Ming dumps a box of receipts on the table: ten thousand of them. The third largest, please, and the five most ordered dishes. Sorting is O(n log n) and the crowd knows it. Mei draws a heap of size k on the board and the room goes quiet."] = "20:52. Siu Ming vuelca una caja de recibos sobre la mesa: diez mil. El tercero más grande, por favor, y los cinco platos más pedidos. Ordenar es O(n log n) y el público lo sabe. Mei dibuja un heap de tamaño k en la pizarra y la sala se queda en silencio.",
  ["21:00. The cook's shift sheet goes up on the board: a dozen (start, end) pairs, out of order, overlapping. When is the kitchen covered, and where are the gaps? Sort by start, keep the last merged shift in view, and each new one either stretches it or starts a fresh block."] = "21:00. La hoja de turnos de los cocineros sube a la pizarra: una docena de pares (start, end), desordenados, solapados. ¿Cuándo está cubierta la cocina y dónde están los huecos? Ordena por inicio, ten a la vista el último turno fusionado, y cada uno nuevo o lo estira o empieza un bloque nuevo.",
  ["21:00. The morning set is long gone and the Rust afternoon is over. Lucky Mac's night shift runs on Python scripts Chef Bo wrote years ago. Tonight the pass screen is blank. Bo hands Alex the laptop; a blue and yellow snake sticker on the lid seems to grin."] = "21:00. El desayuno queda lejos y la tarde de Rust ha terminado. El turno de noche de Lucky Mac funciona con scripts de Python que el chef Bo escribió hace años. Esta noche la pantalla del pase está en negro. Bo le pasa el portátil a Alex; una pegatina de serpiente azul y amarilla en la tapa parece sonreír.",
  ["21:08. The one every backend interview ends with: a cache with a capacity, where the least recently used entry makes room for the new one. Mei keeps it honest: a HashMap for the values, a VecDeque for the order, and a note on the board that the linked-list version makes every step O(1)."] = "21:08. La que cierra toda entrevista de backend: una caché con capacidad, donde la entrada usada hace más tiempo deja sitio a la nueva. Mei la mantiene honesta: un HashMap para los valores, un VecDeque para el orden, y una nota en la pizarra de que la versión con lista enlazada hace cada paso O(1).",
  ["21:15. The last board: Victoria Harbour as a grid of ones and zeros. How many islands? Mei writes sink: stop at the edge, stop at water, turn this cell to water, flood the four neighbours. Count one per unsunk land cell. Siu Ming caps the marker. The screen outside lights up: OFFER."] = "21:15. La última pizarra: Victoria Harbour como cuadrícula de unos y ceros. ¿Cuántas islas? Mei escribe sink: para en el borde, para en el agua, convierte esta celda en agua, inunda los cuatro vecinos. Cuenta una por cada celda de tierra sin hundir. Siu Ming tapa el rotulador. La pantalla de fuera se enciende: OFFER.",
  ["22:00. The back office behind the kitchen: a humming rack, two laptops, a whiteboard with a tree on it. The refund script crashes on the first bad receipt because nobody catches anything. Alex reaches for if err != nil; Bo shakes his head."] = "22:00. La oficina trasera detrás de la cocina: un rack que zumba, dos portátiles, una pizarra con un árbol. El script de reembolsos se cae con el primer recibo malo porque nadie captura nada. Alex va a por if err != nil; Bo niega con la cabeza.",
  ["22:15. The shutter is half down and a small queue waits outside. Chef Bo's queue script counts bowls and people. It is missing every keyword that makes a decision. Mei reads Python like a recipe: colon, then indent."] = "22:15. La persiana está a medio bajar y una pequeña cola espera fuera. El script de la cola del chef Bo cuenta boles y personas. Le faltan todas las palabras clave que toman una decisión. Mei lee Python como una receta: dos puntos, luego indentar.",
  ["23:00. The last order robot at the market stall runs on a class called Order. Its constructor is gone, its methods lost their first parameter, and the receipt prints <__main__.Order object at 0x7f...>. Bo fixes it with Alex; Monty the sticker watches from the lid."] = "23:00. El último robot de pedidos del puesto del mercado funciona con una clase llamada Order. Su constructor desapareció, sus métodos perdieron el primer parámetro y el recibo imprime <__main__.Order object at 0x7f...>. Bo lo arregla con Alex; Monty, la pegatina, mira desde la tapa.",
  ["23:00. The last orders of the night hit three woks. The cook script runs them one after another. Threads will overlap the waiting; the GIL means they will not overlap the arithmetic. For frying, waiting is all that matters."] = "23:00. Los últimos pedidos de la noche llegan a tres woks. El script de cocina los ejecuta uno tras otro. Los hilos solaparán la espera; el GIL significa que no solaparán la aritmética. Para freír, la espera es lo único que importa.",
  ["25 // 6 is 4, 25 / 6 is 4.1666. In Python 3 a single slash always makes a float."] = "25 // 6 es 4, 25 / 6 es 4.1666. En Python 3 una sola barra siempre produce un float.",
  ["25 eggs, 6 per tray: how many whole trays? Which operator divides and rounds down?"] = "25 huevos, 6 por bandeja: ¿cuántas bandejas enteras? ¿Qué operador divide y redondea hacia abajo?",
  ["2^n subsets. When the output itself is exponential no algorithm can be faster; when only the answer is needed, look for a memo."] = "2^n subconjuntos. Cuando la propia salida es exponencial ningún algoritmo puede ser más rápido; cuando solo hace falta la respuesta, busca un memo.",
  ["2^n subsets. When the output itself is exponential no algorithm can be faster; when only the answer is needed, look for a memo. The board is full."] = "2^n subconjuntos. Cuando la propia salida es exponencial ningún algoritmo puede ser más rápido; cuando solo hace falta la respuesta, busca un memo. La pizarra está llena.",
  ["2^n subsets. itertools.combinations lists them; when the output itself is exponential no algorithm can be faster."] = "2^n subconjuntos. itertools.combinations los lista; cuando la propia salida es exponencial ningún algoritmo puede ser más rápido.",
  ["3  ANSWER"] = "3  RESPUESTA",
  ["4  ALL"] = "4  TODO",
  ["4950. For 10,000 guests it is about fifty million. Big O ignores the /2, and rightly: the curve is the same."] = "4950. Para 10.000 invitados son unos cincuenta millones. Big O ignora el /2, y con razón: la curva es la misma.",
  ["4950. For 10,000 guests it is about fifty million. Big O ignores the /2: the curve is the same."] = "4950. Para 10.000 invitados son unos cincuenta millones. Big O ignora el /2: la curva es la misma.",
  ["5  MARKDOWN"] = "5  MARKDOWN",
  ["6  CSV"] = "6  CSV",
  ["7  JSONL"] = "7  JSONL",
  ["7 streets. One language. Type the answers."] = "7 calles. Un lenguaje. Escribe las respuestas.",
  ["8  TXT"] = "8  TXT",
  ["9  SQLITE"] = "9  SQLITE",
  [":= declares and assigns. Type comes from the right-hand side."] = ":= declara y asigna. El tipo viene del lado derecho.",
  [":= infers the type. var names it. const never changes. int starts at 0."] = ":= infiere el tipo. var lo nombra. const nunca cambia. int empieza en 0.",
  ["< PREV"] = "< ANTERIOR",
  ["<-chan T and chan<- T let the compiler stop the wrong side from sending or closing."] = "<-chan T y chan<- T dejan que el compilador impida al lado equivocado enviar o cerrar.",
  ["<= merges [1,3] and [3,5] into [1,5]. Use < if touching intervals should stay apart."] = "<= fusiona [1,3] y [3,5] en [1,5]. Usa < si los intervalos que se tocan deben quedar separados.",
  ["<= takes the left item on ties, so equal receipts keep their order. Merge is O(n); the whole sort O(n log n)."] = "<= toma el elemento izquierdo en los empates, así que los recibos iguales conservan su orden. La mezcla es O(n); toda la ordenación O(n log n).",
  ["? calls From::from on the error. Without the impl, use .map_err(OrderError::BadQty) by hand."] = "? llama a From::from sobre el error. Sin el impl, usa .map_err(OrderError::BadQty) a mano.",
  ["? on Option returns None when it sees None. The function type must be Option as well."] = "? en Option devuelve None cuando ve None. El tipo de la función también debe ser Option.",
  ["? unwraps Ok, or returns Err early from the function. Only works where the return type is Result or Option."] = "? desenvuelve Ok, o devuelve Err saliendo antes de la función. Solo funciona donde el tipo de retorno es Result u Option.",
  ["@classmethod gets cls; return cls(...) builds the right subclass too. The stamp desk closes."] = "@classmethod recibe cls; return cls(...) construye también la subclase correcta. El mostrador de sellos cierra.",
  ['@contextlib.___\ndef safe():\n    f = open("stock.csv")\n    try:\n        yield f\n    finally:\n        f.close()\n'] = '@contextlib.___\ndef safe():\n    f = open("stock.csv")\n    try:\n        yield f\n    finally:\n        f.close()\n',
  ["@contextlib.contextmanager: everything before yield is __enter__, everything after is __exit__. Ten lines become five."] = "@contextlib.contextmanager: todo lo anterior a yield es __enter__, todo lo posterior es __exit__. Diez líneas se vuelven cinco.",
  ["@dataclass reads the annotated fields and writes the boilerplate. Order('tea', 2) just works. The shutter comes down; the night shift is closed."] = "@dataclass lee los campos anotados y escribe el código repetitivo. Order('tea', 2) simplemente funciona. Baja la persiana; el turno de noche está cerrado.",
  ["@functools.___\ndef fib(n):\n    if n < 2:\n        return n\n    return fib(n - 1) + fib(n - 2)    # now O(n)\n"] = "@functools.___\ndef fib(n):\n    if n < 2:\n        return n\n    return fib(n - 1) + fib(n - 2)    # ahora O(n)\n",
  ["@functools.cache (3.9) memoizes by arguments; @lru_cache(maxsize=128) bounds it. fib(40) becomes 40 calls."] = "@functools.cache (3.9) memoriza por argumentos; @lru_cache(maxsize=128) lo acota. fib(40) se vuelve 40 llamadas.",
  ["@functools.cache: a dict keyed by the arguments, O(1) per hit. Go spells this a comma-ok test; Rust memo.get(&n)."] = "@functools.cache: un dict con los argumentos como clave, O(1) por acierto. Go lo escribe con la prueba comma-ok; Rust con memo.get(&n).",
  ["@functools.wraps(fn) copies __name__, __doc__ and more onto the wrapper. Every decorator you write should use it."] = "@functools.wraps(fn) copia __name__, __doc__ y más a la envoltura. Todo decorador que escribas debería usarlo.",
  ["@property makes a getter; @total.setter adds assignment. Go would write a Total() method; Python hides the call."] = "@property crea un getter; @total.setter añade la asignación. Go escribiría un método Total(); Python esconde la llamada.",
  ["@staticmethod: no implicit first argument. It is a namespaced plain function. Often a module-level def is clearer."] = "@staticmethod: sin primer argumento implícito. Es una función normal con espacio de nombres. A menudo un def a nivel de módulo es más claro.",
  ["@timer above def fry is exactly fry = timer(fry). Sugar, nothing more. Decorators stack, top one runs last."] = "@timer encima de def fry es exactamente fry = timer(fry). Azúcar, nada más. Los decoradores se apilan; el de arriba se aplica último.",
  ["A  ALL FORMATS"] = "A  TODOS LOS FORMATOS",
  ["A DP table starts from the cases you can answer by hand. Everything else is built on them."] = "Una tabla DP empieza por los casos que resuelves a mano. Todo lo demás se construye sobre ellos.",
  ["A Go release is a git tag: v1.0.0, pushed. go get pkg@latest picks the highest tag; no tag means a pseudo-version built from the commit. A breaking change is a new major, and a new major is a new import path: module github.com/you/x/v2. retract in go.mod tells everyone a tag was a mistake."] = "Una release de Go es una etiqueta git: v1.0.0, subida. go get pkg@latest elige la etiqueta más alta; sin etiqueta se usa una pseudoversión construida a partir del commit. Un cambio que rompe es un nuevo major, y un nuevo major es una nueva ruta de importación: module github.com/you/x/v2. retract en go.mod avisa a todos de que una etiqueta fue un error.",
  ["A Greek letter. Rust writes |o| o.1 for the same thing."] = "Una letra griega. Rust escribe |o| o.1 para lo mismo.",
  ["A ListNode holds val and next. Reverse with three names: prev, cur, nxt. Two runners find the middle; if the fast one meets the slow one, there is a cycle."] = "Un ListNode guarda val y next. Invierte con tres nombres: prev, cur, nxt. Dos corredores encuentran el medio; si el rápido alcanza al lento, hay un ciclo.",
  ["A Manager is convenience, not speed: every read and write is a round trip to another process. Fine for results, wrong for a hot loop."] = "Un Manager es comodidad, no velocidad: cada lectura y cada escritura es un viaje de ida y vuelta a otro proceso. Bien para resultados, mal para un bucle caliente.",
  ["A Node holds val, left, right; children start as None. Insert goes left when smaller. In-order walk prints sorted. Height is 1 + max of the children. BFS uses a deque and popleft."] = "Un Node guarda val, left, right; los hijos empiezan en None. Insertar va a la izquierda si es menor. El recorrido en orden imprime ordenado. La altura es 1 + el max de los hijos. BFS usa un deque y popleft.",
  ["A Pool starts N interpreters once and feeds them work. pool.map keeps the order and waits for everything; imap yields results as they land; starmap unpacks tuples into several arguments; apply_async returns a handle whose get() blocks. chunksize decides how many items travel per trip, and for tiny tasks it is the whole game."] = "Un Pool arranca N intérpretes una vez y les va dando trabajo. pool.map mantiene el orden y espera a todo; imap entrega los resultados según llegan; starmap despliega tuplas en varios argumentos; apply_async devuelve un manejador cuyo get() bloquea. chunksize decide cuántos elementos viajan por trayecto y, con tareas diminutas, ahí se juega todo.",
  ["A Python list is your Go slice, minus the type. It just grows."] = "Una lista de Python es tu slice de Go, sin el tipo. Simplemente crece.",
  ["A Queue has no close(). What do you put on it to tell the workers to stop?"] = "Una Queue no tiene close(). ¿Qué le pones para decirles a los workers que paren?",
  ["A Semaphore is a lock that lets n holders through. mp also has Event, Condition and Barrier, all with the threading names."] = "Un Semaphore es un bloqueo que deja pasar a n titulares. mp también tiene Event, Condition y Barrier, todos con los nombres de threading.",
  ["A String has one owner. Assigning moves it. & borrows, &mut borrows exclusively. Values drop at the end of their scope."] = "Un String tiene un solo dueño. Asignarlo lo mueve. & lo presta, &mut lo presta en exclusiva. Los valores se liberan al final de su scope.",
  ["A Vec is a stack for free: the end is the top, and both ends of work are O(1)."] = "Un Vec es una pila gratis: el final es la cima, y ambos extremos del trabajo son O(1).",
  ["A Vec is your Go slice. An array knows its length at compile time."] = "Un Vec es tu slice de Go. Un array conoce su longitud al compilar.",
  ["A Vec<char> is the stack: push every opener, pop on every closer and compare. Valid when the stack ends empty. A second Vec of the smallest-so-far gives the minimum in O(1)."] = "Un Vec<char> es la pila: push a cada apertura, pop en cada cierre y compara. Válido cuando la pila termina vacía. Un segundo Vec con el mínimo hasta ahora da el mínimo en O(1).",
  ["A VecDeque grows at both ends in O(1). The stale end is the front, so eviction is a pop from there."] = "Un VecDeque crece por ambos extremos en O(1). El extremo viejo es el frente, así que expulsar es un pop desde ahí.",
  ["A WaitGroup that carries an error, from golang.org/x/sync. Two words joined: err and group."] = "Un WaitGroup que lleva un error, de golang.org/x/sync. Dos palabras unidas: err y group.",
  ["A bang. vec! and format! end the same way."] = "Un signo de exclamación. vec! y format! terminan igual.",
  ["A bool method on every collection, two words joined by an underscore. Not len() == 0, though that works too."] = "Un método bool de toda colección, dos palabras unidas por guion bajo. No len() == 0, aunque también funciona.",
  ["A buffered channel blocks only when full. Unbuffered blocks on every send until someone receives."] = "Un channel con búfer solo bloquea al llenarse. Sin búfer bloquea en cada envío hasta que alguien recibe.",
  ["A buffered channel is a counting semaphore. golang.org/x/sync/semaphore is the weighted version."] = "Un channel con buffer es un semáforo contador. golang.org/x/sync/semaphore es la versión con pesos.",
  ["A buffered channel of capacity 4 is a counting semaphore: the fifth send blocks until a trip finishes."] = "Un channel con capacidad 4 es un semáforo contador: el quinto envío se bloquea hasta que termina un viaje.",
  ["A call that can fail returns Result. Handle Err, or pass it up with ?."] = "Una llamada que puede fallar devuelve Result. Maneja Err, o pásalo arriba con ?.",
  ["A channel that holds 3 muffins before a send blocks. Fill: make(chan string, ___)"] = "Un channel que guarda 3 muffins antes de que un envío bloquee. Completa: make(chan string, ___)",
  ["A closed channel never blocks again, so a for-range over it ends and a bare receive returns instantly, for ever."] = "Un channel cerrado no vuelve a bloquear, así que un for-range sobre él termina y una recepción simple vuelve al instante, para siempre.",
  ["A closer must match the most recent opener. Which method removes and returns the top?"] = "Un cierre debe coincidir con la apertura más reciente. ¿Qué método quita y devuelve el tope?",
  ["A closer must match the most recent opener. Which method takes the top off and returns Option<char>?"] = "Un cierre debe coincidir con la apertura más reciente. ¿Qué método quita la cima y devuelve Option<char>?",
  ["A closer must match the top of the stack. Which map gives the opener it needs?"] = "Un cierre debe coincidir con la cima de la pila. ¿Qué map da la apertura que necesita?",
  ["A closer names the opener it needs. Finish the match: '}' wants which char?"] = "Un cierre nombra la apertura que necesita. Completa el match: ¿qué char quiere '}'?",
  ["A closure captures n. Each call to add(2) has its own n."] = "Un closure captura n. Cada llamada a add(2) tiene su propia n.",
  ["A cold coffee came back. The app says 'error' and nothing else."] = "Devolvieron un café frío. La app dice 'error' y nada más.",
  ["A compile-time value with an UPPER_CASE name and a required type. Which keyword?"] = "Un valor de compilación con nombre en MAYÚSCULAS y tipo obligatorio. ¿Qué palabra clave?",
  ["A constraint that allows int and every type built on int. Fill: ___int | ___float64"] = "Una restricción que permite int y todo tipo construido sobre int. Completa: ___int | ___float64",
  ["A context is the cancel signal of a request. It travels as the first parameter, named ctx, never inside a struct. WithCancel and WithTimeout wrap a parent and hand back a cancel function you always defer. Work watches ctx.Done() and reports ctx.Err(), which is Canceled or DeadlineExceeded."] = "Un context es la señal de cancelación de una petición. Viaja como primer parámetro, llamado ctx, nunca dentro de un struct. WithCancel y WithTimeout envuelven a un padre y devuelven una función cancel que siempre se hace con defer. El trabajo vigila ctx.Done() e informa de ctx.Err(), que es Canceled o DeadlineExceeded.",
  ["A cook locks the rail, pulls one ticket, releases. Which Receiver method blocks until a job arrives?"] = "Un cocinero bloquea el riel, saca un ticket, lo libera. ¿Qué método de Receiver bloquea hasta que llega un trabajo?",
  ["A cook takes the next order, waiting if the queue is empty. Which method?"] = "Un cocinero toma el siguiente pedido, esperando si la cola está vacía. ¿Qué método?",
  ["A copied mutex protects nothing. Anything holding a sync type gets pointer receivers, and never travels by value."] = "Un mutex copiado no protege nada. Todo lo que contenga un tipo de sync lleva receptores por puntero y nunca viaja por valor.",
  ["A counter every process can see. Which attribute reads and writes the shared number?"] = "Un contador que ve todo proceso. ¿Qué atributo lee y escribe el número compartido?",
  ["A counter no mutex guards. Which sync/atomic type holds a 64-bit int?"] = "Un contador que ningún mutex protege. ¿Qué tipo de sync/atomic guarda un entero de 64 bits?",
  ["A crash you can catch in the same goroutine. Which pair: panic and ___?"] = "Un fallo que puedes atrapar en la misma goroutine. ¿Qué pareja: panic y ___?",
  ['A crate writes Display and Error for you from #[error("..")]. Its name?'] = 'Un crate escribe Display y Error por ti a partir de #[error("..")]. ¿Su nombre?',
  ["A customer typed 1x8 sets and the till printed a page of panic. Ticket two."] = "Un cliente escribió 1x8 menús y la caja imprimió una página de panic. Ticket dos.",
  ["A daemon child is terminated when the parent exits, and it may not have children of its own. Use it for watchers, never for work you need finished."] = "Un hijo daemon se termina cuando sale el padre y no puede tener hijos propios. Úsalo para vigilantes, nunca para trabajo que necesitas terminado.",
  ["A decorator is a function that takes a function and returns a new one; @name applies it. functools.wraps keeps the name. @property, @staticmethod and @classmethod are built-in decorators."] = "Un decorador es una función que recibe una función y devuelve una nueva; @name lo aplica. functools.wraps conserva el nombre. @property, @staticmethod y @classmethod son decoradores integrados.",
  ["A def with no return evaluates to None. Printing that is a classic beginner surprise. The pass window is done."] = "Un def sin return evalúa a None. Imprimirlo es la clásica sorpresa del principiante. La ventana del pase está lista.",
  ["A dict from closer to opener. Looking up a closer is O(1); no chain of ifs."] = "Un dict de cierre a apertura. Buscar un cierre es O(1); sin cadena de ifs.",
  ["A dict maps keys to values: {} makes one, d[k] reads, d.get(k, default) reads safely, .items() walks pairs, del removes. set() keeps unique items."] = "Un dict asocia claves a valores: {} crea uno, d[k] lee, d.get(k, default) lee sin riesgo, .items() recorre los pares, del elimina. set() conserva elementos únicos.",
  ["A dict that also remembers which key is oldest. Which class from collections?"] = "Un dict que además recuerda qué clave es la más vieja. ¿Qué clase de collections?",
  ["A directory that builds into a program declares which package?"] = "Un directorio que se compila en un programa declara ¿qué paquete?",
  ["A done signal that carries no data. Fill the element type: make(chan ___)"] = "Una señal de fin que no lleva datos. Completa el tipo del elemento: make(chan ___)",
  ["A dot, then the word for waiting. Only allowed inside an async block or fn."] = "Un punto, luego la palabra inglesa para esperar. Solo se permite dentro de un bloque o fn async.",
  ["A field with no name, only the type. That is embedding."] = "Un campo sin nombre, solo el tipo. Eso es embedding.",
  ["A fixed [26]int beats a map for lowercase ASCII. Then check every count == 0."] = "Un [26]int fijo supera a un map para ASCII en minúsculas. Luego comprueba que cada count == 0.",
  ["A fixed array of exactly 3 frames, size in the type. Fill: var frames ___"] = "Un array fijo de exactamente 3 frames, tamaño en el tipo. Completa: var frames ___",
  ["A fixed tray of three prices. The array type spells out its length. Which number?"] = "Una bandeja fija de tres precios. El tipo del array escribe su longitud. ¿Qué número?",
  ["A fixed window is O(n), not O(n*k): every element enters once and leaves once."] = "Una ventana fija es O(n), no O(n*k): cada elemento entra una vez y sale una vez.",
  ["A flag: dash then four letters. Works with run and build too."] = "Un flag: guion y cuatro letras. También funciona con run y build.",
  ["A folder is a package"] = "Una carpeta es un paquete",
  ["A fresh node has no children yet. What are left and right set to?"] = "Un nodo nuevo aún no tiene hijos. ¿A qué se ponen left y right?",
  ["A function that can fail returns a value and an ___."] = "Una función que puede fallar devuelve un valor y un ___.",
  ["A function that can fail returns which type?"] = "¿Qué tipo devuelve una función que puede fallar?",
  ["A function that remembers n after ident returns. What is that function called?"] = "Una función que recuerda n después de que ident retorne. ¿Cómo se llama esa función?",
  ["A function that runs once before main, and nobody calls it. Its name?"] = "Una función que corre una vez antes de main y nadie la llama. ¿Su nombre?",
  ["A function, past tense, returning a new list. names.sort(key=len) would do it in place."] = "Una función, en pasado, que devuelve una lista nueva. names.sort(key=len) lo haría en el sitio.",
  ["A function, past tense. The method prices.sort() would change the list in place and return None."] = "Una función, en pasado. El método prices.sort() cambiaría la lista en el sitio y devolvería None.",
  ["A gap: this shift starts after the last block ended. Start a new block. Which list method?"] = "Un hueco: este turno empieza después de que terminó el último bloque. Empieza un bloque nuevo. ¿Qué método de lista?",
  ["A generator is a Rust iterator that writes itself. yield instead of impl Iterator."] = "Un generador es un iterador de Rust que se escribe solo. yield en vez de impl Iterator.",
  ["A go.work is a list of use directories and optional replaces. It never lists versions: those still come from each module's own go.mod."] = "Un go.work es una lista de directorios use y replaces opcionales. Nunca lista versiones: esas siguen viniendo del go.mod de cada módulo.",
  ["A goroutine is cheap. Don't confuse it with a thread you create by hand."] = "Una goroutine es barata. No la confundas con un hilo creado a mano.",
  ["A goroutine is not an OS thread: the runtime multiplexes many of them onto GOMAXPROCS threads, so a pool sized by runtime.NumCPU() is the usual answer for CPU work. WaitGroup counts the workers, a buffered channel works as a semaphore, and sync.Pool recycles the buffers they allocate."] = "Una goroutine no es un hilo del sistema: el runtime multiplexa muchas sobre GOMAXPROCS hilos, así que un pool del tamaño de runtime.NumCPU() es la respuesta habitual para trabajo de CPU. WaitGroup cuenta los workers, un channel con buffer hace de semáforo y sync.Pool recicla los buffers que reservan.",
  ["A goroutine that nobody waits for and nothing cancels is a leak: it holds its stack and whatever it captured until the process ends."] = "Una goroutine que nadie espera y que nada cancela es una fuga: retiene su pila y todo lo que capturó hasta que el proceso termina.",
  ["A graph is a dict of lists: defaultdict(list). BFS uses a deque and a visited set; DFS recurses. Mark a node visited when you enqueue it, not when you pop it."] = "Un grafo es un dict de listas: defaultdict(list). BFS usa un deque y un set de visitados; DFS recursa. Marca un nodo como visitado al encolarlo, no al sacarlo.",
  ["A grid is a graph without an adjacency list. Count islands: for every land cell, count one and sink the whole island with a recursive flood that stops at the edges and at water. usize needs wrapping_sub for 'row minus one'."] = "Una cuadrícula es un grafo sin lista de adyacencia. Contar islas: por cada celda de tierra, cuenta una y hunde toda la isla con una inundación recursiva que se detiene en los bordes y en el agua. usize necesita wrapping_sub para 'fila menos uno'.",
  ["A grid is a graph: each cell has four neighbours. Flood fill: stop off the map or on water, sink the cell, recurse four ways. Count one island per unsunk land cell in the double loop."] = "Una cuadrícula es un grafo: cada celda tiene cuatro vecinos. Relleno por inundación: detente fuera del mapa o en el agua, hunde la celda, recurre en las cuatro direcciones. Cuenta una isla por cada celda de tierra sin hundir en el doble bucle.",
  ["A handful of index variables, however long the Vec. Constant."] = "Un puñado de variables índice, por largo que sea el Vec. Constante.",
  ["A handful of index variables, however long the list. Constant."] = "Un puñado de variables índice, por larga que sea la lista. Constante.",
  ["A handful of index variables, however long the slice. Constant."] = "Un puñado de variables índice, por largo que sea el slice. Constante.",
  ["A heap is a list whose front is its root. The front index."] = "Un heap es una lista cuyo frente es su raíz. El índice del frente.",
  ["A heap of size k, Mei. Rust's is a max-heap, so you'll need the little wrapper that flips it."] = "Un heap de tamaño k, Mei. El de Rust es un max-heap, así que necesitarás el pequeño wrapper que le da la vuelta.",
  ["A heap pointer to a dyn trait: Box, angle brackets, dyn, the trait."] = "Un puntero al heap hacia un dyn trait: Box, ángulos, dyn, el trait.",
  ["A helper inside the class that needs neither self nor the class. Which decorator?"] = "Un ayudante dentro de la clase que no necesita ni self ni la clase. ¿Qué decorador?",
  ["A hit: the key was just used, so it becomes the newest. Which OrderedDict method?"] = "Un acierto: la clave se acaba de usar, así que pasa a ser la más nueva. ¿Qué método de OrderedDict?",
  ["A linear scan. Found early is lucky; Big O counts the worst case, n. A HashSet<String> makes it O(1)."] = "Un barrido lineal. Encontrarlo pronto es suerte; Big O cuenta el peor caso, n. Un HashSet<String> lo vuelve O(1).",
  ["A linear scan. Found early is lucky; Big O counts the worst case, n. A map[string]bool makes it O(1)."] = "Un barrido lineal. Encontrarlo pronto es suerte; Big O cuenta el peor caso, n. Un map[string]bool lo vuelve O(1).",
  ["A list grows with append and shrinks with pop. len counts. a[1:3] slices, a[-1] is the last item. [f(x) for x in a] builds a new list. sorted returns a new list."] = "Una lista crece con append y encoge con pop. len cuenta. a[1:3] rebana, a[-1] es el último elemento. [f(x) for x in a] construye una lista nueva. sorted devuelve una lista nueva.",
  ["A list is Option<Box<ListNode>>. take() moves a node out and leaves None. Reverse with prev and cur; slow and fast runners find the middle."] = "Una lista es Option<Box<ListNode>>. take() saca un nodo y deja None. Invierte con prev y cur; los corredores slow y fast encuentran el medio.",
  ["A list is a stack: append pushes, pop takes the top, st[-1] peeks. Openers go on, closers must match the top. A second list of running minimums makes a min stack."] = "Una lista es una pila: append apila, pop saca el tope, st[-1] mira sin sacar. Las aperturas entran, los cierres deben coincidir con el tope. Una segunda lista de mínimos acumulados hace una min stack.",
  ["A list is not an iterator; get one from it. Which built-in?"] = "Una lista no es un iterador; obtén uno de ella. ¿Qué función integrada?",
  ["A list of order names. Which built-in generic, lowercase since 3.9?"] = "Una lista de nombres de pedidos. ¿Qué genérico integrado, en minúsculas desde 3.9?",
  ["A list of the dishes on the board, just the names. Which method?"] = "Una lista de los platos de la carta, solo los nombres. ¿Qué método?",
  ["A loop over n guests inside a loop over m tables. The two sizes differ. Cost?"] = "Un bucle sobre n invitados dentro de un bucle sobre m mesas. Los dos tamaños difieren. ¿Coste?",
  ["A loop over n guests inside a loop over the same n guests. Cost, in Big O?"] = "Un bucle sobre n invitados dentro de un bucle sobre los mismos n invitados. ¿Coste, en Big O?",
  ["A loop that returns a value? Go cannot do that."] = "¿Un bucle que devuelve un valor? Go no puede hacer eso.",
  ["A major.minor like 1.23. Since Go 1.21 it is a real floor: an older toolchain will fetch a newer one."] = "Un major.minor como 1.23. Desde Go 1.21 es un suelo real: una toolchain vieja descargará una más nueva.",
  ["A map built on hashing, CapWords. A Vec of pairs would need a scan, O(n)."] = "Un map construido sobre hashing, en CapWords. Un Vec de pares necesitaría un barrido, O(n).",
  ["A map entry pointing at a removed node is a bug waiting: the map and the list must always agree."] = "Una entrada del map que apunta a un nodo eliminado es un bug en espera: el map y la lista deben coincidir siempre.",
  ["A map finds it, a list remembers the order. Two structures that agree."] = "Un map lo encuentra, una lista recuerda el orden. Dos estructuras que se ponen de acuerdo.",
  ['A map from string to int. Fill the type: prices := ___{"muffin": 18}'] = 'Un map de string a int. Completa el tipo: prices := ___{"muffin": 18}',
  ["A map is a hash table. comma-ok tells you if the key was there. delete removes it."] = "Un map es una tabla hash. comma-ok te dice si la clave estaba. delete la quita.",
  ["A map of last positions lets the left edge jump instead of creeping one step at a time."] = "Un map de últimas posiciones deja que el borde izquierdo salte en vez de avanzar paso a paso.",
  ["A map turns 'does this closer match?' into one lookup. Openers are the values, closers the keys."] = "Un map convierte '¿coincide este cierre?' en una sola búsqueda. Las aperturas son los valores, los cierres las claves.",
  ["A map turns O(n^2) two-sum into O(n). Two pointers check a palindrome. A [26]int counts letters."] = "Un map convierte two-sum de O(n^2) en O(n). Dos punteros comprueban un palíndromo. Un [26]int cuenta letras.",
  ["A match guard does the test. With < instead, (1,3) and (3,5) would stay apart; ask the interviewer which they want."] = "Un match guard hace la prueba. Con < en su lugar, (1,3) y (3,5) quedarían separados; pregunta al entrevistador cuál quiere.",
  ["A method on context.Context. Its channel closes on cancel."] = "Un método de context.Context. Su channel se cierra al cancelar.",
  ["A method that changes the order needs a pointer receiver. Fill: func (o ___) Add(p int)"] = "Un método que cambia el pedido necesita un receptor puntero. Completa: func (o ___) Add(p int)",
  ["A min stack answers the minimum in O(1). Each push also records the smaller of x and the old low. Which built-in?"] = "Una min stack responde el mínimo en O(1). Cada push guarda también el menor entre x y el mínimo anterior. ¿Qué función integrada?",
  ["A min stack answers the minimum in O(1): a second slice keeps the running minimum. What is pushed onto low?"] = "Un min stack responde el mínimo en O(1): un segundo slice guarda el mínimo acumulado. ¿Qué se apila en low?",
  ["A miss: compute it from the two smaller ones. Fill the second call: fib(___, memo)"] = "Un fallo: calcúlalo a partir de los dos menores. Completa la segunda llamada: fib(___, memo)",
  ["A module is a tree of packages with one go.mod at its root. go mod init names it, and that name is the prefix of every import path inside it, so name it after the repo: github.com/you/project. The go directive is the minimum toolchain. Modules have been the only mode since Go 1.16; GOPATH is history."] = "Un módulo es un árbol de paquetes con un único go.mod en su raíz. go mod init le da nombre, y ese nombre es el prefijo de toda ruta de importación dentro de él, así que llámalo como el repositorio: github.com/you/project. La directiva go es la toolchain mínima. Los módulos son el único modo desde Go 1.16; GOPATH es historia.",
  ["A move. Integers are Copy and stay valid; a String is moved and the old name dies. No double free, ever."] = "Un move. Los enteros son Copy y siguen válidos; un String se mueve y el nombre viejo muere. Nunca hay double free.",
  ["A mutex for a single int is a lot of ceremony for one number."] = "Un mutex para un solo int es mucha ceremonia para un número.",
  ["A name that cannot be assigned later. Which keyword?"] = "Un nombre que no se puede reasignar después. ¿Qué palabra clave?",
  ["A new neighbour: mark it seen when you enqueue it. Which set method?"] = "Una vecina nueva: márcala como vista al encolarla. ¿Qué método de set?",
  ["A nil *Order stored in an interface. Is the interface == nil? It prints ___"] = "Un *Order nil guardado en una interface. ¿La interface == nil? Imprime ___",
  ["A nil map panics when you write to it. Allocate one: floors = ___(map[string]int)"] = "Un map nil hace panic al escribir en él. Reserva uno: floors = ___(map[string]int)",
  ["A node points at two children of its own type. Fill the field type: Left, Right ___"] = "Un nodo apunta a dos hijos de su propio tipo. Completa el tipo del campo: Left, Right ___",
  ["A phone book: open the middle, decide left or right, throw half away. Again."] = "Una guía telefónica: abre por el medio, decide izquierda o derecha, tira la mitad. Otra vez.",
  ["A pipe that carries string. Fill: ch := make(___)"] = "Una tubería que lleva string. Completa: ch := make(___)",
  ["A pointer receiver: a star before the type name."] = "Un receptor puntero: un asterisco antes del nombre del tipo.",
  ["A pointer to Order. Fill the type of p: var p ___Order"] = "Un puntero a Order. Completa el tipo de p: var p ___Order",
  ["A pointer to the node type of container/list."] = "Un puntero al tipo de nodo de container/list.",
  ["A pointer, or the struct would contain itself forever. Star then the type."] = "Un puntero, o el struct se contendría a sí mismo para siempre. Asterisco y luego el tipo.",
  ["A range with two dots, like Go's [1:3]."] = "Un rango con dos puntos seguidos, como el [1:3] de Go.",
  ["A receive-only parameter makes the compiler enforce the direction: a worker that tries to send on jobs will not build."] = "Un parámetro de solo recepción hace que el compilador imponga la dirección: un worker que intente enviar por jobs no compila.",
  ["A recursive def needs a base case and a smaller call. A dict memo or @functools.cache turns fib from 2^n into n."] = "Un def recursivo necesita un caso base y una llamada más pequeña. Un memo en un dict o @functools.cache convierte fib de 2^n en n.",
  ["A recursive fn needs a base case and a smaller call. A HashMap memo turns fib from 2^n into n."] = "Una fn recursiva necesita un caso base y una llamada más pequeña. Un memo con HashMap convierte fib de 2^n en n.",
  ["A recursive func needs a base case and a smaller call. A memo map turns fib from 2^n into n."] = "Una func recursiva necesita un caso base y una llamada más pequeña. Un map memo convierte fib de 2^n en n.",
  ["A reference must not outlive what it points at. 'a names how long; 'static means the whole program."] = "Una referencia no debe vivir más que aquello a lo que apunta. 'a nombra cuánto; 'static significa todo el programa.",
  ["A repo grows a shape: cmd/<name>/main.go per binary, internal/ for packages the compiler refuses to let outsiders import, a doc comment on every package, and menu_test.go in package menu_test so the tests use the package the way a caller would."] = "Un repo va tomando forma: cmd/<name>/main.go por binario, internal/ para los paquetes que el compilador no deja importar a extraños, un comentario de documentación en cada paquete, y menu_test.go en package menu_test para que las pruebas usen el paquete como lo haría quien lo llama.",
  ["A room frees up when this start is not before the earliest end."] = "Una sala se libera cuando este inicio no es anterior al fin más temprano.",
  ["A seat number that may not exist. Which type wraps a value that can be missing?"] = "Un número de asiento que puede no existir. ¿Qué tipo envuelve un valor que puede faltar?",
  ["A second test after an if. Which keyword is Python's 'else if'?"] = "Una segunda prueba tras un if. ¿Cuál es la palabra clave de Python para 'else if'?",
  ["A sentinel error value the whole package can compare against. Fill: errors.___"] = "Un valor de error centinela con el que todo el paquete puede comparar. Completa: errors.___",
  ["A sentinel infinity. math.MaxInt would overflow the moment you add 1 to it."] = "Un infinito centinela. math.MaxInt se desbordaría en cuanto le sumaras 1.",
  ["A set answers 'seen?' in O(1). A list would make BFS O(n^2)."] = "Un set responde '¿visto?' en O(1). Una lista haría a BFS O(n^2).",
  ["A set built on hashing, CapWords, in std::collections. insert returns false when the value was already in."] = "Un set construido sobre hashing, en CapWords, en std::collections. insert devuelve false cuando el valor ya estaba dentro.",
  ["A set of methods, no fields. Which keyword?"] = "Un conjunto de métodos, sin campos. ¿Qué palabra clave?",
  ["A set of seen stations. Fill the value type: map[string]___"] = "Un conjunto de estaciones vistas. Completa el tipo del valor: map[string]___",
  ["A size is Small or Large and nothing else. Which keyword lists the variants?"] = "Un tamaño es Small o Large y nada más. ¿Qué palabra clave lista las variantes?",
  ["A slice is Go's stack: this pushes, st[:len(st)-1] pops. Both O(1), amortized."] = "Un slice es la pila de Go: esto apila, st[:len(st)-1] desapila. Ambos O(1), amortizado.",
  ["A slice is a stack: append pushes, st[:len(st)-1] pops. Push every opener, match every closer against the top, valid when the stack ends empty. A min stack keeps a second stack of running minimums."] = "Un slice es una pila: append apila, st[:len(st)-1] desapila. Apila cada apertura, empareja cada cierre con la cima, válido cuando la pila acaba vacía. Un min stack guarda una segunda pila con los mínimos acumulados.",
  ["A slice is a view: pointer, len, cap. append may grow it. len is the length."] = "Un slice es una vista: puntero, len, cap. append puede agrandarlo. len es la longitud.",
  ["A slice is a window, not a copy. Both look at the same memory."] = "Un slice es una ventana, no una copia. Ambos miran la misma memoria.",
  ["A slice of int, not a fixed array. Fill the type: s := ___{1, 2, 3}"] = "Un slice de int, no un array fijo. Completa el tipo: s := ___{1, 2, 3}",
  ["A sorted copy of the prices, leaving the original as it is. Which built-in?"] = "Una copia ordenada de los precios, dejando el original como está. ¿Qué función integrada?",
  ["A sorted copy, leaving the original untouched, needs a second Vec. Extra space: O(___)"] = "Una copia ordenada, dejando el original intacto, necesita un segundo Vec. Espacio extra: O(___)",
  ["A sorted copy, leaving the original untouched, needs a second list. Extra space: O(___)"] = "Una copia ordenada, dejando el original intacto, necesita una segunda lista. Espacio extra: O(___)",
  ["A sorted copy, leaving the original untouched, needs a second slice. Extra space: O(___)"] = "Una copia ordenada, dejando el original intacto, necesita un segundo slice. Espacio extra: O(___)",
  ["A stack that also reports its smallest value in O(1). Push keeps a second stack of the smallest so far. Which i32 method picks the smaller of x and m?"] = "Una pila que además da su valor mínimo en O(1). push mantiene una segunda pila con el mínimo hasta ahora. ¿Qué método de i32 elige el menor entre x y m?",
  ["A star, then the name the body uses. Inside, it is a tuple."] = "Un asterisco, y luego el nombre que usa el cuerpo. Dentro es una tupla.",
  ["A struct, so it comes as a pointer. r.Method, r.URL, r.Body."] = "Un struct, así que llega como puntero. r.Method, r.URL, r.Body.",
  ["A switch with no condition is Go's if-else chain. sort.SearchInts does this for you."] = "Un switch sin condición es la cadena if-else de Go. sort.SearchInts lo hace por ti.",
  ["A sync.Mutex is usable at its zero value. Lock, then defer Unlock. Never copy a struct that holds one: go vet calls that passing a lock by value. sync.RWMutex lets many readers in at once with RLock, and TryLock returns instead of waiting."] = "Un sync.Mutex sirve tal cual, con su valor cero. Lock y luego defer Unlock. Nunca copies un struct que lo contenga: go vet lo llama pasar un lock por valor. sync.RWMutex deja entrar a muchos lectores a la vez con RLock, y TryLock vuelve en lugar de esperar.",
  ["A test function in order_test.go. Fill the name prefix: func ___(t *testing.T)"] = "Una función de test en order_test.go. Completa el prefijo del nombre: func ___(t *testing.T)",
  ["A thin arrow, minus then greater-than. Go writes nothing there."] = "Una flecha fina, menos y luego mayor que. Go no escribe nada ahí.",
  ["A thing that counts, capitalized. It is a dict subclass with 0 for missing keys."] = "Algo que cuenta, con mayúscula. Es una subclase de dict con 0 para las claves ausentes.",
  ["A thread-safe queue of orders. Which class from the queue module?"] = "Una cola de pedidos segura entre hilos. ¿Qué clase del módulo queue?",
  ["A tick and an underscore: the anonymous lifetime."] = "Un apóstrofo y un guion bajo: el lifetime anónimo.",
  ["A tick and one letter, the same as both inputs."] = "Un apóstrofo y una letra, la misma que ambas entradas.",
  ["A tick and the word for something that never moves."] = "Un apóstrofo y la palabra para algo que nunca se mueve (static).",
  ["A timeout is a deadline computed from now. It is inherited: a child can be stricter than its parent, never looser."] = "Un timeout es un plazo calculado desde ahora. Se hereda: un hijo puede ser más estricto que su padre, nunca más laxo.",
  ["A trait is a set of methods. impl Trait for Type promises them; dyn Trait picks at run time."] = "Un trait es un conjunto de métodos. impl Trait for Tipo los promete; dyn Trait elige en tiempo de ejecución.",
  ["A tree node holds *Node children. insert recurses left or right until nil. height is 1 + max of both sides."] = "Un nodo del árbol tiene hijos *Node. insert recurre a izquierda o derecha hasta nil. height es 1 + max de ambos lados.",
  ["A tree node owns Option<Box<Node>> children. insert recurses left or right until None. height is 1 + max of both sides."] = "Un nodo del árbol posee hijos Option<Box<Node>>. insert recursa a izquierda o derecha hasta None. height es 1 + max de ambos lados.",
  ["A tuple struct with one field whose Ord is the other way round. Same word as the iterator's rev, spelled out."] = "Un tuple struct con un campo cuyo Ord va al revés. La misma palabra que el rev del iterador, sin abreviar.",
  ["A type parameter that accepts anything. Fill: func ident[T ___](v T) T"] = "Un parámetro de tipo que acepta cualquier cosa. Completa: func ident[T ___](v T) T",
  ["A value receiver copies the struct, mutex and all, and locks the copy. Point at the original."] = "Un receptor por valor copia el struct entero, mutex incluido, y bloquea la copia. Apunta al original.",
  ["A view of the 2nd and 3rd items only (index 1 and 2). Fill: two := tray[___]"] = "Una vista solo del 2.º y 3.º elemento (índices 1 y 2). Completa: two := tray[___]",
  ["A worker only reads jobs. Which channel type says so in the signature?"] = "Un worker solo lee jobs. ¿Qué tipo de channel lo dice en la firma?",
  ["A worker pool with queue.Queue"] = "Un pool de workers con queue.Queue",
  ["A worker runs until the jobs channel closes. Fill: for j := ___ jobs"] = "Un worker corre hasta que el channel jobs se cierra. Completa: for j := ___ jobs",
  ["ADVANCED  -  the back office"] = "ADVANCED  -  la oficina trasera",
  ["ADVANCED  -  the kitchen"] = "ADVANCED  -  la cocina",
  ["ANSWER"] = "RESPUESTA",
  ["ARROWS walk    ENTER go    1-7 jump    Q quest    TAB Go/Rust    %s"] = "FLECHAS andar    ENTER ir    1-7 saltar    Q misión    TAB Go/Rust    %s",
  ["ARROWS walk    ENTER go    1-7 jump    Q quest    TAB language    %s"] = "FLECHAS andar    ENTER entrar    1-7 saltar    Q misión    TAB lenguaje    %s",
  ["ASCII letters take one byte; CJK characters take three."] = "Las letras ASCII ocupan un byte; los caracteres CJK, tres.",
  ["ASCII to integer. The line below goes the other way."] = "ASCII a entero. La línea de abajo va en sentido contrario.",
  ["AUTO"] = "AUTO",
  ["Able to be turned into bytes by the pickle module. The adjective."] = "Que el módulo pickle pueda convertirlo en bytes. El adjetivo.",
  ["Actually run the Future and get the u32 out. What goes after the call?"] = "Ejecuta de verdad el Future y saca el u32. ¿Qué va después de la llamada?",
  ["Add 18 to the end of the orders list. Which method?"] = "Añade 18 al final de la lista de pedidos. ¿Qué método?",
  ["Add a dependency at an exact version. Which subcommand?"] = "Añade una dependencia en una versión exacta. ¿Qué subcomando?",
  ["Add a third module to the workspace by hand. Which go.work directive lists a folder?"] = "Añade un tercer módulo al espacio de trabajo a mano. ¿Qué directiva de go.work lista una carpeta?",
  ["Add a tray to the end of the list. Which method?"] = "Añadir una bandeja al final de la lista. ¿Qué método?",
  ["Add before go, Done inside, Wait after. Never Add inside the goroutine."] = "Add antes de go, Done dentro, Wait después. Nunca Add dentro de la goroutine.",
  ["Add before the go statement, Done deferred inside it, Wait after the loop. Add inside the goroutine is the classic race."] = "Add antes del go, Done con defer dentro y Wait después del bucle. Hacer Add dentro de la goroutine es la carrera clásica.",
  ["Add before you go. Done in the goroutine. Wait in main."] = "Add antes del go. Done en la goroutine. Wait en main.",
  ["Add every price together through an iterator. Which method finishes the chain?"] = "Suma todos los precios a través de un iterador. ¿Qué método cierra la cadena?",
  ["Add missing dependencies and drop unused ones. Fill: go mod ___"] = "Añade dependencias que faltan y quita las no usadas. Completa: go mod ___",
  ["Add one to count, in place: the augmented assignment."] = "Suma uno a count, en el sitio: la asignación aumentada.",
  ["Add one to the served count with no lock at all. Which atomic method?"] = "Suma uno al contador de servidos sin ningún lock. ¿Qué método atómico?",
  ["Add the order number but keep the cause inside. Which verb wraps?"] = "Añade el número de pedido pero conserva la causa dentro. ¿Qué verbo envuelve?",
  ["Add to the end of out. A list, not a tuple, so the end can still be extended later."] = "Agrega al final de out. Una lista, no una tupla, para que el final aún pueda extenderse después.",
  ["Add up the bill in one call. Which method?"] = "Suma la cuenta en una sola llamada. ¿Qué método?",
  ["Adding an edge to a station with no list yet. Which entry method starts an empty Vec on demand?"] = "Añadir una arista a una estación que aún no tiene lista. ¿Qué método de entry crea un Vec vacío a demanda?",
  ["Adjacency list: HashMap<u32, Vec<u32>>. BFS uses a VecDeque and pop_front, DFS a Vec and pop. A HashSet remembers visits."] = "Lista de adyacencia: HashMap<u32, Vec<u32>>. BFS usa un VecDeque y pop_front, DFS un Vec y pop. Un HashSet recuerda las visitas.",
  ["After breakfast, Lucky Mac wants a delivery app by the lunch rush. Ship it in Go."] = "Tras el desayuno, Lucky Mac quiere una app de reparto para la hora punta. Entrégala en Go.",
  ["After decorating, fry.__name__ says 'wrapper'. Which functools decorator keeps the original name and docstring?"] = "Tras decorar, fry.__name__ dice 'wrapper'. ¿Qué decorador de functools conserva el nombre y el docstring originales?",
  ["After flipping, move on: prev becomes cur, and cur becomes the saved node. Fill it."] = "Tras girar, avanzar: prev pasa a ser cur, y cur pasa a ser el nodo guardado. Complétalo.",
  ["After frying, tell the queue this job is finished so join can count it. Which method?"] = "Tras freír, decirle a la cola que este trabajo está terminado para que join pueda contarlo. ¿Qué método?",
  ["After let b = a; the name a is invalid. What did the String do?"] = "Tras let b = a; el nombre a ya no es válido. ¿Qué hizo el String?",
  ["After the loop append the leftovers: out = append(out, l[i:]...) and r[j:]..."] = "Tras el bucle añade los restos: out = append(out, l[i:]...) y r[j:]...",
  ["After the loop the heap holds the k biggest and the smallest of them is on top: the kth largest. Which method reads the top without removing it?"] = "Tras el bucle el heap guarda los k mayores y el menor de ellos está en la cima: el k-ésimo mayor. ¿Qué método lee la cima sin quitarla?",
  ["After the loop, k items remain and the kth largest is the smallest of them. Which index holds it?"] = "Tras el bucle quedan k elementos y el k-ésimo mayor es el menor de ellos. ¿Qué índice lo guarda?",
  ["After the loop, what makes the string valid? Every opener found its closer, so the stack is what?"] = "Tras el bucle, ¿qué hace válida la cadena? Cada apertura encontró su cierre, ¿así que cómo queda la pila?",
  ["Alex"] = "Alex",
  ["Alias for interface{}. The constraint that allows every type."] = "Alias de interface{}. La restricción que permite todo tipo.",
  ["Allocate a slice with length 0 and room for 8. Which built-in?"] = "Reserva un slice con longitud 0 y espacio para 8. ¿Qué función integrada?",
  ["Always assign the result back. It may allocate a new backing array."] = "Asigna siempre el resultado de vuelta. Puede reservar un nuevo array subyacente.",
  ["Ampersand and the string slice type. Elision fills in the rest."] = "Ampersand y el tipo string slice. La elisión rellena el resto.",
  ["Ampersand. & takes an address, * reads through one."] = "Ampersand. & toma una dirección, * lee a través de una.",
  ["An LRU cache"] = "Una caché LRU",
  ["An LRU cache with OrderedDict"] = "Una caché LRU con OrderedDict",
  ["An adjacency list: each station id maps to the ids one hop away. What holds the list of neighbours?"] = "Una lista de adyacencia: cada id de estación mapea a los ids a un salto. ¿Qué guarda la lista de vecinos?",
  ["An alternative constructor: Order.from_line('2 x egg'). Which decorator passes the class instead of an instance?"] = "Un constructor alternativo: Order.from_line('2 x egg'). ¿Qué decorador pasa la clase en vez de una instancia?",
  ["An ampersand and the word the body already uses to reach qty."] = "Un ampersand y la palabra que el cuerpo ya usa para llegar a qty.",
  ["An ampersand and three letters: the borrowed string slice."] = "Un ampersand y tres letras: el string slice prestado.",
  ["An arrow pointing out of the channel, then the channel's name. Two characters and three."] = "Una flecha que sale del channel y luego el nombre del channel. Dos caracteres y tres.",
  ["An asyncio server must not block on a resize. Which loop method hands it to the pool?"] = "Un servidor asyncio no debe bloquearse reduciendo una imagen. ¿Qué método del loop se lo pasa al pool?",
  ["An empty stack on a closer is a failure too: ')(' must not pass. Then pop by reslicing."] = "Una pila vacía ante un cierre también es un fallo: ')(' no debe pasar. Luego desapila recortando el slice.",
  ["An empty struct. Zero size. The idiom for 'just a signal'."] = "Un struct vacío. Tamaño cero. La forma idiomática de 'solo una señal'.",
  ["An empty tray, all fields zero, without typing them. Which call?"] = "Una bandeja vacía, todos los campos a cero, sin escribirlos. ¿Qué llamada?",
  ["An existing key is a touch, not an eviction: get(k) moves it to the back and the len check is skipped."] = "Una clave existente es un toque, no una expulsión: get(k) la mueve al final y se salta la comprobación de len.",
  ["An import path that starts with a host is fetched from that host: go get github.com/x/y@v1.2.3 downloads the tagged commit into the module cache, adds a require line to go.mod and a hash to go.sum. // indirect marks a dependency of a dependency. Nothing is copied into your repo; everything is reproducible from the two files."] = "Una ruta de importación que empieza por un host se descarga de ese host: go get github.com/x/y@v1.2.3 baja el commit etiquetado a la caché de módulos, añade una línea require a go.mod y un hash a go.sum. // indirect marca una dependencia de una dependencia. Nada se copia en tu repo; todo es reproducible a partir de los dos ficheros.",
  ["An interface is (type, value). The type *Order is set, so it is not the nil interface."] = "Una interface es (tipo, valor). El tipo *Order está fijado, así que no es la interface nil.",
  ["An opener goes onto the stack. Which builtin grows the slice?"] = "Una apertura va a la pila. ¿Qué función integrada agranda el slice?",
  ["An opener waits for its closer on the stack. Which list method puts c on top?"] = "Una apertura espera a su cierre en la pila. ¿Qué método de lista pone c en el tope?",
  ["An opener waits for its partner. Which Vec method puts c on top of the stack?"] = "Una apertura espera a su pareja. ¿Qué método de Vec pone c en la cima de la pila?",
  ["An unbuffered send needs a receiver already waiting. Put the send in a goroutine or buffer the channel."] = "Un envío sin búfer necesita un receptor ya esperando. Pon el envío en una goroutine o dale búfer al channel.",
  ["An underscore and four letters, the same suffix the file name carries. The only case of two packages in one directory."] = "Un guion bajo y cuatro letras, el mismo sufijo que lleva el nombre del fichero. El único caso de dos paquetes en un directorio.",
  ["Anagram: same letters, same counts. Lowercase ASCII only. How many slots does the counter array need?"] = "Anagrama: mismas letras, mismos conteos. Solo ASCII en minúsculas. ¿Cuántas casillas necesita el array contador?",
  ["And on the way out, error or not. Which method closes the file?"] = "Y al salir, con error o sin él. ¿Qué método cierra el archivo?",
  ["And the compiler says my price function does not exist, even though it is right there."] = "Y el compilador dice que mi función price no existe, aunque está ahí mismo.",
  ["And the log n is how many times you can halve. Levels times work per level."] = "Y el log n es cuántas veces puedes partir a la mitad. Niveles por trabajo por nivel.",
  ["And the size is an enum. Small or Large, nothing in between, the compiler makes sure."] = "Y el tamaño es un enum. Small o Large, nada en medio, el compilador se asegura.",
  ["Angle brackets around the lifetime, like a generic parameter."] = "Ángulos alrededor del lifetime, como un parámetro genérico.",
  ["Any Cook, chosen at run time, behind a reference. Which keyword?"] = "Cualquier Cook, elegido en ejecución, tras una referencia. ¿Qué palabra clave?",
  ["Any type with one method is an error. Which method?"] = "Cualquier tipo con un método es un error. ¿Qué método?",
  ["Anything under internal/ can be imported only by code rooted at internal's parent. The cousin's shop gets a compile error, and you keep the right to delete."] = "Todo lo que hay bajo internal/ solo puede importarlo código con raíz en el padre de internal. La tienda del primo recibe un error de compilación y tú conservas el derecho a borrar.",
  ["Append a &str to the end of a mutable String. Which method?"] = "Añade un &str al final de un String mutable. ¿Qué método?",
  ["Apply the timer wrapper to fry without changing its body. Which character goes before timer?"] = "Aplicar la envoltura timer a fry sin cambiar su cuerpo. ¿Qué carácter va delante de timer?",
  ["Arc shares ownership across threads; Mutex guards changes; atomics count without a lock."] = "Arc comparte el ownership entre threads; Mutex protege los cambios; los atómicos cuentan sin lock.",
  ["Arc, Mutex and atomics"] = "Arc, Mutex y atómicos",
  ["Arc::clone(&sold) bumps the count, never copies the data. Same as sold.clone(), but the full path shows it is cheap."] = "Arc::clone(&sold) sube el contador, nunca copia los datos. Igual que sold.clone(), pero la ruta completa muestra que es barato.",
  ["Arc<Mutex<Receiver<Job>>> is Send + Sync, so it can be moved into every worker. The rail is shared, the pull is exclusive."] = "Arc<Mutex<Receiver<Job>>> es Send + Sync, así que puede moverse a cada worker. El riel se comparte, la extracción es exclusiva.",
  ["Arc<Mutex<T>> is the shared-and-mutable idiom. Arc shares, Mutex guards; neither alone is enough."] = "Arc<Mutex<T>> es el idioma de compartido y mutable. Arc comparte, Mutex protege; ninguno basta por sí solo.",
  ["Arc<T> counts references atomically, so clones may live on different threads. Rc is cheaper but not Send."] = "Arc<T> cuenta referencias de forma atómica, así que los clones pueden vivir en threads distintos. Rc es más barato pero no es Send.",
  ["Arrays, slices, append"] = "Arrays, slices, append",
  ["Arrow pointing at the channel. Receive is the same arrow on the left of =."] = "Flecha apuntando al channel. Recibir es la misma flecha a la izquierda del =.",
  ["Arrow then chan. chan<- string would be send-only."] = "Flecha y luego chan. chan<- string sería solo envío.",
  ["As many new ints as there are old ones. Linear, without the O( )."] = "Tantos ints nuevos como viejos hay. Lineal, sin el O( ).",
  ["As many new slots as there are old ones. Linear, without the O( )."] = "Tantas ranuras nuevas como viejas hay. Lineal, sin el O( ).",
  ["Ascending: i goes before j when its start is smaller."] = "Ascendente: i va antes que j cuando su inicio es menor.",
  ["Ask all three riders at once and collect the answers. Which asyncio function?"] = "Preguntar a los tres repartidores a la vez y recoger las respuestas. ¿Qué función de asyncio?",
  ["Ask for warnings about non-idiomatic code. Which subcommand?"] = "Pide avisos sobre código poco idiomático. ¿Qué subcomando?",
  ["Ask the compiler to write Clone and Debug for Order. Which attribute?"] = "Pide al compilador que escriba Clone y Debug para Order. ¿Qué atributo?",
  ["Ask the tool chain to find data races at run time. Fill the flag: go test ___ ./..."] = "Pide a la cadena de herramientas que busque data races en ejecución. Completa el flag: go test ___ ./...",
  ["Ask your AI: why is `%s` the answer here, and what breaks with anything else?"] = "Pregunta a tu IA: ¿por qué `%s` es la respuesta aquí, y qué se rompe con cualquier otra cosa?",
  ["Assigning e alone is the classic bug: [1, 10] then [2, 3] would end at 3."] = "Asignar e a secas es el bug clásico: [1, 10] y luego [2, 3] terminaría en 3.",
  ["Async in Go: a goroutine and a channel"] = "Async en Go: una goroutine y un channel",
  ["AsyncResult.get() blocks and re-raises whatever the worker raised. apply_async plus get is exactly go plus <-ch."] = "AsyncResult.get() bloquea y vuelve a lanzar lo que lanzara el worker. apply_async más get es exactamente go más <-ch.",
  ["At most 3 requests in flight: a semaphore from a buffered channel. Fill: make(chan struct{}, ___)"] = "Como máximo 3 peticiones en vuelo: un semáforo con un channel con buffer. Completa: make(chan struct{}, ___)",
  ["Atomics and sync.Once"] = "Atómicos y sync.Once",
  ["Await is a receive with a nicer name. Go left it out of the language because a generic type and one operator are enough."] = "Await es una recepción con un nombre más bonito. Go lo dejó fuera del lenguaje porque un tipo genérico y un operador bastan.",
  ["BACK"] = "ATRÁS",
  ["BADGE  %s"] = "INSIGNIA  %s",
  ["BADGES"] = "INSIGNIAS",
  ["BFS and DFS"] = "BFS y DFS",
  ["BFS and DFS on the MTR"] = "BFS y DFS en el MTR",
  ["BFS explores outward in rings: everything one stop away, then two. The first path found is the shortest."] = "BFS explora hacia fuera en anillos: todo a una parada, luego a dos. El primer camino encontrado es el más corto.",
  ["BFS: a slice as a queue, pop the front with q[1:]. DFS: recursion plus a visited map."] = "BFS: un slice como cola, saca el frente con q[1:]. DFS: recursión más un map de visitados.",
  ["BIG O  -  how fast is it"] = "BIG O  -  qué tan rápido es",
  ["BIG O  ·  the Go round"] = "BIG O  ·  la ronda de Go",
  ["BIG O  ·  the Python round"] = "BIG O  ·  la ronda de Python",
  ["BIG O  ·  the Rust round"] = "BIG O  ·  la ronda de Rust",
  ["BIG O MASTER"] = "MAESTRO DE BIG O",
  ["BST invariant: left < node <= right. Average insert is O(log n)."] = "Invariante del BST: izquierda < nodo <= derecha. La inserción media es O(log n).",
  ["BST rule: everything smaller is in the left subtree. &mut n.left reborrows the child for the recursive call."] = "Regla del BST: todo lo menor está en el subárbol izquierdo. &mut n.left vuelve a prestar el hijo para la llamada recursiva.",
  ["Bake menu.json into the binary at compile time. Fill the directive: //go:___"] = "Incrusta menu.json en el binario al compilar. Completa la directiva: //go:___",
  ["Base case first, always. Without it Python raises RecursionError at depth 1000."] = "Caso base primero, siempre. Sin él Python lanza RecursionError a profundidad 1000.",
  ["Base case first, always. Without it the stack overflows."] = "El caso base primero, siempre. Sin él, la pila se desborda.",
  ["Base case first, always. Without it the stack overflows. No semicolon: the if is the return value."] = "Primero el caso base, siempre. Sin él la pila desborda. Sin punto y coma: el if es el valor de retorno.",
  ["Base cases seed the table. From here every entry is built from the two before it."] = "Los casos base siembran la tabla. Desde aquí cada entrada se construye con las dos anteriores.",
  ["Base cases seed the table. dp[0] = 1 is the empty climb; without it dp[2] would be wrong."] = "Los casos base siembran la tabla. dp[0] = 1 es la subida vacía; sin él dp[2] saldría mal.",
  ["Because every Go function is already the async one. There is no second colour of function to await."] = "Porque toda función de Go ya es la asíncrona. No hay un segundo color de función al que esperar.",
  ["Before the dinner rush, rewrite the delivery backend in Rust. Ship it."] = "Antes de la hora punta de la cena, reescribe el backend de reparto en Rust. Entrégalo.",
  ["Before the morning van"] = "Antes de la furgoneta de la mañana",
  ["Benchmark* takes *testing.B and loops b.N times. Go 1.24 adds b.Loop()."] = "Benchmark* recibe *testing.B e itera b.N veces. Go 1.24 añade b.Loop().",
  ["Best k hours in a row: slide a window of size k. One element enters, which one leaves?"] = "Las mejores k horas seguidas: desliza una ventana de tamaño k. Un elemento entra, ¿cuál sale?",
  ["Best subarray sum: at each x, either extend the current run or start fresh at x. Which method picks the larger?"] = "Mejor suma de subarray: en cada x, o extiendes la racha actual o empiezas de nuevo en x. ¿Qué método elige el mayor?",
  ["Big O is one question: when the input doubles, what happens to the work?"] = "Big O es una sola pregunta: cuando la entrada se duplica, ¿qué pasa con el trabajo?",
  ["Binary search and merge sort"] = "Búsqueda binaria y merge sort",
  ["Binary search checks the middle of lo..hi. Which operator finds the midpoint index?"] = "La búsqueda binaria mira el medio de lo..hi. ¿Qué operador encuentra el índice medio?",
  ["Binary search checks the middle of lo..hi. Which operator gives a whole-number midpoint?"] = "La búsqueda binaria mira el medio de lo..hi. ¿Qué operador da un punto medio entero?",
  ["Binary search halves [lo, hi) with mid. Merge sort splits, recurses, and merges two sorted halves."] = "La búsqueda binaria parte [lo, hi) con mid. Merge sort divide, recurre y fusiona dos mitades ordenadas.",
  ["Binary search has one precondition. The slice must be ___"] = "La búsqueda binaria tiene una condición previa. El slice debe estar ___",
  ["Binary search tree"] = "Árbol binario de búsqueda",
  ["Binary search: the target is bigger than a[mid]. Where does lo move?"] = "Búsqueda binaria: el objetivo es mayor que a[mid]. ¿A dónde se mueve lo?",
  ["BinaryHeap implements FromIterator, so collect heapifies in O(n). Then k pops: O(n + k log n)."] = "BinaryHeap implementa FromIterator, así que collect construye el heap en O(n). Luego k pops: O(n + k log n).",
  ["BinaryHeap is a max-heap. Reverse(x) turns it into a min-heap. kth largest: push everything, pop whenever len > k, peek. Top k frequent: count with a HashMap, collect (count, word) into a heap, pop k times."] = "BinaryHeap es un max-heap. Reverse(x) lo convierte en min-heap. k-ésimo mayor: push de todo, pop cuando len > k, peek. Top k frecuentes: cuenta con un HashMap, recoge (count, word) en un heap, pop k veces.",
  ["BinaryHeap: kth largest and top k"] = "BinaryHeap: el k-ésimo mayor y los top k",
  ["Bindings, mutability and types"] = "Bindings, mutabilidad y tipos",
  ["Blocking I/O and NumPy's C loops both drop the GIL, so threads overlap waiting perfectly. Pure Python arithmetic never drops it."] = "La E/S bloqueante y los bucles en C de NumPy sueltan el GIL, así que los hilos solapan la espera a la perfección. La aritmética en Python puro no lo suelta nunca.",
  ["Blocks are indented, no braces. elif chains ifs. for walks anything iterable; range counts. while loops on a condition."] = "Los bloques se indentan, sin llaves. elif encadena ifs. for recorre cualquier iterable; range cuenta. while repite con una condición.",
  ["Blocks until the counter is zero. In its own goroutine so main can keep reading."] = "Bloquea hasta que el contador llega a cero. En su propia goroutine para que main siga leyendo.",
  ["Borrow only the second and third price, indices 1 and 2. What goes in the brackets?"] = "Presta solo el segundo y tercer precio, índices 1 y 2. ¿Qué va entre los corchetes?",
  ["Both tills add to one sold counter and the number is wrong every time."] = "Las dos cajas suman a un mismo contador de ventas y el número sale mal cada vez.",
  ["Bottom-up DP: O(n) time, O(n) table, and two variables would make it O(1) space."] = "DP de abajo arriba: O(n) de tiempo, tabla O(n), y con dos variables sería O(1) de espacio.",
  ["Bottom-up fib: O(n) time, no recursion, and only two cells are ever needed, so O(1) space is possible."] = "fib de abajo arriba: O(n) tiempo, sin recursión, y solo hacen falta dos celdas, así que O(1) espacio es posible.",
  ["Box<Node> is one pointer wide, so Node has a size. Option<Box<T>> costs nothing extra: None is the null pointer."] = "Box<Node> ocupa un puntero, así que Node tiene tamaño. Option<Box<T>> no cuesta nada extra: None es el puntero nulo.",
  ["Box<dyn Error> accepts any error type via From. Good for main and prototypes, not libraries."] = "Box<dyn Error> acepta cualquier tipo de error vía From. Bueno para main y prototipos, no para bibliotecas.",
  ["Branch on what v really is. Fill: switch x := v.(___)"] = "Ramifica según lo que v es en realidad. Completa: switch x := v.(___)",
  ["Breadth first needs a FIFO: in at the back, out at the front. Which std collection?"] = "La anchura necesita una FIFO: entra por atrás, sale por delante. ¿Qué colección de std?",
  ["Build a String from pieces without printing it. Which macro?"] = "Construye un String a partir de piezas sin imprimirlo. ¿Qué macro?",
  ["Build a growable list from three literal prices. Which macro?"] = "Construye una lista que crece a partir de tres precios literales. ¿Qué macro?",
  ["Build a max-heap of (count, word) straight from the map's iterator. Which method turns an iterator into a collection?"] = "Construye un max-heap de (count, word) directamente desde el iterador del map. ¿Qué método convierte un iterador en una colección?",
  ["Build that copy by hand: a new slice as long as a, then copy into it. Which built-in gives the length?"] = "Construir esa copia a mano: un slice nuevo tan largo como a, y luego copiar dentro. ¿Qué función integrada da la longitud?",
  ["Build the label as a string, without printing. Which fmt function?"] = "Construye la etiqueta como string, sin imprimir. ¿Qué función de fmt?",
  ["By default go get asks proxy.golang.org, which caches every public module for ever and checks its hash against sum.golang.org. A private GitHub repo is invisible to the proxy: set GOPRIVATE=github.com/yourorg/* so the tool goes straight to git, and teach git to use ssh for github.com so the clone authenticates. When the cache turns stale or the disk fills, go clean -modcache."] = "Por defecto go get pregunta a proxy.golang.org, que cachea para siempre cada módulo público y comprueba su hash contra sum.golang.org. Un repo privado de GitHub es invisible para el proxy: pon GOPRIVATE=github.com/yourorg/* para que la herramienta vaya directa a git, y enseña a git a usar ssh con github.com para que el clone se autentique. Cuando la caché se estropea o el disco se llena, go clean -modcache.",
  ["By hand: look the answer up before computing. Which dict is checked?"] = "A mano: buscar la respuesta antes de calcular. ¿Qué dict se consulta?",
  ["C  continue at %s   (%d/%d streets clear)"] = "C  continuar en %s   (%d/%d calles listas)",
  ["CALLBACK  -  the whiteboard"] = "CALLBACK  -  la pizarra",
  ["CALLBACK  ·  the Go round"] = "CALLBACK  ·  la ronda de Go",
  ["CALLBACK  ·  the Python round"] = "CALLBACK  ·  la ronda de Python",
  ["CALLBACK  ·  the Rust round"] = "CALLBACK  ·  la ronda de Rust",
  ["CALLBACK 1  -  the brackets"] = "CALLBACK 1  -  los paréntesis",
  ["CALLBACK 2  -  the stairs"] = "CALLBACK 2  -  las escaleras",
  ["CALLBACK 3  -  the window"] = "CALLBACK 3  -  la ventana",
  ["CALLBACK 4  -  the heap"] = "CALLBACK 4  -  el heap",
  ["CALLBACK 4  -  the top k"] = "CALLBACK 4  -  los k mayores",
  ["CALLBACK 5  -  the calendar"] = "CALLBACK 5  -  el calendario",
  ["CALLBACK 5  -  the shifts"] = "CALLBACK 5  -  los turnos",
  ["CALLBACK 6  -  the cache"] = "CALLBACK 6  -  la caché",
  ["CALLBACK 7  -  the islands"] = "CALLBACK 7  -  las islas",
  ["CLEAR"] = "LISTO",
  ["CLEAR   ENTER  next"] = "¡LISTO!   ENTER  siguiente",
  ["CLEAR   ENTER back to the map"] = "¡LISTO!   ENTER volver al mapa",
