  ["CODE RUSH  -  the interview"] = "CODE RUSH  -  la entrevista",
  ["CODE RUSH  ·  Times Square"] = "CODE RUSH  ·  Times Square",
  ["CODE RUSH  ·  the Python round"] = "CODE RUSH  ·  la ronda de Python",
  ["CODE RUSH  ·  the Rust round"] = "CODE RUSH  ·  la ronda de Rust",
  ["COMBO x%d"] = "COMBO x%d",
  ["COMBO x10"] = "COMBO x10",
  ["COMBO x5"] = "COMBO x5",
  ["COPIED  %s"] = "COPIADO  %s",
  ["COPY  (ask your AI why)"] = "COPIAR  (pregunta a tu IA por qué)",
  ["Call it what its GitHub URL will be. Every import inside starts with that string."] = "Llámalo como será su URL de GitHub. Cada import de dentro empieza por esa cadena.",
  ["Call the map API over HTTP with one line. Which popular async client crate?"] = "Llama a la API de mapas por HTTP en una línea. ¿Qué crate cliente async popular?",
  ["Callback round, Chef. Whiteboard, no keyboard. First: are these brackets balanced?"] = "Ronda de callback, chef. Pizarra, sin teclado. Primero: ¿están balanceados estos paréntesis?",
  ["Callback round, Mei. No buzzer this time, just the whiteboard. Warm-up: are these brackets balanced?"] = "Ronda callback, Mei. Esta vez sin pulsador, solo la pizarra. Calentamiento: ¿están equilibrados estos paréntesis?",
  ["Cancel automatically after two seconds. Fill: context.___(ctx, 2*time.Second)"] = "Cancela automáticamente tras dos segundos. Completa: context.___(ctx, 2*time.Second)",
  ["Capital = exported. Small = private to the package. Same rule for types and fields."] = "Mayúscula = exportado. Minúscula = privado del paquete. Misma regla para tipos y campos.",
  ["Capital E, returns string. That one method is the whole error interface."] = "E mayúscula, devuelve string. Ese único método es toda la interfaz error.",
  ["Capital M. MarshalIndent pretty-prints. The opposite is on the next blank."] = "M mayúscula. MarshalIndent imprime con formato. Lo contrario va en el siguiente hueco.",
  ["Capital N. Go's nil, Rust's Option::None. Compare it with is, not ==."] = "N mayúscula. El nil de Go, el Option::None de Rust. Compáralo con is, no con ==.",
  ["Capital S. The fmt.Stringer interface has exactly this one method."] = "S mayúscula. La interface fmt.Stringer tiene exactamente este único método.",
  ["Capital first letter. Lower-case fields are invisible outside the package, json included."] = "Primera letra mayúscula. Los campos en minúscula son invisibles fuera del paquete, json incluido.",
  ["Capital means exported, and that goes for types, fields, methods and constants too. A struct with lowercase fields cannot even be filled in from another package."] = "Mayúscula significa exportado, y eso vale también para tipos, campos, métodos y constantes. Un struct con campos en minúscula ni siquiera se puede rellenar desde otro paquete.",
  ["Cargo, the build tool"] = "Cargo, la herramienta de construcción",
  ["Carry the order id through five calls of logging. Which constructor?"] = "Lleva el id del pedido a través de cinco llamadas de registro. ¿Qué constructor?",
  ["Causeway Bay"] = "Causeway Bay",
  ["Causeway Bay station"] = "Estación Causeway Bay",
  ["Channel pipelines, closed and nil"] = "Tuberías de channels, cerrados y nil",
  ["Channels"] = "Channels",
  ["Channels in Go, mpsc in Rust, and now a Queue. Same kitchen every time."] = "Canales en Go, mpsc en Rust, y ahora una Queue. La misma cocina cada vez.",
  ["Check bounds before touching g[r][c]: Python would raise IndexError on the right edge, and g[-1] silently wraps."] = "Comprueba los límites antes de tocar g[r][c]: Python lanzaría IndexError en el borde derecho, y g[-1] da la vuelta en silencio.",
  ["Check bounds before you index, or the recursion panics at the shoreline."] = "Comprueba los límites antes de indexar, o la recursión hace panic en la orilla.",
  ["Check for an order without waiting; the till must keep beeping. Which method?"] = "Comprueba si hay pedido sin esperar; la caja debe seguir pitando. ¿Qué método?",
  ["Check the hints before running the shift. Which tool, the classic one?"] = "Comprobar las anotaciones antes de correr el turno. ¿Qué herramienta, la clásica?",
  ["Checking every guest against every other guest for a double booking. Fine with 20. Not with 2000."] = "Comparar cada invitado con cada otro invitado buscando una reserva doble. Bien con 20. No con 2000.",
  ["Checking every guest against every other guest for a double booking. It was fine with 20. It is not fine with 2000."] = "Comparar cada invitado con cada otro invitado buscando una reserva doble. Iba bien con 20. No va bien con 2000.",
  ["Chef Bo"] = "Chef Bo",
  ["Close results only after every worker is done. Fill: wg.___(); close(results)"] = "Cierra results solo cuando todos los workers hayan terminado. Completa: wg.___(); close(results)",
  ["Close the receipt printer whether the refund worked or not. Which clause always runs?"] = "Cerrar la impresora de recibos funcione o no el reembolso. ¿Qué cláusula siempre corre?",
  ["Code is done. Now build it like a Rustacean: one tool for everything. Ticket six."] = "El código está listo. Ahora constrúyelo como un Rustacean: una herramienta para todo. Ticket seis.",
  ["Coin c on top of the best answer for a - c, if that beats what we have. Which built-in keeps the smaller?"] = "La moneda c encima de la mejor respuesta para a - c, si supera lo que ya tenemos. ¿Qué función integrada se queda con el menor?",
  ["Coin change, fewest coins. Before the loop, mark every amount with a value no real answer can reach. Which?"] = "Cambio de monedas, las menos posibles. Antes del bucle, marca cada importe con un valor que ninguna respuesta real pueda alcanzar. ¿Cuál?",
  ["Coin change: dp[a] is the fewest coins for amount a. The table starts full of 'impossible'. Which amount costs zero coins?"] = "Cambio de monedas: dp[a] es el mínimo de monedas para la cantidad a. La tabla empieza llena de 'imposible'. ¿Qué cantidad cuesta cero monedas?",
  ["Coin change: fewest coins for each amount. Unreachable amounts start at infinity. Fill the float."] = "Cambio de monedas: las menos monedas para cada cantidad. Las cantidades inalcanzables empiezan en infinito. Completa el float.",
  ["Coins [2] for 3 returns -1. Table, transition, base case, impossible marker: every DP has the four."] = "Monedas [2] para 3 devuelve -1. Tabla, transición, caso base, marcador de imposible: todo DP tiene los cuatro.",
  ["Colon then equals. Only inside a function."] = "Dos puntos y luego igual. Solo dentro de una función.",
  ["Compare characters, not bytes, so 銅鑼灣 works. Fill: r := []___(s)"] = "Compara caracteres, no bytes, para que 銅鑼灣 funcione. Completa: r := []___(s)",
  ["Compare code against several patterns and pick one arm. Which keyword?"] = "Compara code con varios patrones y elige una rama. ¿Qué palabra clave?",
  ["Compare the start with the end of the last block in out. Equal counts as touching."] = "Compara el inicio con el final del último bloque de out. Igual cuenta como tocar.",
  ["CompareAndSwap returns false when someone beat you to it, so the loop reads and tries again. That retry loop is how lock-free code is written."] = "CompareAndSwap devuelve false cuando alguien se te adelantó, así que el bucle vuelve a leer y lo intenta otra vez. Ese bucle de reintento es como se escribe el código sin cerrojos.",
  ["Comparing each pair once is n(n-1)/2 checks. For 100 guests, how many?"] = "Comparar cada par una vez son n(n-1)/2 comprobaciones. Para 100 invitados, ¿cuántas?",
  ["Compile everything into one binary called delivery. Fill: go ___ -o delivery ."] = "Compila todo en un solo binario llamado delivery. Completa: go ___ -o delivery .",
  ["Compile with optimisations for the live server. Which flag?"] = "Compila con optimizaciones para el servidor en producción. ¿Qué flag?",
  ["Compute, remember, return. Fill the second term: fib(n-1) + fib(___)"] = "Calcula, recuerda, devuelve. Completa el segundo término: fib(n-1) + fib(___)",
  ["Computed once, never again. Put v into the memo under key n. Which method?"] = "Calculado una vez, nunca más. Mete v en el memo bajo la clave n. ¿Qué método?",
  ["Constant time"] = "Tiempo constante",
  ["Constant. A Python list is an array of pointers; index 3 is base plus 3 times a pointer's size."] = "Constante. Una lista de Python es un array de punteros; el índice 3 es la base más 3 veces el tamaño de un puntero.",
  ["Constant. A slice is a pointer and a length; index 3 is pointer plus 3 times the element size, after a bounds check."] = "Constante. Un slice es un puntero y una longitud; el índice 3 es el puntero más 3 veces el tamaño del elemento, tras una comprobación de límites.",
  ["Constant. The slice knows its base address; index 3 is base plus 3 times the element size."] = "Constante. El slice conoce su dirección base; el índice 3 es la base más 3 veces el tamaño del elemento.",
  ["Context and tests"] = "Context y tests",
  ["Context managers"] = "Gestores de contexto",
  ["Conversion is T(x). int and float64 never mix without it."] = "La conversión es T(x). int y float64 nunca se mezclan sin ella.",
  ["Convert the rune back to a string. The index i is a byte offset."] = "Convierte el rune de vuelta a string. El índice i es un desplazamiento en bytes.",
  ["Copies are the tax of multiprocessing: a global changed in a child stays in the child. multiprocessing.shared_memory.SharedMemory gives every process the same block of bytes, found by name and read through .buf, which NumPy can wrap without copying. You close() your view and unlink() the block exactly once, or it outlives the program."] = "Las copias son el impuesto de multiprocessing: una global cambiada en el hijo se queda en el hijo. multiprocessing.shared_memory.SharedMemory da a cada proceso el mismo bloque de bytes, localizado por nombre y leído por .buf, que NumPy puede envolver sin copiar. Haces close() de tu vista y unlink() del bloque exactamente una vez, o sobrevivirá al programa.",
  ["Count characters, not bytes. Which iterator do you count?"] = "Cuenta caracteres, no bytes. ¿Qué iterador cuentas?",
  ["Count characters, not bytes. Which unicode/utf8 function?"] = "Cuenta caracteres, no bytes. ¿Qué función de unicode/utf8?",
  ["Count each letter of a word in one call. Which collections class?"] = "Contar cada letra de una palabra en una llamada. ¿Qué clase de collections?",
  ["Count islands: every land cell still standing starts a new one. Fill the call that sinks the whole island."] = "Cuenta islas: cada celda de tierra que siga en pie empieza una nueva. Completa la llamada que hunde la isla entera.",
  ["Count letters of a, uncount letters of b; all zero means anagram. Fill: count[c-'a']___"] = "Cuenta las letras de a, descuenta las de b; todo cero significa anagrama. Completa: count[c-'a']___",
  ["Count muffins per table: insert 0 if the key is new, then add 1. Which HashMap method starts that?"] = "Cuenta muffins por mesa: inserta 0 si la clave es nueva, luego suma 1. ¿Qué método de HashMap empieza eso?",
  ["Count the arrows. 2 to this power is 1024."] = "Cuenta las flechas. 2 elevado a esta potencia es 1024.",
  ["Count the nodes without taking ownership: cur is a &Link. Step to the following node: cur = &node.___"] = "Cuenta los nodos sin tomar posesión: cur es un &Link. Avanza al nodo siguiente: cur = &node.___",
  ["Count the values. The length is part of the type, so [i32; 4] would be a different type."] = "Cuenta los valores. La longitud es parte del tipo, así que [i32; 4] sería otro tipo.",
  ["Counter(word).most_common(1) gives the top letter. Go's count[c-'a']++ in one line. Round six to Bo."] = "Counter(word).most_common(1) da la letra más frecuente. El count[c-'a']++ de Go en una línea. Sexta ronda para Bo.",
  ["Counting the queue takes one look per person. Twice the queue, twice the looking."] = "Contar la cola cuesta una mirada por persona. El doble de cola, el doble de miradas.",
  ["Crate name, two colons, the function it sits on."] = "Nombre del crate, dos dos puntos, la función sobre la que se coloca.",
  ["Create a fresh binary project called delivery. Which cargo subcommand?"] = "Crea un proyecto binario nuevo llamado delivery. ¿Qué subcomando de cargo?",
  ["Custom errors and ?"] = "Errores propios y ?",
  ["Cut a slice into two slices at mid, no copying. Which slice method returns the pair?"] = "Corta un slice en dos slices en mid, sin copiar. ¿Qué método de slice devuelve el par?",
  ["DELIVERY  -  the app"] = "DELIVERY  -  la app",
  ["DFS dives down one line before backing up. Same O(V + E) as BFS. Mind the 1000-deep recursion limit. Round three to Bo."] = "DFS baja por una línea antes de retroceder. El mismo O(V + E) que BFS. Cuidado con el límite de 1000 de recursión. Tercera ronda para Bo.",
  ["DFS is recursion plus a visited set. Maps are reference-like: no pointer needed."] = "DFS es recursión más un set de visitados. Los maps son como referencias: no hace falta puntero.",
  ["DP fills a table from small answers up. Stairs: dp[i] = dp[i-1] + dp[i-2]. Coin change: dp[a] = min over coins of dp[a-c] + 1, with amount+1 as 'impossible'."] = "DP rellena una tabla desde las respuestas pequeñas hacia arriba. Escaleras: dp[i] = dp[i-1] + dp[i-2]. Cambio de monedas: dp[a] = min sobre las monedas de dp[a-c] + 1, con amount+1 como 'imposible'.",
  ["DP: a table of answers to smaller problems, filled from the base cases up. Stairs: dp[i] = dp[i-1] + dp[i-2]. Coin change: dp[a] = min over coins of dp[a-c] + 1, with a sentinel for 'impossible'."] = "DP: una tabla de respuestas a problemas más pequeños, rellenada desde los casos base hacia arriba. Escaleras: dp[i] = dp[i-1] + dp[i-2]. Cambio de monedas: dp[a] = el mínimo sobre las monedas de dp[a-c] + 1, con un centinela para 'imposible'.",
  ["DP: solve the small cases once, build the bigger ones from them. Stairs: ways(i) = ways(i-1) + ways(i-2). Coins: dp[a] = min over coins of dp[a-c] + 1, with inf for unreachable."] = "DP: resuelve los casos pequeños una vez y construye los grandes a partir de ellos. Escaleras: ways(i) = ways(i-1) + ways(i-2). Monedas: dp[a] = min sobre las monedas de dp[a-c] + 1, con inf para lo inalcanzable.",
  ["Declare a function. Which keyword starts the line?"] = "Declara una función. ¿Qué palabra clave inicia la línea?",
  ["Declare with an explicit type, outside any function. Which keyword?"] = "Declara con tipo explícito, fuera de cualquier función. ¿Qué palabra clave?",
  ["Decorators"] = "Decoradores",
  ["Define your own error type for the kitchen. What must it inherit from?"] = "Define tu propio tipo de error para la cocina. ¿De qué debe heredar?",
  ["Depth first, recursive: visit, then call yourself on each unseen neighbour. Fill the call."] = "Primero en profundidad, recursivo: visitar, luego llamarte a ti mismo en cada vecina no vista. Completa la llamada.",
  ["Depth first: same loop, but the newest station goes next. Which Vec method takes from the end?"] = "Profundidad: el mismo bucle, pero va la estación más nueva. ¿Qué método de Vec saca del final?",
  ["Depth-first: visit, then recurse into each unseen neighbour. Fill the call."] = "En profundidad: visita y luego recurre en cada vecino no visto. Completa la llamada.",
  ["Dicts and sets"] = "Dicts y sets",
  ["Did any of those futures leak? Which runtime call counts the live goroutines?"] = "¿Se filtró alguno de esos futures? ¿Qué llamada de runtime cuenta las goroutines vivas?",
  ["Did the child succeed? Which attribute holds its exit status after join?"] = "¿Salió bien el hijo? ¿Qué atributo guarda su estado de salida tras join?",
  ["Different indexes are different memory, so no lock is needed. Since Go 1.22 each iteration gets its own i, so the closure captures the right one."] = "Índices distintos son memoria distinta, así que no hace falta lock. Desde Go 1.22 cada iteración tiene su propia i, así que el closure captura la correcta.",
  ["Directory, package name, exported names"] = "Directorio, nombre de paquete, nombres exportados",
  ["Display does not care which lifetime Receipt has. Which placeholder says so?"] = "A Display no le importa qué lifetime tiene Receipt. ¿Qué marcador lo dice?",
  ["Divide and conquer: split the slice in the middle. Fill: let mid = v.len() / ___"] = "Divide y vencerás: parte el slice por el medio. Completa: let mid = v.len() / ___",
  ["Divide, recurse, merge: O(n log n) always. Base case is a slice of length 0 or 1."] = "Divide, recurre, fusiona: O(n log n) siempre. El caso base es un slice de longitud 0 o 1.",
  ["Do not block if nothing is ready. Which case label?"] = "No bloquees si nada está listo. ¿Qué etiqueta de case?",
  ["Do not recurse. Fill a table from the bottom step up."] = "No recurras. Rellena una tabla desde el escalón de abajo hacia arriba.",
  ["Do not start a Process per photo. Forty thousand interpreters is not parallelism, it is a fire."] = "No arranques un Process por foto. Cuarenta mil intérpretes no son paralelismo, son un incendio.",
  ["Doc comments are the API reference: go doc, gopls hover and pkg.go.dev all read them. Start each with the name it documents so it reads as a sentence."] = "Los comentarios de documentación son la referencia de la API: go doc, el hover de gopls y pkg.go.dev los leen. Empieza cada uno con el nombre que documenta para que se lea como una frase.",
  ["Does the order contain egg? Which keyword tests membership?"] = "¿El pedido contiene egg? ¿Qué palabra clave comprueba pertenencia?",
  ["Does this shift start before the last merged block ends? Fill the overlap test."] = "¿Este turno empieza antes de que termine el último bloque fusionado? Completa la prueba de solapamiento.",
  ["Don't share memory. Pass the hash brown on a channel."] = "No compartas memoria. Pasa el hash brown por un channel.",
  ["Double every price into a new list, in one line. Which keyword sits in the middle of the comprehension?"] = "Duplicar cada precio en una lista nueva, en una línea. ¿Qué palabra clave va en medio de la comprensión?",
  ["Double every quantity. How does a closure name its one parameter?"] = "Duplica cada cantidad. ¿Cómo nombra un closure su único parámetro?",
  ["Dunder around the text type's name. Its sibling __repr__ is for the debugger."] = "Dunder alrededor del nombre del tipo de texto. Su hermano __repr__ es para el depurador.",
  ["Dunder around the verb for going in. Its return value is what as binds."] = "Dunder alrededor del verbo de entrar. Su valor de retorno es lo que enlaza as.",
  ["Dunder around the verb for going out. It receives three values about any exception."] = "Dunder alrededor del verbo de salir. Recibe tres valores sobre cualquier excepción.",
  ["Dynamic programming"] = "Programación dinámica",
  ["Dynamic programming: stairs and coins"] = "Programación dinámica: escaleras y monedas",
  ["EARLY BIRD"] = "MADRUGADOR",
  ["ENTER  pick a street"] = "ENTER  elige una calle",
  ["ENTER  street map      ESC  title"] = "ENTER  mapa de calles      ESC  título",
  ["ESC back"] = "ESC volver",
  ["ESC title"] = "ESC título",
  ["EXPORT  to ~/Downloads"] = "EXPORTAR  a ~/Downloads",
  ["Each Fibonacci number is the sum of the two before it."] = "Cada número de Fibonacci es la suma de los dos anteriores.",
  ["Each call handles one step and delegates the rest: n * (n-1)!"] = "Cada llamada resuelve un paso y delega el resto: n * (n-1)!",
  ["Each call handles one step and delegates the rest: n * (n-1)!. Python ints never overflow, so fact(100) just works."] = "Cada llamada maneja un paso y delega el resto: n * (n-1)!. Los int de Python nunca desbordan, así que fact(100) simplemente funciona.",
  ["Each call is one step closer to 1. fact(20) is the biggest that fits in u64. The crowd claps."] = "Cada llamada acerca un paso más al 1. fact(20) es el mayor que cabe en u64. El público aplaude.",
  ["Each cell is visited a constant number of times: O(rows*cols). A BFS with a queue avoids deep recursion. OFFER."] = "Cada celda se visita un número constante de veces: O(filas*columnas). Un BFS con cola evita la recursión profunda. OFFER.",
  ["Each closer maps to its opener. Fill the value stored for ')'."] = "Cada cierre corresponde a su apertura. Completa el valor guardado para ')'.",
  ["Each interval is compared with the last merged one, which may need to grow. Which method borrows the last element mutably as Option?"] = "Cada intervalo se compara con el último fusionado, que quizá tenga que crecer. ¿Qué método presta el último elemento de forma mutable como Option?",
  ["Each n is computed once: O(n) calls, O(n) memory. Round one, no misses. Combo x1."] = "Cada n se calcula una vez: O(n) llamadas, O(n) memoria. Ronda uno, sin fallos. Combo x1.",
  ["Each node links to the next one. Fill the field type: Next ___"] = "Cada nodo enlaza con el siguiente. Completa el tipo del campo: Next ___",
  ["Each thread needs its own handle to the same counter. Which call makes one from &sold?"] = "Cada thread necesita su propio handle al mismo contador. ¿Qué llamada crea uno a partir de &sold?",
  ["Each version is unpacked once into pkg/mod/github.com/alex/luckymac@v1.2.0 and never touched again. go clean -modcache wipes it when the disk fills up."] = "Cada versión se desempaqueta una vez en pkg/mod/github.com/alex/luckymac@v1.2.0 y no se toca más. go clean -modcache la borra cuando el disco se llena.",
  ["Eight cooks, one order book. That I understand."] = "Ocho cocineros, una comanda. Eso sí lo entiendo.",
  ["Eight cores, one busy"] = "Ocho núcleos, uno ocupado",
  ["Eight letters, the opposite of external. The rule is in the compiler, not in a linter."] = "Ocho letras, lo contrario de external. La regla está en el compilador, no en un linter.",
  ["Eight letters, what a house or an object has. Then o.total works, no parentheses."] = "Ocho letras, lo que tiene una casa o un objeto. Entonces o.total funciona, sin paréntesis.",
  ["Eight letters: every goroutine waits on every other. The send never returns."] = "Ocho letras: cada goroutine espera a las demás. El envío nunca retorna.",
  ["Eight letters: like find, but it gives you where, not what. Option<usize>."] = "Ocho letras: como find, pero te da dónde, no qué. Option<usize>.",
  ["Eight shared doubles with a lock and no NumPy. Which multiprocessing class?"] = "Ocho doubles compartidos con un bloqueo y sin NumPy. ¿Qué clase de multiprocessing?",
  ["Eight workers, one label printer. The labels came out with two orders on one sticker."] = "Ocho workers, una impresora de etiquetas. Salió una pegatina con dos pedidos encima.",
  ["Eight workers, started once, reused all night. Which class?"] = "Ocho workers, arrancados una vez, reutilizados toda la noche. ¿Qué clase?",
  ["Elision: one input reference (here &self) means the output borrows from it. Most signatures need no 'a at all. The receipt prints."] = "Elisión: una sola referencia de entrada (aquí &self) significa que la salida presta de ella. La mayoría de firmas no necesitan ningún 'a. El recibo se imprime.",
  ["Empty brackets then the element type. [3]int would be an array."] = "Corchetes vacíos y luego el tipo del elemento. [3]int sería un array.",
  ["Empty parentheses. go needs a call, not just a function value."] = "Paréntesis vacíos. go necesita una llamada, no solo un valor función.",
  ["Empty the whole map in one call (Go 1.21). Which built-in?"] = "Vacía todo el map en una llamada (Go 1.21). ¿Qué función integrada?",
  ["Errors and defer"] = "Errores y defer",
  ["Errors are exceptions: try runs the risky part, except catches a type, finally always runs, raise throws. Your own errors subclass Exception."] = "Los errores son excepciones: try ejecuta la parte arriesgada, except captura un tipo, finally siempre corre, raise lanza. Tus propios errores heredan de Exception.",
  ["Errors: New, wrap, Is, As"] = "Errores: New, wrap, Is, As",
  ["Even with separate memory, processes still share the machine: one printer, one log file, one counter in shared memory. multiprocessing.Lock is the mutex across processes, used as a with block. Value and Array put a number in shared memory and hand you get_lock() for it, and a Manager serves ordinary dicts and lists over a proxy."] = "Aun con memoria separada, los procesos siguen compartiendo la máquina: una impresora, un fichero de log, un contador en memoria compartida. multiprocessing.Lock es el mutex entre procesos y se usa como bloque with. Value y Array ponen un número en memoria compartida y te dan su get_lock(), y un Manager sirve dicts y listas normales a través de un proxy.",
  ["Evening edition of CODE RUSH! Rust round. Mei, you're up. Factorial, then fib. Buzzer's live!"] = "¡Edición de noche de CODE RUSH! Ronda de Rust. Mei, te toca. Factorial, luego fib. ¡El pulsador está en vivo!",
  ["Every Go file starts with package. import brings other packages in."] = "Todo archivo Go empieza con package. import trae otros paquetes.",
  ["Every Rust program starts in which function?"] = "¿En qué función empieza todo programa Rust?",
  ["Every cell is visited once by the loop and at most once by a DFS: O(rows * cols). The screen says OFFER."] = "Cada celda la visita el bucle una vez y un DFS como máximo una vez: O(rows * cols). La pantalla dice OFFER.",
  ["Every closer knows its opener. Fill the opener that } maps to."] = "Cada cierre conoce su apertura. Completa la apertura a la que corresponde }.",
  ["Every dish gets a stamp: time it, log it. I do not want to write that in fifty functions."] = "Cada plato recibe un sello: cronométralo, regístralo. No quiero escribir eso en cincuenta funciones.",
  ["Every dish is a function. fry(egg), brew(tea). Someone deleted the word that starts them."] = "Cada plato es una función. fry(egg), brew(tea). Alguien borró la palabra que las empieza.",
  ["Every get must be paired with a task_done, or join waits forever. Go's wg.Done()."] = "Cada get debe emparejarse con un task_done, o join espera para siempre. El wg.Done() de Go.",
  ["Every get needs one task_done, or q.join() waits for ever. It is the WaitGroup of the queue world."] = "Cada get necesita un task_done, o q.join() espera para siempre. Es el WaitGroup del mundo de las colas.",
  ["Every island is counted exactly once because its cells are water by the time the loop reaches them again. OFFER."] = "Cada isla se cuenta exactamente una vez porque sus celdas ya son agua cuando el bucle vuelve a llegar a ellas. OFFER.",
  ["Every item is moved exactly once per level, however many pieces there are."] = "Cada elemento se mueve exactamente una vez por nivel, por muchas piezas que haya.",
  ["Every item sent to a worker is pickled and shipped down a pipe. Below a few microseconds of work per item, the shipping is the program."] = "Cada elemento que va a un worker se serializa con pickle y viaja por una tubería. Por debajo de unos microsegundos de trabajo por elemento, el transporte es el programa.",
  ["Every key of the price map, as an iterator (Go 1.23). Fill: maps.___(prices)"] = "Cada clave del map de precios, como iterador (Go 1.23). Completa: maps.___(prices)",
  ["Every one of these is 'use a map' or 'use two pointers'. Pick the right one."] = "Todos estos son 'usa un map' o 'usa dos punteros'. Elige el correcto.",
  ["Every opener must have been closed. What does the function return at the end?"] = "Toda apertura debe haberse cerrado. ¿Qué devuelve la función al final?",
  ["Every opener must have found its closer. What does valid return after the loop?"] = "Cada apertura debe haber encontrado su cierre. ¿Qué devuelve valid después del bucle?",
  ["Every price but the first must lose a comparison to be ruled out. One less than the count."] = "Todo precio menos el primero debe perder una comparación para quedar descartado. Uno menos que la cuenta.",
  ["Every process closes its view. Which call, made once, frees the block itself?"] = "Cada proceso cierra su vista. ¿Qué llamada, hecha una vez, libera el bloque en sí?",
  ["Every public download is checked against a transparency log. Name its host."] = "Toda descarga pública se comprueba contra un registro de transparencia. Nombra su host.",
  ["Every real answer grows out of dp[0]. The marker amount + 1 lets min work without an Option."] = "Toda respuesta real crece a partir de dp[0]. El marcador amount + 1 deja que min funcione sin un Option.",
  ["Every receipt goes onto a min-heap. Which heapq function adds x and keeps the heap order?"] = "Cada recibo va a un min-heap. ¿Qué función de heapq agrega x y mantiene el orden del heap?",
  ["Every recursion stops somewhere. fact(0) and fact(1) evaluate to what?"] = "Toda recursión para en algún sitio. ¿A qué evalúan fact(0) y fact(1)?",
  ["Every recursion stops somewhere. fact(0) and fact(1) return what?"] = "Toda recursión se detiene en algún punto. ¿Qué devuelven fact(0) y fact(1)?",
  ["Every runnable Go program lives in which package?"] = "¿En qué paquete vive todo programa Go ejecutable?",
  ["Every topping can be on or off. Ten toppings, a thousand combos. Twenty, a million. That is 2^n."] = "Cada ingrediente puede estar o no. Diez ingredientes, mil combinaciones. Veinte, un millón. Eso es 2^n.",
  ["Every topping on or off, n toppings. How many combinations, as a power?"] = "Cada ingrediente sí o no, n ingredientes. ¿Cuántas combinaciones, como potencia?",
  ["Every worker allocates a receipt buffer. Which sync.Pool method hands one back?"] = "Cada worker reserva un buffer para el recibo. ¿Qué método de sync.Pool te da uno?",
  ["Every worker must report in before Wait returns. Which method, deferred?"] = "Cada worker debe fichar antes de que Wait vuelva. ¿Qué método, con defer?",
  ["Everyone's shifts overlap. Six to ten, nine to two, one to four. When is the kitchen actually staffed?"] = "Los turnos de todos se solapan. De seis a diez, de nueve a dos, de una a cuatro. ¿Cuándo hay gente en la cocina de verdad?",
  ["Everything bigger than the node. Five letters."] = "Todo lo mayor que el nodo. Cinco letras.",
  ["Everything from index 1 to the end. A slice expression, no copy."] = "Todo desde el índice 1 hasta el final. Una expresión de slice, sin copia.",
  ["Everything from the second block on. zip stops at the shorter list, so no index error."] = "Todo desde el segundo bloque en adelante. zip se detiene en la lista más corta, así que no hay error de índice.",
  ["Everything is immutable until you say mut. The tram sign forgot that."] = "Todo es inmutable hasta que dices mut. El letrero del tranvía lo olvidó.",
  ["Everything written before the close happens before <-ready returns, so reading menu after it is not a race. That rule is the Go memory model."] = "Todo lo escrito antes del cierre ocurre antes de que <-ready vuelva, así que leer menu después no es una carrera. Esa regla es el modelo de memoria de Go.",
  ["Exponential time"] = "Tiempo exponencial",
  ["Exponential: two to the power of n. Each level of the call tree is twice as wide as the one above."] = "Exponencial: dos elevado a n. Cada nivel del árbol de llamadas es el doble de ancho que el de arriba.",
  ["F for a file or writer, then printf. The writer is the first argument."] = "F de file o writer, luego printf. El writer es el primer argumento.",
  ["FAILED  %s"] = "FALLÓ  %s",
  ["FAST!"] = "¡RÁPIDO!",
  ["FINAL  -  the islands"] = "FINAL  -  las islas",
  ["FINAL  -  the kitchen"] = "FINAL  -  la cocina",
  ["FIRST CLEAR"] = "PRIMER CLEAR",
  ["FIRST STAMP"] = "PRIMER SELLO",
  ["FIVE PERFECTS"] = "CINCO PERFECTOS",
  ["FULL"] = "COMPLETA",
  ["Fan-in: workers send, one closer closes. Closing from a worker would panic the others, so the closer is the goroutine that waits."] = "Fan-in: los workers envían y uno solo cierra. Cerrar desde un worker haría entrar en panic a los demás, así que quien cierra es la goroutine que espera.",
  ["Feed nine orders into the queue. Which method adds one?"] = "Meter nueve pedidos en la cola. ¿Qué método añade uno?",
  ["Fewest coins wins, so keep the smaller of the old value and the new candidate."] = "Ganan las menos monedas, así que quédate con el menor entre el valor viejo y el nuevo candidato.",
  ["Fibonacci in disguise: the sum of the two entries just before it."] = "Fibonacci disfrazado: la suma de las dos entradas justo anteriores.",
  ["Final question. A map of the harbour, ones for land, zeros for water. How many islands? Get this and the offer is yours."] = "Pregunta final. Un mapa del puerto, unos para tierra, ceros para agua. ¿Cuántas islas? Acierta esta y la oferta es tuya.",
  ["Final round, Mei! Get the drop and the join in the right order and you're HIRED!"] = "¡Ronda final, Mei! ¡Pon el drop y el join en el orden correcto y estás CONTRATADA!",
  ["Final round. The delivery map as a grid of 1s and 0s. How many separate islands of buildings?"] = "Ronda final. El mapa de reparto como cuadrícula de 1s y 0s. ¿Cuántas islas separadas de edificios hay?",
  ["Final round: a worker pool. Three cooks, one queue, nine orders. Nothing lost, nothing done twice."] = "Ronda final: un pool de workers. Tres cocineros, una cola, nueve pedidos. Nada perdido, nada hecho dos veces.",
  ["Finally, types. Even if the interpreter ignores them."] = "Por fin, tipos. Aunque el intérprete los ignore.",
  ["Find land, sink the whole island, count one. Repeat until the map is all water."] = "Encuentra tierra, hunde la isla entera, cuenta una. Repite hasta que el mapa sea todo agua.",
  ["Find suspicious code the compiler allows: wrong Printf verbs, copied locks. Fill: go ___ ./..."] = "Encuentra código sospechoso que el compilador permite: verbos Printf erróneos, locks copiados. Completa: go ___ ./...",
  ["Find the middle: slow moves one, fast moves two. Fill the fast step: fast = fast.next.___"] = "Encontrar el medio: slow avanza uno, fast avanza dos. Completa el paso rápido: fast = fast.next.___",
  ["Find where 38 belongs in the sorted amounts in O(log n). Which bisect function?"] = "Encontrar dónde va 38 en los importes ordenados en O(log n). ¿Qué función de bisect?",
  ["Finding the largest of n unsorted prices needs at least how many comparisons?"] = "Encontrar el mayor de n precios sin ordenar necesita al menos ¿cuántas comparaciones?",
  ["Finish Go's proverb: do not communicate by sharing memory; share memory by ___."] = "Completa el proverbio de Go: no te comuniques compartiendo memoria; comparte memoria ___.",
  ["Five letters, Go's only way to loop over a slice's elements. slices.Contains does exactly this inside."] = "Cinco letras, la única forma de Go de recorrer los elementos de un slice. slices.Contains hace exactamente esto por dentro.",
  ["Five letters, a builtin that takes a channel. It never blocks and every receiver wakes."] = "Cinco letras, una función integrada que toma un channel. Nunca bloquea y despierta a todos los receptores.",
  ["Five letters, a stash of things already fetched. Its older sibling takes a maxsize."] = "Cinco letras, un escondite de cosas ya traídas. Su hermano mayor acepta un maxsize.",
  ["Five letters, a verb in the third person: what the wrapper does to fn."] = "Cinco letras, un verbo en tercera persona: lo que la envoltura hace con fn.",
  ["Five letters, a verb: wait for it. Rust puts the same word after a dot."] = "Cinco letras, un verbo: espéralo. Rust pone la misma palabra tras un punto.",
  ["Five letters, capitalised: what Value is, but with a length."] = "Cinco letras, en mayúscula inicial: lo que es Value, pero con longitud.",
  ["Five letters, goes before fn. The opposite of sync."] = "Cinco letras, va antes de fn. Lo contrario de sync.",
  ["Five letters, lower case: the box has one, and this is how you open it."] = "Cinco letras, en minúscula: la caja tiene uno dentro y así se abre.",
  ["Five letters, lowercase, no package in front of it. Go needs fmt for this; Python does not."] = "Cinco letras, minúsculas, sin paquete delante. Go necesita fmt para esto; Python no.",
  ["Five letters, meaning 'give way'. Like return, but the function resumes on the next pull."] = "Cinco letras, que significan 'ceder'. Como return, pero la función se reanuda en la siguiente extracción.",
  ["Five letters, plural. for k in menu alone gives only the keys."] = "Cinco letras, en plural. for k in menu solo da las claves.",
  ["Five letters, same as Go, but Rust insists on the : u8 part."] = "Cinco letras, igual que Go, pero Rust insiste en la parte : u8.",
  ["Five letters, short for asynchronous. Rust spells it the same way in front of fn."] = "Cinco letras, abreviatura de asynchronous. Rust la escribe igual delante de fn.",
  ["Five letters, short for mutual exclusion."] = "Cinco letras, abreviatura de mutual exclusion.",
  ["Five letters, since Python 3.9: the unbounded memo. Its older cousin takes a maxsize."] = "Cinco letras, desde Python 3.9: el memo sin límite. Su primo mayor acepta un maxsize.",
  ["Five letters, the opposite of open. Forgetting it is why the morning count was wrong."] = "Cinco letras, lo contrario de open. Olvidarlo es la razón de que el recuento de la mañana estuviera mal.",
  ["Five letters, the opposite of stop. Not run(): that would call fry in the current thread."] = "Cinco letras, lo contrario de stop. No run(): eso llamaría a fry en el hilo actual.",
  ["Five letters, the shape of a line at a counter. Go spells it chan."] = "Cinco letras, la forma de una fila ante el mostrador. Go lo escribe chan.",
  ["Five letters, the trait every Vec<T: Clone> implements. to_vec() from a slice is the other spelling."] = "Cinco letras, el trait que implementa todo Vec<T: Clone>. to_vec() desde un slice es la otra forma de escribirlo.",
  ["Five letters, the word for 'above'. It returns a proxy to the parent class."] = "Cinco letras, la palabra para 'encima'. Devuelve un proxy a la clase padre.",
  ["Five letters, the word for a stash of things you already fetched. Its older sibling takes a maxsize."] = "Cinco letras, la palabra para un escondite de cosas ya traídas. Su hermano mayor acepta un maxsize.",
  ["Five letters, what a fish does with eggs. The alternatives are fork and forkserver."] = "Cinco letras, lo que hace un pez con las huevas. Las alternativas son fork y forkserver.",
  ["Five letters, what a fish does with eggs. The closure must be 'static, hence move."] = "Cinco letras en inglés: lo que hace un pez con sus huevas. El closure debe ser 'static, de ahí el move.",
  ["Five letters. A region with a clear start and end."] = "Cinco letras. Una región con principio y fin claros, en inglés.",
  ["Five letters. A slot for one key, whether it exists yet or not."] = "Cinco letras. Un hueco para una clave, exista ya o no.",
  ["Five letters. Also asks for a location."] = "Cinco letras. También pregunta por un lugar, en inglés.",
  ["Five letters. Also ends a switch or select case early."] = "Cinco letras. También termina antes un case de switch o select.",
  ["Five letters. Explicit, so you always see where the copying cost is."] = "Cinco letras. Explícito, así siempre ves dónde está el coste de copiar.",
  ["Five letters. Go 1.22 borrowed the idea as for i := range 3."] = "Cinco letras. Go 1.22 tomó la idea como for i := range 3.",
  ["Five letters. Go called it an interface."] = "Cinco letras. Go lo llamaba interface.",
  ["Five letters. Go has struct plus methods; Python puts both under one word. Names are CapWords."] = "Cinco letras. Go tiene struct más métodos; Python pone ambos bajo una palabra. Los nombres van en CapWords.",
  ["Five letters. Go's switch, but exhaustive and it returns a value."] = "Cinco letras. El switch de Go, pero exhaustivo y devuelve un valor.",
  ['Five letters. It returns a Result because "1x8" is not a number.'] = 'Cinco letras. Devuelve un Result porque "1x8" no es un número.',
  ["Five letters. On a slice it zeroes every element instead."] = "Cinco letras. En un slice, en cambio, pone cada elemento a cero.",
  ["Five letters. Return an error for expected failure; this is for the impossible."] = "Cinco letras. Devuelve un error para fallos esperados; esto es para lo imposible.",
  ["Five letters. Same verb as std::thread uses to start a new thread."] = "Cinco letras. El mismo verbo que usa std::thread para arrancar un hilo nuevo.",
  ["Five letters. Sender has it; Receiver does not."] = "Cinco letras. Sender lo tiene; Receiver no, en inglés.",
  ["Five letters. The same word as in C and Python; Go spells it for."] = "Cinco letras. La misma palabra que en C y Python; Go la escribe for.",
  ["Five letters. What a key maps to. The json! macro builds one."] = "Cinco letras. Aquello a lo que apunta una clave (valor, en inglés). La macro json! construye uno.",
  ["Five letters. What fish and goroutines do."] = "Cinco letras. Lo que hacen los peces y las goroutines, en inglés.",
  ["Five letters. What the kettle does between orders."] = "Cinco letras. Lo que hace el hervidor entre pedidos, en inglés.",
  ["Five letters. go run compiles and runs; this one only compiles."] = "Cinco letras. go run compila y ejecuta; este solo compila.",
  ["Five letters: the Entry API. One lookup for both the check and the insert."] = "Cinco letras: la Entry API. Una sola búsqueda para la comprobación y la inserción.",
  ["Five letters; Java and JavaScript say throw. Rust's panic!, but meant to be caught."] = "Cinco letras; Java y JavaScript dicen throw. El panic! de Rust, pero pensado para capturarse.",
  ["Fix the Go bugs. Get the morning set."] = "Arregla los bugs de Go. Consigue el desayuno.",
  ["Fix the Python scripts. Close the night shift."] = "Arregla los scripts de Python. Cierra el turno de noche.",
  ["Fix the Rust bugs. Get the afternoon tea set."] = "Arregla los bugs de Rust. Consigue la merienda.",
  ["Flip it to > for a max-heap. sort.Interface plus Push and Pop is the whole contract."] = "Cámbialo a > para un max-heap. sort.Interface más Push y Pop es todo el contrato.",
  ["Flood fill on a grid: return when out of bounds or not land, sink the cell to mark it, recurse into the four neighbours. Count islands by starting a fill from every land cell still standing."] = "Relleno por inundación en una cuadrícula: vuelve si estás fuera de límites o no es tierra, hunde la celda para marcarla, recurre en los cuatro vecinos. Cuenta islas iniciando un relleno desde cada celda de tierra que siga en pie.",
  ["Flood the four neighbours. r + 1 is fine, but r - 1 on a usize at row 0 panics in debug. Which method subtracts and wraps to usize::MAX instead?"] = "Inunda los cuatro vecinos. r + 1 está bien, pero r - 1 en un usize en la fila 0 hace panic en debug. ¿Qué método resta y da la vuelta a usize::MAX en su lugar?",
  ["Flood the four neighbours: down, up, right and one more. Fill the missing one."] = "Inunda los cuatro vecinos: abajo, arriba, derecha y uno más. Completa el que falta.",
  ["Floor 8. Type the floor. Don't hard-code magic."] = "Piso 8. Escribe el piso. No pongas números mágicos a mano.",
  ["Floor is a named type over int. Convert the int 3 into a Floor. Fill: f := ___(3)"] = "Floor es un tipo con nombre sobre int. Convierte el int 3 en un Floor. Completa: f := ___(3)",
  ["Floors 1 to 5, and 5 must be included. Which range operator?"] = "Pisos 1 a 5, y el 5 debe incluirse. ¿Qué operador de rango?",
  ["Floyd's check: if the fast rider ever lands on the slow one, the route loops. Which operator compares identity?"] = "La comprobación de Floyd: si el repartidor rápido cae alguna vez sobre el lento, la ruta da vueltas. ¿Qué operador compara identidad?",
  ["Floyd: fast moves two steps per turn. Fill: fast = fast.Next.___"] = "Floyd: fast avanza dos pasos por turno. Completa: fast = fast.Next.___",
  ["Followed by the value, then case labels. No break needed."] = "Seguido del valor, luego etiquetas case. No hace falta break.",
  ["For a pure function, the standard library has the whole cache as a decorator. Which keyword caps its size?"] = "Para una función pura, la biblioteca estándar tiene la caché completa como decorador. ¿Qué argumento con nombre limita su tamaño?",
  ["For each amount a and coin c that fits: one coin c on top of the best for a - c. Keep the smaller. Which method?"] = "Para cada cantidad a y moneda c que quepa: una moneda c sobre lo mejor para a - c. Quédate con el menor. ¿Qué método?",
  ["For each coin c that fits into a: one coin, plus the best for what is left. Fill the index."] = "Por cada moneda c que cabe en a: una moneda, más lo mejor para lo que queda. Completa el índice.",
  ["For one number, an atomic beats a mutex: atomic.Int64 has Add, Load, Store and CompareAndSwap, all lock free. atomic.Pointer[T] swaps a whole value in one step. sync.Once runs setup exactly once; sync.OnceValue caches what it returned."] = "Para un solo número, un atómico le gana al mutex: atomic.Int64 tiene Add, Load, Store y CompareAndSwap, todo sin cerrojos. atomic.Pointer[T] cambia un valor entero en un paso. sync.Once ejecuta la preparación exactamente una vez; sync.OnceValue guarda lo que devolvió.",
  ["Forty riders, eight bikes"] = "Cuarenta repartidores, ocho bicis",
  ["Forty thousand photos"] = "Cuarenta mil fotos",
  ["Forty thousand photos before the morning van, and threads made it no faster. Fill every core with processes."] = "Cuarenta mil fotos antes de la furgoneta de la mañana, y los hilos no lo hicieron más rápido. Llena todos los núcleos con procesos.",
  ["Forty thousand results will not fit in memory. Which method yields them one by one?"] = "Cuarenta mil resultados no caben en memoria. ¿Qué método los entrega uno a uno?",
  ["Found and removed from its old spot: now k goes to the fresh end. Which VecDeque method appends at the back?"] = "Encontrada y quitada de su sitio viejo: ahora k va al extremo fresco. ¿Qué método de VecDeque añade al final?",
  ["Four directions, no diagonals. Deep grids hit the recursion limit near 1000: an explicit stack of (r, c) fixes that."] = "Cuatro direcciones, sin diagonales. Las cuadrículas profundas chocan con el límite de recursión cerca de 1000: una pila explícita de (r, c) lo arregla.",
  ["Four hundred HTTP calls, and four hundred image resizes. Same code, different executor."] = "Cuatrocientas llamadas HTTP y cuatrocientas reducciones de imagen. El mismo código, distinto executor.",
  ["Four hundred image resizes, eight cores. Which executor class?"] = "Cuatrocientas imágenes que reducir, ocho núcleos. ¿Qué clase de executor?",
  ["Four letters, a Greek one. Resets to 0 in every const block, +1 per line."] = "Cuatro letras, una griega. Vuelve a 0 en cada bloque const, +1 por línea.",
  ["Four letters, a preposition. It replaces try/finally: f.close() for the common case."] = "Cuatro letras, una preposición. Sustituye a try/finally: f.close() para el caso común.",
  ["Four letters, as in workspace. Go 1.18. It writes a go.work file beside the two folders."] = "Cuatro letras, como en workspace. Go 1.18. Escribe un fichero go.work junto a las dos carpetas.",
  ["Four letters, capital K. slices.Sorted(maps.Keys(m)) gives a sorted slice."] = "Cuatro letras, K mayúscula. slices.Sorted(maps.Keys(m)) da un slice ordenado.",
  ["Four letters, capital O. Its only method is Do."] = "Cuatro letras, O mayúscula. Su único método es Do.",
  ["Four letters, capital S. SortFunc takes a compare function."] = "Cuatro letras, S mayúscula. SortFunc recibe una función de comparación.",
  ["Four letters, capitalised. The same name threading uses, and Go calls it sync.Mutex."] = "Cuatro letras, en mayúscula inicial. El mismo nombre que usa threading, y Go lo llama sync.Mutex.",
  ["Four letters, capitalized; Go calls it a Mutex. with acquires and releases it."] = "Cuatro letras, con mayúscula; Go lo llama Mutex. with lo adquiere y lo libera.",
  ["Four letters, plural of what you look a value up by."] = "Cuatro letras, plural de aquello con lo que buscas un valor.",
  ["Four letters, short for implementation. Go attaches methods one by one; Rust groups them."] = "Cuatro letras, abreviatura de implementation. Go añade métodos uno a uno; Rust los agrupa.",
  ["Four letters, short for receive. Returns Result<Job, RecvError>. try_recv would not wait."] = "Cuatro letras, abreviatura de receive en inglés. Devuelve Result<Job, RecvError>. try_recv no esperaría.",
  ["Four letters, the append of every Vec."] = "Cuatro letras, el método para añadir de todo Vec.",
  ["Four letters, the opposite of Store."] = "Cuatro letras, lo contrario de Store.",
  ["Four letters, the opposite of first. The length is stored, so no counting."] = "Cuatro letras, lo contrario de first. La longitud está guardada, así que no hay que contar.",
  ["Four letters, the opposite of send, cut short."] = "Cuatro letras, lo contrario de send, recortado.",
  ["Four letters, the same word Go uses for a set of workers reading one channel."] = "Cuatro letras, la misma palabra que usa Go para un conjunto de workers que leen un channel.",
  ["Four letters, the same word Rust's JoinHandle uses. Go spells it wg.Wait()."] = "Cuatro letras, la misma palabra que usa el JoinHandle de Rust. Go lo escribe wg.Wait().",
  ["Four letters, the same word as Thread.join, but on the queue: wait until the count of unfinished tasks is zero."] = "Cuatro letras, la misma palabra que Thread.join, pero sobre la cola: esperar hasta que el recuento de tareas sin terminar sea cero.",
  ["Four letters, the same word threading uses. Go spells it wg.Wait()."] = "Cuatro letras, la misma palabra que usa threading. Go lo escribe wg.Wait().",
  ["Four letters, the start of iterator. A for loop calls it for you."] = "Cuatro letras, el inicio de iterator. Un bucle for la llama por ti.",
  ["Four letters, the type of true. map[T]struct{} saves a byte per entry and is the other idiom."] = "Cuatro letras, el tipo de true. map[T]struct{} ahorra un byte por entrada y es el otro idiom.",
  ["Four letters, the type {} makes. A list of pairs would need a scan, O(n)."] = "Cuatro letras, el tipo que crea {}. Una lista de pares necesitaría un barrido, O(n).",
  ["Four letters, the word in the warning itself. It also works on go run and go build."] = "Cuatro letras, la palabra que aparece en el propio aviso. También sirve con go run y go build.",
  ["Four letters, to enumerate. -m means modules rather than packages; -u adds available upgrades."] = "Cuatro letras, enumerar. -m significa módulos en vez de paquetes; -u añade las actualizaciones disponibles.",
  ["Four letters, what a shell puts between two commands. It returns two ends."] = "Cuatro letras, lo que un shell pone entre dos órdenes. Devuelve dos extremos.",
  ["Four letters. An alias of int32. byte is the alias of uint8."] = "Cuatro letras. Un alias de int32. byte es el alias de uint8.",
  ["Four letters. Consumes the handle and returns Result<T, Box<dyn Any + Send>>."] = "Cuatro letras. Consume el handle y devuelve Result<T, Box<dyn Any + Send>>.",
  ["Four letters. Every file may have one; the runtime calls it for you."] = "Cuatro letras. Cada archivo puede tener una; el runtime la llama por ti.",
  ["Four letters. Go fakes it with const and iota; Rust has the real thing."] = "Cuatro letras. Go lo imita con const e iota; Rust tiene el de verdad.",
  ["Four letters. Go writes for { } with no condition; Rust has a word for it."] = "Cuatro letras. Go escribe for { } sin condición; Rust tiene una palabra para eso.",
  ["Four letters. Go's append, but it changes the Vec in place, so it needs mut."] = "Cuatro letras. El append de Go, pero cambia el Vec en el sitio, así que necesita mut.",
  ["Four letters. Go's receiver (o *Order), Rust's &self, but here it is an ordinary parameter by convention."] = "Cuatro letras. El receptor de Go (o *Order), el &self de Rust, pero aquí es un parámetro ordinario por convención.",
  ["Four letters. It also builds maps and channels."] = "Cuatro letras. También construye maps y channels.",
  ["Four letters. It answers the question 'what type is this'. isinstance(x, float) is the check you use in code."] = "Cuatro letras. Responde a '¿qué tipo es esto?'. isinstance(x, float) es la comprobación que usas en el código.",
  ["Four letters. It counts the group down; Add counted it up."] = "Cuatro letras. Descuenta uno del grupo; Add lo había sumado.",
  ["Four letters. Let go of it now instead of at the end of scope."] = "Cuatro letras. Suéltalo ahora en vez de al final del scope.",
  ["Four letters. Like std::mem::take: gives you the value, puts the default (None) back."] = "Cuatro letras. Como std::mem::take: te da el valor y deja el valor por defecto (None) en su sitio.",
  ["Four letters. Not copied: the heap buffer changed hands."] = "Cuatro letras. No se copió: el buffer del heap cambió de manos.",
  ["Four letters. Take it, do not borrow it."] = "Cuatro letras. Tómalo, no lo prestes.",
  ["Four letters. The From trait gives it to you. to_string() does the same job."] = "Cuatro letras. El trait From te lo da. to_string() hace el mismo trabajo.",
  ["Four letters. The block gets one from the operating system, like a file in /dev/shm."] = "Cuatro letras. El bloque recibe uno del sistema operativo, como un fichero en /dev/shm.",
  ["Four letters. The borrowing one. into_ in front of it would consume the Vec."] = "Cuatro letras. El que toma prestado. Con into_ delante consumiría el Vec.",
  ["Four letters. The channel is closed when the context is finished, so every watcher wakes at once."] = "Cuatro letras. El channel se cierra cuando el context termina, así que todos los vigilantes despiertan a la vez.",
  ["Four letters. The opposite of None."] = "Cuatro letras. Lo contrario de None.",
  ["Four letters. The same keyword that opens a block of methods, used as a type."] = "Cuatro letras. La misma palabra clave que abre un bloque de métodos, usada como tipo.",
  ["Four letters. The same rule Go applies to a local variable you never read."] = "Cuatro letras. La misma regla que Go aplica a una variable local que nunca lees.",
  ["Four letters. The same word that starts an implementation block."] = "Cuatro letras. La misma palabra que abre un bloque de implementación.",
  ["Four letters. The same word you put in the attribute over the function."] = "Cuatro letras. La misma palabra que pones en el atributo sobre la función.",
  ["Four letters. The word that follows if. The block must diverge: return, break, panic."] = "Cuatro letras. La palabra que sigue a if. El bloque debe divergir: return, break, panic.",
  ["Four letters. Threads use the same word to wait for each other."] = "Cuatro letras. Los hilos usan la misma palabra para esperarse unos a otros.",
  ["Four letters. What Rust does for you at the end of every scope, called by hand."] = "Cuatro letras. Lo que Rust hace por ti al final de cada scope, llamado a mano.",
  ["Four letters. What you do to a menu."] = "Cuatro letras. Lo que haces con un menú, en inglés.",
  ["Four letters. What you do to a paper napkin, over and over, into one small square."] = "Cuatro letras. Lo que haces con una servilleta de papel, una y otra vez, hasta un cuadradito (doblar, en inglés).",
  ["Four letters. What you do to the drawer at closing time."] = "Cuatro letras. Lo que haces con el cajón al cerrar, en inglés.",
  ["Four letters. What you do with a parcel."] = "Cuatro letras. Lo que haces con un paquete, en inglés.",
  ["Four letters. Where two roads meet again."] = "Cuatro letras. Donde dos caminos se vuelven a unir, en inglés.",
  ["Four letters. fork gives one lazily, spawn makes one from the pickle. Either way it is not yours."] = "Cuatro letras. fork te da una de forma perezosa y spawn la crea desde el pickle. En cualquier caso no es la tuya.",
  ["Four letters: a look at the top. Returns Option<&T>, hence the * and the unwrap."] = "Cuatro letras: un vistazo a la cima. Devuelve Option<&T>, de ahí el * y el unwrap.",
  ["Four letters: else and if squeezed into one word."] = "Cuatro letras: else e if apretados en una palabra.",
  ["Four letters: make it neat. Run it before every commit."] = "Cuatro letras: ponlo en orden. Ejecútalo antes de cada commit.",
  ["Four letters: my, and the language's first two. pyright is the other common one."] = "Cuatro letras: my, y las dos primeras del lenguaje. pyright es la otra común.",
  ["Four letters: the one after this one. Rust's iterator method has the same name."] = "Cuatro letras: el que viene después de este. El método del iterador de Rust tiene el mismo nombre.",
  ["Four letters: to clean up. The error message itself tells you the command."] = "Cuatro letras: ordenar. El propio mensaje de error te dice el comando.",
  ["Four letters: what the threads finally are, and what the build is called."] = "Cuatro letras: lo que por fin son los hilos, y también el nombre de la compilación.",
  ["Four quests: BASIC, ADVANCED, DELIVERY, CODE RUSH. Q switches."] = "Cuatro misiones: BÁSICA, AVANZADA, ENTREGA, CODE RUSH. Q cambia.",
  ["Four recursive calls, each O(1) plus its own flood: every cell is sunk once, so the whole grid is O(rows * cols)."] = "Cuatro llamadas recursivas, cada una O(1) más su propia inundación: cada celda se hunde una vez, así que toda la cuadrícula es O(rows * cols).",
  ["Four workers, many eggs, no hand-made threads. Which executor from concurrent.futures?"] = "Cuatro trabajadores, muchos huevos, sin hilos hechos a mano. ¿Qué ejecutor de concurrent.futures?",
  ["Fprintf writes to any io.Writer: files, buffers, network, ResponseWriter."] = "Fprintf escribe en cualquier io.Writer: archivos, buffers, red, ResponseWriter.",
  ["Free the tray right now, before the end of the block. Which function?"] = "Libera la bandeja ahora mismo, antes del final del bloque. ¿Qué función?",
  ["From a str. Two words with an underscore, like the FromStr trait in lowercase."] = "Desde un str. Dos palabras con guion bajo, como el trait FromStr en minúsculas.",
  ["From m to the end. a[:m] and a[m:] cover the slice exactly once."] = "Desde m hasta el final. a[:m] y a[m:] cubren el slice exactamente una vez.",
  ["Functions and Option"] = "Funciones y Option",
  ["Functions and returns"] = "Funciones y retornos",
  ["Futures need a runtime. Which attribute makes main async on tokio?"] = "Los Futures necesitan un runtime. ¿Qué atributo hace main async en tokio?",
  ["GO SET  -  the walk"] = "GO SET  -  el paseo",
  ["GO plus the word for not public, all capitals. A comma-separated list of path globs."] = "GO más la palabra para no público, en mayúsculas. Una lista separada por comas de patrones de ruta.",
  ["GO, then the three letters of the file, all capitals. It walks up from the current directory."] = "GO y luego las tres letras del fichero, en mayúsculas. Sube desde el directorio actual.",
  ["GOMAXPROCS(0) reports without changing it. Thousands of goroutines still exist; only this many are running Go code at any instant."] = "GOMAXPROCS(0) informa sin cambiar nada. Siguen existiendo miles de goroutines; solo estas ejecutan código Go en un instante dado.",
  ["GOPATH still exists as the download cache ($GOPATH/pkg/mod) and the go install bin dir, but your code lives wherever you like."] = "GOPATH sigue existiendo como caché de descargas ($GOPATH/pkg/mod) y como bin de go install, pero tu código vive donde quieras.",
  ["GOPRIVATE sets GONOPROXY and GONOSUMDB together: those modules skip the proxy and the checksum database, and their hashes go only in your go.sum."] = "GOPRIVATE fija a la vez GONOPROXY y GONOSUMDB: esos módulos se saltan el proxy y la base de datos de checksums, y sus hashes solo van a tu go.sum.",
  ["GOPROXY, GOPRIVATE, ssh"] = "GOPROXY, GOPRIVATE, ssh",
  ["Generators and iterators"] = "Generadores e iteradores",
  ["Generics and trait bounds"] = "Genéricos y trait bounds",
  ["Generics, embedding, closures"] = "Genéricos, embedding, closures",
  ["Generics. Say <T> and tell the compiler what T can do."] = "Genéricos. Di <T> y cuéntale al compilador qué puede hacer T.",
  ["Get the guard so you can change the counter. Which method?"] = "Consigue el guard para poder cambiar el contador. ¿Qué método?",
  ["Get, Put and evict all O(1): that is the whole point of the LRU question."] = "Get, Put y expulsar, todos O(1): ese es todo el sentido de la pregunta LRU.",
  ["Get: a hit becomes the most recently used. Which list method moves the node to the front?"] = "Get: un acierto pasa a ser el más recientemente usado. ¿Qué método de la lista mueve el nodo al frente?",
  ["Give me a pipe. Send on one end, I receive on the other."] = "Dame una tubería. Envía por un extremo, yo recibo por el otro.",
  ["Give the ETA call two seconds and no more. Which constructor?"] = "Dale a la llamada del ETA dos segundos y ni uno más. ¿Qué constructor?",
  ["Give the error a human message for {}. Which fmt trait?"] = "Dale al error un mensaje humano para {}. ¿Qué trait de fmt?",
  ["Give the future room for one result so a lost caller cannot strand the goroutine."] = "Dale al future sitio para un resultado, para que un llamador perdido no deje varada a la goroutine.",
  ["Give the opened file a name inside the block. Which keyword?"] = "Darle un nombre al archivo abierto dentro del bloque. ¿Qué palabra clave?",
  ["Give up after one second. Fill: case <-time.___(time.Second)"] = "Ríndete tras un segundo. Completa: case <-time.___(time.Second)",
  ["Gives index and value. The blank _ throws the index away."] = "Da índice y valor. El _ descarta el índice.",
  ["Global Interpreter Lock, by its initials."] = "Global Interpreter Lock, por sus iniciales.",
  ["Global Interpreter Lock, said as one word."] = "Global Interpreter Lock, dicho como una sola palabra.",
  ["Go + routine. Not a full OS thread. The scheduler parks them."] = "Go + routine. No es un hilo completo del SO. El planificador las aparca.",
  ["Go 1.21 has a builtin for the smaller of two numbers."] = "Go 1.21 tiene una función integrada para el menor de dos números.",
  ["Go 1.21 wraps that pattern and caches the result. Which sync helper?"] = "Go 1.21 envuelve ese patrón y además guarda el resultado. ¿Qué ayudante de sync?",
  ["Go 1.21-1.23: slices, maps, min, iterators"] = "Go 1.21-1.23: slices, maps, min, iteradores",
  ["Go 1.22 loops over a plain number. Fill: for i := ___ 3"] = "Go 1.22 itera sobre un número a secas. Completa: for i := ___ 3",
  ["Go finds the nearest go.mod above you. A second go.mod in a subdirectory starts a different module, which is almost never what you meant."] = "Go encuentra el go.mod más cercano por encima de ti. Un segundo go.mod en un subdirectorio empieza otro módulo, que casi nunca es lo que querías.",
  ["Go had goroutines. Where is the go keyword?"] = "Go tenía goroutines. ¿Dónde está la palabra go?",
  ["Go has no async and no await, on purpose. A goroutine plus a buffered channel is a future: go starts it, <-ch awaits it. The runtime parks a goroutine that blocks on I/O and runs another on the same OS thread, so ordinary blocking code is already asynchronous. errgroup runs a batch and returns the first error; runtime.NumGoroutine() shows the ones you forgot to stop."] = "Go no tiene async ni await, y es a propósito. Una goroutine más un channel con buffer es un future: go lo arranca, <-ch lo espera. El runtime aparca una goroutine bloqueada en E/S y ejecuta otra en el mismo hilo del sistema, así que el código bloqueante corriente ya es asíncrono. errgroup ejecuta un lote y devuelve el primer error; runtime.NumGoroutine() muestra las que olvidaste parar.",
  ["Go has no set type; a map to this type is the idiom. struct{} also works."] = "Go no tiene tipo set; un map a este tipo es el idiom. struct{} también sirve.",
  ["Go has no while. Which keyword loops while i < 8?"] = "Go no tiene while. ¿Qué palabra clave repite mientras i < 8?",
  ["Go has one loop: for. if needs no parentheses. range walks a slice."] = "Go tiene un bucle: for. if no necesita paréntesis. range recorre un slice.",
  ["Go has structs and methods. Here the method gets self by hand?"] = "Go tiene structs y métodos. ¿Aquí el método recibe self a mano?",
  ["Go never converts numbers silently. Type name, then parentheses. 64-bit float."] = "Go nunca convierte números en silencio. Nombre del tipo y luego paréntesis. Float de 64 bits.",
  ["Go never leaves a variable uninitialized. Numbers start here."] = "Go nunca deja una variable sin inicializar. Los números empiezan aquí.",
  ["Go returns errors. Python throws them. Catch the one you expect, let the rest fly."] = "Go devuelve errores. Python los lanza. Captura el que esperas, deja volar el resto.",
  ["Go spells every loop for; Python has this second word for the condition-only loop."] = "Go escribe todos los bucles con for; Python tiene esta segunda palabra para el bucle de solo condición.",
  ["Go, Chef! Same seven rounds as this afternoon. The memo one is a one-liner in Python."] = "¡Vamos, chef! Las mismas siete rondas que esta tarde. La del memo es una sola línea en Python.",
  ["Go, Mei! I did this show at lunch. The memo one gets everybody."] = "¡Vamos, Mei! Yo hice este programa al mediodía. La del memo pilla a todo el mundo.",
  ["Goroutines"] = "Goroutines",
  ["Goroutines, then. What is the Python word?"] = "Goroutines, entonces. ¿Cuál es la palabra en Python?",
  ["Graphs: BFS and DFS"] = "Grafos: BFS y DFS",
  ["Greater than or equal. With > alone, g[g.len()] would panic."] = "Mayor o igual. Solo con >, g[g.len()] haría panic.",
  ["Greedy fails on coins {1,3,4} for 6 (4+1+1). DP tries every last coin and finds 3+3."] = "El voraz falla con monedas {1,3,4} para 6 (4+1+1). DP prueba cada última moneda y encuentra 3+3.",
  ["Grill and Wok are different sizes. What element type lets one Vec hold both?"] = "Grill y Wok tienen tamaños distintos. ¿Qué tipo de elemento deja que un Vec guarde ambos?",
  ["Grill promises to be a Cook. Complete the header."] = "Grill promete ser un Cook. Completa la cabecera.",
  ["Grill, wok, steamer. Every station must answer name() and greet()."] = "Parrilla, wok, vaporera. Cada estación debe responder name() y greet().",
  ["Group an item name and a quantity under one named type. Which keyword?"] = "Agrupa el nombre de un artículo y una cantidad bajo un tipo con nombre. ¿Qué palabra clave?",
  ["Group name and price in one type. Which keyword?"] = "Agrupa nombre y precio en un tipo. ¿Qué palabra clave?",
  ["Grow a slice by one hash brown. Which built-in?"] = "Agranda un slice con un hash brown más. ¿Qué función integrada?",
  ["HERE"] = "AQUÍ",
  ["HIDE"] = "OCULTAR",
  ["HINT"] = "PISTA",
  ["Half-open [lo, hi): loop while lo < hi, no off-by-one."] = "Semiabierto [lo, hi): bucle mientras lo < hi, sin error de uno de más.",
  ["Halve the gap. (lo+hi)/2 can overflow in other languages; this form never does."] = "Divide la distancia a la mitad. (lo+hi)/2 puede desbordarse en otros lenguajes; esta forma nunca.",
  ["Halve, halve, halve, then zip the halves back together. Ties go left."] = "Parte por la mitad, otra vez y otra, y luego cose las mitades. Los empates van a la izquierda.",
  ["Halving gives log n levels. Integer division: 5 / 2 is 2, and that is fine."] = "Partir por la mitad da log n niveles. División entera: 5 / 2 es 2, y está bien.",
  ["Hand both values back to the caller. Which keyword?"] = "Devuelve ambos valores a quien llama. ¿Qué palabra clave?",
  ["Hand out one bowl at a time and pause. Which keyword makes a function a generator?"] = "Entregar un bol a la vez y pausar. ¿Qué palabra clave convierte una función en generador?",
  ["Hand the total back to the caller. Which keyword?"] = "Devolver el total a quien llama. ¿Qué palabra clave?",
  ["Hand the value to one owner over a channel and there is nothing to lock. The order belongs to whoever received it."] = "Entrega el valor a un único dueño por un channel y no queda nada que bloquear. El pedido es de quien lo recibió.",
  ["Handle + Func. Plain Handle takes an http.Handler value instead."] = "Handle + Func. Handle a secas recibe en cambio un valor http.Handler.",
  ["HandleFunc maps a path to func(w, r). Fprintf(w) replies. ListenAndServe runs."] = "HandleFunc asocia una ruta a func(w, r). Fprintf(w) responde. ListenAndServe arranca.",
  ['HandleFunc registers on the default mux. Go 1.22 routes can say "GET /order/{id}".'] = 'HandleFunc registra en el mux por defecto. Las rutas de Go 1.22 pueden decir "GET /order/{id}".',
  ["Hash brown on one burner. Muffin on another. Both at once."] = "Hash brown en un fogón. Muffin en otro. Los dos a la vez.",
  ["Hash maps, chars and counts"] = "Hash maps, chars y conteos",
  ["HashMap: O(1) average, O(n) worst case when everything collides. BTreeMap is O(log n) but ordered."] = "HashMap: O(1) en promedio, O(n) en el peor caso cuando todo colisiona. BTreeMap es O(log n) pero ordenado.",
  ["HashMap<u32, Vec<u32>>: O(1) to find a station, then its neighbours in order. g[&n] panics on a missing key; get returns Option."] = "HashMap<u32, Vec<u32>>: O(1) para encontrar una estación, luego sus vecinos en orden. g[&n] hace panic con una clave que falta; get devuelve Option.",
  ["HashSet: one O(1) insert per guest, O(n) total. Fifty million checks become ten thousand."] = "HashSet: un insert O(1) por invitado, O(n) en total. Cincuenta millones de comprobaciones se vuelven diez mil.",
  ["Have we seen the partner of x? Fill the lookup: seen[target-x]"] = "¿Ya vimos la pareja de x? Completa la búsqueda: seen[target-x]",
  ["Height is one plus the taller child. Which built-in picks the taller?"] = "La altura es uno más el hijo más alto. ¿Qué función integrada elige el más alto?",
  ["Height is one plus the taller subtree. Fill: 1 + max(height(n.Left), height(n.___))"] = "La altura es uno más el subárbol más alto. Completa: 1 + max(height(n.Left), height(n.___))",
  ["Hello, Python"] = "Hola, Python",
  ["Hello, Rust"] = "Hola, Rust",
  ["Hints document types without enforcing them: def f(x: int) -> str. list[str], dict[str, float], Optional[str]. mypy checks them before you run."] = "Las anotaciones documentan tipos sin imponerlos: def f(x: int) -> str. list[str], dict[str, float], Optional[str]. mypy las comprueba antes de ejecutar.",
  ["How big a batch each worker collects per trip. One word, no underscore."] = "Cómo de grande es el lote que recoge cada worker por trayecto. Una palabra, sin guion bajo.",
  ["How many goroutines may run Go code at the same instant? Which setting?"] = "¿Cuántas goroutines pueden ejecutar código Go en el mismo instante? ¿Qué ajuste?",
  ["How many items are in prices? Which method returns a usize?"] = "¿Cuántos elementos hay en prices? ¿Qué método devuelve un usize?",
  ["How many items are in the slice right now? Which built-in?"] = "¿Cuántos elementos hay en el slice ahora mismo? ¿Qué función integrada?",
  ["How many items fit before append must reallocate? Which built-in?"] = "¿Cuántos elementos caben antes de que append deba reservar de nuevo? ¿Qué función integrada?",
  ["How many trays? Which built-in counts a list?"] = "¿Cuántas bandejas? ¿Qué función integrada cuenta una lista?",
  ["How many workers? Ask the machine. Which function?"] = "¿Cuántos workers? Pregúntaselo a la máquina. ¿Qué función?",
  ["How much room does the belt have in total? Which builtin?"] = "¿Cuánto sitio tiene la cinta en total? ¿Qué función integrada?",
  ["I copied the threading code, changed one word, and the script started itself forever."] = "Copié el código de threading, cambié una palabra y el script empezó a arrancarse a sí mismo sin parar.",
  ["I do not want to tag a release every time I change a line. Point it at my folder."] = "No quiero etiquetar una release cada vez que cambio una línea. Apúntala a mi carpeta.",
  ["I gave the photo job eight threads. The fan spun up and the clock did not move."] = "Le di ocho hilos al trabajo de las fotos. El ventilador se puso a girar y el reloj no se movió.",
  ["I made the repo private and go get says 404, even though I can clone it fine."] = "Hice privado el repo y go get dice 404, aunque yo lo clono sin problema.",
  ["If dp[amount] never dropped below the marker, no combination works. What does the function return then?"] = "Si dp[amount] nunca bajó del marcador, ninguna combinación sirve. ¿Qué devuelve entonces la función?",
  ["If no combination reaches the amount, its cell still holds the sentinel. Return what?"] = "Si ninguna combinación alcanza el importe, su celda aún guarda el centinela. ¿Qué devolver?",
  ["If the amount is still infinite, no coins reach it. What does the function return then?"] = "Si la cantidad sigue en infinito, ninguna moneda la alcanza. ¿Qué devuelve la función entonces?",
  ["If the guest leaves, cancel. The fryer stops."] = "Si el cliente se va, cancela. La freidora para.",
  ["If there is a loop the fast runner laps the slow one. O(1) memory."] = "Si hay un bucle, el corredor rápido alcanza al lento. Memoria O(1).",
  ["If you miss the word, write it yourself. Fill the body of Await."] = "Si echas de menos la palabra, escríbela tú. Rellena el cuerpo de Await.",
  ["Import from GitHub"] = "Importar desde GitHub",
  ["Import the package from main.go. Write the whole path."] = "Importa el paquete desde main.go. Escribe la ruta entera.",
  ["In Go I would write a json tag. Show me the Rust way."] = "En Go escribiría un tag json. Muéstrame cómo se hace en Rust.",
  ["In Go this was three pointers. In Rust, who owns the next node?"] = "En Go esto eran tres punteros. En Rust, ¿quién posee el nodo siguiente?",
  ["In JavaScript I would write await fetchMenu(). Go's editor does not even know the word."] = "En JavaScript escribiría await fetchMenu(). El editor de Go ni conoce la palabra.",
  ["In Rust the compiler stops you. In Go nothing stops you, so the race detector is the compiler you run at test time."] = "En Rust te para el compilador. En Go no te para nada, así que el detector de carreras es el compilador que ejecutas al probar.",
  ["In Rust, if gives back a value. No ternary needed. The gate forgot its else."] = "En Rust, if devuelve un valor. No hace falta ternario. La puerta olvidó su else.",
  ["In a {start, end} pair, the end is the second element."] = "En un par {inicio, fin}, el fin es el segundo elemento.",
  ["In order, smallest to largest. The line above the search does it."] = "En orden, de menor a mayor. La línea encima de la búsqueda lo hace.",
  ["In real code None is more honest. key in self.d is O(1): a hash lookup."] = "En código real None es más honesto. key in self.d es O(1): una búsqueda por hash.",
  ["In real code: sort a slice of structs by price. Fill: sort.___(orders, func(i, j int) bool {...})"] = "En código real: ordena un slice de structs por precio. Completa: sort.___(orders, func(i, j int) bool {...})",
  ["In-order on a BST yields sorted output. Pre-order (self first) copies a tree; post-order (self last) frees one."] = "El recorrido en orden de un BST produce salida ordenada. El preorden (uno mismo primero) copia un árbol; el postorden (uno mismo último) lo libera.",
  ["In-order on a BST yields sorted output. Pre-order: node first. Post-order: node last."] = "In-order en un BST da salida ordenada. Pre-order: nodo primero. Post-order: nodo al final.",
  ["In-order walk: left subtree, this node, then which subtree? That gives sorted output."] = "Recorrido en orden: subárbol izquierdo, este nodo, ¿y luego qué subárbol? Eso da salida ordenada.",
  ["Inclusive count from l to r: the difference, plus one."] = "Conteo inclusivo de l a r: la diferencia, más uno.",
  ["Increment a counter without a mutex. Which package? ___.AddInt64(&count, 1)"] = "Incrementa un contador sin mutex. ¿Qué package? ___.AddInt64(&count, 1)",
  ["Indexes start at 0, so the last one is one less than the count. len itself is O(1): Go keeps it in the slice header."] = "Los índices empiezan en 0, así que el último es uno menos que la cuenta. len en sí es O(1): Go lo guarda en la cabecera del slice.",
  ["Indexes start at 0, so the last one is the length less one. One character."] = "Los índices empiezan en 0, así que el último es la longitud menos uno. Un carácter.",
  ["Insert at the recent end and get the new node back."] = "Inserta en el extremo reciente y recibe el nodo nuevo.",
  ["Inside Lucky Mac Express the kitchen runs on Rust threads. Earn the tea set."] = "Dentro de Lucky Mac Express la cocina funciona con hilos de Rust. Gánate la merienda.",
  ["Inside Lucky Mac the kitchen runs on goroutines. Earn the morning set."] = "Dentro de Lucky Mac la cocina funciona con goroutines. Gánate el desayuno.",
  ["Inside a workspace every listed module is built from disk, so a change in luckymac is seen by cousinshop on the next build. go.work is for your machine; do not commit it."] = "Dentro de un espacio de trabajo cada módulo listado se compila desde disco, así que un cambio en luckymac lo ve cousinshop en la siguiente compilación. go.work es para tu máquina; no lo subas.",
  ["Is ErrCold anywhere in that chain? Fill: errors.___(err, ErrCold)"] = "¿Está ErrCold en algún punto de esa cadena? Completa: errors.___(err, ErrCold)",
  ["Is a name in the Vec? Without a set you must look at each one. Which iterator adapter stops at the first match?"] = "¿Hay un nombre en el Vec? Sin un set debes mirar cada uno. ¿Qué adaptador de iterador se detiene en la primera coincidencia?",
  ["Is a name in the list? Python has a keyword for it, but on a list it scans. Which keyword?"] = "¿Hay un nombre en la lista? Python tiene una palabra clave para ello, pero sobre una lista barre. ¿Qué palabra clave?",
  ["Is a name in the slice? Without a map you must look at each one. Which keyword walks the slice?"] = "¿Hay un nombre en el slice? Sin un map debes mirar cada uno. ¿Qué palabra clave recorre el slice?",
  ['Is muffin on the list? Fill: slices.___(names, "muffin")'] = '¿Está muffin en la lista? Completa: slices.___(names, "muffin")',
  ["Is the ETA Some and under 10 minutes, in one call, no unwrap? Which Option method?"] = "¿El ETA es Some y menor de 10 minutos, en una llamada, sin unwrap? ¿Qué método de Option?",
  ["It appended to its own copy. Nothing crosses a process boundary unless you send it."] = "Hizo append en su propia copia. Nada cruza la frontera de un proceso si no lo envías.",
  ["It closes over n. Inner func, outer variable."] = "Se cierra sobre n. func interna, variable externa.",
  ["It did not fall over. It just made the kitchen printer thrash. Give me a queue and a few workers."] = "No se cayó. Solo volvió loca a la impresora de cocina. Dame una cola y unos cuantos workers.",
  ['It is an error, not a warning, so dead imports never pile up. goimports adds and removes them for you; _ "pkg" keeps one only for its init side effect.'] = 'Es un error, no un aviso, así que los imports muertos nunca se acumulan. goimports los añade y quita por ti; _ "pkg" conserva uno solo por su efecto de init.',
  ["It is an operating-system semaphore under the hood, so it works across processes. Like a Queue, it must be created in the parent and passed down."] = "Por debajo es un semáforo del sistema operativo, así que funciona entre procesos. Como una Queue, hay que crearlo en el padre y pasarlo hacia abajo.",
  ["It returns the *Element the map needs. An existing key is an update plus a touch, not a second node."] = "Devuelve el *Element que el map necesita. Una clave existente es una actualización más un toque, no un segundo nodo.",
  ["It runs on your laptop. Make it build on the shop's machine."] = "Corre en tu laptop. Haz que compile en la máquina de la tienda.",
  ["It's DFS, Mei, same as the MTR round, but the neighbours are up, down, left, right. Mind the usize!"] = "Es DFS, Mei, igual que la ronda del MTR, pero los vecinos son arriba, abajo, izquierda, derecha. ¡Cuidado con el usize!",
  ["It's fib in a hat, Chef. Then the coin one: fewest coins for the exact change."] = "Es fib disfrazado, chef. Luego la de las monedas: las menos monedas para el cambio exacto.",
  ["It's fib with a table instead of a memo. Bottom up, Mei. No recursion, no stack overflow."] = "Es fib con una tabla en vez de un memo. De abajo arriba, Mei. Sin recursión, sin stack overflow.",
  ["It's the graph round in disguise, Bo. Sink every island as you find it, and count the finds."] = "Es la ronda de grafos disfrazada, Bo. Hunde cada isla en cuanto la encuentres, y cuenta los hallazgos.",
  ["Iterator::eq compares two iterators without building a String. chars() walks Unicode scalars, not bytes."] = "Iterator::eq compara dos iteradores sin construir un String. chars() recorre escalares Unicode, no bytes.",
  ["Iterators and closures"] = "Iteradores y closures",
  ["JoinHandle<T>: T is what the closure returns, here (). Drop the handle and the thread is detached, still running."] = "JoinHandle<T>: T es lo que devuelve el closure, aquí (). Suelta el handle y el thread queda suelto, todavía corriendo.",
  ["Jumps to the next iteration. break would leave the loop entirely."] = "Salta a la siguiente iteración. break saldría del bucle por completo.",
  ["Just the size, no coefficient. 2n, 3n and n/2 are all the same order."] = "Solo el tamaño, sin coeficiente. 2n, 3n y n/2 son todos el mismo orden.",
  ["Just the size, no coefficient. 2n, 3n and n/2 are the same order."] = "Solo el tamaño, sin coeficiente. 2n, 3n y n/2 son el mismo orden.",
  ["Just the sum. Adding a semicolon would turn it into a statement and return ()."] = "Solo la suma. Añadir punto y coma la convertiría en sentencia y devolvería ().",
  ["Kadane's algorithm: O(n), one pass, two variables. A negative prefix is never worth keeping."] = "El algoritmo de Kadane: O(n), una pasada, dos variables. Un prefijo negativo nunca vale la pena conservarlo.",
  ["Kadane's algorithm: O(n), one pass, two variables. A negative run never helps, so it is dropped."] = "El algoritmo de Kadane: O(n), una pasada, dos variables. Una racha negativa nunca ayuda, así que se descarta.",
  ["Kadane's algorithm: a negative run is worth dropping. O(n) time, O(1) space, no nested loop."] = "El algoritmo de Kadane: una racha negativa conviene soltarla. O(n) tiempo, O(1) espacio, sin bucle anidado.",
  ["Kadane: at each x, extend the run or restart at x, keep the best. A fixed window adds the newcomer and drops a[i-k]. Two pointers only move right: O(n) for the longest substring without repeats."] = "Kadane: en cada x, extiende la racha o reinicia en x, guarda la mejor. Una ventana fija suma al recién llegado y quita a[i-k]. Dos punteros que solo avanzan a la derecha: O(n) para la subcadena más larga sin repetidos.",
  ["Kadane: cur = max(x, cur + x), best = max(best, cur). A fixed window adds one and drops one. A growing window moves l forward until the window is clean again."] = "Kadane: cur = max(x, cur + x), best = max(best, cur). Una ventana fija suma uno y quita uno. Una ventana que crece mueve l hacia adelante hasta que la ventana vuelve a estar limpia.",
  ["Kadane: cur = x.max(cur + x). A fixed window adds the new item and drops the old one. A growing window moves its left end while a HashSet says repeat. Two pointers walk in from both ends of a sorted slice."] = "Kadane: cur = x.max(cur + x). Una ventana fija suma el elemento nuevo y quita el viejo. Una ventana que crece mueve su extremo izquierdo cuando un HashSet dice repetido. Dos punteros avanzan desde ambos extremos de un slice ordenado.",
  ["Keep a AND give b its own copy of the text. Which method?"] = "Conserva a Y dale a b su propia copia del texto. ¿Qué método?",
  ["Keep a tiny heap of the k biggest. Whatever falls out was never the answer."] = "Mantén un heap diminuto con los k mayores. Lo que se cae nunca fue la respuesta.",
  ["Keep only paid orders. Which adapter takes a bool closure?"] = "Conserva solo los pedidos pagados. ¿Qué adaptador recibe un closure que devuelve bool?",
  ["Keep only three, Chef. The smallest of the three is the answer; throw out anything smaller."] = "Guarda solo tres, chef. El menor de los tres es la respuesta; tira lo que sea más pequeño.",
  ["Keep serving as long as the queue is not empty. Which keyword loops on a condition?"] = "Seguir sirviendo mientras la cola no esté vacía. ¿Qué palabra clave repite con una condición?",
  ["Keyword chan, then the element type. make allocates it."] = "Palabra clave chan, luego el tipo del elemento. make lo asigna.",
  ["Kitchen should gain Grill's methods without wrapping. Put Grill where?"] = "Kitchen debe ganar los métodos de Grill sin envolverlo. ¿Dónde pones Grill?",
  ["Know the algorithm for the whiteboard, use the library in production."] = "Conoce el algoritmo para la pizarra, usa la librería en producción.",
  ["Kth largest: keep a min-heap of the k largest so far. When it grows past k, which heap call drops the smallest?"] = "K-ésimo mayor: mantén un min-heap con los k mayores hasta ahora. Cuando pasa de k, ¿qué llamada de heap descarta el menor?",
  ["LAND"] = "HORIZ.",
  ["LEVEL UP!  LV %d"] = "¡SUBES DE NIVEL!  LV %d",
  ["LRU cache"] = "Caché LRU",
  ["LRU: a HashMap for the values and a VecDeque for recency, fresh at the back, stale at the front. get moves the key to the back. put evicts the front when full, then inserts. The O(1) version swaps the VecDeque for a linked list."] = "LRU: un HashMap para los valores y un VecDeque para la recencia, fresco al final, viejo al frente. get mueve la clave al final. put expulsa el frente cuando está llena y luego inserta. La versión O(1) cambia el VecDeque por una lista enlazada.",
  ["LRU: a map from key to *list.Element plus a container/list in recency order. Get moves the node to the front, Put pushes a new one at the front, over capacity evicts l.Back() from both the list and the map. Every operation O(1)."] = "LRU: un map de clave a *list.Element más un container/list en orden de uso reciente. Get mueve el nodo al frente, Put mete uno nuevo al frente, al pasar la capacidad expulsa l.Back() tanto de la lista como del map. Toda operación O(1).",
  ["LRU: least recently used goes first. OrderedDict remembers order: move_to_end on every use, popitem(last=False) evicts the oldest. get and put are O(1). functools.lru_cache is the built-in."] = "LRU: el menos usado recientemente sale primero. OrderedDict recuerda el orden: move_to_end en cada uso, popitem(last=False) expulsa al más viejo. get y put son O(1). functools.lru_cache es la integrada.",
  ["LV %d   XP %d / %d"] = "LV %d   XP %d / %d",
  ["LV %d  ·  %d XP  ·  %d badges"] = "LV %d  ·  %d XP  ·  %d insignias",
  ["Last board of the night, Python column. Same question: input doubles, then what?"] = "Última pizarra de la noche, columna de Python. La misma pregunta: la entrada se duplica, ¿y entonces?",
  ["Last customers before the shutter. The queue script decides who gets a bowl."] = "Los últimos clientes antes de la persiana. El script de la cola decide quién se lleva un bol.",
  ["Last one. A map of Victoria Harbour as ones and zeros. How many islands?"] = "La última. Un mapa de Victoria Harbour en unos y ceros. ¿Cuántas islas?",
  ["Last ticket. Code review. Every match with one arm and an early return gets a modern spelling."] = "Último ticket. Revisión de código. Cada match con un brazo y un retorno temprano recibe una escritura moderna.",
  ["Laying out a repo"] = "Cómo organizar un repo",
  ["Least recently used. A map for the values and a queue for the order; every get is a touch."] = "La usada hace más tiempo. Un map para los valores y una cola para el orden; cada get es un toque.",
  ["Leave note out of the JSON when it is empty. Fill the tag option."] = "Deja note fuera del JSON cuando esté vacío. Completa la opción del tag.",
  ["Leave the function early when n is 0. Which keyword?"] = "Sal de la función antes cuando n es 0. ¿Qué palabra clave?",
  ["Leave the note out of the JSON when it is None. Which attribute?"] = "Deja la nota fuera del JSON cuando es None. ¿Qué atributo?",
  ["Left, node, right: a BST walked in order comes out sorted. if let on &Link needs no unwrap."] = "Izquierda, nodo, derecha: un BST recorrido en orden sale ordenado. if let sobre &Link no necesita unwrap.",
  ["Left, self, then which side, to print the values in sorted order?"] = "Izquierda, uno mismo, y luego ¿qué lado, para imprimir los valores en orden?",
  ["Left: the same row, one column back."] = "Izquierda: la misma fila, una columna atrás.",
  ["Len, Less, Swap take a value; Push and Pop take a pointer because they resize the slice."] = "Len, Less y Swap reciben un valor; Push y Pop reciben un puntero porque redimensionan el slice.",
  ["Less than or equal. With a strict < equal items would swap order and the sort would not be stable."] = "Menor o igual. Con un < estricto los elementos iguales cambiarían de orden y la ordenación no sería estable.",
  ["Less than or equal: the equal case is the touching pair."] = "Menor o igual: el caso igual es el par que se toca.",
  ["Less than, or equal. A strict < would take the right one on a tie and break stability."] = "Menor que, o igual. Un < estricto tomaría el de la derecha en un empate y rompería la estabilidad.",
  ["Let ? turn a ParseIntError into OrderError by itself. Which trait do you implement?"] = "Deja que ? convierta un ParseIntError en OrderError por sí solo. ¿Qué trait implementas?",
  ["Let count() read the String without taking it. Which symbol goes before the type?"] = "Deja que count() lea el String sin quedárselo. ¿Qué símbolo va antes del tipo?",
  ["Let println! print the whole struct with {:?}. Which attribute word generates Debug?"] = "Deja que println! imprima todo el struct con {:?}. ¿Qué palabra del atributo genera Debug?",
  ["Let serde write the JSON code for the struct. Which trait goes with Deserialize?"] = "Deja que serde escriba el código JSON del struct. ¿Qué trait acompaña a Deserialize?",
  ["Level by level with a deque: take from the front. Which method?"] = "Nivel a nivel con un deque: tomar del frente. ¿Qué método?",
  ["Lifetimes"] = "Lifetimes",
  ["Like %v, but with w for wrap. errors.Unwrap gets the inner error back."] = "Como %v, pero con w de wrap. errors.Unwrap recupera el error interno.",
  ["Like fmt.Errorf but on t. Fatalf would stop this test at once."] = "Como fmt.Errorf pero en t. Fatalf detendría este test al instante.",
  ["Like last(), with the suffix every mutable borrow in std carries."] = "Como last(), con el sufijo que lleva todo préstamo mutable en std.",
  ["Like unwrap, but with your own panic message. Which method?"] = "Como unwrap, pero con tu propio mensaje de panic. ¿Qué método?",
  ["Linear time"] = "Tiempo lineal",
  ["Linear: the work grows in step with the input. A one-word built-in is still a loop underneath."] = "Lineal: el trabajo crece al paso de la entrada. Una integrada de una palabra sigue siendo un bucle por debajo.",
  ["Linear: the work grows in step with the input. Iterator chains hide the loop but not the cost."] = "Lineal: el trabajo crece al paso de la entrada. Las cadenas de iteradores esconden el bucle pero no el coste.",
  ["Linear: the work grows in step with the input. Write it with a capital O and the size in brackets."] = "Lineal: el trabajo crece al paso de la entrada. Escríbelo con una O mayúscula y el tamaño entre paréntesis.",
  ["Linked list without pointers"] = "Lista enlazada sin punteros",
  ["Linked list: reverse, cycle"] = "Lista enlazada: invertir, ciclo",
  ["Linked lists"] = "Listas enlazadas",
  ["Listen, And, Serve. Returns only on error, hence log.Fatal."] = "Listen, And, Serve. Solo retorna con error, de ahí log.Fatal.",
  ["ListenAndServe blocks forever. Every request runs in its own goroutine."] = "ListenAndServe bloquea para siempre. Cada petición corre en su propia goroutine.",
  ["Lists and slices"] = "Listas y rebanadas",
  ["Load and Store are the read and write. Reading the field directly is a data race even for one int."] = "Load y Store son la lectura y la escritura. Leer el campo directamente es una carrera de datos aunque sea un solo int.",
  ["Lock a shared counter. Fill the type: var mu sync.___"] = "Bloquea un contador compartido. Completa el tipo: var mu sync.___",
  ["Lock then defer Unlock, on the next line, always. A lock released only on the happy path is a deadlock waiting for the first error."] = "Lock y en la línea siguiente defer Unlock, siempre. Un lock que solo se suelta en el camino feliz es un deadlock esperando al primer error.",
  ["Lock; defer Unlock is the pattern. A forgotten Unlock deadlocks the next caller."] = "Lock; defer Unlock es el patrón. Un Unlock olvidado deja en deadlock al siguiente que llame.",
  ["Locks, Value and Manager"] = "Bloqueos, Value y Manager",
  ["Log each total the moment it lands, in any order. Which helper?"] = "Registra cada total en cuanto llega, en cualquier orden. ¿Qué ayudante?",
  ["Logarithmic time"] = "Tiempo logarítmico",
  ["Logarithmic: O of the logarithm of n. The base does not matter in Big O."] = "Logarítmico: O del logaritmo de n. La base no importa en Big O.",
  ["Long bounds go under the signature. Which keyword starts that clause?"] = "Los bounds largos van bajo la firma. ¿Qué palabra clave empieza esa cláusula?",
  ["Longest run of distinct bytes: a window [l, r] and a HashSet of what is inside. When b[r] is already in, drop from the left until it is not. Which HashSet method removes?"] = "La racha más larga de bytes distintos: una ventana [l, r] y un HashSet con lo que hay dentro. Cuando b[r] ya está, quita por la izquierda hasta que no esté. ¿Qué método de HashSet elimina?",
  ["Longest run with no repeated dish. When c is already in the window, drop from the left until it is not. Which set method?"] = "La racha más larga sin plato repetido. Cuando c ya está en la ventana, quita por la izquierda hasta que no lo esté. ¿Qué método de set?",
  ["Longest substring without a repeat: remember where each char was last seen. What is stored under last[c]?"] = "Subcadena más larga sin repetidos: recuerda dónde se vio cada carácter por última vez. ¿Qué se guarda en last[c]?",
  ["Look at the load: one core at 100, seven asleep. That is not a threading bug, that is the design."] = "Mira la carga: un núcleo al 100 y siete dormidos. Eso no es un fallo de hilos, es el diseño.",
  ["Look the answer up before computing. Fill the comma-ok test: if v, ok := memo[n]; ___"] = "Buscar la respuesta antes de calcular. Completa la prueba comma-ok: if v, ok := memo[n]; ___",
  ["Look the answer up before computing. Which HashMap method?"] = "Buscar la respuesta antes de calcular. ¿Qué método de HashMap?",
  ["Looks like switch, but every case is a channel send or receive."] = "Parece un switch, pero cada case es un envío o recepción de channel.",
  ["Lowercase, three letters, and a bang because it is a macro."] = "Minúsculas, tres letras y un signo de exclamación porque es una macro.",
  ["Lucky Mac  ·  Causeway Bay"] = "Lucky Mac  ·  Causeway Bay",
  ["Lucky Mac  ·  delivery app"] = "Lucky Mac  ·  app de entregas",
  ["Lucky Mac  ·  the back office"] = "Lucky Mac  ·  la oficina trasera",
  ["Lucky Mac  ·  the morning set"] = "Lucky Mac  ·  el menú de desayuno",
  ["Lucky Mac  ·  the night shift"] = "Lucky Mac  ·  el turno de noche",
  ["Lucky Mac Express  ·  Rust backend"] = "Lucky Mac Express  ·  backend en Rust",
  ["Lucky Mac Express  ·  Times Square"] = "Lucky Mac Express  ·  Times Square",
  ["Lucky Mac Express  ·  the tea set"] = "Lucky Mac Express  ·  la merienda",
  ["Lucky Mac is found. Leave the loop right now. Which keyword?"] = "Lucky Mac encontrado. Sal del bucle ahora mismo. ¿Qué palabra clave?",
  ["Lucky Mac queue"] = "Fila de Lucky Mac",
  ["Lucky Mac, table 4"] = "Lucky Mac, mesa 4",
  ["MAP"] = "MAPA",
  ["MODULES  -  the repo"] = "MODULES  -  el repo",
  ["MODULES  ·  the repo"] = "MODULES  ·  el repo",
  ["MTR exit A, the underpass"] = "Salida A del MTR, el paso subterráneo",
  ["Main waits until all nine orders are marked done, then prints the receipt. Which queue method?"] = "El principal espera hasta que los nueve pedidos están marcados como hechos y luego imprime el recibo. ¿Qué método de la cola?",
  ["Make a context you can stop by hand. Which constructor?"] = "Crea un context que puedas parar a mano. ¿Qué constructor?",
  ["Make a pipe with a sending end and a receiving end. Which function?"] = "Crea una tubería con un extremo que envía y otro que recibe. ¿Qué función?",
  ["Make an enum, impl Display and Error, impl From so ? converts. Box<dyn Error> catches the rest."] = "Crea un enum, impl Display y Error, impl From para que ? convierta. Box<dyn Error> atrapa el resto.",
  ["Make an owned String out of a string literal. Which constructor?"] = "Crea un String propio a partir de un literal de cadena. ¿Qué constructor?",
  ["Make that copy without sorting: a new list with the same items. Which built-in, called on a?"] = "Hacer esa copia sin ordenar: una lista nueva con los mismos elementos. ¿Qué función integrada, llamada sobre a?",
  ["Make that copy: a new owned Vec with the same contents. Which method?"] = "Hacer esa copia: un Vec nuevo y propio con el mismo contenido. ¿Qué método?",
  ["Make the Safe class usable with 'with'. Which method runs on the way in?"] = "Hacer que la clase Safe se pueda usar con 'with'. ¿Qué método corre al entrar?",
  ["Make the menu rangeable. Fill the return type: iter.___[string]"] = "Haz que el menú se pueda recorrer con range. Completa el tipo de retorno: iter.___[string]",
  ["Make the write visible to the other goroutine. Which builtin call ends the wait?"] = "Haz visible esa escritura a la otra goroutine. ¿Qué llamada integrada termina la espera?",
  ["Many of the thing an operating system schedules. Fifteen letters, one word."] = "El plural de eso que planifica un sistema operativo. Quince letras, una palabra.",
  ["Many readers at once, one writer. Fill the read lock: mu.___()"] = "Muchos lectores a la vez, un escritor. Completa el candado de lectura: mu.___()",
  ["Map keys must support ==. Fill the constraint: func Has[K ___](m map[K]bool, k K)"] = "Las claves de map deben admitir ==. Completa la restricción: func Has[K ___](m map[K]bool, k K)",
  ["Maps"] = "Maps",
  ["Mark a function so calling it returns a Future instead of running. Which keyword?"] = "Marca una función para que llamarla devuelva un Future en vez de ejecutarse. ¿Qué palabra clave?",
  ["Mark on enqueue, not on dequeue, or a station can be queued twice from two neighbours."] = "Marca al encolar, no al desencolar, o una estación puede encolarse dos veces desde dos vecinas.",
  ["Mark the cell visited by sinking it. What is written into the grid?"] = "Marca la celda como visitada hundiéndola. ¿Qué se escribe en la cuadrícula?",
  ["Mark the cell visited by turning it into water. Fill the value."] = "Marca la celda como visitada convirtiéndola en agua. Completa el valor.",
  ["Marking in place is the visited set: O(1) extra space. Interviewers may ask you not to mutate; then use a HashSet<(usize, usize)>."] = "Marcar en el sitio es el conjunto de visitados: O(1) de espacio extra. Los entrevistadores pueden pedirte que no mutes; entonces usa un HashSet<(usize, usize)>.",
  ["Marshal returns []byte and an error. Never ignore the error."] = "Marshal devuelve []byte y un error. Nunca ignores el error.",
  ["Max subarray sum: at each x, either extend the current run or start fresh. Fill the fresh start."] = "Suma máxima de subarray: en cada x, o extiendes la racha actual o empiezas de cero. Completa el nuevo comienzo.",
  ["Max subarray: extend the current run with x, or restart at x alone. Fill the second choice."] = "Subarreglo máximo: extiende la racha actual con x, o reinicia solo con x. Completa la segunda opción.",
  ["Maybe a String, maybe nothing. Which return type?"] = "Quizás un String, quizás nada. ¿Qué tipo de retorno?",
  ["Meeting rooms: sort starts and ends separately. A start reuses a room when the earliest end is already over. Fill the test."] = "Salas de reunión: ordena inicios y fines por separado. Un inicio reutiliza una sala cuando el fin más temprano ya pasó. Completa la prueba.",
  ["Mei"] = "Mei",
  ["Memoization: check the map before computing. fib(90) becomes instant."] = "Memoización: consulta el map antes de calcular. fib(90) se vuelve instantáneo.",
  ["Memoized recursion is DP from the top. Same O(n), but the call stack is n deep: RecursionError near 1000."] = "La recursión memoizada es DP desde arriba. El mismo O(n), pero la pila de llamadas tiene n de profundidad: RecursionError cerca de 1000.",
  ["Merge intervals"] = "Fusionar intervalos",
  ["Merge intervals, meeting rooms"] = "Fusionar intervalos, salas de reunión",
  ["Merge sort and binary search"] = "Ordenación por mezcla y búsqueda binaria",
  ["Merge sort has log n levels of splitting. Merging all the pieces on one level costs how much?"] = "La ordenación por mezcla tiene log n niveles de división. ¿Cuánto cuesta mezclar todas las piezas de un nivel?",
  ["Merge sort recurses on both halves. Fill: merge(mergeSort(a[:m]), mergeSort(a[___]))"] = "Merge sort recurre en ambas mitades. Completa: merge(mergeSort(a[:m]), mergeSort(a[___]))",
  ["Merge sort splits in the middle. Which operator gives a whole-number midpoint?"] = "La ordenación por mezcla divide por el medio. ¿Qué operador da un punto medio entero?",
  ["Merge sort: split at len // 2, sort both halves, merge with <=. sorted and list.sort take key=. bisect finds a slot in a sorted list in O(log n)."] = "Ordenación por mezcla: dividir en len // 2, ordenar ambas mitades, mezclar con <=. sorted y list.sort aceptan key=. bisect encuentra un hueco en una lista ordenada en O(log n).",
  ["Merge sort: split_at(len / 2), sort both, merge with <= for stability. In practice: sort_by_key, sort_unstable, binary_search."] = "Merge sort: split_at(len / 2), ordena las dos, fusiona con <= para la estabilidad. En la práctica: sort_by_key, sort_unstable, binary_search.",
  ["Merge two sorted halves: take from the left while its item is no bigger. Which comparison keeps the sort stable?"] = "Mezclar dos mitades ordenadas: tomar de la izquierda mientras su elemento no sea mayor. ¿Qué comparación mantiene la ordenación estable?",
  ["Merge two sorted halves: take the smaller head and advance that side. Fill: ___++"] = "Fusiona dos mitades ordenadas: toma la cabeza menor y avanza ese lado. Completa: ___++",
  ["Merging two sorted halves. On a tie take from the left, so equal items keep their order. Which comparison?"] = "Fusionando dos mitades ordenadas. En un empate toma el de la izquierda, así los iguales conservan su orden. ¿Qué comparación?",
  ["Method calls bind tighter than +, so it is 1 + (left.max(right)). Round two clean. Combo x2."] = "Las llamadas a métodos ligan más fuerte que +, así que es 1 + (left.max(right)). Ronda dos limpia. Combo x2.",
  ["Methods are written in a separate block. Which keyword opens it?"] = "Los métodos se escriben en un bloque aparte. ¿Qué palabra clave lo abre?",
  ["Midnight edition of CODE RUSH! Python round. Chef Bo at the keyboard. Factorial, then fib. Buzzer's live!"] = "¡Edición de medianoche de CODE RUSH! Ronda de Python. El chef Bo al teclado. Factorial, luego fib. ¡El timbre está activo!",
  ["Min of the k largest is the kth largest. Top-k frequent is the same loop over a count map."] = "El mínimo de los k mayores es el k-ésimo mayor. Los top-k más frecuentes son el mismo bucle sobre un map de conteos.",
  ["Modern Rust idioms"] = "Idiomas modernos de Rust",
  ["Module error, trait of the same name with a capital. Every method has a default."] = "Módulo error, trait del mismo nombre con mayúscula. Cada método tiene un valor por defecto.",
  ["Module path plus directory equals import path. That is the whole rule, and it is why a module named after its repo just works from anywhere."] = "Ruta del módulo más directorio igual a ruta de importación. Esa es toda la regla, y por eso un módulo con el nombre de su repo funciona desde cualquier parte.",
  ["Module path plus directory is the import path. Fill the path of the menu package."] = "Ruta del módulo más directorio es la ruta de importación. Rellena la ruta del paquete menu.",
  ["Modules and the go tool"] = "Módulos y la herramienta go",
  ["More than k inside: the smallest cannot be the kth largest. Which function removes the root?"] = "Más de k adentro: el menor no puede ser el k-ésimo mayor. ¿Qué función quita la raíz?",
  ["More than k inside: the smallest, on top, has to go. Which method removes the top?"] = "Más de k dentro: el menor, en la cima, tiene que irse. ¿Qué método quita la cima?",
  ["Morning set. Don't show him your laptop bugs."] = "Menú de desayuno. No le enseñes los bugs de tu laptop.",
  ["Morning set. Lucky Mac. The kiosk on the door is stuck on a Go bug."] = "Menú de desayuno. Lucky Mac. El kiosco de la puerta está atascado en un bug de Go.",
  ["Most tree questions are this shape: nil returns a base value, else combine both sides."] = "Casi todas las preguntas de árboles tienen esta forma: nil devuelve un valor base, si no, combina ambos lados.",
  ["Move it to the recent end of the list, which is the front. One method, three words."] = "Muévelo al extremo reciente de la lista, que es el frente. Un método, tres palabras.",
  ["Move next out, flip the arrow, push node onto prev. No take() needed: while let moved cur into node. prev is the new head."] = "Saca next, gira la flecha, empuja node sobre prev. No hace falta take(): el while let movió cur a node. prev es la nueva cabeza.",
  ["Muffin ready, or hash brown, or timeout. Pick one."] = "Muffin listo, o hash brown, o timeout. Elige uno.",
  ["Multiply 100 by 99, then halve it."] = "Multiplica 100 por 99, luego divídelo a la mitad.",
  ["Must start with Test and take *testing.T. File name ends with _test.go."] = "Debe empezar por Test y recibir *testing.T. El nombre del archivo termina en _test.go.",
  ["Mutating the grid is the O(1) extra-space visited set. Copy it first if the caller needs it back."] = "Mutar la cuadrícula es el conjunto de visitados con O(1) de espacio extra. Cópiala antes si quien llama la necesita intacta.",
  ["Mutating the input saves a visited set. If the caller needs the grid back, copy it first."] = "Mutar la entrada ahorra un set de visitados. Si quien llama necesita la cuadrícula de vuelta, cópiala primero.",
  ["Mutex and WaitGroup"] = "Mutex y WaitGroup",
  ["Mutex locks shared memory. WaitGroup waits for a set of goroutines to finish."] = "Mutex bloquea memoria compartida. WaitGroup espera a que un grupo de goroutines termine.",
  ["Mutual exclusion, shortened to five letters. lock() gives a guard; the guard unlocks on drop."] = "Exclusión mutua, abreviada a cinco letras. lock() da un guard; el guard desbloquea al soltarse.",
  ["Mutual exclusion. Capital M. In package sync."] = "Exclusión mutua. M mayúscula. En el package sync.",
  ["My cousin's shop wants your menu package. He typed the GitHub path into an import and it just downloaded."] = "La tienda de mi primo quiere tu paquete menu. Escribió la ruta de GitHub en un import y se descargó sin más.",
  ["My first version started one goroutine per order. Forty thousand orders, forty thousand goroutines."] = "Mi primera versión arrancaba una goroutine por pedido. Cuarenta mil pedidos, cuarenta mil goroutines.",
  ["NEXT"] = "SIGUIENTE",
  ["NEXT >"] = "SIGUIENTE >",
  ["NICE!"] = "¡BIEN!",
  ["NIGHT OWL"] = "BÚHO NOCTURNO",
  ["NIGHT SHIFT  -  the kitchen"] = "NIGHT SHIFT  -  la cocina",
  ["Name the module after the repo it will live in. Fill the path."] = "Nombra el módulo como el repositorio donde va a vivir. Rellena la ruta.",
  ["Named after a paperclip assistant from old office software. Six letters, double p."] = "Lleva el nombre de un asistente con forma de clip de un viejo software de oficina. Seis letras, doble p.",
  ["Named types, assertions, type switch"] = "Tipos con nombre, aserciones, type switch",
  ["Negative indexes count from the end. Go would panic on this."] = "Los índices negativos cuentan desde el final. Go haría panic con esto.",
  ["Negative indexing counts from the end; the last item is one back."] = "El índice negativo cuenta desde el final; el último elemento está uno atrás.",
  ["Nested loops multiply their sizes. Two different letters, a star between them."] = "Los bucles anidados multiplican sus tamaños. Dos letras distintas, un asterisco entre ellas.",
  ["Newer Go has helpers for that. Lunch is on the house."] = "El Go más reciente tiene ayudantes para eso. El almuerzo va por cuenta de la casa.",
  ["Next of Next. The loop condition already checked fast.Next is not nil."] = "Next de Next. La condición del bucle ya comprobó que fast.Next no es nil.",
  ["Night shift. Every station runs a Python script I wrote. Tonight none of them start."] = "Turno de noche. Cada puesto corre un script de Python que escribí yo. Esta noche ninguno arranca.",
  ["Nine letters, 'to count off'. Go gives you the index for free in range; Python asks you to wrap the list."] = "Nueve letras, 'ir contando'. Go te da el índice gratis en range; Python te pide envolver la lista.",
  ["Nine letters, a railway signal. Go builds the same thing from a buffered channel."] = "Nueve letras, una señal de ferrocarril. Go construye lo mismo con un channel con buffer.",
  ["Nine letters. To number things one by one. zip() pairs two iterators instead."] = "Nueve letras. Numerar cosas una por una. zip() en cambio empareja dos iteradores.",
  ["Nine letters. go test -bench=. runs them."] = "Nueve letras. go test -bench=. los ejecuta.",
  ["No allocation, O(1): the node is relinked in place. Value is an any, so the type assertion unpacks the entry."] = "Sin asignar memoria, O(1): el nodo se reenlaza en el sitio. Value es un any, así que la aserción de tipo desempaqueta la entry.",
  ["No eggs left: stop the order with an error. Which keyword throws?"] = "No quedan huevos: detener el pedido con un error. ¿Qué palabra clave lanza?",
  ["No garbage collector, and it still knows when to free the tray?"] = "¿Sin garbage collector, y aun así sabe cuándo liberar la bandeja?",
  ["No input reference to borrow from. Which lifetime does a literal string have?"] = "No hay referencia de entrada de la que prestar. ¿Qué lifetime tiene un string literal?",
  ["No nested loops. A window slides; the answer updates as it goes."] = "Sin bucles anidados. Una ventana se desliza; la respuesta se actualiza sobre la marcha.",
  ["No nil in Rust. If a value may be missing, the type says Option."] = "No hay nil en Rust. Si un valor puede faltar, el tipo dice Option.",
  ["No nil. Every failure is a value you must look at."] = "Sin nil. Cada fallo es un valor que tienes que mirar.",
  ["No note on the order yet. Which value means 'nothing here'?"] = "El pedido aún no tiene nota. ¿Qué valor significa 'aquí no hay nada'?",
  ["No overlap, or out is still empty: the current interval starts a new block. Which Vec method appends it?"] = "Sin solape, o out aún vacío: el intervalo actual empieza un bloque nuevo. ¿Qué método de Vec lo añade?",
  ["No overlap: cur starts a new merged interval. Fill the builtin."] = "Sin solapamiento: cur empieza un nuevo intervalo fusionado. Completa la función integrada.",
  ["No partner yet: remember this value and where it was. What is stored under seen[x]?"] = "Todavía sin pareja: recordar este valor y dónde estaba. ¿Qué se guarda bajo seen[x]?",
  ["Nobody told it to stop. Nothing in Go kills a goroutine from outside."] = "Nadie le dijo que parase. En Go nada mata una goroutine desde fuera.",
  ["Node contains Node. The compiler needs a fixed size, so the child lives on the heap behind which pointer?"] = "Node contiene Node. El compilador necesita un tamaño fijo, así que el hijo vive en el heap detrás de ¿qué puntero?",
  ["None is a value, not a null pointer. Read it with match or if let Some(s) = seat(t). The board lights up."] = "None es un valor, no un puntero nulo. Léelo con match o if let Some(s) = seat(t). El tablero se ilumina.",
  ["None is the base case: put a fresh leaf there. The Some arms recurse. Match ergonomics let n be &mut Box<Node>."] = "None es el caso base: pon ahí una hoja nueva. Las ramas Some recursan. Las match ergonomics hacen que n sea &mut Box<Node>.",
  ["None is the one value of NoneType. A function with no return gives None too."] = "None es el único valor de NoneType. Una función sin return también devuelve None.",
  ["None marks an empty subtree. Every tree function starts with: if node is None."] = "None marca un subárbol vacío. Toda función de árbol empieza con: if node is None.",
  ["None on an empty out falls to the _ arm and pushes. The borrow ends with the match, so out.push is allowed there."] = "None con out vacío cae en el brazo _ y hace push. El préstamo termina con el match, así que out.push está permitido ahí.",
  ["None terminates the list. Walk with while node: and stop when it is falsy."] = "None termina la lista. Recorre con while node: y para cuando sea falso.",
  ["Not TODO (that is a placeholder). The empty, never-cancelled root."] = "No TODO (eso es un marcador). La raíz vacía que nunca se cancela.",
  ["Not equal. The statement before ; runs first, and err lives only inside the if."] = "Distinto. La sentencia antes del ; corre primero, y err vive solo dentro del if.",
  ["Not null, not None. Three letters. The only zero for interfaces with no type."] = "Ni null ni None. Tres letras. El único cero para interfaces sin tipo.",
  ["Not quite. Read the hint and try again. HINT again shows the answer."] = "Casi. Lee la pista e inténtalo de nuevo. PISTA otra vez muestra la respuesta.",
  ["Not struct. Variants, one of which carries the ParseIntError inside."] = "No struct. Variantes, una de las cuales lleva el ParseIntError dentro.",
  ["Not the stack. The other one, the one the garbage collector sweeps."] = "No la pila. La otra, la que barre el recolector de basura.",
  ["Nothing runs yet. Which method actually starts the thread?"] = "Todavía no corre nada. ¿Qué método arranca realmente el hilo?",
  ["Nothing tells parse which type to build. Say i32 with the turbofish."] = "Nada le dice a parse qué tipo construir. Di i32 con el turbofish.",
  ["Now collect the number. Which method of the Future?"] = "Ahora recoge el número. ¿Qué método del Future?",
  ["Now the worker takes two arguments. Which method unpacks each tuple?"] = "Ahora el worker toma dos argumentos. ¿Qué método despliega cada tupla?",
  ["Now wait for the answer. Write Go's await."] = "Ahora espera la respuesta. Escribe el await de Go.",
  ["Num, then the thing Go is famous for, singular."] = "Num y luego aquello por lo que Go es famoso, en singular.",
  ["Num, then the three letters on the chip."] = "Num, y luego las tres letras del chip.",
  ["Number in the brackets, then the element type. It cannot grow."] = "Número entre corchetes, luego el tipo del elemento. No puede crecer.",
  ["Number of islands"] = "Número de islas",
  ["Number of islands: DFS on a grid"] = "Número de islas: DFS en una cuadrícula",
  ["Number the constants 0, 1, 2 automatically. Which identifier?"] = "Numera las constantes 0, 1, 2 automáticamente. ¿Qué identificador?",
  ["Number the trays from 1 while looping. Which built-in pairs an index with each item?"] = "Numerar las bandejas desde 1 mientras se recorren. ¿Qué función integrada empareja un índice con cada elemento?",
  ["Numbers, strings, None"] = "Números, cadenas, None",
  ["O(1) extra, near enough: the list is rearranged where it lives and sort() returns None to say so."] = "O(1) extra, o casi: la lista se reordena donde vive y sort() devuelve None para decirlo.",
  ["O(1) extra: pdqsort swaps within the slice. The input itself is never counted as extra space."] = "O(1) extra: pdqsort intercambia dentro del slice. La propia entrada nunca cuenta como espacio extra.",
  ["O(1) extra: pdqsort swaps within the slice. Vec::sort, the stable one, allocates an O(n) buffer instead."] = "O(1) extra: pdqsort intercambia dentro del slice. Vec::sort, el estable, reserva en cambio un búfer O(n).",
  ["O(1) lookups need a map from key to its node in the list. Fill the value type."] = "Las búsquedas O(1) necesitan un map de clave a su nodo en la lista. Completa el tipo del valor.",
  ["O(1): a million items or ten, one multiply and one load. Written O(1), read 'order one'."] = "O(1): un millón de elementos o diez, una multiplicación y una carga. Se escribe O(1), se lee 'orden uno'.",
  ["O(1): the OrderedDict is a doubly linked list plus a dict. The newest lives at the end, the oldest at the front."] = "O(1): el OrderedDict es una lista doblemente enlazada más un dict. La más nueva vive al final, la más vieja al frente.",
  ["O(1): the bounds check is one compare, the read one load, whatever n is. Read 'order one'."] = "O(1): la comprobación de límites es una comparación, la lectura una carga, sea n lo que sea. Se lee 'orden uno'.",
  ["O(1): the same number of steps however big the input. Indexing a Vec, a HashMap lookup, .last(). Doubling n changes nothing."] = "O(1): el mismo número de pasos por grande que sea la entrada. Indexar un Vec, buscar en un HashMap, .last(). Duplicar n no cambia nada.",
  ["O(1): the same number of steps however big the input. Indexing a list, a dict lookup, items[-1]. Doubling n changes nothing."] = "O(1): el mismo número de pasos por grande que sea la entrada. Indexar una lista, buscar en un dict, items[-1]. Duplicar n no cambia nada.",
  ["O(1): the same number of steps however big the input. Indexing a slice, a map lookup, the last element. Doubling n changes nothing."] = "O(1): el mismo número de pasos por grande que sea la entrada. Indexar un slice, buscar en un map, el último elemento. Duplicar n no cambia nada.",
  ["O(2^n). fib(35) already takes seconds in Python; fib(50) would take days. The worst curve on the board."] = "O(2^n). fib(35) ya tarda segundos en Python; fib(50) llevaría días. La peor curva de la pizarra.",
  ["O(2^n). fib(40) is about a billion calls even in Rust; fib(50) would take a day. The worst curve on the board."] = "O(2^n). fib(40) son unos mil millones de llamadas incluso en Rust; fib(50) llevaría un día. La peor curva de la pizarra.",
  ["O(2^n). fib(40) is about a billion calls; fib(50) would take a day. The worst curve on the board."] = "O(2^n). fib(40) son unos mil millones de llamadas; fib(50) llevaría un día. La peor curva de la pizarra.",
  ["O(2^n): the work doubles when n grows by one. Naive fib makes two calls per call. @functools.cache brings it to O(n). Listing every subset of n items is 2^n and cannot be helped."] = "O(2^n): el trabajo se duplica cuando n crece en uno. El fib ingenuo hace dos llamadas por llamada. @functools.cache lo lleva a O(n). Listar todos los subconjuntos de n elementos es 2^n y no tiene remedio.",
  ["O(2^n): the work doubles when n grows by one. Naive fib makes two calls per call. A HashMap memo brings it to O(n). Listing every subset of n items is 2^n and cannot be helped."] = "O(2^n): el trabajo se duplica cuando n crece en uno. El fib ingenuo hace dos llamadas por llamada. Un memo en HashMap lo lleva a O(n). Listar todos los subconjuntos de n elementos es 2^n y no tiene remedio.",
  ["O(2^n): the work doubles when n grows by one. Naive fib makes two calls per call. A memo brings it to O(n). Listing every subset of n items is 2^n and cannot be helped."] = "O(2^n): el trabajo se duplica cuando n crece en uno. El fib ingenuo hace dos llamadas por llamada. Un memo lo lleva a O(n). Listar todos los subconjuntos de n elementos es 2^n y no tiene remedio.",
  ["O(amount * coins). Each cell asks: which last coin gives the fewest in total?"] = "O(importe * monedas). Cada celda pregunta: ¿qué última moneda da el mínimo total?",
  ["O(amount * coins). Greedy fails here: coins [1, 3, 4] for 6 is two coins, not 4 + 1 + 1."] = "O(amount * coins). El voraz falla aquí: monedas [1, 3, 4] para 6 son dos monedas, no 4 + 1 + 1.",
  ["O(amount * coins). The greedy 'biggest coin first' fails for coins like 1, 3, 4 and amount 6; the table does not."] = "O(amount * coins). El voraz 'la moneda más grande primero' falla con monedas 1, 3, 4 y cantidad 6; la tabla no.",
  ["O(log k) per push. Python's heapq is a min-heap only; for a max-heap push -x."] = "O(log k) por push. El heapq de Python es solo min-heap; para un max-heap haz push de -x.",
  ["O(log n) per search. Sorting first pays off after the first few lookups. The sorting hat is done."] = "O(log n) por búsqueda. Ordenar primero compensa tras las primeras búsquedas. El sombrero seleccionador está hecho.",
  ["O(log n) stack frames on average. Every axis on the board has a name now. Alex takes the O(1) stamp."] = "O(log n) marcos de pila en promedio. Cada eje de la pizarra tiene ya un nombre. Alex se lleva el sello O(1).",
  ["O(log n) stack frames on average. Every axis on the board has a name. Mei takes the O(1) stamp for the Rust round."] = "O(log n) marcos de pila en promedio. Cada eje de la pizarra tiene un nombre. Mei se lleva el sello O(1) de la ronda de Rust.",
  ["O(log n) stack frames on average. Every axis on the last board has a name. The Python round takes the O(1) stamp; the night is over."] = "O(log n) marcos de pila en promedio. Cada eje de la última pizarra tiene un nombre. La ronda de Python se lleva el sello O(1); la noche ha terminado.",
  ["O(log n). Balanced trees, heaps and skip lists live here too. It is the second-best cost after O(1)."] = "O(log n). Los árboles equilibrados, los heaps y las skip lists también viven aquí. Es el segundo mejor coste tras O(1).",
  ["O(log n). Err(i) even tells you where to insert. BTreeMap and BinaryHeap live at the same cost."] = "O(log n). Err(i) incluso te dice dónde insertar. BTreeMap y BinaryHeap viven al mismo coste.",
  ["O(log n). heapq lives at the same cost per push and pop. The second-best cost after O(1)."] = "O(log n). heapq vive al mismo coste por push y pop. El segundo mejor coste tras O(1).",
  ["O(log n): each step halves what is left. Binary search on a sorted slice: 1024 items in 10 steps, a million in 20. Needs sorted input."] = "O(log n): cada paso parte a la mitad lo que queda. Búsqueda binaria en un slice ordenado: 1024 elementos en 10 pasos, un millón en 20. Necesita entrada ordenada.",
  ["O(log n): each step halves what is left. bisect on a sorted list: 1024 items in 10 steps, a million in 20. Needs sorted input."] = "O(log n): cada paso parte a la mitad lo que queda. bisect en una lista ordenada: 1024 elementos en 10 pasos, un millón en 20. Necesita entrada ordenada.",
  ["O(log n): each step halves what is left. slice::binary_search on a sorted Vec: 1024 items in 10 steps, a million in 20. Needs sorted input."] = "O(log n): cada paso parte a la mitad lo que queda. slice::binary_search en un Vec ordenado: 1024 elementos en 10 pasos, un millón en 20. Necesita entrada ordenada.",
  ["O(n log k) time, O(k) space: better than sorting all n when k is small."] = "Tiempo O(n log k), espacio O(k): mejor que ordenar los n cuando k es pequeño.",
  ["O(n log n) for the sort; everything after is O(n). Lists sort by first element anyway, so shifts.sort() works here too."] = "O(n log n) por el sort; todo lo demás es O(n). Las listas se ordenan por el primer elemento de todos modos, así que shifts.sort() también sirve aquí.",
  ["O(n log n), and after it every overlap sits next to its neighbour. slices.SortFunc does the same in Go 1.21."] = "O(n log n), y después cada solapamiento queda junto a su vecino. slices.SortFunc hace lo mismo en Go 1.21.",
  ["O(n log n), and it dominates: the merge walk after it is O(n). mut iv lets the function sort in place."] = "O(n log n), y domina: el recorrido de fusión que sigue es O(n). mut iv deja que la función ordene en el sitio.",
  ["O(n log n). A million items: about 20 million comparisons, not a trillion. The proven lower bound for comparison sorts."] = "O(n log n). Un millón de elementos: unos 20 millones de comparaciones, no un billón. La cota inferior demostrada para las ordenaciones por comparación.",
  ["O(n log n). A million items: about 20 million comparisons. The proven lower bound for comparison sorts."] = "O(n log n). Un millón de elementos: unos 20 millones de comparaciones. La cota inferior demostrada para las ordenaciones por comparación.",
  ["O(n log n). A million items: about 20 million comparisons. Timsort is O(n) on already-sorted input, a bonus."] = "O(n log n). Un millón de elementos: unos 20 millones de comparaciones. Timsort es O(n) con entrada ya ordenada, un extra.",
  ["O(n log n): the cost of a good sort. Merge sort has log n levels, each doing O(n) work. sort, sort_unstable and sort_by_key all live here. Sort once, search many times."] = "O(n log n): el coste de una buena ordenación. La ordenación por mezcla tiene log n niveles, cada uno con O(n) de trabajo. sort, sort_unstable y sort_by_key viven todos aquí. Ordena una vez, busca muchas.",
  ["O(n log n): the cost of a good sort. Merge sort has log n levels, each doing O(n) work. sort.Ints, sort.Strings and slices.Sort all live here. Sort once, search many times."] = "O(n log n): el coste de una buena ordenación. La ordenación por mezcla tiene log n niveles, cada uno con O(n) de trabajo. sort.Ints, sort.Strings y slices.Sort viven todos aquí. Ordena una vez, busca muchas.",
  ["O(n log n): the cost of a good sort. Merge sort has log n levels, each doing O(n) work. sorted and list.sort are Timsort and live here. Sort once, search many times."] = "O(n log n): el coste de una buena ordenación. La ordenación por mezcla tiene log n niveles, cada uno con O(n) de trabajo. sorted y list.sort son Timsort y viven aquí. Ordena una vez, busca muchas.",
  ["O(n) instead of O(n * k): the sum is updated, never recomputed. Fixed windows are always this trick."] = "O(n) en vez de O(n * k): la suma se actualiza, nunca se recalcula. Las ventanas fijas son siempre este truco.",
  ["O(n) per level times log n levels. That product is the whole reason n log n exists."] = "O(n) por nivel por log n niveles. Ese producto es toda la razón de que exista n log n.",
  ["O(n) time, O(n) table. Keep only the last two entries and it is O(1) space."] = "Tiempo O(n), tabla O(n). Guarda solo las dos últimas entradas y es O(1) de espacio.",
  ["O(n) with a dict instead of O(n^2) with two loops. Check before storing so x does not pair with itself."] = "O(n) con un dict en vez de O(n^2) con dos bucles. Comprueba antes de guardar para que x no se emparejé consigo mismo.",
  ["O(n). Big O keeps only the fastest-growing term and drops its coefficient. Sequential loops add; nested loops multiply."] = "O(n). Big O conserva solo el término que crece más rápido y descarta su coeficiente. Los bucles secuenciales suman; los anidados multiplican.",
  ["O(n). Every element is touched once. The most common cost in everyday code, and often the best possible."] = "O(n). Cada elemento se toca una vez. El coste más común en el código de cada día, y a menudo el mejor posible.",
  ["O(n). Memoization trades O(n) memory for the exponential time. The biggest win in this whole quest."] = "O(n). La memorización cambia O(n) de memoria por el tiempo exponencial. La mayor victoria de toda esta misión.",
  ["O(n). Memoization trades O(n) memory for the exponential time. The single biggest win in this whole quest."] = "O(n). La memorización cambia O(n) de memoria por el tiempo exponencial. La mayor victoria de toda esta misión.",
  ["O(n). Merge sort needs the same: an O(n) scratch buffer for merging. Python's sorted() copies too."] = "O(n). La ordenación por mezcla necesita lo mismo: un búfer de trabajo O(n) para mezclar. El sorted() de Python también copia.",
  ["O(n). Rust makes the cost visible: clone() is a word you have to type. Python's sorted() copies silently."] = "O(n). Rust hace visible el coste: clone() es una palabra que tienes que teclear. El sorted() de Python copia en silencio.",
  ["O(n). Sequential passes add and the constant drops. Nested passes multiply: that is the next street but one."] = "O(n). Las pasadas secuenciales suman y la constante cae. Las pasadas anidadas multiplican: eso es dentro de dos calles.",
  ["O(n). Sequential passes add and the constant drops. Nested passes multiply: that is two streets on."] = "O(n). Las pasadas secuenciales suman y la constante cae. Las pasadas anidadas multiplican: eso es dentro de dos calles.",
  ["O(n). sorted() always copies; a.sort() never does. Choose by whether you still need the original order."] = "O(n). sorted() siempre copia; a.sort() nunca lo hace. Elige según sigas necesitando el orden original o no.",
  ["O(n). sum, map, filter, count: every adapter is one pass. Zero-cost abstractions are still O(n) abstractions."] = "O(n). sum, map, filter, count: cada adaptador es una pasada. Las abstracciones de coste cero siguen siendo abstracciones O(n).",
  ["O(n). sum, max, min, any, all, list.count: every one is a pass. Faster in C, same order."] = "O(n). sum, max, min, any, all, list.count: cada una es una pasada. Más rápido en C, mismo orden.",
  ["O(n): one pass over the input; double n, double the work. A range loop, a sum, a scan for a value. O(n) + O(n) is still O(n): constants drop."] = "O(n): una pasada sobre la entrada; duplica n, duplica el trabajo. Un bucle range, una suma, un barrido en busca de un valor. O(n) + O(n) sigue siendo O(n): las constantes caen.",
  ["O(n): one pass over the input; double n, double the work. iter().sum(), any(), Vec::contains. O(n) + O(n) is still O(n): constants drop."] = "O(n): una pasada sobre la entrada; duplica n, duplica el trabajo. iter().sum(), any(), Vec::contains. O(n) + O(n) sigue siendo O(n): las constantes caen.",
  ["O(n): one pass over the input; double n, double the work. sum, max, x in list. O(n) + O(n) is still O(n): constants drop."] = "O(n): una pasada sobre la entrada; duplica n, duplica el trabajo. sum, max, x in list. O(n) + O(n) sigue siendo O(n): las constantes caen.",
  ["O(n*m). Only when both loops run over the same n does it collapse to n^2. The seating chart is fixed."] = "O(n*m). Solo cuando ambos bucles recorren la misma n se colapsa a n^2. El plano de mesas está arreglado.",
  ["O(n^2). Double the guests, four times the checks. Bubble sort and selection sort live here too."] = "O(n^2). El doble de invitados, el cuádruple de comprobaciones. La ordenación de burbuja y la de selección también viven aquí.",
  ["O(n^2): a loop inside a loop over the same n. Comparing every pair. 100 items is 4950 pairs; 10,000 is fifty million. A HashSet turns most of these into O(n)."] = "O(n^2): un bucle dentro de un bucle sobre la misma n. Comparar cada par. 100 elementos son 4950 pares; 10.000 son cincuenta millones. Un HashSet convierte la mayoría en O(n).",
  ["O(n^2): a loop inside a loop over the same n. Comparing every pair. 100 items is 4950 pairs; 10,000 is fifty million. A map turns most of these into O(n)."] = "O(n^2): un bucle dentro de un bucle sobre la misma n. Comparar cada par. 100 elementos son 4950 pares; 10.000 son cincuenta millones. Un map convierte la mayoría en O(n).",
  ["O(n^2): a loop inside a loop over the same n. Comparing every pair. 100 items is 4950 pairs; 10,000 is fifty million. A set turns most of these into O(n)."] = "O(n^2): un bucle dentro de un bucle sobre la misma n. Comparar cada par. 100 elementos son 4950 pares; 10.000 son cincuenta millones. Un set convierte la mayoría en O(n).",
  ["OK"] = "OK",
  ["Octopus tap. The gate function returns ok, err."] = "Pasa la Octopus. La función del torniquete devuelve ok, err.",
  ["Off the map on any side: stop. Fill the width the column index is checked against."] = "Fuera del mapa por cualquier lado: detente. Completa el ancho contra el que se comprueba el índice de columna.",
  ["Ok(2). On an unsorted slice the result is meaningless, so sort first. Err(i) is where to insert to stay sorted."] = "Ok(2). Sobre un slice sin ordenar el resultado no significa nada, así que ordena primero. Err(i) es dónde insertar para seguir ordenado.",
  ["Old tutorials talk about GOPATH. What is GO111MODULE since Go 1.16?"] = "Los tutoriales viejos hablan de GOPATH. ¿Qué vale GO111MODULE desde Go 1.16?",
  ["Once, plus the word for what a function gives back. There is a two-result twin for (T, error)."] = "Once, más la palabra para lo que devuelve una función. Hay un gemelo de dos resultados para (T, error).",
  ["One CPython process runs bytecode under a global interpreter lock, so eight threads doing arithmetic still use one core. The GIL is released around I/O and inside C extensions, which is why threads help downloads and not sums. multiprocessing sidesteps it: every process has its own interpreter and its own lock."] = "Un proceso de CPython ejecuta bytecode bajo un bloqueo global del intérprete, así que ocho hilos haciendo aritmética siguen usando un núcleo. El GIL se libera alrededor de la E/S y dentro de las extensiones en C, por eso los hilos ayudan a las descargas y no a las sumas. multiprocessing lo esquiva: cada proceso tiene su propio intérprete y su propio bloqueo.",
  ["One HashSet method adds m and tells you whether it was new. Which one?"] = "Un método de HashSet añade m y te dice si era nuevo. ¿Cuál?",
  ["One Unicode character in single quotes. Which type?"] = "Un carácter Unicode entre comillas simples. ¿Qué tipo?",
  ["One cargo command builds the crate and starts it. Which word?"] = "Un comando de cargo compila el crate y lo arranca. ¿Qué palabra?",
  ["One character passes the error straight back to the caller. Which?"] = "Un carácter pasa el error directo a quien llama. ¿Cuál?",
  ["One character, the ampersand. The call site already uses it."] = "Un carácter, el ampersand. La llamada ya lo usa.",
  ["One character, the one in an email address. Rust uses it for attributes with #[...] instead."] = "Un carácter, el de una dirección de correo. Rust usa #[...] para atributos en su lugar.",
  ["One character. Go and Rust use two slashes; Python uses the hash sign."] = "Un carácter. Go y Rust usan dos barras; Python usa la almohadilla.",
  ["One character. The same one that returns Err early in a Result function."] = "Un carácter. El mismo que devuelve Err temprano en una función Result.",
  ["One character. The same underscore Go uses to throw a value away."] = "Un carácter. El mismo guion bajo que Go usa para descartar un valor.",
  ["One cook, one thread. The grill must not wait for the kettle."] = "Un cocinero, un thread. La parrilla no debe esperar al hervidor.",
  ["One counter, changed by many threads. Which wrapper allows only one writer at a time?"] = "Un contador, cambiado por muchos threads. ¿Qué envoltorio permite un solo escritor a la vez?",
  ["One decorator remembers every result by argument. Which one, from functools?"] = "Un decorador recuerda cada resultado por argumento. ¿Cuál, de functools?",
  ["One directory is one package: every .go file in it says the same package name, normally the directory's. Only identifiers that start with a capital letter are visible from outside. You import a package by its full path, module path plus directory, never by a relative path, and an import you do not use is a compile error."] = "Un directorio es un paquete: todo fichero .go dentro declara el mismo nombre de paquete, normalmente el del directorio. Solo los identificadores que empiezan por mayúscula se ven desde fuera. Un paquete se importa por su ruta completa, ruta del módulo más directorio, nunca por una ruta relativa, y un import sin usar es un error de compilación.",
  ["One function for muffin or hash brown. Don't copy-paste."] = "Una función para muffin o hash brown. No copies y pegues.",
  ["One go.mod at the root"] = "Un go.mod en la raíz",
  ["One less than n. fact(n) would never terminate."] = "Uno menos que n. fact(n) nunca terminaría.",
  ["One less than n. u64 cannot go below zero, which is why the base case checks <= 1."] = "Uno menos que n. u64 no puede bajar de cero, por eso el caso base comprueba <= 1.",
  ["One less than zero. Go spells the same thing items[len(items)-1]."] = "Uno menos que cero. Go escribe lo mismo como items[len(items)-1].",
  ["One letter in front of Lock. Its partner is RUnlock."] = "Una letra delante de Lock. Su pareja es RUnlock.",
  ["One letter: the loop variable. Each goroutine owns exactly one slot."] = "Una letra: la variable del bucle. Cada goroutine posee exactamente una casilla.",
  ["One line: 'open' when bowls remain, otherwise 'closed'. Which keyword completes the conditional expression?"] = "Una línea: 'open' si quedan boles, si no 'closed'. ¿Qué palabra clave completa la expresión condicional?",
  ["One loop over n prices, adding each: what is the cost in Big O?"] = "Un bucle sobre n precios, sumando cada uno: ¿cuál es el coste en Big O?",
  ["One main.go with nine hundred lines. Time to split it into packages, and the first question is what to call the module."] = "Un main.go de novecientas líneas. Toca partirlo en paquetes, y la primera pregunta es cómo llamar al módulo.",
  ["One megabyte every process can map. Which class from multiprocessing.shared_memory?"] = "Un megabyte que todo proceso puede mapear. ¿Qué clase de multiprocessing.shared_memory?",
  ["One more than the amount itself: no real answer uses more coins than the amount."] = "Uno más que el propio importe: ninguna respuesta real usa más monedas que el importe.",
  ["One pass, Bo. Keep the run if it's still helping, drop it the moment it isn't."] = "Una sola pasada, Bo. Conserva la racha mientras siga ayudando, suéltala en cuanto deje de hacerlo.",
  ["One pass, one HashMap: O(n) instead of the O(n^2) double loop. seen[&want] then fetches the partner's index."] = "Una pasada, un HashMap: O(n) en vez del doble bucle O(n^2). seen[&want] saca luego el índice del compañero.",
  ["One pass, one map: O(n). Store after checking so x does not pair with itself."] = "Una pasada, un map: O(n). Guarda después de comprobar para que x no se empareje consigo mismo.",
  ["One pass. If the running total goes negative, it can only hurt: start again."] = "Una pasada. Si el total acumulado se vuelve negativo, solo puede estorbar: empieza de nuevo.",
  ["One pointer per node: singly linked. Two (Prev) makes it doubly linked."] = "Un puntero por nodo: lista simplemente enlazada. Dos (Prev) la hace doblemente enlazada.",
  ["One printer, eight cooks"] = "Una impresora, ocho cocineros",
  ["One put crashes with TypeError. What must everything on the queue be?"] = "Un put revienta con TypeError. ¿Cómo debe ser todo lo que va a la cola?",
  ["One slash. On integers Rust truncates, so no floor operator is needed. lo + (hi-lo)/2 avoids overflow."] = "Una barra. Con enteros Rust trunca, así que no hace falta operador de suelo. lo + (hi-lo)/2 evita el desbordamiento.",
  ["One slash. On ints Go rounds toward zero, so no floor operator is needed."] = "Una barra. Con ints Go redondea hacia cero, así que no hace falta operador de suelo.",
  ["One ticket rail: the front sends boxed jobs, the cooks receive them. Which mpsc function makes the (tx, rx) pair?"] = "Un riel de tickets: el mostrador envía trabajos en Box, los cocineros los reciben. ¿Qué función de mpsc crea el par (tx, rx)?",
  ["One tray, one owner. Hand it over and it is gone. Lend it with & and you keep it."] = "Una bandeja, un dueño. Entrégala y ya no es tuya. Préstala con & y te la quedas.",
  ["One type, several ways an order can fail. Which keyword declares it?"] = "Un tipo, varias formas en que un pedido puede fallar. ¿Qué palabra clave lo declara?",
  ["One word, no underscore: the largest size the cache may reach. None means unbounded."] = "Una palabra, sin guion bajo: el tamaño máximo que puede alcanzar la caché. None significa sin límite.",
  ["One writer at the printer. Which multiprocessing primitive?"] = "Un solo escritor ante la impresora. ¿Qué primitiva de multiprocessing?",
  ["Only four riders out at a time. Complete the release at the end of the trip."] = "Solo cuatro repartidores fuera a la vez. Completa la devolución al final del viaje.",
  ["Only land spreads the flood. Which byte marks land in the grid?"] = "Solo la tierra propaga la inundación. ¿Qué byte marca la tierra en la cuadrícula?",
  ["Only land spreads. Which cell value means a building?"] = "Solo la tierra se extiende. ¿Qué valor de celda significa un edificio?",
  ["Only names that start with a capital letter leave their package. Which fmt function prints a line?"] = "Solo los nombres que empiezan con mayúscula salen de su paquete. ¿Qué función de fmt imprime una línea?",
  ["Only one move reaches the first step: a single step of one."] = "Solo un movimiento llega al primer escalón: un único paso de uno.",
  ["Only the sender closes. Sending after this panics."] = "Solo el emisor cierra. Enviar después de esto hace panic.",
  ["Only the sender should call it. Never close from the receive side."] = "Solo el emisor debe llamarlo. Nunca cierres desde el lado receptor.",
  ["Only three workers may hit the payments API at once. Which primitive counts?"] = "Solo tres workers pueden tocar la API de pagos a la vez. ¿Qué primitiva cuenta?",
  ["Only types with this marker trait may move to another thread. Which one?"] = "Solo los tipos con este marker trait pueden moverse a otro thread. ¿Cuál?",
  ["Only useful inside defer. Returns nil if we are not panicking."] = "Solo sirve dentro de defer. Devuelve nil si no hay panic.",
  ["Open the file so it is closed no matter what happens inside. Which keyword?"] = "Abrir el archivo de modo que se cierre pase lo que pase dentro. ¿Qué palabra clave?",
  ["Open the middle, decide left or right, throw half away. The bisect module did it first."] = "Abre por el medio, decide izquierda o derecha, tira la mitad. El módulo bisect lo hizo primero.",
  ["Open the middle, decide left or right, throw half away. The std library already wrote it."] = "Abre por el medio, decide izquierda o derecha, tira la mitad. La biblioteca std ya lo escribió.",
  ["Opposite of var. Compile error if you try to change it."] = "Lo opuesto de var. Error de compilación si intentas cambiarlo.",
  ["Option does the empty case for free: a closer with nothing to pop is a mismatch, no extra if needed."] = "Option resuelve gratis el caso vacío: un cierre sin nada que sacar es un fallo, sin if extra.",
  ["Option<Box<ListNode>>: each node owns the next, the last one holds None. Same size as a raw pointer."] = "Option<Box<ListNode>>: cada nodo posee al siguiente, el último guarda None. Del mismo tamaño que un puntero crudo.",
  ["Option<T> is an enum in the standard library, generic like your own types. No null anywhere in Rust."] = "Option<T> es un enum de la biblioteca estándar, genérico como tus propios tipos. No hay null en ningún sitio de Rust.",
  ["Option<u32> is an enum: Some(12) or None. The caller must handle both, so no nil crash."] = "Option<u32> es un enum: Some(12) o None. Quien llama debe manejar ambos, así que no hay crash por nil.",
  ["Option<usize> would be more Rust; the interview version returns -1. Either way: check the marker before trusting the cell."] = "Option<usize> sería más Rust; la versión de entrevista devuelve -1. En ambos casos: comprueba el marcador antes de fiarte de la celda.",
  ["Optional[str] is str | None. Rust's Option<String>, made visible to the checker."] = "Optional[str] es str | None. El Option<String> de Rust, hecho visible al comprobador.",
  ["Order 18. Morning set. Don't forget to cancel the context."] = "Pedido 18. Menú de desayuno. No olvides cancelar el context.",
  ["Order is a struct. Point at it. The till talks through an interface."] = "Order es un struct. Apúntalo. La caja habla a través de una interface.",
  ["Orders come through the web now. Put a handler on /order."] = "Los pedidos ahora llegan por la web. Pon un handler en /order.",
  ["Over capacity: the least recently used sits at the far end of the list. Which method finds it?"] = "Sobre la capacidad: el menos recientemente usado está en el extremo opuesto de la lista. ¿Qué método lo encuentra?",
  ["Overlap: the current interval starts no later than the last one ends. (1,3) and (3,5) touch and should merge. Which comparison?"] = "Solape: el intervalo actual empieza no más tarde de que termine el último. (1,3) y (3,5) se tocan y deberían fusionarse. ¿Qué comparación?",
  ["Overlaps are only neighbours once the intervals are ordered by start. Which Vec method sorts by a key closure?"] = "Los solapes solo son vecinos una vez que los intervalos están ordenados por inicio. ¿Qué método de Vec ordena con una closure de clave?",
  ["Owner says: ship before 18:00 and the dinner set is on the house."] = "El dueño dice: entrega antes de las 18:00 y el menú de la cena corre por cuenta de la casa.",
  ["Ownership and borrowing"] = "Ownership y borrowing",
  ["PARALLEL  -  the night batch"] = "PARALLEL  -  el lote nocturno",
  ["PARALLEL  ·  the night batch"] = "PARALLEL  ·  el lote nocturno",
  ["PERFECT STREET"] = "CALLE PERFECTA",
  ["PERFECT!"] = "¡PERFECTO!",
  ["POLYGLOT"] = "POLÍGLOTA",
  ["PORT"] = "VERTICAL",
  ["Package name and directory name are separate things that everyone keeps identical. Short, lowercase, no underscores: menu, not menuUtils."] = "Nombre de paquete y nombre de directorio son cosas distintas que todo el mundo mantiene idénticas. Corto, en minúsculas, sin guiones bajos: menu, no menuUtils.",
  ["Packages and imports"] = "Paquetes e imports",
  ["Palindrome with two pointers: i at the start, j at the end. Fill: j = len(s) ___ 1"] = "Palíndromo con dos punteros: i al principio, j al final. Completa: j = len(s) ___ 1",
  ["Palindrome: the chars read the same backwards. Which iterator method walks from the end?"] = "Palíndromo: los chars se leen igual del revés. ¿Qué método de iterador recorre desde el final?",
  ["Partial, then the word for ordering. Ord alone is too strict for f64."] = "Partial, luego la palabra para orden (Ord). Ord solo es demasiado estricto para f64.",
  ["Pause here until fetch has its answer, letting other tasks run. Which keyword?"] = "Pausar aquí hasta que fetch tenga su respuesta, dejando correr otras tareas. ¿Qué palabra clave?",
  ["Pause this thread for 300 ms. Which function?"] = "Pausa este thread 300 ms. ¿Qué función?",
  ["Pay() can fail. Check the error. Close the drawer with defer."] = "Pay() puede fallar. Comprueba el error. Cierra el cajón con defer.",
  ["Peek at the most recent opener without removing it. Which index?"] = "Mira la apertura más reciente sin quitarla. ¿Qué índice?",
  ["Percival Street"] = "Percival Street",
  ["Percival Street at dawn. Walk if the crossing is clear, else wait. Go has no while: a for with a condition is the while."] = "Percival Street al amanecer. Cruza si el paso está libre, si no espera. Go no tiene while: un for con condición es el while.",
  ["Percival Street tram stop"] = "Parada del tranvía de Percival Street",
  ["Pick a branch by value without a chain of ifs. Which keyword?"] = "Elige una rama por valor sin una cadena de ifs. ¿Qué palabra clave?",
  ["Pick the bigger of a and b in one line. Which keyword starts the expression?"] = "Elige el mayor de a y b en una línea. ¿Qué palabra clave empieza la expresión?",
  ["Pipe() gives two Connection objects with send and recv. It is faster than a Queue and safe for exactly two processes."] = "Pipe() da dos objetos Connection con send y recv. Es más rápido que una Queue y seguro para exactamente dos procesos.",
  ["Plain dicts keep insertion order since 3.7, but only this one has move_to_end and popitem(last=False)."] = "Los dict normales conservan el orden de inserción desde 3.7, pero solo este tiene move_to_end y popitem(last=False).",
  ["Plain integers: equal values are indistinguishable, so stability is wasted. The faster in-place sort with no allocation?"] = "Enteros simples: los valores iguales no se distinguen, así que la estabilidad se desperdicia. ¿El sort más rápido, en el sitio y sin reservar memoria?",
  ["Plural of the type a single Unicode scalar has in Rust."] = "Plural del tipo que tiene un solo escalar Unicode en Rust.",
  ["Point the current node backwards. Fill: cur.Next = ___"] = "Apunta el nodo actual hacia atrás. Completa: cur.Next = ___",
  ["Point the import path at the folder next door while you work. Which directive?"] = "Apunta la ruta de importación a la carpeta de al lado mientras trabajas. ¿Qué directiva?",
  ["Pointer receiver to mutate or for big structs; value receiver for small read-only types."] = "Receptor puntero para mutar o para structs grandes; receptor por valor para tipos pequeños de solo lectura.",
  ["Pointer to the same struct type, like the tree node."] = "Puntero al mismo tipo struct, como el nodo del árbol.",
  ["Pool: map, imap, starmap, chunks"] = "Pool: map, imap, starmap, trozos",
  ["Price list is a map. Hash brown: 8 dollars."] = "La lista de precios es un map. Hash brown: 8 dólares.",
  ["Price now returns cents, not dollars: a breaking change. What does the module path gain?"] = "Price ahora devuelve céntimos, no dólares: un cambio que rompe. ¿Qué gana la ruta del módulo?",
  ["Print every dish with its price. Which method walks the key-value pairs?"] = "Imprimir cada plato con su precio. ¿Qué método recorre los pares clave-valor?",
  ["Print the missing key from the error object. Which keyword binds the exception to a name?"] = "Imprimir la clave que falta desde el objeto de error. ¿Qué palabra clave enlaza la excepción a un nombre?",
  ["Print the struct with its field names. Which verb?"] = "Imprime el struct con los nombres de sus campos. ¿Qué verbo?",
  ["Print the values sorted: left subtree, node, right subtree. Fill the first call."] = "Imprime los valores ordenados: subárbol izquierdo, nodo, subárbol derecho. Completa la primera llamada.",
  ["Print then ln. fmt.println with a small p does not exist outside fmt."] = "Print y luego ln. fmt.println con p minúscula no existe fuera de fmt.",
  ["Problem five: search and sort. Binary search on a sorted slice with half-open bounds, then merge sort, the recursion every interviewer loves. And the one-liner from the library."] = "Problema cinco: buscar y ordenar. Búsqueda binaria en un slice ordenado con límites semiabiertos, luego merge sort, la recursión favorita de todo entrevistador. Y la línea única de la librería.",
  ["Problem four: the order queue as a singly linked list. Reverse it in place with three pointers, then detect a cycle with two runners of different speed."] = "Problema cuatro: la cola de pedidos como lista simplemente enlazada. Inviértela in situ con tres punteros y luego detecta un ciclo con dos corredores de distinta velocidad.",
  ["Problem seven, the one they always ask: N workers pull jobs from a channel and push results. Get the close and the wait in the right order and the job is yours."] = "Problema siete, el que siempre preguntan: N workers toman jobs de un channel y empujan resultados. Acierta el orden del close y del wait y el puesto es tuyo.",
  ["Problem six: the classics. Two numbers that add up to the set price, a palindrome check that handles CJK, and whether two dish names are anagrams."] = "Problema seis: los clásicos. Dos números que suman el precio del menú, un chequeo de palíndromo que soporta CJK, y si dos nombres de platos son anagramas.",
  ["Problem three: walk the MTR graph. Breadth-first with a queue for shortest hops, depth-first with recursion for reachability. Both need a visited set."] = "Problema tres: recorre el grafo del MTR. En anchura con una cola para el menor número de saltos, en profundidad con recursión para la alcanzabilidad. Ambos necesitan un set de visitados.",
  ["Problem two: a binary search tree of order numbers. Insert, walk in order, measure the height. In Go a tree is just a struct with two pointers and a nil at every leaf."] = "Problema dos: un árbol binario de búsqueda de números de pedido. Inserta, recorre en orden, mide la altura. En Go un árbol es solo un struct con dos punteros y un nil en cada hoja.",
  ["Process, start, join, __main__"] = "Process, start, join, __main__",
  ["ProcessPoolExecutor and choosing"] = "ProcessPoolExecutor y cómo elegir",
  ["Processes share nothing, so everything travels: a multiprocessing.Queue is a pipe plus a feeder thread plus pickle at both ends. put and get carry any picklable object; a Pipe is the raw two-ended version. Workers stop on a sentinel, usually None, and a JoinableQueue lets the parent wait with task_done and join."] = "Los procesos no comparten nada, así que todo viaja: una multiprocessing.Queue es una tubería más un hilo alimentador más pickle en los dos extremos. put y get llevan cualquier objeto picklable; un Pipe es la versión cruda de dos extremos. Los workers paran con un centinela, normalmente None, y una JoinableQueue deja al padre esperar con task_done y join.",
  ["Pull a *RefundError out of the chain to read its fields. Fill: errors.___(err, &re)"] = "Saca un *RefundError de la cadena para leer sus campos. Completa: errors.___(err, &re)",
  ["Pull a crate in from the terminal without editing the file by hand. Which subcommand?"] = "Trae un crate desde la terminal sin editar el archivo a mano. ¿Qué subcomando?",
  ["Pull exactly one bowl from the generator by hand. Which built-in?"] = "Sacar exactamente un bol del generador a mano. ¿Qué función integrada?",
  ["Push appends through the pointer, because it must change the slice itself. Fill the receiver type."] = "Push añade a través del puntero, porque debe cambiar el propio slice. Completa el tipo del receptor.",
  ["Push, Pop and Min all O(1): low[len(low)-1] is always the smallest thing still on the stack."] = "Push, Pop y Min, todos O(1): low[len(low)-1] es siempre lo más pequeño que sigue en la pila.",
  ["Put a new key: a new node at the front, and its address in the map. Fill the list method."] = "Put de una clave nueva: un nodo nuevo al frente, y su dirección en el map. Completa el método de la lista.",
  ["Python 3.13 ships an experimental build without the lock. What is it called?"] = "Python 3.13 trae una compilación experimental sin el bloqueo. ¿Cómo se llama?",
  ["Python has no braces, Alex. The indentation is the block."] = "Python no tiene llaves, Alex. La indentación es el bloque.",
  ["Python ignores the rest of a line after which character?"] = "¿Python ignora el resto de una línea después de qué carácter?",
  ["Python's nothing, capital N. Go's nil pointer, Rust's Option::None."] = "La nada de Python, N mayúscula. El puntero nil de Go, el Option::None de Rust.",
  ["Python's nothing, capitalised. One per worker, because each one eats exactly one."] = "La nada de Python, con mayúscula inicial. Uno por worker, porque cada uno se come exactamente uno.",
  ["Q other quest"] = "Q otra misión",
  ["Q: "] = "P: ",
  ["QUEST %d"] = "MISIÓN %d",
  ["QUEST CLEAR!"] = "¡MISIÓN CUMPLIDA!",
  ["Quadratic time"] = "Tiempo cuadrático",
  ["Quadratic: n squared. Write the power with a caret."] = "Cuadrático: n al cuadrado. Escribe la potencia con un acento circunflejo.",
  ["Queue board is stuck at zero. Nobody can order until it counts."] = "El tablero de la fila está atascado en cero. Nadie puede pedir hasta que cuente.",
  ["Queue for wide, stack for deep. Same loop, different end of the Vec."] = "Cola para lo ancho, pila para lo hondo. El mismo bucle, distinto extremo del Vec.",
  ["Queues, pipes and pickle"] = "Colas, tuberías y pickle",
  ["R then Lock. Writers still use Lock and Unlock."] = "R y luego Lock. Los escritores siguen usando Lock y Unlock.",
  ["RLock blocks only while a writer holds the lock. Readers never block each other."] = "RLock solo bloquea mientras alguien escribe. Los lectores nunca se bloquean entre sí.",
  ["ROUND 1  -  the brackets"] = "RONDA 1  -  los paréntesis",
  ["ROUND 1  -  the buzzer"] = "RONDA 1  -  el timbre",
  ["ROUND 2  -  the stairs"] = "RONDA 2  -  las escaleras",
  ["ROUND 2  -  the tree"] = "RONDA 2  -  el árbol",
  ["ROUND 3  -  the map"] = "RONDA 3  -  el mapa",
  ["ROUND 3  -  the window"] = "RONDA 3  -  la ventana",
  ["ROUND 4  -  the chain"] = "RONDA 4  -  la cadena",
  ["ROUND 4  -  the top k"] = "RONDA 4  -  los k mayores",
  ["ROUND 5  -  the shifts"] = "RONDA 5  -  los turnos",
  ["ROUND 5  -  the shuffle"] = "RONDA 5  -  la mezcla",
  ["ROUND 6  -  the cache"] = "RONDA 6  -  la caché",
  ["ROUND 6  -  the classics"] = "RONDA 6  -  los clásicos",
  ["ROUND 7  -  the kitchen"] = "RONDA 7  -  la cocina",
  ["RUST SET  -  the walk"] = "RUST SET  -  el paseo",
  ["RWMutex: RLock for readers, Lock for the one writer. Use it when reads dominate."] = "RWMutex: RLock para lectores, Lock para el único escritor. Úsalo cuando dominan las lecturas.",
  ["Race the cooking against the cancel. Which method gives the channel to select on?"] = "Haz competir la cocina contra la cancelación. ¿Qué método da el channel para el select?",
  ["Rc counts on one thread only. Which shared pointer may cross threads?"] = "Rc cuenta en un solo thread. ¿Qué puntero compartido puede cruzar threads?",
  ["Reached an empty spot: make the node here. Fill: if n == ___"] = "Llegaste a un hueco vacío: crea el nodo aquí. Completa: if n == ___",
  ["Read JSON bytes into the struct. Fill: json.___(b, &order)"] = "Lee bytes JSON en el struct. Completa: json.___(b, &order)",
  ["Read a price that may not exist, with 0 as the fallback, without a crash. Which method?"] = "Leer un precio que quizá no existe, con 0 como respaldo, sin caerse. ¿Qué método?",
  ["Read and write, then the word for lock. Readers share it; a writer gets it alone."] = "Lectura y escritura, y luego la palabra para cerrojo. Los lectores lo comparten; el que escribe lo tiene solo.",
  ["Read the counter without a lock and without a race. Which method?"] = "Lee el contador sin lock y sin carrera. ¿Qué método?",
  ["Read the root value without moving the Box out of the Option. Which Option method borrows the inside?"] = "Lee el valor de la raíz sin sacar el Box del Option. ¿Qué método de Option presta el interior?",
  ["Reading items[3] from a Vec of n items: how many steps, in Big O?"] = "Leer items[3] de un Vec de n elementos: ¿cuántos pasos, en Big O?",
  ["Reading items[3] from a list of n items: how many steps, in Big O?"] = "Leer items[3] de una lista de n elementos: ¿cuántos pasos, en Big O?",
  ["Reading items[3] from a slice of n items: how many steps, in Big O?"] = "Leer items[3] de un slice de n elementos: ¿cuántos pasos, en Big O?",
  ["Real life: sort orders by price, cheapest first, equal prices keep their order. Which stable slice method takes a key closure?"] = "Vida real: ordena los pedidos por precio, el más barato primero, a igual precio se conserva el orden. ¿Qué método estable de slice toma un closure de clave?",
  ["Receipt holds a &'a str. What must the struct declare after its name?"] = "Receipt guarda un &'a str. ¿Qué debe declarar el struct tras su nombre?",
  ["Receipt<'_> means some lifetime, I do not need to name it. Clearer than impl<'a> Display for Receipt<'a> when 'a is never used."] = "Receipt<'_> significa algún lifetime, no necesito nombrarlo. Más claro que impl<'a> Display for Receipt<'a> cuando 'a nunca se usa.",
  ["Receive until the channel is closed. Fill: for m := ___ ch"] = "Recibe hasta que el channel se cierre. Completa: for m := ___ ch",
  ["Receiver is Send but not Sync: three cooks cannot read the rail at once. Arc shares it; what hands out turns?"] = "Receiver es Send pero no Sync: tres cocineros no pueden leer el riel a la vez. Arc lo comparte; ¿qué reparte los turnos?",
  ["Recurse into the same side you assign to. Mirror of the else branch."] = "Recurre por el mismo lado al que asignas. Espejo de la rama else.",
  ["Recursion and memoization"] = "Recursión y memoización",
  ["Recursion uses the call stack. Quicksort's average recursion depth, hence stack space, is O(___)"] = "La recursión usa la pila de llamadas. La profundidad media de recursión de quicksort, y por tanto su espacio de pila, es O(___)",
  ["Recursive types need a pointer. nil children mark the end."] = "Los tipos recursivos necesitan un puntero. Los hijos nil marcan el final.",
  ["Reduce with your own start value and closure. Which method?"] = "Reduce con tu propio valor inicial y closure. ¿Qué método?",
  ["Refill the ice only if nobody is at the machine. Which method returns false instead of waiting?"] = "Rellena el hielo solo si no hay nadie en la máquina. ¿Qué método devuelve false en vez de esperar?",
  ["Reformat every file to the standard style before the commit. Which subcommand?"] = "Reformatea cada archivo al estilo estándar antes del commit. ¿Qué subcomando?",
  ["Release the lock however the function exits. Fill: defer mu.___()"] = "Libera el candado salga como salga la función. Completa: defer mu.___()",
  ["Release the lock however the function leaves, error or not. Which keyword?"] = "Suelta el lock salga como salga la función, con error o sin él. ¿Qué palabra clave?",
  ["Release the module. Which git command names the commit?"] = "Publica el módulo. ¿Qué comando git le pone nombre al commit?",
  ["Remember which stations were seen, with O(1) lookup. Which built-in?"] = "Recordar qué estaciones se vieron, con búsqueda O(1). ¿Qué función integrada?",
  ["Remove a key from a map. Which built-in?"] = "Quita una clave de un map. ¿Qué función integrada?",
  ["Repeat forever until break hands back a value. Which keyword?"] = "Repite para siempre hasta que break devuelva un valor. ¿Qué palabra clave?",
  ["Repeat while a condition holds. Which keyword?"] = "Repite mientras se cumpla una condición. ¿Qué palabra clave?",
  ['Report a failed check and keep the test running. Fill: t.___("got %d", n)'] = 'Reporta una comprobación fallida y sigue con el test. Completa: t.___("got %d", n)',
  ["Resize every photo and keep the input order. Which method?"] = "Reduce todas las fotos y conserva el orden de entrada. ¿Qué método?",
  ["Response + Writer. An interface, so no star. It is also an io.Writer."] = "Response + Writer. Una interfaz, así que sin asterisco. También es un io.Writer.",
  ["ResponseWriter: headers, status, body. Write the status before the body."] = "ResponseWriter: cabeceras, estado, cuerpo. Escribe el estado antes del cuerpo.",
  ["Result and the ? operator"] = "Result y el operador ?",
  ["Result<T, E> is either Ok(value) or Err(error). The compiler makes you check. The till lights up."] = "Result<T, E> es Ok(valor) o Err(error). El compilador te obliga a comprobarlo. La caja se ilumina.",
  ["Return a plus b without the return keyword. What is the last line of the body?"] = "Devuelve a más b sin la palabra return. ¿Cuál es la última línea del cuerpo?",
  ["Return an iterator without naming its long type. Which keyword in the return position?"] = "Devuelve un iterador sin nombrar su tipo largo. ¿Qué palabra clave en la posición de retorno?",
  ["Return the cached answer if it is there. Fill the comma-ok test: if v, ok := memo[n]; ___"] = "Devuelve la respuesta en caché si está ahí. Completa la prueba comma-ok: if v, ok := memo[n]; ___",
  ["Returning &o is safe in Go: the compiler sees the reference outlive the frame and moves the value to the heap. Sharing across goroutines does the same."] = "Devolver &o es seguro en Go: el compilador ve que la referencia sobrevive al marco y mueve el valor al heap. Compartir entre goroutines hace lo mismo.",
  ["Returns a channel that fires once, later. Capital A."] = "Devuelve un channel que dispara una vez, más tarde. A mayúscula.",
  ["Reverse in place: point the current node back at the one before it. Fill: cur.next = ___"] = "Invertir en el sitio: apuntar el nodo actual de vuelta al anterior. Completa: cur.next = ___",
  ["Reverse with prev/cur/next pointers. Floyd's cycle check: slow moves one, fast moves two."] = "Invierte con los punteros prev/cur/next. Ciclo de Floyd: slow avanza uno, fast avanza dos.",
  ["Reverse(3) < Reverse(2). Wrapping at push time is the whole trick; no custom Ord impl needed."] = "Reverse(3) < Reverse(2). Envolver en el push es todo el truco; no hace falta un impl Ord propio.",
  ["Reverse: point the current node backwards. Fill: node.next = ___"] = "Invertir: haz que el nodo actual apunte hacia atrás. Completa: node.next = ___",
  ["Right minus left, plus one for the inclusive end."] = "Derecha menos izquierda, más uno por el extremo incluido.",
  ["Room made: store the value. Which HashMap method writes k to v, replacing an old value if there was one?"] = "Sitio hecho: guarda el valor. ¿Qué método de HashMap escribe k a v, reemplazando el valor viejo si lo había?",
  ["Round five. A shoebox of receipts on the screen. Bo writes merge sort by hand for the crowd, then admits that sorted() has been Timsort all along, and finds a receipt by amount with bisect."] = "Quinta ronda. Una caja de zapatos con recibos en la pantalla. Bo escribe la ordenación por mezcla a mano para el público, luego admite que sorted() ha sido Timsort todo el tiempo, y encuentra un recibo por importe con bisect.",
  ["Round five. Every cook's shift as [start, end]. When is the kitchen staffed at all, as one clean list?"] = "Ronda cinco. El turno de cada cocinero como [inicio, fin]. ¿Cuándo hay alguien en la cocina, como una sola lista limpia?",
  ["Round five. Merge the intervals, Mei. Sort first; the interviewer always waits for that word."] = "Ronda cinco. Fusiona los intervalos, Mei. Ordena primero; el entrevistador siempre espera esa palabra.",
  ["Round five. Staff shifts as {start, end}. Merge the overlapping ones into one schedule."] = "Quinta ronda. Turnos del personal como {inicio, fin}. Fusiona los que se solapan en un solo horario.",
  ["Round five. The night market's noodle stall next door lends its counter as a second whiteboard. Siu Ming lists the cooks' shifts, overlapping every which way, and wants the hours the kitchen is covered as a list of clean blocks. Sort, then one pass: every merged interval is either extended or started."] = "Ronda cinco. El puesto de fideos de al lado en el mercado nocturno presta su mostrador como segunda pizarra. Siu Ming lista los turnos de los cocineros, solapados de cualquier manera, y quiere las horas en que la cocina está cubierta como una lista de bloques limpios. Ordenar, luego una pasada: cada intervalo fusionado o se extiende o se inicia.",
  ["Round five: sort the night's receipts. Write merge sort, then use the built-ins like a grown-up."] = "Quinta ronda: ordena los recibos de la noche. Escribe la ordenación por mezcla, luego usa las integradas como un adulto.",
  ["Round five: the shuffle. Write merge sort by hand, then show me you know the std sorts. O(n log n) or bust!"] = "Ronda cinco: la barajada. Escribe merge sort a mano, y luego demuéstrame que conoces los sorts de std. ¡O(n log n) o nada!",
  ["Round four. A chain of delivery stops, each pointing to the next. Bo reverses it in place, sends two riders down it at different speeds to find the middle, and checks whether the route loops."] = "Cuarta ronda. Una cadena de paradas de reparto, cada una apuntando a la siguiente. Bo la invierte en el sitio, manda dos repartidores a distintas velocidades para encontrar el medio y comprueba si la ruta da vueltas.",
  ["Round four. A million order totals stream past. The third largest, without sorting them all."] = "Cuarta ronda. Un millón de totales de pedidos pasan en flujo. El tercero mayor, sin ordenarlos todos.",
  ["Round four. A million receipts stream past. The third biggest, at any moment, without sorting."] = "Ronda cuatro. Un millón de recibos pasan en streaming. El tercero más grande, en cualquier momento, sin ordenar.",
  ["Round four. Receipts by the million, and Siu Ming wants the kth biggest while they are still arriving. Sorting everything is n log n and needs it all in memory; a heap of k keeps just the contenders. Bo draws a small pile with the smallest on top and starts pushing."] = "Ronda cuatro. Recibos por millones, y Siu Ming quiere el k-ésimo mayor mientras siguen llegando. Ordenarlo todo es n log n y necesita todo en memoria; un heap de k guarda solo a los candidatos. Bo dibuja un montoncito con el menor arriba y empieza a hacer push.",
  ["Round four. Ten thousand receipts: the third biggest, and the five dishes ordered most. Without sorting all of it."] = "Ronda cuatro. Diez mil recibos: el tercero más grande, y los cinco platos más pedidos. Sin ordenarlo todo.",
  ["Round four: a linked list. Reverse it, find the middle, catch the loop."] = "Cuarta ronda: una lista enlazada. Inviértela, encuentra el medio, atrapa el bucle.",
  ["Round four: reverse the chain, then find its middle. The borrow checker is watching."] = "Ronda cuatro: invierte la cadena, luego encuentra su medio. El borrow checker está mirando.",
  ["Round six, the one we always ask. A cache of the last 100 menus. Get and Put in O(1). Go."] = "Sexta ronda, la que siempre preguntamos. Una caché de los últimos 100 menús. Get y Put en O(1). Adelante.",
  ["Round six. A cache that holds n routes. When it is full, the one nobody asked for longest goes."] = "Ronda seis. Una caché que guarda n rutas. Cuando está llena, se va la que nadie ha pedido en más tiempo.",
  ["Round six. Fast hands, Mei. The crab on the kiosk is keeping time."] = "Ronda seis. Manos rápidas, Mei. El cangrejo del kiosco lleva el tiempo.",
  ["Round six. The classics: which two receipts add up to the till's total, are two dish names anagrams, is the shop's slogan a palindrome. A dict, a sort and two pointers. The crowd knows these; Bo has to be fast."] = "Sexta ronda. Los clásicos: qué dos recibos suman el total de la caja, si dos nombres de plato son anagramas, si el eslogan de la tienda es un palíndromo. Un dict, una ordenación y dos punteros. El público se los sabe; Bo tiene que ser rápido.",
  ["Round six. The delivery app looks up the same few routes all night, and the map API charges per call. Siu Ming wants a cache of n routes where the least recently used one leaves first, with get and put in O(1). Bo writes one dict that remembers its order and two methods."] = "Ronda seis. La app de reparto consulta las mismas pocas rutas toda la noche, y la API del mapa cobra por llamada. Siu Ming quiere una caché de n rutas donde la menos usada recientemente sale primero, con get y put en O(1). Bo escribe un dict que recuerda su orden y dos métodos.",
  ["Round six. The menu API caches the last hundred dishes. Which one goes when the hundred-and-first arrives?"] = "Ronda seis. La API del menú cachea los últimos cien platos. ¿Cuál se va cuando llega el ciento uno?",
  ["Round six: the three questions every interview asks. Two-sum, anagram, palindrome. Go!"] = "Sexta ronda: las tres preguntas que hace toda entrevista. Two-sum, anagrama, palíndromo. ¡Ya!",
  ["Round three. A week of profits and losses per hour. Which run of hours made the most?"] = "Ronda tres. Una semana de ganancias y pérdidas por hora. ¿Qué racha de horas ganó más?",
  ["Round three. Daily sales, some negative. Which stretch of days made the most money?"] = "Tercera ronda. Ventas diarias, algunas negativas. ¿Qué tramo de días ganó más dinero?",
  ["Round three. Siu Ming writes a row of numbers on the board: the till, hour by hour, some hours negative. The best run of hours, the best three hours in a row, then the longest streak of orders with no dish repeated. Three windows, each slid across the row exactly once."] = "Ronda tres. Siu Ming escribe una fila de números en la pizarra: la caja, hora a hora, algunas horas en negativo. La mejor racha de horas, las mejores tres horas seguidas, y luego la racha más larga de pedidos sin repetir plato. Tres ventanas, cada una deslizada por la fila exactamente una vez.",
  ["Round three. The MTR map: stations are nodes, lines are edges. Bo builds the adjacency dict, then finds every station reachable from Causeway Bay, breadth first, then depth first."] = "Tercera ronda. El mapa del MTR: las estaciones son nodos, las líneas son aristas. Bo construye el dict de adyacencia y luego encuentra cada estación alcanzable desde Causeway Bay, primero en anchura, luego en profundidad.",
  ["Round three: the MTR map as a graph. Breadth first, then depth first. Do not visit a station twice!"] = "Ronda tres: el mapa del MTR como grafo. Primero en anchura, luego en profundidad. ¡No visites una estación dos veces!",
  ["Round three: the MTR map as a graph. Build it, sweep it wide, then sweep it deep."] = "Tercera ronda: el mapa del MTR como grafo. Constrúyelo, bárrelo a lo ancho, luego a lo profundo.",
  ["Round three: the best run of sales in a week, the busiest k hours, the longest streak of different dishes. All one pass."] = "Ronda tres: la mejor racha de ventas de una semana, las k horas más ocupadas, la racha más larga de platos distintos. Todo en una pasada.",
  ["Round two. Siu Ming draws a staircase and a pile of coins. Bo has climbed the MTR exit ten thousand times and counted the till's change every night; now the question is how many ways and how few coins. A table that fills from the bottom up, and a marker for the impossible."] = "Ronda dos. Siu Ming dibuja una escalera y un montón de monedas. Bo ha subido la salida del MTR diez mil veces y ha contado el cambio de la caja cada noche; ahora la pregunta es cuántas formas y cuántas monedas como mínimo. Una tabla que se llena de abajo arriba, y un marcador para lo imposible.",
  ["Round two. The MTR exit has n steps, you take one or two at a time. How many ways up?"] = "Segunda ronda. La salida del MTR tiene n escalones, subes de uno o de dos en dos. ¿Cuántas formas de subir?",
  ["Round two. The Times Square stairs: one or two steps at a time. How many ways up? Then make change for the till."] = "Ronda dos. Las escaleras de Times Square: uno o dos escalones por vez. ¿Cuántas formas de subir? Luego da el cambio en la caja.",
  ["Round two. The screen shows the whiteboard from the back office: a tree of order numbers. Smaller to the left, larger to the right. Bo has to grow it, walk it in order, measure it and sweep it level by level."] = "Segunda ronda. La pantalla muestra la pizarra de la oficina trasera: un árbol de números de pedido. Menores a la izquierda, mayores a la derecha. Bo tiene que hacerlo crecer, recorrerlo en orden, medirlo y barrerlo nivel a nivel.",
  ["Round two: a binary search tree. Insert, walk it in order, measure it, then level by level."] = "Segunda ronda: un árbol binario de búsqueda. Insertar, recorrerlo en orden, medirlo, luego nivel a nivel.",
  ["Rows go 0..len, so len itself is out. The same test on c covers the right edge; the top and left are handled by wrapping."] = "Las filas van de 0..len, así que len mismo queda fuera. La misma prueba sobre c cubre el borde derecho; arriba e izquierda los maneja el wrapping.",
  ["Rows run from 0 to len(g)-1; len(g) itself is already outside."] = "Las filas van de 0 a len(g)-1; len(g) en sí ya está fuera.",
  ["Run close() when this function returns, even on error. Which keyword?"] = "Ejecuta close() cuando esta función retorne, incluso con error. ¿Qué palabra clave?",
  ["Run cross(), then test its error in the same if. Fill the operator: err ___ nil"] = "Ejecuta cross() y prueba su error en el mismo if. Completa el operador: err ___ nil",
  ["Run every function marked with the #[...] attribute for checks. Which subcommand?"] = "Ejecuta cada función marcada con el atributo #[...] de comprobaciones. ¿Qué subcomando?",
  ["Run fry beside the main thread. Which class from threading?"] = "Ejecutar fry junto al hilo principal. ¿Qué clase de threading?",
  ["Run grind on its own core. Which multiprocessing class?"] = "Ejecuta grind en su propio núcleo. ¿Qué clase de multiprocessing?",
  ["Run the cooks, stop on the first error, wait for all. Fill: g.___()"] = "Lanza los cocineros, para al primer error, espera a todos. Completa: g.___()",
  ["Rune, Count, In, String: one long name. Or len([]rune(s))."] = "Rune, Count, In, String: un nombre largo. O len([]rune(s)).",
  ["Russell Street"] = "Russell Street",
  ["Rust ignores the rest of a line after which two characters?"] = "¿Tras qué dos caracteres ignora Rust el resto de la línea?",
  ["Rust? I only know Go. Is it far?"] = "¿Rust? Yo solo sé Go. ¿Está lejos?",
  ["RwLock: many .read() guards at once, or one .write(). Use it when reads far outnumber writes; Mutex is simpler otherwise."] = "RwLock: muchos guards .read() a la vez, o un solo .write(). Úsalo cuando las lecturas superan de largo a las escrituras; si no, Mutex es más simple.",
  ["S  THIS STREET"] = "S  ESTA CALLE",
  ["S  WHOLE QUEST"] = "S  TODA LA MISIÓN",
  ["S  WHOLE TRACK"] = "S  TODA LA RUTA",
  ["S for string, then printf. Fprintf writes to a writer, Printf to stdout."] = "S de string, luego printf. Fprintf escribe en un writer, Printf en stdout.",
  ["SAVED  %s"] = "GUARDADO  %s",
  ["SAVED %d FILES  in %s"] = "%d ARCHIVOS GUARDADOS  en %s",
  ["SHARE"] = "COMPARTIR",
  ["SHARE THIS QUIZ"] = "COMPARTIR ESTE QUIZ",
  ["SHARED IT"] = "COMPARTIDO",
  ["SPEED TYPER"] = "DEDOS RÁPIDOS",
  ["STOP"] = "PARAR",
  ["STREAK x%d"] = "RACHA x%d",
  ["STREET CLEAR!"] = "¡CALLE SUPERADA!",
  ["Same &mut memo goes into both calls, one after the other. The borrow checker is happy: they do not overlap."] = "El mismo &mut memo entra en las dos llamadas, una tras otra. El borrow checker está contento: no se solapan.",
  ["Same board, Rust this time. The question never changes: input doubles, then what?"] = "La misma pizarra, Rust esta vez. La pregunta nunca cambia: la entrada se duplica, ¿y entonces?",
  ["Same built-in as for slices. A literal map[string]int{} also works."] = "La misma función integrada que para slices. Un literal map[string]int{} también sirve.",
  ["Same keyword as for slices. No index; just the value."] = "La misma palabra clave que para slices. Sin índice; solo el valor.",
  ["Same lesson as the Go till, one floor up: the resource is shared even when the memory is not."] = "La misma lección que la caja de Go, un piso más arriba: el recurso es compartido aunque la memoria no lo sea.",
  ["Same name as Go's entry function, but it needs no package line."] = "Mismo nombre que la función de entrada de Go, pero no necesita línea package.",
  ["Same name as on HashMap, but on a set it returns bool. No contains check needed first."] = "El mismo nombre que en HashMap, pero en un set devuelve bool. No hace falta comprobar contains antes.",
  ["Same name as strings.Contains. Index returns the position or -1."] = "El mismo nombre que strings.Contains. Index devuelve la posición o -1.",
  ["Same name as the Display helper on any value. to_string_pretty adds newlines."] = "El mismo nombre que el ayudante de Display en cualquier valor. to_string_pretty añade saltos de línea.",
  ["Same name as the blocking one in the time module, but awaited."] = "El mismo nombre que la versión bloqueante del módulo time, pero con await.",
  ["Same name as the derived trait, in lowercase."] = "El mismo nombre que el trait derivado, en minúsculas.",
  ["Same row, one column to the left."] = "La misma fila, una columna a la izquierda.",
  ["Same six letters as Go. Use it for early exits, not for the last line."] = "Las mismas seis letras que Go. Úsalo para salidas tempranas, no para la última línea.",
  ["Same thing for both repos at once, with no edit to either go.mod. Which subcommand?"] = "Lo mismo para los dos repos a la vez, sin tocar ningún go.mod. ¿Qué subcomando?",
  ["Same thing from a generator: setup, yield, teardown. Which contextlib decorator?"] = "Lo mismo desde un generador: preparar, yield, limpiar. ¿Qué decorador de contextlib?",
  ["Same verb as go run. cargo build only compiles."] = "El mismo verbo que go run. cargo build solo compila.",
  ["Same word as Go and Rust. Its sibling skips to the next turn instead."] = "La misma palabra que en Go y Rust. Su hermana salta a la siguiente vuelta.",
  ["Same word as Go, but a method that changes the list in place and returns None."] = "La misma palabra que en Go, pero un método que cambia la lista en el sitio y devuelve None.",
  ["Same word as Go, no quotes, no parentheses. from x import y picks one name out."] = "La misma palabra que en Go, sin comillas ni paréntesis. from x import y saca un solo nombre.",
  ["Same word as Go. Rust can drop it on the last line; Python cannot."] = "La misma palabra que en Go. Rust puede omitirla en la última línea; Python no.",
  ["Same word as WaitGroup's. It returns the first non-nil error."] = "La misma palabra que en WaitGroup. Devuelve el primer error no nil.",
  ["Same word as a single import, then parentheses."] = "La misma palabra que un import simple, luego paréntesis.",
  ["Same word as in switch. Turns select into a poll."] = "La misma palabra que en switch. Convierte select en un sondeo.",
  ["Same word, one letter changed. Go has no public keyword; the first letter is the keyword."] = "La misma palabra, una letra cambiada. Go no tiene palabra clave public; la primera letra es la palabra clave.",
  ["Same. Big O drops constants: O(2), O(500) are all O(1). The flat line is drawn."] = "«Same», igual. Big O descarta constantes: O(2), O(500) son todos O(1). La línea plana está dibujada.",
  ["Same. Big O drops constants: O(2), O(500) are all written O(1). The flat line is drawn; the counter street is done."] = "«Same», igual. Big O descarta constantes: O(2), O(500) se escriben todos O(1). La línea plana está dibujada; la calle del mostrador está hecha.",
  ["Satisfied implicitly: any type with those methods implements it."] = "Se satisface implícitamente: cualquier tipo con esos métodos la implementa.",
  ["Save next, flip the link, advance both. prev is the new head when the loop ends."] = "Guarda next, invierte el enlace, avanza ambos. prev es la nueva cabeza al terminar el bucle.",
  ["Save nxt, flip the pointer, step. Three names, one pass, O(1) space. The tuple swap on the last line steps both."] = "Guarda nxt, gira el puntero, avanza. Tres nombres, una pasada, O(1) de espacio. El intercambio de tupla de la última línea avanza ambos.",
  ["Schedules a call for later. Last in, first out. After the return happens."] = "Programa una llamada para después. Último en entrar, primero en salir. Tras el return.",
  ["Second python, second core"] = "Segundo python, segundo núcleo",
  ["Semantic import versioning: v1 and v2 are different packages with different paths, so one binary can depend on both and nothing breaks by surprise."] = "Versionado semántico de importaciones: v1 y v2 son paquetes distintos con rutas distintas, así que un binario puede depender de ambos y nada se rompe por sorpresa.",
  ["Semver tags and the /v2 rule"] = "Etiquetas semver y la regla /v2",
  ["Send a value into the channel. Fill the operator: ch ___ muffin"] = "Envía un valor al channel. Completa el operador: ch ___ muffin",
  ["Send one job now and keep the handle. Which method?"] = "Manda un trabajo ahora y quédate con el manejador. ¿Qué método?",
  ["Send results back to the parent. Which multiprocessing class?"] = "Devuelve los resultados al padre. ¿Qué clase de multiprocessing?",
  ["Send the jobs, then tell the workers there are no more. Which built-in?"] = "Envía los jobs y luego avisa a los workers de que no hay más. ¿Qué built-in?",
  ["Send: safe to move to another thread. Sync: safe to share by &T. Rc has neither, Arc<T> has both when T does. The count is right. Milk tea and a pineapple bun: the afternoon tea set is yours."] = "Send: seguro de mover a otro thread. Sync: seguro de compartir por &T. Rc no tiene ninguno, Arc<T> tiene ambos cuando T los tiene. El contador está bien. Té con leche y un bollo de piña: la merienda es tuya.",
  ["Sender is Clone, Receiver is not: that is the mp and the sc in mpsc. Both tills feed one kitchen."] = "Sender es Clone, Receiver no: eso es la mp y la sc de mpsc. Las dos cajas alimentan una cocina.",
  ["Separate interpreters mean separate memory: nothing is shared by accident, and everything shared on purpose has to be sent."] = "Intérpretes separados significan memoria separada: nada se comparte por accidente y todo lo que se comparte a propósito hay que enviarlo.",
  ['Serve /order with the function serve. Fill: http.___("/order", serve)'] = 'Sirve /order con la función serve. Completa: http.___("/order", serve)',
  ["Serve three bowls, numbered 0, 1, 2. Which built-in counts for the for loop?"] = "Servir tres boles, numerados 0, 1, 2. ¿Qué función integrada cuenta para el bucle for?",
  ["SetMeal extends Order and must run Order's __init__ first. Which built-in reaches the parent?"] = "SetMeal extiende Order y debe ejecutar primero el __init__ de Order. ¿Qué función integrada alcanza al padre?",
  ["Setting a channel to nil disables its case without touching the loop. It is the standard way to drain two inputs that end at different times."] = "Poner un channel a nil desactiva su caso sin tocar el bucle. Es la forma estándar de vaciar dos entradas que terminan en momentos distintos.",
  ["Seven letters, an adverb: at the end, no matter what. Go's defer."] = "Siete letras, un adverbio: al final, pase lo que pase. El defer de Go.",
  ["Seven letters, the end of almost every iterator chain. The type annotation on the left tells it what to build."] = "Siete letras, el final de casi toda cadena de iteradores. La anotación de tipo a la izquierda le dice qué construir.",
  ["Seven letters, the opposite of acquire. Go writes it defer mu.Unlock()."] = "Siete letras, lo contrario de acquire. Go lo escribe defer mu.Unlock().",
  ["Seven letters, the unbounded one. sync_channel(n) would take a capacity."] = "Siete letras, el que no tiene límite. sync_channel(n) llevaría una capacidad.",
  ["Seven letters, to take back a statement. Go 1.16. The tag stays; go get stops choosing it."] = "Siete letras, retirar una afirmación. Go 1.16. La etiqueta se queda; go get deja de elegirla.",
  ["Seven letters. Does the value ... this pattern? Same verb, plural form."] = "Siete letras. ¿El valor ... con este patrón? El verbo inglés match, en tercera persona.",
  ["Seven letters. For humans; Debug is for {:?}."] = "Siete letras. Para humanos; Debug es para {:?}.",
  ["Seven letters. Gather everything into a container: Vec, String, HashMap, even Result."] = "Siete letras. Reúne todo en un contenedor: Vec, String, HashMap, incluso Result.",
  ["Seven letters. Go spelled it chan."] = "Siete letras. Go lo escribía chan.",
  ["Seven letters. The opposite of a debug build. The binary lands in target/ under that name."] = "Siete letras. Lo contrario de una build de debug. El binario cae en target/ bajo ese nombre.",
  ["Seven letters: a whole server process that owns the objects and answers questions about them."] = "Siete letras: todo un proceso servidor que posee los objetos y responde preguntas sobre ellos.",
  ["Seven letters: swap one thing for another. The arrow reads 'with'."] = "Siete letras: cambiar una cosa por otra. La flecha se lee 'por'.",
  ["Seven letters: to need. Several of them go in one parenthesised block."] = "Siete letras: necesitar. Varias van en un solo bloque entre paréntesis.",
  ["Seven streets of Big O. Read a loop, name its cost, then write the faster one, in Go."] = "Siete calles de Big O. Lee un bucle, di su coste, y luego escribe el más rápido, en Go.",
  ["Seven streets of Big O. Read a loop, name its cost, then write the faster one, in Python."] = "Siete calles de Big O. Lee un bucle, di su coste, y luego escribe el más rápido, en Python.",
  ["Seven streets of Big O. Read a loop, name its cost, then write the faster one, in Rust."] = "Siete calles de Big O. Lee un bucle, di su coste, y luego escribe el más rápido, en Rust.",
  ["Shared and mutable across threads: wrap it, then lock it."] = "Compartido y mutable entre threads: envuélvelo, luego bloquéalo.",
  ["Shared references and data races"] = "Referencias compartidas y carreras de datos",
  ["Shipped. One more: the code still sorts by hand."] = "Publicado. Una más: el código aún ordena a mano.",
  ["Short declaration. Fill the operator: floor ___ 8"] = "Declaración corta. Completa el operador: floor ___ 8",
  ["Short for format. Println lives there."] = "Abreviatura de format. Println vive ahí.",
  ["Short for function. Then the name, then arguments in parentheses."] = "Abreviatura de function. Luego el nombre, luego los argumentos entre paréntesis.",
  ["Shout the shop name. Which strings function upper-cases?"] = "Grita el nombre de la tienda. ¿Qué función de strings pasa a mayúsculas?",
  ["Shouted in capitals, and also an environment variable. GO, MAX, and short for processors."] = "Se grita en mayúsculas y también es una variable de entorno. GO, MAX y la abreviatura de procesadores.",
  ["Signed, 32 bits, the default integer type. Write the annotation."] = "Con signo, 32 bits, el tipo entero por defecto. Escribe la anotación.",
  ["Since Go 1.17 go.mod lists every module the build needs, direct or not, so one file describes the whole graph. go mod tidy keeps the comments honest."] = "Desde Go 1.17 go.mod lista todos los módulos que la compilación necesita, directos o no, así que un fichero describe el grafo entero. go mod tidy mantiene honestos los comentarios.",
  ["Since Go 1.19 the type itself is atomic, so no &x is needed. Name and bit width."] = "Desde Go 1.19 el tipo mismo es atómico, así que no hace falta &x. Nombre y ancho en bits.",
  ["Since Python 3.8 this is real POSIX shared memory: one block of bytes, mapped into every process that asks for it by name."] = "Desde Python 3.8 esto es memoria compartida POSIX de verdad: un bloque de bytes mapeado en cada proceso que lo pide por su nombre.",
  ["Siu Ming"] = "Siu Ming",
  ["Siu Ming draws the Causeway Bay MTR exit: n steps. Then the till: coins of 1, 3 and 4, and an amount to make with the fewest coins. Two problems, one trick: write the answer for the small cases, then build every bigger one out of the ones already on the board."] = "Siu Ming dibuja la salida del MTR de Causeway Bay: n escalones. Luego la caja: monedas de 1, 3 y 4, y un importe que formar con las menos monedas posibles. Dos problemas, un truco: escribe la respuesta de los casos pequeños y construye cada uno mayor con los que ya están en la pizarra.",
  ["Siu Ming pins a strip of numbers to the board: Lucky Mac's daily profit for a month, red on the bad days. Best run of days, best k days in a row, longest run of distinct dishes on the specials board. Three questions, one shape: a window that slides right and never looks back."] = "Siu Ming clava una tira de números en la pizarra: la ganancia diaria de Lucky Mac durante un mes, en rojo los días malos. La mejor racha de días, los mejores k días seguidos, la racha más larga de platos distintos en el tablero de especiales. Tres preguntas, una forma: una ventana que se desliza a la derecha y nunca mira atrás.",
  ["Siu Ming pins the week's roster to the board: thirty shifts, half of them overlapping, the manager wants one clean line per stretch of coverage, and then how many cooks are ever on at once. Mei taps the first column: sort by start and the mess becomes a walk."] = "Siu Ming clava el cuadrante de la semana en la pizarra: treinta turnos, la mitad solapados, el gerente quiere una línea limpia por cada tramo cubierto, y luego cuántos cocineros llegan a estar a la vez. Mei toca la primera columna: ordena por inicio y el lío se vuelve un paseo.",
  ["Siu Ming's phone book of suppliers, sorted by name. Nobody reads it from the front. Open the middle, go left or right, and the book is half as thick every time. Mei draws a line that climbs, then almost stops."] = "La guía telefónica de proveedores de Siu Ming, ordenada por nombre. Nadie la lee desde el principio. Abre por el medio, ve a la izquierda o a la derecha, y el libro es la mitad de grueso cada vez. Mei dibuja una línea que sube y luego casi se detiene.",
  ["Siu Ming's phone book of suppliers, sorted by name. Open the middle, go left or right, and the book is half as thick every time. Mei draws the line that climbs, then almost lies down."] = "La guía telefónica de proveedores de Siu Ming, ordenada por nombre. Abre por el medio, ve a la izquierda o a la derecha, y el libro es la mitad de grueso cada vez. Mei dibuja la línea que sube y luego casi se tumba.",
  ["Six goroutines write one slice with no lock. Which expression keeps that safe?"] = "Seis goroutines escriben en un slice sin lock. ¿Qué expresión lo mantiene seguro?",
  ["Six letters, capital O. Rust's answer to nil: the type itself says maybe."] = "Seis letras, O mayúscula. La respuesta de Rust a nil: el propio tipo dice quizás.",
  ["Six letters, same word as Go, but there is no type keyword in front."] = "Seis letras, la misma palabra que Go, pero sin la palabra type delante.",
  ["Six letters, takes a reference to the key, returns the old value as Option."] = "Seis letras, recibe una referencia a la clave, devuelve el valor viejo como Option.",
  ["Six letters, the most recent. @v1 or @main work too: a major, a branch, a commit hash."] = "Seis letras, lo más reciente. @v1 o @main también valen: un major, una rama, un hash de commit.",
  ["Six letters, the noun for what a function gives back. This one blocks until it exists."] = "Seis letras, el sustantivo de lo que devuelve una función. Este bloquea hasta que exista.",
  ["Six letters, the same method a HashMap uses to store a key. Takes the value, not a reference."] = "Seis letras, el mismo método que usa un HashMap para guardar una clave. Recibe el valor, no una referencia.",
  ["Six letters, the same word the C library uses for deleting a file."] = "Seis letras, la misma palabra que usa la biblioteca de C para borrar un fichero.",
  ["Six letters, the word Unix uses for a background service."] = "Seis letras, la palabra que usa Unix para un servicio en segundo plano.",
  ["Six letters, the word for a supplier. The folder it makes has the same name."] = "Seis letras, la palabra para un proveedor. La carpeta que crea lleva el mismo nombre.",
  ["Six letters, the write of every HashMap. Returns the previous value as Option."] = "Seis letras, la escritura de todo HashMap. Devuelve el valor anterior como Option.",
  ["Six letters, under sync/. Go 1.19 also has atomic.Int64 with .Add(1)."] = "Seis letras, bajo sync/. Go 1.19 también tiene atomic.Int64 con .Add(1).",
  ["Six letters, what you do with a form. It returns immediately, with a Future."] = "Seis letras, lo que se hace con un formulario. Vuelve enseguida, con un Future.",
  ["Six letters. Every result, in order, comma separated."] = "Seis letras. Cada resultado, en orden, separado por comas.",
  ["Six letters. Generic over T: Some(T) or None."] = "Seis letras. Genérico sobre T: Some(T) o None.",
  ["Six letters. Give the field a different name on the wire. rename_all does a whole struct."] = "Seis letras. Dale al campo otro nombre en el cable. rename_all hace un struct entero.",
  ["Six letters. Like a coffee one: only what passes the test comes through."] = "Seis letras. Como el del café: solo pasa lo que supera la prueba.",
  ["Six letters. The closure gets &char and returns bool; true keeps the item."] = "Seis letras. El closure recibe &char y devuelve bool; true conserva el elemento.",
  ["Six letters. The compiler writes the trait implementation for you."] = "Seis letras. El compilador escribe la implementación del trait por ti.",
  ["Six letters. The word in fmt spelled out. Variables can go straight inside the braces."] = "Seis letras. La palabra de fmt escrita entera. Las variables pueden ir directamente dentro de las llaves.",
  ["Six letters. To obtain from a source."] = "Seis letras. Obtener de una fuente, en inglés.",
  ["Six letters. Two arms: Ok(T) and Err(E)."] = "Seis letras. Dos ramas: Ok(T) y Err(E).",
  ["Six letters. What you do when you are sure it is there."] = "Seis letras. Lo que haces cuando estás seguro de que está ahí.",
  ["Six letters: straight to the source, no proxy in between."] = "Seis letras: directo a la fuente, sin proxy en medio.",
  ["Six letters: to bring together. tokio::join! does the same for a fixed number."] = "Seis letras: reunir. tokio::join! hace lo mismo para un número fijo.",
  ["Six letters; other languages say catch. Name the type after it, never bare."] = "Seis letras; otros lenguajes dicen catch. Nombra el tipo después, nunca a pelo.",
  ["Six riders wait on the kerb because the backend asks the map API one address at a time."] = "Seis repartidores esperan en la acera porque el backend pregunta a la API de mapas una dirección a la vez.",
  ["Six tickets sent. Now end the cooks' loops: recv must return Err. What do you do with tx?"] = "Seis tickets enviados. Ahora termina los bucles de los cocineros: recv debe devolver Err. ¿Qué haces con tx?",
  ["Six woks, one tray rack, one map of dish counts. The program died with: concurrent map writes."] = "Seis woks, una estantería, un map con la cuenta de platos. El programa murió con: concurrent map writes.",
  ["Six workers, one out channel. Who ends the range over out, and how?"] = "Seis workers, un channel out. ¿Quién termina el range sobre out, y cómo?",
  ["Size the pool by the machine. Which runtime call reports the cores?"] = "Dimensiona el pool según la máquina. ¿Qué llamada de runtime informa de los núcleos?",
  ["Skip a closed shop and go on to the next one. Which keyword?"] = "Salta una tienda cerrada y pasa a la siguiente. ¿Qué palabra clave?",
  ["Skip writing __init__, __repr__ and __eq__ by hand. Which decorator generates them from the fields?"] = "Ahorrarse escribir __init__, __repr__ y __eq__ a mano. ¿Qué decorador los genera a partir de los campos?",
  ["Slices alias. Use copy() or append([]int(nil), a...) when you need your own."] = "Los slices comparten memoria. Usa copy() o append([]int(nil), a...) cuando necesites el tuyo propio.",
  ["Sliding window, two pointers"] = "Ventana deslizante, dos punteros",
  ["Sliding window: O(n) instead of O(n*k) for summing every window from scratch."] = "Ventana deslizante: O(n) en vez de O(n*k) por sumar cada ventana desde cero.",
  ["Sliding windows and two pointers"] = "Ventanas deslizantes y dos punteros",
  ["Smaller goes left, bigger goes right. Draw it before you type it."] = "Lo menor va a la izquierda, lo mayor a la derecha. Dibújalo antes de teclearlo.",
  ["Smaller goes left, bigger goes right. In Rust a leaf is None and a child is a Box."] = "El menor va a la izquierda, el mayor a la derecha. En Rust una hoja es None y un hijo es un Box.",
  ["Smaller left, larger right: the BST invariant. Assigning the result back handles the None case."] = "Menores a la izquierda, mayores a la derecha: el invariante del BST. Asignar el resultado de vuelta maneja el caso None.",
  ["Smaller values go down one side. Fill the arm: if v < n.val => insert(&mut n.___, v)"] = "Los valores menores bajan por un lado. Completa la rama: if v < n.val => insert(&mut n.___, v)",
  ["Smaller values go left. Fill: n.Left = insert(n.___, v)"] = "Los valores menores van a la izquierda. Completa: n.Left = insert(n.___, v)",
  ["Smaller wins: the smallest value floats to index 0."] = "Gana el menor: el valor más pequeño flota hasta el índice 0.",
  ["So I only have to know which one waits and which one computes."] = "Entonces solo tengo que saber cuál espera y cuál calcula.",
  ["So binary search on n sorted items costs how much, in Big O?"] = "Entonces, ¿cuánto cuesta la búsqueda binaria sobre n elementos ordenados, en Big O?",
  ["So binary_search on n sorted items costs how much, in Big O?"] = "Entonces, ¿cuánto cuesta binary_search sobre n elementos ordenados, en Big O?",
  ["So bisect on n sorted items costs how much, in Big O?"] = "Entonces, ¿cuánto cuesta bisect sobre n elementos ordenados, en Big O?",
  ["So put it somewhere they cannot reach. Go has a folder name for exactly that."] = "Pues ponla donde no lleguen. Go tiene un nombre de carpeta justo para eso.",
  ["So share the bytes and send only the name of the block?"] = "¿Entonces comparto los bytes y solo envío el nombre del bloque?",
  ["Sockets, file handles, locks and lambdas do not travel. Send plain data and let the child open what it needs on its own side."] = "Sockets, descriptores de fichero, bloqueos y lambdas no viajan. Envía datos planos y deja que el hijo abra lo que necesite en su lado.",
  ["Sogo"] = "Sogo",
  ["Sogo's directory is a map from shop name to floor. Missing keys return the zero value, so you must ask comma-ok before you trust the number."] = "El directorio de Sogo es un map de nombre de tienda a piso. Las claves ausentes devuelven el valor cero, así que pregunta con comma-ok antes de fiarte del número.",
  ["Some or None. Rust has no null, so the possibly-empty next is spelled out in the type."] = "Some o None. Rust no tiene null, así que el siguiente, que puede estar vacío, se escribe en el tipo.",
  ["Sort by start, then walk once: if the next interval starts before the last merged one ends, extend that end to the larger; otherwise push a new interval. O(n log n) for the sort, O(n) for the walk."] = "Ordena por inicio y luego recorre una vez: si el siguiente intervalo empieza antes de que termine el último fusionado, extiende ese final al mayor; si no, haz push de un intervalo nuevo. O(n log n) por el sort, O(n) por el recorrido.",
  ["Sort by start. Walk once: if the next interval starts before the last merged one ends, extend that end to the larger of the two; otherwise start a new block."] = "Ordena por inicio. Recorre una vez: si el siguiente intervalo empieza antes de que termine el último fusionado, extiende ese final al mayor de los dos; si no, empieza un bloque nuevo.",
  ["Sort first, Bo. Once they're in order, overlaps are always neighbours."] = "Ordena primero, Bo. Una vez en orden, los solapamientos siempre son vecinos.",
  ["Sort first. Sorted, the only interval that can overlap is the one you just kept."] = "Ordena primero. Ordenado, el único intervalo que puede solaparse es el que acabas de conservar.",
  ["Sort intervals by start; then every overlap is adjacent. Overlap when cur's start <= last's end: extend last's end with max. Otherwise append. Rooms: sort starts and ends separately, two pointers."] = "Ordena los intervalos por inicio; así cada solapamiento queda adyacente. Se solapan cuando el inicio de cur <= el fin de last: extiende el fin de last con max. Si no, añade. Salas: ordena inicios y fines por separado, dos punteros.",
  ["Sort once for O(n log n), then look items up many times. Each lookup then costs O(___)"] = "Ordenar una vez por O(n log n), luego buscar elementos muchas veces. Cada búsqueda cuesta entonces O(___)",
  ["Sort orders by price with a one-line function. Which keyword makes it?"] = "Ordenar los pedidos por precio con una función de una línea. ¿Qué palabra clave la crea?",
  ["Sort the amounts a little faster, when equal items may swap order. Which Vec method?"] = "Ordenar los importes un poco más rápido, cuando los elementos iguales pueden cambiar de orden. ¿Qué método de Vec?",
  ["Sort the dish names by length, into a new list. Which built-in?"] = "Ordenar los nombres de los platos por longitud, en una lista nueva. ¿Qué función integrada?",
  ["Sort the dish names shortest first, in place. Which built-in is the key?"] = "Ordenar los nombres de los platos del más corto al más largo, en el sitio. ¿Qué función integrada es la key?",
  ["Sort the intervals by start, earliest first. Fill the comparison."] = "Ordena los intervalos por inicio, el más temprano primero. Completa la comparación.",
  ["Sort the names in place. Fill: slices.___(names)"] = "Ordena los nombres in situ. Completa: slices.___(names)",
  ["Sort the shifts by start time so overlaps sit side by side. Which element does the key pick?"] = "Ordena los turnos por hora de inicio para que los solapados queden juntos. ¿Qué elemento elige la key?",
  ["Sort the supplier names. Which function from the sort package?"] = "Ordenar los nombres de los proveedores. ¿Qué función del paquete sort?",
  ["Sort, then one pass with a running last: O(n log n) total, O(n) output. The gaps are between the blocks."] = "Ordena, luego una pasada con un last en marcha: O(n log n) total, O(n) de salida. Los huecos están entre los bloques.",
  ["Sorted input trades the HashMap for two indices: O(n) time and O(1) space after the sort."] = "La entrada ordenada cambia el HashMap por dos índices: O(n) tiempo y O(1) espacio tras el sort.",
  ["Sorted prices. Find 25 in log n. Then sort the unsorted ones in n log n."] = "Precios ordenados. Encuentra 25 en log n. Luego ordena los desordenados en n log n.",
  ["Sorted. Sorting costs O(n log n) once; every search after is O(log n). The phone book street is done."] = "«Sorted», ordenado. Ordenar cuesta O(n log n) una vez; cada búsqueda después es O(log n). La calle de la guía telefónica está hecha.",
  ["Sorting and searching"] = "Ordenar y buscar",
  ["Sorting: n log n"] = "Ordenación: n log n",
  ["Sounds like request, spelled with a w. Built on hyper and tokio."] = "Suena como request, escrito con w. Construido sobre hyper y tokio.",
  ["Space complexity"] = "Complejidad espacial",
  ["Space counts extra memory, not the input. In-place sort: O(1). A copy of the list: O(n). Recursion uses stack: quicksort O(log n) on average. Memos trade space for time."] = "El espacio cuenta la memoria extra, no la entrada. Ordenación en el sitio: O(1). Una copia de la lista: O(n). La recursión usa pila: quicksort O(log n) en promedio. Los memos cambian espacio por tiempo.",
  ["Space counts extra memory, not the input. list.sort in place: O(1). sorted() makes a copy: O(n). Recursion uses stack: quicksort O(log n) on average. Memos trade space for time."] = "El espacio cuenta la memoria extra, no la entrada. list.sort en el sitio: O(1). sorted() hace una copia: O(n). La recursión usa pila: quicksort O(log n) en promedio. Los memos cambian espacio por tiempo.",
  ["Space counts extra memory, not the input. sort_unstable in place: O(1). A clone of the Vec: O(n). Recursion uses stack: quicksort O(log n) on average. Memos trade space for time."] = "El espacio cuenta la memoria extra, no la entrada. sort_unstable en el sitio: O(1). Un clone del Vec: O(n). La recursión usa pila: quicksort O(log n) en promedio. Los memos cambian espacio por tiempo.",
  ["Spawn re-imports your file in the child. Anything at top level runs again, including the spawning."] = "spawn reimporta tu fichero en el hijo. Todo lo del nivel superior vuelve a ejecutarse, incluido el arranque.",
  ["Split in half, sort each half, merge. The merge is where the n comes from."] = "Partir por la mitad, ordenar cada mitad, mezclar. La mezcla es de donde sale la n.",
  ["Split the app into packages and let the Times Square shop import it from GitHub. Paths, go.mod, go get, tags. Ship v1.0.0."] = "Parte la app en paquetes y deja que la tienda de Times Square la importe desde GitHub. Rutas, go.mod, go get, etiquetas. Publica v1.0.0.",
  ["Spread to all four neighbours: down, up, right, and the last one. Fill it."] = "Extiende a los cuatro vecinos: abajo, arriba, derecha, y el último. Complétalo.",
  ["Sprintf returns the text. %s string, %d int, %v anything."] = "Sprintf devuelve el texto. %s string, %d int, %v cualquier cosa.",
  ["Stairs, one or two steps at a time. How many ways reach step 2?"] = "Escaleras, de uno o dos escalones a la vez. ¿Cuántas formas llegan al escalón 2?",
  ["Star before the type. & takes the address. *p reads through it."] = "Asterisco antes del tipo. & toma la dirección. *p lee a través de él.",
  ["Star then the type name. A value receiver (o Order) would change a copy."] = "Asterisco y luego el nombre del tipo. Un receptor por valor (o Order) cambiaría una copia.",
  ["Start a new module for the project. Fill the subcommand: go ___ init"] = "Inicia un módulo nuevo para el proyecto. Completa el subcomando: go ___ init",
  ["Start a new thread that runs this closure. Which function?"] = "Arranca un thread nuevo que ejecute este closure. ¿Qué función?",
  ["Start a task in the background and keep going. Which tokio function?"] = "Arranca una tarea en segundo plano y sigue adelante. ¿Qué función de tokio?",
  ["Start an anonymous function as a goroutine. What closes the line?"] = "Lanza una función anónima como goroutine. ¿Qué cierra la línea?",
  ["Start fetch in the background and keep going without awaiting it yet. Which asyncio function?"] = "Arrancar fetch en segundo plano y seguir sin hacerle await todavía. ¿Qué función de asyncio?",
  ["Start fry() in a new goroutine. Which keyword?"] = "Lanza fry() en una goroutine nueva. ¿Qué palabra clave?",
  ["Start the event loop with main(). Which asyncio function?"] = "Arrancar el bucle de eventos con main(). ¿Qué función de asyncio?",
  ["Start the fetch without waiting for it. Which keyword is Go's async?"] = "Arranca el fetch sin esperarlo. ¿Qué palabra clave es el async de Go?",
  ['Start the server on port 8080 and block. Fill: http.___(":8080", nil)'] = 'Arranca el servidor en el puerto 8080 y bloquea. Completa: http.___(":8080", nil)',
  ["Start them all first, then join them all: otherwise the second loop waits for the first wok before lighting the second."] = "Arráncalos todos primero, luego únelos todos: si no, el segundo bucle espera al primer wok antes de encender el segundo.",
  ["Start three workers, counting each one first. Fill: wg.___(1)"] = "Arranca tres workers, contando cada uno primero. Completa: wg.___(1)",
  ["Start with an empty dict. What literal is it?"] = "Empezar con un dict vacío. ¿Qué literal es?",
  ["Starting at 0 would answer 0 for [-3, -1]; the right answer is -1. Seed from the data."] = "Empezar en 0 respondería 0 para [-3, -1]; la respuesta correcta es -1. Siembra desde los datos.",
  ["Starts like is_some(), then one more word joining a condition. Three words, two underscores."] = "Empieza como is_some(), luego una palabra más que une una condición. Tres palabras, dos guiones bajos.",
  ["Station to its neighbours: a dict whose missing keys start as an empty list. Fill the factory."] = "De estación a sus vecinas: un dict cuyas claves ausentes empiezan como lista vacía. Completa la fábrica.",
  ["Steam. Hash brown. We did it."] = "Vapor. Hash brown. Lo logramos.",
  ["Step i is reached from one step below or two steps below. Fill dp[i]."] = "Al escalón i se llega desde uno más abajo o desde dos más abajo. Completa dp[i].",
  ["Stop everything: the till has no paper and that is a bug. Which built-in raises the crash?"] = "Para todo: la caja no tiene papel y eso es un bug. ¿Qué built-in lanza el fallo?",
  ["Stop the child from spawning children. Which dunder goes in the guard?"] = "Impide que el hijo cree hijos. ¿Qué dunder va en la guarda?",
  ["Stop when the guest walks out. Fill: case <-ctx.___()"] = "Para cuando el cliente se vaya. Completa: case <-ctx.___()",
  ["StopIteration ends the protocol; return inside a generator raises it. The conveyor serves ten thousand bowls, one at a time."] = "StopIteration termina el protocolo; un return dentro de un generador la lanza. La cinta sirve diez mil boles, uno a uno.",
  ["Store into memo[n] before returning. Same shape works for any overlapping subproblem."] = "Guarda en memo[n] antes de devolver. La misma forma sirve para cualquier subproblema solapado.",
  ["String and &str"] = "String y &str",
  ["String owns, &str borrows. len() counts bytes, chars().count() counts characters."] = "String posee, &str toma prestado. len() cuenta bytes, chars().count() cuenta caracteres.",
  ["String() string satisfies fmt.Stringer. Println and %v call it automatically."] = "String() string satisface fmt.Stringer. Println y %v lo llaman automáticamente.",
  ['String::from("..") or "..".to_string(). &str borrows, String owns and can grow.'] = 'String::from("..") o "..".to_string(). &str toma prestado, String posee y puede crecer.',
  ['Strings, not ints: "1" != 1 in Python. Read the input type before the first line.'] = 'Strings, no ints: "1" != 1 en Python. Lee el tipo de la entrada antes de la primera línea.',
  ["Strings, runes, bytes"] = "Strings, runes, bytes",
  ["Struct tags and encoding/json"] = "Struct tags y encoding/json",
  ["Struct tags are strings after the type. json, xml, db... each package reads its own."] = "Los struct tags son strings tras el tipo. json, xml, db... cada paquete lee el suyo.",
  ["Structs, pointers, methods, interfaces"] = "Structs, punteros, métodos, interfaces",
  ["Sum of every window of k items: add the newcomer, subtract the one that just left. Which index left?"] = "Suma de cada ventana de k elementos: suma el que entra, resta el que acaba de salir. ¿Qué índice salió?",
  ["Summing n prices with an iterator: what is the cost in Big O?"] = "Sumar n precios con un iterador: ¿cuál es el coste en Big O?",
  ["Swap the first word for Thread and the same block does I/O instead. That is the whole API: one word decides which kind of parallelism you get."] = "Cambia la primera palabra por Thread y el mismo bloque hace E/S. Esa es toda la API: una palabra decide qué clase de paralelismo obtienes.",
  ["Swap the whole menu in one step while readers are reading. Which atomic type?"] = "Cambia el menú entero de un paso mientras los lectores leen. ¿Qué tipo atómico?",
  ["Switch one select case off for good. What do you set the channel to?"] = "Apaga un caso de select para siempre. ¿A qué pones el channel?",
  ["T: PartialOrd + Copy. Bounds are checked at compile time, so largest(&[1.5, 2.5]) and largest(&[18, 22]) both work."] = "T: PartialOrd + Copy. Los bounds se comprueban al compilar, así que largest(&[1.5, 2.5]) y largest(&[18, 22]) funcionan los dos.",
  ["TAB again: answer   ESC map"] = "TAB otra vez: respuesta   ESC mapa",
  ["TAB hint   F5 auto   ESC map"] = "TAB pista   F5 auto   ESC mapa",
  ["TAB hint   F5 auto   F6 share   ESC map"] = "TAB pista   F5 auto   F6 compartir   ESC mapa",
  ["THREADS  -  the lunch rush"] = "THREADS  -  la hora punta del mediodía",
  ["THREADS  ·  the lunch rush"] = "THREADS  ·  la hora punta del mediodía",
  ["THREE LANGUAGES"] = "TRES LENGUAJES",
  ["Table 7 has a seat. Every other table has nothing. What does the last line return?"] = "La mesa 7 tiene asiento. Las demás no tienen nada. ¿Qué devuelve la última línea?",
  ["Tag it v1.0.0"] = "Etiquétalo v1.0.0",
  ["Tags are immutable in Go's world: moving one breaks every go.sum that saw it. retract, then tag v1.0.2, is the only honest fix."] = "En el mundo de Go las etiquetas son inmutables: mover una rompe todos los go.sum que la vieron. retract y luego etiquetar v1.0.2 es el único arreglo honesto.",
  ["Take any Cook without naming a type parameter. Which keyword goes before the trait?"] = "Acepta cualquier Cook sin nombrar un parámetro de tipo. ¿Qué palabra clave va antes del trait?",
  ["Take one back out of the buffered channel. Arrow, then the channel's name."] = "Saca uno del channel con buffer. Flecha y luego el nombre del channel.",
  ["Take one from stock, but only if nobody moved it since you read it. Which method?"] = "Descuenta uno del stock, pero solo si nadie lo movió desde que lo leíste. ¿Qué método?",
  ['Take the address of a new Order so p is a *Order. Fill: p := ___Order{Item: "set"}'] = 'Toma la dirección de un Order nuevo para que p sea un *Order. Completa: p := ___Order{Item: "set"}',
  ["Take the front station off the queue. Fill: queue = queue[___]"] = "Saca la estación del frente de la cola. Completa: queue = queue[___]",
  ["Take the next result, waiting if the queue is empty. Which method?"] = "Coge el siguiente resultado y espera si la cola está vacía. ¿Qué método?",
  ["Take the second and third tray, items 1 and 2. What goes in the brackets?"] = "Tomar la segunda y la tercera bandeja, elementos 1 y 2. ¿Qué va entre los corchetes?",
  ["Take the station that has waited longest. Which VecDeque method returns Option<u32> from the front?"] = "Toma la estación que más ha esperado. ¿Qué método de VecDeque devuelve Option<u32> desde el frente?",
  ["Takes the key and the value by value. Returns the old value as an Option, which we ignore here."] = "Toma la clave y el valor por valor. Devuelve el valor anterior como Option, que aquí ignoramos.",
  ["Tea first, lifetimes second. The set is almost ready."] = "Primero el té, luego los lifetimes. La merienda casi está.",
  ['Teach println!("{}") to print an Order. Which fmt trait?'] = 'Enseña a println!("{}") a imprimir un Order. ¿Qué trait de fmt?',
  ["Tell an empty order from a shut belt. Name the second variable of the receive."] = "Distingue un pedido vacío de una cinta parada. Nombra la segunda variable de la recepción.",
  ["Tell receivers no more hash browns will come. Which built-in?"] = "Avisa a los receptores de que no vendrán más hash browns. ¿Qué built-in?",
  ["Test the package the way a caller sees it. Fill the suffix of the test package name."] = "Prueba el paquete tal como lo ve quien lo llama. Rellena el sufijo del nombre del paquete de prueba.",
  ["Text plus a number fails. Which built-in turns 4 into text first?"] = "Texto más un número falla. ¿Qué función integrada convierte primero 4 en texto?",
  ["That is BFS: pop front, push unseen neighbours. First arrival is the shortest path."] = "Eso es BFS: saca del frente, mete los vecinos no vistos. La primera llegada es el camino más corto.",
  ["That is a trait. Go had interfaces; Rust makes you say impl."] = "Eso es un trait. Go tenía interfaces; Rust te hace decir impl.",
  ["That is the module path doing its job. Now he needs it pinned, or tomorrow's build is a different program."] = "Eso es la ruta del módulo haciendo su trabajo. Ahora necesita fijarla, o la compilación de mañana será otro programa.",
  ["That is the second value of a receive. One line tells you which."] = "Ese es el segundo valor de una recepción. Una línea te dice cuál de los dos.",
  ["That is why the sender closes: only the side that knows nothing more is coming can say so safely."] = "Por eso cierra el emisor: solo el lado que sabe que no viene nada más puede decirlo sin peligro.",
  ["That push is the release. The proxy notices the tag the first time anyone asks for it; there is nothing else to upload."] = "Ese push es la release. El proxy se entera de la etiqueta la primera vez que alguien la pide; no hay nada más que subir.",
  ["The ! marks a macro call. Macros can take any number of arguments; functions cannot."] = "El ! marca una llamada a macro. Las macros aceptan cualquier número de argumentos; las funciones no.",
  ["The * you would write in resize(*job), spelled out, then map."] = "El * que escribirías en resize(*job), deletreado, y luego map.",
  ["The 1 a.m. callback is the Python round. Seven whiteboard classics. Get the OFFER."] = "El callback de la 1 de la madrugada es la ronda de Python. Siete clásicos de pizarra. Consigue la OFFER.",
  ["The 11:00 price change holds the write side. Which call does a reader make?"] = "El cambio de precio de las 11:00 tiene el lado de escritura. ¿Qué llamada hace un lector?",
  ["The Express counter"] = "El mostrador del Express",
  ["The Express kiosks run Rust. Finish your coffee, I will show you main."] = "Los kioscos del Express corren Rust. Termina tu café, te enseño main.",
  ["The Express kitchen"] = "La cocina del Express",
  ["The Express set"] = "El menú del Express",
  ["The Express till"] = "La caja del Express",
  ["The GIL protects CPython's own memory bookkeeping. It makes single-threaded code fast and multi-threaded arithmetic pointless."] = "El GIL protege la contabilidad de memoria del propio CPython. Hace rápido el código de un solo hilo y vuelve inútil la aritmética con varios.",
  ["The GIL serializes bytecode; C extensions and I/O release it. Python 3.13 can build without it. Three woks fry at once; the shift is over."] = "El GIL serializa el bytecode; las extensiones en C y la E/S lo liberan. Python 3.13 puede compilarse sin él. Tres woks fríen a la vez; el turno ha terminado.",
  ["The Go 1.21 builtin that picks the larger of two ints."] = "La función integrada de Go 1.21 que elige el mayor de dos ints.",
  ["The I in the middle of GIL, written out: the thing that runs your bytecode."] = "La I del medio de GIL, escrita entera: lo que ejecuta tu bytecode.",
  ['The JSON says "dish" but the field is name. Which serde attribute maps them?'] = 'El JSON dice "dish" pero el campo es name. ¿Qué atributo de serde los relaciona?',
  ["The MTR gate is a function: tap(card) (ok bool, err error). Go functions can return more than one value. That is how errors travel."] = "El torniquete del MTR es una función: tap(card) (ok bool, err error). Las funciones Go pueden devolver más de un valor. Así viajan los errores.",
  ["The MTR map is a graph. Level by level is BFS; as deep as you can is DFS."] = "El mapa del MTR es un grafo. Nivel por nivel es BFS; tan hondo como puedas es DFS.",
  ["The O(n) fix: remember each name as you go. What value type makes the map a set?"] = "El arreglo O(n): recordar cada nombre según avanzas. ¿Qué tipo de valor convierte el map en un set?",
  ["The O(n) fix: remember each name as you go. Which built-in is the set?"] = "El arreglo O(n): recordar cada nombre según avanzas. ¿Qué función integrada es el set?",
  ["The O(n) fix: remember each name as you go. Which std collection is the set?"] = "El arreglo O(n): recordar cada nombre según avanzas. ¿Qué colección de std es el set?",
  ["The __name__ guard: the script runs main() when executed, stays quiet when imported. The shift begins."] = "La guarda __name__: el script ejecuta main() al correr y calla al importarse. Empieza el turno.",
  ["The amount still to make after spending this one coin."] = "El importe que queda por formar tras gastar esta moneda.",
  ["The ampersand, then the same word that made a changeable."] = "El ampersand y luego la misma palabra que hizo a a modificable.",
  ["The argument is evaluated on the defer line. Only the call is delayed."] = "El argumento se evalúa en la línea del defer. Solo la llamada se retrasa.",
  ["The arrow leans out of the channel this time. Mirror of the chan<- next to it."] = "Esta vez la flecha sale del channel. El espejo del chan<- que tiene al lado.",
  ["The back office robot runs on generators, decorators and asyncio. Earn the midnight bowl."] = "El robot de la oficina trasera funciona con generadores, decoradores y asyncio. Gánate el bol de medianoche.",
  ["The base class of every catchable error, capital E. Not BaseException: that one includes Ctrl-C."] = "La clase base de todo error capturable, con E mayúscula. No BaseException: esa incluye Ctrl-C.",
  ["The bell"] = "La campana",
  ["The belt is closed and empty. What comes out of the next receive?"] = "La cinta está cerrada y vacía. ¿Qué sale de la siguiente recepción?",
  ["The belt kept handing me empty trays after the kitchen shut. Empty tray, or no more trays?"] = "La cinta me siguió dando bandejas vacías después de cerrar la cocina. ¿Bandeja vacía o ya no hay bandejas?",
  ["The belt to the counter"] = "La cinta hacia el mostrador",
  ["The blank identifier. Compile error if you name a value you never use."] = "El identificador vacío. Error de compilación si nombras un valor que nunca usas.",
  ["The board mixes prices, names and a sold-out flag. What is v today?"] = "La pizarra mezcla precios, nombres y una marca de agotado. ¿Qué es v hoy?",
  ["The bool from the map lookup. True when the key exists."] = "El bool de la búsqueda en el map. True cuando la clave existe.",
  ["The booth"] = "El reservado",
  ["The booth code used to duplicate fry for every item. Generics write it once. A Kitchen that embeds Grill gets Grill's methods for free."] = "El código del reservado duplicaba fry para cada plato. Los genéricos lo escriben una vez. Una Kitchen que embebe Grill obtiene sus métodos gratis.",
  ["The buffer size is the number of tokens. The fourth send waits."] = "El tamaño del buffer es el número de tokens. El cuarto envío espera.",
  ["The built-in constraint for types that allow == and !=."] = "La restricción built-in para tipos que permiten == y !=.",
  ["The built-in interface for failure. Last return value by convention."] = "La interface integrada para fallos. Último valor de retorno por convención.",
  ["The built-in that picks the smaller of two values."] = "La función integrada que elige el menor de dos valores.",
  ["The built-in whole-number type, three letters, after the colon."] = "El tipo entero integrado, tres letras, tras los dos puntos.",
  ["The builtin that adds an element to the end of a slice."] = "La función integrada que añade un elemento al final de un slice.",
  ["The builtin that adds to the end of a slice and returns the new slice."] = "La función integrada que añade al final de un slice y devuelve el slice nuevo.",
  ["The builtin that ends a range. One goroutine waits for the workers and then calls it once."] = "La función integrada que termina un range. Una goroutine espera a los workers y la llama una vez.",
  ["The builtin that takes a map and a key. Six letters."] = "La función integrada que recibe un map y una clave. Seis letras.",
  ["The busiest k hours: keep one running sum. The window moves right by one: add a[i], and subtract which element?"] = "Las k horas más ocupadas: mantén una sola suma acumulada. La ventana avanza uno a la derecha: suma a[i], ¿y resta qué elemento?",
  ["The cache is 9 GB and one entry is corrupt. Wipe it. Fill the flag."] = "La caché ocupa 9 GB y una entrada está corrupta. Bórrala. Rellena el flag.",
  ["The cache is read-only on purpose, so a corrupt entry cannot be edited, only removed. go.sum makes the re-download provably the same code."] = "La caché es de solo lectura a propósito, así que una entrada corrupta no se puede editar, solo eliminar. go.sum hace que la nueva descarga sea demostrablemente el mismo código.",
  ["The cheapest of three prices, no loop, no import. Which built-in (Go 1.21)?"] = "El más barato de tres precios, sin bucle, sin import. ¿Qué función integrada (Go 1.21)?",
  ["The child adds to a global and the parent still prints 0. What did the child change?"] = "El hijo suma a una global y el padre sigue imprimiendo 0. ¿Qué cambió el hijo?",
  ["The classic bug is forgetting max: a short interval inside a long one must not cut it. last is &mut, so this writes into out."] = "El bug clásico es olvidar max: un intervalo corto dentro de uno largo no debe recortarlo. last es &mut, así que esto escribe en out.",
  ["The classics! Two-sum, palindrome, anagram. Everyone has done these. Once."] = "¡Los clásicos! Two-sum, palíndromo, anagrama. Todo el mundo ha hecho estos. Una vez.",
  ["The closer-to-opener map from the first blank."] = "El map de cierre a apertura del primer hueco.",
  ["The cold room"] = "La cámara frigorífica",
  ["The combinatorics counter"] = "El mostrador de combinatoria",
  ["The combinatorics counter at the noodle stall: pick any toppings. Bo counts the combinations and the number doubles with every topping. He draws the curve that goes vertical almost at once."] = "El mostrador de combinatoria del puesto de fideos: elige los ingredientes que quieras. Bo cuenta las combinaciones y el número se duplica con cada ingrediente. Dibuja la curva que se pone vertical casi de inmediato.",
  ["The combinatorics counter at the noodle stall: pick any toppings. Bo counts the combinations and the number doubles with every topping. Mei draws the curve that goes vertical almost at once."] = "El mostrador de combinatoria del puesto de fideos: elige los ingredientes que quieras. Bo cuenta las combinaciones y el número se duplica con cada ingrediente. Mei dibuja la curva que se pone vertical casi de inmediato.",
  ["The combinatorics counter at the noodle stall: pick any toppings. Bo counts the combinations and the number doubles with every topping. Mei draws the last curve, the one that goes vertical almost at once."] = "El mostrador de combinatoria del puesto de fideos: elige los ingredientes que quieras. Bo cuenta las combinaciones y el número se duplica con cada ingrediente. Mei dibuja la última curva, la que se pone vertical casi de inmediato.",
  ["The comma-ok idiom. Same word twice on those two lines."] = "El idioma comma-ok. La misma palabra dos veces en esas dos líneas.",
  ["The compound operator that walks j one step toward the smaller values, on the left."] = "El operador compuesto que lleva j un paso hacia los valores menores, a la izquierda.",
  ["The conveyor"] = "La cinta transportadora",
  ["The conveyor carries bowls from the wok to the pass. Its script builds a list of every bowl of the night before serving the first. A generator would hand them out one at a time, and the belt would never wait."] = "La cinta lleva boles del wok al pase. Su script construye una lista de todos los boles de la noche antes de servir el primero. Un generador los entregaría uno a uno, y la cinta nunca esperaría.",
  ["The conveyor script loads every bowl into memory at once. Ten thousand bowls."] = "El script de la cinta carga todos los boles en memoria a la vez. Diez mil boles.",
  ["The counter"] = "El mostrador",
  ["The counts drift and nothing crashes. Which flag makes the test print WARNING: DATA RACE?"] = "Las cuentas bailan y nada revienta. ¿Qué flag hace que la prueba imprima WARNING: DATA RACE?",
  ["The cousin asks which version is safe. Right now the answer is 'whichever commit was on main when he ran go get'."] = "El primo pregunta qué versión es segura. Ahora mismo la respuesta es 'el commit que estuviera en main cuando hizo go get'.",
  ["The cousin wants the newest tag, whatever it is. Fill the version query."] = "El primo quiere la etiqueta más nueva, sea cual sea. Rellena la consulta de versión.",
  ["The cousin's shop imported my rider package and now they call the function I wanted to delete."] = "La tienda del primo importó mi paquete rider y ahora llaman a la función que quería borrar.",
  ["The crash that pairs with recover. Six letters here, in the third person."] = "El fallo que hace pareja con recover. Aquí en tercera persona.",
  ["The cube is a slice of ads. append one more."] = "El cubo es un slice de anuncios. append uno más.",
  ["The curly opener, as a char literal in single quotes."] = "La apertura de llave, como literal char entre comillas simples.",
  ["The curly opener, as a one-character string like the other two values."] = "La llave de apertura, como string de un carácter, igual que los otros dos valores.",
  ["The current index: the right edge of the window."] = "El índice actual: el borde derecho de la ventana.",
  ["The current value. Its partner is target minus it."] = "El valor actual. Su pareja es target menos él.",
  ["The customer closed the app two minutes ago and your goroutine is still fetching the ETA."] = "El cliente cerró la app hace dos minutos y tu goroutine sigue buscando el ETA.",
  ["The decorator builds an inner function and must hand it back. What does timer return?"] = "El decorador construye una función interna y debe devolverla. ¿Qué devuelve timer?",
  ["The delivery radio"] = "La radio de reparto",
  ["The delivery radio at the door. Three riders report their position; the script asks each in turn and waits a full second for every answer. Asked at once, the three answers would arrive together."] = "La radio de reparto en la puerta. Tres repartidores informan de su posición; el script pregunta a cada uno por turno y espera un segundo entero por cada respuesta. Preguntados a la vez, las tres respuestas llegarían juntas.",
  ["The dict defined on the first line, the one written to two lines below the blank."] = "El dict definido en la primera línea, el que se escribe dos líneas debajo del hueco.",
  ["The dict from the first line of the body, value to index."] = "El dict de la primera línea del cuerpo, de valor a índice.",
  ["The dict method that removes and returns one (key, value) pair; last=False takes it from the front."] = "El método de dict que quita y devuelve un par (clave, valor); last=False lo toma del frente.",
  ["The digit for land, as a byte literal in single quotes."] = "El dígito de la tierra, como literal byte entre comillas simples.",
  ["The digit one as a u8: a b before the single quotes."] = "El dígito uno como u8: una b antes de las comillas simples.",
  ["The directory the file sits in, nothing more. Look at how rider is done on the next line."] = "El directorio donde está el fichero, nada más. Mira cómo está hecho rider en la línea siguiente.",
  ["The directory's name. It could legally be anything, and it should be this."] = "El nombre del directorio. Legalmente podría ser cualquier cosa, y debería ser este.",
  ["The door sensor counts every customer. Only one number, thousands of times a minute."] = "El sensor de la puerta cuenta a cada cliente. Un solo número, miles de veces por minuto.",
  ["The dumbwaiter"] = "El montaplatos",
  ["The element on its own: a run that begins right here and has nothing before it."] = "El elemento por sí solo: una racha que empieza justo aquí y no tiene nada antes.",
  ["The element that just fell off the left edge: k places behind i."] = "El elemento que acaba de caer por el borde izquierdo: k lugares detrás de i.",
  ["The element that just fell off the left edge: k positions behind i."] = "El elemento que acaba de caer por el borde izquierdo: k posiciones detrás de i.",
  ["The element type, plural, capitalized, like sort.Ints for ints."] = "El tipo del elemento, en plural, con mayúscula, como sort.Ints para ints.",
  ["The empty till. Making nothing takes no coins at all."] = "La caja vacía. Formar nada no cuesta ninguna moneda.",
  ["The end of every Python chain, capital N."] = "El final de toda cadena de Python, N mayúscula.",
  ["The entry API: one lookup, insert or update. The classics done, no misses. Combo x6. One round left."] = "La API entry: una búsqueda, insertar o actualizar. Los clásicos hechos, sin fallos. Combo x6. Queda una ronda.",
  ["The evening CODE RUSH is the Rust round. Seven classic problems. Get HIRED."] = "El CODE RUSH de la tarde es la ronda de Rust. Siete problemas clásicos. Consigue el CONTRATADO.",
  ["The evening callback is the Rust round. Seven whiteboard classics. Get the OFFER."] = "El callback de la tarde es la ronda de Rust. Siete clásicos de pizarra. Consigue la OFFER.",
  ["The evicted key must leave the map too, or the cache leaks. Which HashMap method deletes by key?"] = "La clave expulsada también debe salir del map, o la caché tiene fugas. ¿Qué método de HashMap borra por clave?",
  ["The field from stage one. Borrow it with &, and cur stays a &Link."] = "El campo de la etapa uno. Préstalo con &, y cur sigue siendo un &Link.",
  ["The field that is not right. Mei said it in her speech bubble."] = "El campo que no es right. Mei lo dijo en su bocadillo.",
  ["The file is menu/price.go. What does its first line say?"] = "El fichero es menu/price.go. ¿Qué dice su primera línea?",
  ["The final round. Three cook threads pull orders from one queue and fry them. Bo has to feed the queue, drain it safely, mark every job finished and wait for the last one before the receipt prints. Then the screen says HIRED."] = "La ronda final. Tres hilos cocineros sacan pedidos de una cola y los fríen. Bo tiene que alimentar la cola, vaciarla con seguridad, marcar cada trabajo terminado y esperar al último antes de que se imprima el recibo. Entonces la pantalla dice CONTRATADO.",
  ["The final sheet is a grid of bytes: '1' is land, '0' is water, Hong Kong Island and Kowloon and a scatter of rocks. Siu Ming wants the count. Alex writes a recursive dfs that sinks whatever it touches, then a double loop that calls it on every '1' still standing and counts the calls. The marker squeaks. Then: OFFER."] = "La hoja final es una cuadrícula de bytes: '1' es tierra, '0' es agua, la isla de Hong Kong y Kowloon y un puñado de rocas. Siu Ming quiere el conteo. Alex escribe un dfs recursivo que hunde todo lo que toca, luego un doble bucle que lo llama en cada '1' que sigue en pie y cuenta las llamadas. El rotulador chirría. Y entonces: OFFER.",
  ["The final. 01:40. Siu Ming draws Causeway Bay as a grid: 1 for a building, 0 for the road. Bo has to count the islands of buildings, each a patch of 1s touching up, down, left or right. One DFS per island, sinking it as it goes; the count of sinkings is the answer, and the answer is the OFFER."] = "La final. 01:40. Siu Ming dibuja Causeway Bay como una cuadrícula: 1 para un edificio, 0 para la calle. Bo tiene que contar las islas de edificios, cada una un parche de 1s que se tocan arriba, abajo, izquierda o derecha. Un DFS por isla, hundiéndola sobre la marcha; el número de hundimientos es la respuesta, y la respuesta es la OFFER.",
  ["The first element of each pair is the start."] = "El primer elemento de cada par es el inicio.",
  ["The first element. The loop then starts from the second, see the slice."] = "El primer elemento. El bucle empieza entonces desde el segundo, mira el slice.",
  ["The first handler argument is where the reply goes. Fill its type: w http.___"] = "El primer argumento del handler es adonde va la respuesta. Completa su tipo: w http.___",
  ["The first letter of format. Since Python 3.6."] = "La primera letra de format. Desde Python 3.6.",
  ["The first line of go.mod names the module. Which keyword?"] = "La primera línea de go.mod nombra el módulo. ¿Qué palabra clave?",
  ["The flat"] = "El apartamento",
  ["The flood function from the blanks above."] = "La función de inundación de los huecos anteriores.",
  ["The flood stops at the edge of the map. Fill the row check."] = "La inundación se detiene en el borde del mapa. Completa la comprobación de la fila.",
  ["The footbridge to Times Square"] = "La pasarela a Times Square",
  ["The four-letter function from the prelude that ends a value early. Not close: channels have no close."] = "La función de cuatro letras del prelude que termina un valor antes de tiempo. No es close: los canales no tienen close.",
  ["The free slots are the gaps between merged blocks: pair each block with the next. Fill the slice."] = "Los huecos libres son los espacios entre bloques fusionados: empareja cada bloque con el siguiente. Completa el slice.",
  ["The free-threaded build removes the GIL and pays for it in single-thread speed and C extension support. Until it is the default, processes are the answer."] = "La compilación free-threaded quita el GIL y lo paga en velocidad de un hilo y en soporte de extensiones C. Hasta que sea la opción por defecto, la respuesta son los procesos.",
  ["The full word this time. Then the go version, then require lines."] = "Esta vez la palabra completa. Luego la versión de go, luego líneas require.",
  ["The function calls itself. Same name as on the last line."] = "La función se llama a sí misma. Mismo nombre que en la última línea.",
  ["The function itself. The map is shared, so a plain map argument works."] = "La función misma. El map es compartido, así que basta pasar el map tal cual.",
  ["The function that measures a string, passed by name, no parentheses."] = "La función que mide una cadena, pasada por nombre, sin paréntesis.",
  ["The function's own name. The recursion is the stack."] = "El propio nombre de la función. La recursión es la pila.",
  ["The generic one that holds an address, not a number."] = "El genérico que guarda una dirección, no un número.",
  ["The go directive also picks language semantics: for-loop variables became per-iteration only for modules that say go 1.22 or later."] = "La directiva go también elige la semántica del lenguaje: las variables de un for pasaron a ser por iteración solo en módulos que declaran go 1.22 o posterior.",
  ["The grid holds bytes, not ints: '1' is 49, 1 is 1. Compare with the character."] = "La cuadrícula guarda bytes, no ints: '1' es 49, 1 es 1. Compara con el carácter.",
  ["The grid holds one-character strings, and the road is the zero."] = "La cuadrícula guarda strings de un carácter, y la calle es el cero.",
  ["The grill line"] = "La línea de la parrilla",
  ["The growable array. Three letters, capital V. A neighbour can be pushed on."] = "El array que crece. Tres letras, V mayúscula. Se le puede hacer push a un vecino.",
  ["The heap never grows past k: O(n log k) time, O(k) space. Sorting would be O(n log n) and O(n)."] = "El heap nunca pasa de k: O(n log k) de tiempo, O(k) de espacio. Ordenar sería O(n log n) y O(n).",
  ["The heap package does the sifting; your Pop only trims the tail. O(log n) per operation."] = "El paquete heap hace el sifting; tu Pop solo recorta la cola. O(log n) por operación.",
  ["The host, the user, the repo, joined with slashes, no https://. The tool echoes it back on the next line."] = "El host, el usuario y el repo, unidos con barras, sin https://. La herramienta lo repite en la línea siguiente.",
  ["The index enumerate hands out, one letter. The return line reads it back."] = "El índice que entrega enumerate, una letra. La línea del return lo lee de vuelta.",
  ["The index just checked, plus one: everything up to it is too small."] = "El índice recién comprobado, más uno: todo hasta él es demasiado pequeño.",
  ["The index of the left half, mirroring j++ in the else."] = "El índice de la mitad izquierda, espejo del j++ en el else.",
  ["The inner def's name, without parentheses: the function itself, not a call of it."] = "El nombre del def interno, sin paréntesis: la función en sí, no una llamada a ella.",
  ["The int32 code point type. Indexing a string gives bytes."] = "El tipo de punto de código int32. Indexar un string da bytes.",
  ["The interview asked me this three times. Let's get it right in Go first."] = "La entrevista me lo preguntó tres veces. Hagámoslo bien primero en Go.",
  ["The interview convention: a negative one, since cached values are non-negative."] = "La convención de entrevista: un menos uno, ya que los valores en caché no son negativos.",
  ["The invariant: map.len() == order.len(), always. Break it once and the cap check lies."] = "El invariante: map.len() == order.len(), siempre. Rómpelo una vez y la comprobación de cap miente.",
  ["The jobs are tiny and the pool is slower than one core. Which argument fixes it?"] = "Las tareas son diminutas y el pool va más lento que un núcleo. ¿Qué argumento lo arregla?",
  ["The key exactly as the phone spells it, inside the quotes."] = "La clave tal como la escribe el teléfono, dentro de las comillas.",
  ["The keyword type, where a type name would go. Only inside a switch."] = "La palabra clave type, donde iría un nombre de tipo. Solo dentro de un switch.",
  ["The kiosk"] = "El kiosco",
  ['The kiosk reads "18" from the keypad. Turn it into an i32. Which method?'] = 'El kiosco lee "18" del teclado. Conviértelo en un i32. ¿Qué método?',
  ["The kiosk row"] = "La fila de kioscos",
  ["The kiosk wants one function for prices and for weights. Go had any; what now?"] = "El kiosco quiere una sola función para precios y para pesos. Go tenía any; ¿y ahora?",
  ["The kitchen"] = "La cocina",
  ["The kitchen at 23:00"] = "La cocina a las 23:00",
  ["The kitchen build box has no internet. Copy every dependency into the repo. Fill the subcommand."] = "La máquina de compilación de la cocina no tiene internet. Copia todas las dependencias al repo. Rellena el subcomando.",
  ["The kitchen is concurrent. One cook cannot wait for the hash brown before starting the muffin. go fry() starts a function in a new goroutine."] = "La cocina es concurrente. Un cocinero no puede esperar al hash brown antes de empezar el muffin. go fry() lanza una función en una goroutine nueva.",
  ["The kitchen sends one more order after closing. What happens?"] = "La cocina envía un pedido más después de cerrar. ¿Qué pasa?",
  ["The kitchen waits until an order arrives. Which method blocks and takes one?"] = "La cocina espera hasta que llega un pedido. ¿Qué método bloquea y toma uno?",
  ["The label maker"] = "La etiquetadora",
  ["The label maker printed 'None' on forty bowls. Somebody returned nothing."] = "La etiquetadora imprimió 'None' en cuarenta boles. Alguien no devolvió nada.",
  ["The label maker prints a name and a price per bowl. Half its functions return None by accident and nobody noticed until forty bowls said so. Type hints would have caught it before the shift."] = "La etiquetadora imprime un nombre y un precio por bol. La mitad de sus funciones devuelven None por accidente y nadie lo notó hasta que cuarenta boles lo dijeron. Las anotaciones de tipo lo habrían cazado antes del turno.",
  ["The larger of the two ends wins; a shift fully inside another must not shrink the block."] = "Gana el mayor de los dos finales; un turno contenido en otro no debe encoger el bloque.",
  ["The last arm must catch every other number. Which pattern matches anything?"] = "La última rama debe atrapar cualquier otro número. ¿Qué patrón coincide con todo?",
  ["The last expression is the return value. One pass, one stack: O(n) time, O(n) space at worst."] = "La última expresión es el valor de retorno. Una pasada, una pila: O(n) tiempo, O(n) espacio en el peor caso.",
  ["The last index of a slice of n items."] = "El último índice de un slice de n elementos.",
  ["The last item of a Vec in one step, as an Option. Which method?"] = "El último elemento de un Vec en un paso, como Option. ¿Qué método?",
  ["The last item of a list in one step, without len. Which index?"] = "El último elemento de una lista en un paso, sin len. ¿Qué índice?",
  ["The last item of a slice in one step. What is subtracted from the length?"] = "El último elemento de un slice en un paso. ¿Qué se resta a la longitud?",
  ["The last sheet before the break is the classic: an LRU cache. Lucky Mac's menu service is slow, keep the hundred most recently asked-for menus in memory, throw out the one nobody has touched for longest. Alex draws a map on the left and a doubly linked list on the right and joins them with arrows."] = "La última hoja antes del descanso es el clásico: una caché LRU. El servicio de menús de Lucky Mac es lento; guarda en memoria los cien menús pedidos más recientemente y descarta el que nadie ha tocado durante más tiempo. Alex dibuja un map a la izquierda y una lista doblemente enlazada a la derecha y las une con flechas.",
  ["The last stop points nowhere. What is next set to at creation?"] = "La última parada no apunta a ningún sitio. ¿A qué se pone next al crearla?",
  ["The last tray, without len. Which index?"] = "La última bandeja, sin len. ¿Qué índice?",
  ["The left pointer only ever moves right, so the while loop costs O(n) over the whole run, not per r."] = "El puntero izquierdo solo avanza a la derecha, así que el while cuesta O(n) en todo el recorrido, no por cada r.",
  ["The length of any collection has which unsigned, pointer-sized type?"] = "¿Qué tipo sin signo, del tamaño de un puntero, tiene la longitud de cualquier colección?",
  ["The letter v and the new major number, as the last element of the path. Tag it v2.0.0."] = "La letra v y el nuevo número major, como último elemento de la ruta. Etiquétalo v2.0.0.",
  ["The lift"] = "El ascensor",
  ["The lift panel is a tiny Go program. Floor, name, and a constant for Lucky Mac's opening hour. Zero values matter: an unset int is not blank."] = "El panel del ascensor es un programa Go diminuto. Piso, nombre y una constante con la hora de apertura de Lucky Mac. Los valores cero importan: un int sin asignar no está vacío.",
  ["The list forgot the node; the map must forget the key too. Which builtin removes a map entry?"] = "La lista olvidó el nodo; el map también debe olvidar la clave. ¿Qué función integrada quita una entrada del map?",
  ["The list method that grows the end. The end of the list is the top of the stack."] = "El método de lista que hace crecer el final. El final de la lista es el tope de la pila.",
  ["The lock needs no constructor: its zero value is ready. Which type?"] = "El lock no necesita constructor: su valor cero ya sirve. ¿Qué tipo?",
  ["The log tailer must not keep the batch alive. Which flag makes a child die with its parent?"] = "El seguidor de logs no debe mantener vivo el lote. ¿Qué marca hace que un hijo muera con su padre?",
  ["The loop keyword, inside the brackets, after the expression."] = "La palabra clave del bucle, dentro de los corchetes, después de la expresión.",
  ["The mall atrium"] = "El atrio del centro comercial",
  ["The map finds the node in O(1); the list moves it in O(1). Neither alone can do both."] = "El map encuentra el nodo en O(1); la lista lo mueve en O(1). Ninguno solo puede hacer ambas cosas.",
  ["The menu board"] = "La pizarra del menú",
  ["The menu board at the shutter. Prices live in a dict, dish to dollars. It is Go's map with braces instead of make, and a KeyError instead of a zero value when the dish is missing."] = "La carta junto a la persiana. Los precios viven en un dict, de plato a dólares. Es el map de Go con llaves en vez de make, y un KeyError en vez de un valor cero cuando falta el plato.",
  ["The menu board reads prices from a dict. Ask for a dish we do not have and it crashes."] = "La carta lee los precios de un dict. Pide un plato que no tenemos y se cae.",
  ["The menu is read by two hundred goroutines and written once an hour. Which lock?"] = "El menú lo leen doscientas goroutines y se escribe una vez por hora. ¿Qué lock?",
  ["The menu is read often, written rarely. Which method takes a shared read guard?"] = "El menú se lee a menudo y se escribe rara vez. ¿Qué método toma un guard de lectura compartido?",
  ["The menu maps dish names to prices. Which generic takes two types?"] = "La carta asocia nombres de platos a precios. ¿Qué genérico acepta dos tipos?",
  ["The merge pass is O(n); the sort before it makes the whole thing O(n log n)."] = "La pasada de fusión es O(n); la ordenación previa hace que todo sea O(n log n).",
  ["The method reads its own item. What is the first parameter of every method?"] = "El método lee su propio item. ¿Cuál es el primer parámetro de todo método?",
  ["The middle index without overflow. Fill: mid := lo + (hi-lo)/___"] = "El índice medio sin desbordamiento. Completa: mid := lo + (hi-lo)/___",
  ["The midnight CODE RUSH is the Python round. Seven classic problems. Get HIRED."] = "El CODE RUSH de medianoche es la ronda de Python. Siete problemas clásicos. Consigue el CONTRATADO.",
  ["The mirror of the helper on the next line: n, then the superlative of big."] = "El espejo del ayudante de la línea siguiente: n, y luego el superlativo de grande.",
  ["The module name, singular, capitalized. Go's go keyword, as an object."] = "El nombre del módulo, en singular, con mayúscula. La palabra clave go de Go, como objeto.",
  ["The module path from the comment, a slash, the directory. Not menu on its own, not ./menu."] = "La ruta del módulo del comentario, una barra, el directorio. Ni menu a secas ni ./menu.",
  ["The module path is a name, not a URL: nothing is fetched when you init. It only has to match the repo later, when somebody else runs go get on it."] = "La ruta del módulo es un nombre, no una URL: al hacer init no se descarga nada. Solo tiene que coincidir con el repo más adelante, cuando otro haga go get.",
  ["The module path is the import path"] = "La ruta del módulo es la ruta de importación",
  ["The module's name, an underscore, and the side an equal item is inserted on: the left one here."] = "El nombre del módulo, un guion bajo, y el lado en que se inserta un elemento igual: aquí el izquierdo.",
  ["The module's name, capitalized. Not deque: that one has no locks."] = "El nombre del módulo, con mayúscula. No deque: ese no tiene cerrojos.",
  ["The module's name, singular, after the dot. It is a decorator, so it sits on the line above the class."] = "El nombre del módulo, en singular, tras el punto. Es un decorador, así que va en la línea de encima de la clase.",
  ["The module's own name in CamelCase, the two words joined."] = "El nombre del propio módulo en CamelCase, con las dos palabras unidas.",
  ["The module's own name, in double underscores. It is '__main__' only in the script you ran."] = "El nombre del propio módulo, entre dobles guiones bajos. Solo vale '__main__' en el script que ejecutaste.",
  ["The morning set"] = "El menú de desayuno",
  ["The multiplicative identity. Returning 0 would zero every factorial."] = "La identidad multiplicativa. Devolver 0 anularía todos los factoriales.",
  ["The name imported on the first line. Since 3.10 you may write the type, a pipe, and None instead."] = "El nombre importado en la primera línea. Desde 3.10 puedes escribir el tipo, una barra vertical y None en su lugar.",
  ["The name imported on the first line: a pool of threads that executes."] = "El nombre importado en la primera línea: un pool de hilos que ejecuta.",
  ["The name is a short string, so the argument you pickle is tiny no matter how large the block is. That is the whole trick."] = "El nombre es una cadena corta, así que el argumento que serializas es diminuto por grande que sea el bloque. Ese es todo el truco.",
  ["The name saved on the first line of the loop, before the pointer was flipped. cur.next is no longer it."] = "El nombre guardado en la primera línea del bucle, antes de girar el puntero. cur.next ya no es él.",
  ["The name x, wrapped in the vertical bar character on both sides."] = "El nombre x, envuelto en el carácter de barra vertical por ambos lados.",
  ["The new sign says 銅鑼灣. The app counts it as nine letters."] = "El letrero nuevo dice 銅鑼灣. La app lo cuenta como nueve letras.",
  ["The next sheet is a stream: order totals arriving faster than anyone could sort them. Siu Ming wants the kth largest at any moment. Go has no heap type, only container/heap and an interface to satisfy. Alex writes IntHeap on the board, five methods, and a loop that never lets the heap grow past k."] = "La siguiente hoja es un flujo: totales de pedidos que llegan más rápido de lo que nadie podría ordenarlos. Siu Ming quiere el k-ésimo mayor en cualquier momento. Go no tiene tipo heap, solo container/heap y una interfaz que cumplir. Alex escribe IntHeap en la pizarra, cinco métodos y un bucle que nunca deja al heap crecer más allá de k.",
  ["The night shift at Lucky Mac runs on Chef Bo's Python scripts. Fix every station before closing."] = "El turno de noche de Lucky Mac funciona con los scripts de Python del chef Bo. Arregla cada puesto antes de cerrar.",
  ["The node that was before cur, saved on the first line. That is what reversing means."] = "El nodo que iba antes de cur, guardado en la primera línea. Eso es lo que significa invertir.",
  ["The node we just came from. nil on the first step, which becomes the new tail."] = "El nodo del que acabamos de venir. nil en el primer paso, que se convierte en la nueva cola.",
  ["The note may be text or None. Which typing name says so?"] = "La nota puede ser texto o None. ¿Qué nombre de typing lo dice?",
  ["The number of columns: the length of one row, say the first."] = "El número de columnas: la longitud de una fila, digamos la primera.",
  ["The number of times you can halve n. Same answer as the phone book, applied to memory."] = "El número de veces que puedes partir n a la mitad. La misma respuesta que la guía telefónica, aplicada a la memoria.",
  ["The old position of this char, from the map lookup."] = "La posición anterior de este carácter, sacada del map.",
  ["The one everybody gets asked, Chef. In Python the dict already remembers the order for you."] = "La que le preguntan a todo el mundo, chef. En Python el dict ya recuerda el orden por ti.",
  ["The one package name that does not follow its directory. The same word as the function."] = "El único nombre de paquete que no sigue a su directorio. La misma palabra que la función.",
  ["The opposite end from the front, where the untouched ones drift."] = "El extremo contrario al frente, adonde van a parar los que nadie toca.",
  ["The opposite of Lock. defer it on the very next line."] = "Lo contrario de Lock. Ponlo en defer en la línea siguiente.",
  ["The opposite of absolute. Paths that start with ./ or ../ are it."] = "Lo contrario de absoluta. Las rutas que empiezan por ./ o ../ lo son.",
  ["The opposite of direct. Your code never names it; something you require does."] = "Lo contrario de directa. Tu código nunca la nombra; algo que tú requieres sí.",
  ["The opposite of held. Past participle, eight letters."] = "Lo contrario de retenido. Participio, ocho letras en inglés.",
  ["The opposite of insert, six letters. Takes a reference, returns whether it was there."] = "Lo contrario de insert, seis letras. Recibe una referencia, devuelve si estaba.",
  ["The opposite of output. It shows the prompt and returns a str, always a str."] = "Lo contrario de output. Muestra el prompt y devuelve un str, siempre un str.",
  ["The opposite of the -- below. Go's ++ is a statement, not an expression."] = "Lo opuesto al -- de abajo. En Go ++ es una sentencia, no una expresión.",
  ["The order app"] = "La app de pedidos",
  ["The order queue"] = "La cola de pedidos",
  ["The order robot"] = "El robot de pedidos",
  ["The other child. max is a Go 1.21 built-in."] = "El otro hijo. max es un built-in de Go 1.21.",
  ["The other direction: struct to bytes. Same word without the De in front."] = "La otra dirección: de struct a bytes. La misma palabra sin el De delante.",
  ["The other half of Option. Not nil, not null. Four letters, capital N."] = "La otra mitad de Option. No es nil, no es null. Cuatro letras, N mayúscula.",
  ["The other variant of Option. Capital N, no parentheses."] = "La otra variante de Option. N mayúscula, sin paréntesis.",
  ["The p >= l test matters: a repeat before the window's left edge is already outside and must not pull l back."] = "La prueba p >= l importa: un repetido anterior al borde izquierdo ya está fuera y no debe tirar de l hacia atrás.",
  ["The package function that removes the root and returns it."] = "La función del paquete que quita la raíz y la devuelve.",
  ["The package that holds WaitGroup and Once, then the six-letter word for a lock."] = "El paquete donde viven WaitGroup y Once, y luego la palabra de seis letras para un cerrojo.",
  ["The package the Go tool looks for when you type go run."] = "El paquete que la herramienta Go busca cuando escribes go run.",
  ["The parameter, the station already in seen on the line above."] = "El parámetro, la estación que ya está en seen en la línea de arriba.",
  ["The parent must not print the total before the child finishes. Which method?"] = "El padre no debe imprimir el total antes de que el hijo termine. ¿Qué método?",
  ["The parse fails. Which method gives a fallback value instead of a panic?"] = "El parse falla. ¿Qué método da un valor de respaldo en vez de un panic?",
  ["The part already flipped. None on the first lap, which becomes the new tail."] = "La parte a la que ya has dado la vuelta. None en la primera vuelta, que pasa a ser la nueva cola.",
  ["The pass"] = "El pase",
  ["The pass holds three trays; a fourth send should wait. Which constructor?"] = "El pase aguanta tres bandejas; un cuarto send debe esperar. ¿Qué constructor?",
  ["The pass window"] = "La ventana del pase",
  ["The pass window is a channel. One goroutine fries, another plates. Do not share the same variable; send the value through the pipe."] = "La ventanilla del pase es un channel. Una goroutine fríe, otra emplata. No compartas la misma variable; envía el valor por la tubería.",
  ["The pass window, 22:30. Chef Bo's recipe file is a list of functions: fry, brew, plate. Alex knows func; here it is three letters and a colon, and the body is whatever is indented under it."] = "La ventana del pase, 22:30. El archivo de recetas del chef Bo es una lista de funciones: fry, brew, plate. Alex conoce func; aquí son tres letras y dos puntos, y el cuerpo es lo que esté indentado debajo.",
  ["The pass, 21:00"] = "El pase, 21:00",
  ["The path is long but unambiguous: two modules can both have a menu directory and never collide. The name you use in code is the package's own name, menu."] = "La ruta es larga pero inequívoca: dos módulos pueden tener un directorio menu sin chocar nunca. El nombre que usas en el código es el propio del paquete, menu.",
  ["The phone book"] = "La guía telefónica",
  ["The phone book street's answer, without the O( ). Halving each step."] = "La respuesta de la calle de la guía telefónica, sin el O( ). Partiendo a la mitad en cada paso.",
  ["The phone calls the field dish, not Item. Fill the tag so json reads that key."] = "El teléfono llama al campo dish, no Item. Completa el tag para que json lea esa clave.",
  ['The phone sends the price as text. Parse "18" into an int. Which strconv function?'] = 'El teléfono envía el precio como texto. Convierte "18" en un int. ¿Qué función de strconv?',
  ['The phone sends {"dish":"set"}. Our struct says Item. Nothing arrives.'] = 'El teléfono envía {"dish":"set"}. Nuestro struct dice Item. No llega nada.',
  ["The pickup bell is a select. Whichever channel is ready first wins. If none are ready, default fires instead of blocking the till."] = "La campana de recogida es un select. El channel que esté listo primero gana. Si ninguno lo está, default se dispara en vez de bloquear la caja.",
  ["The pickup queue"] = "La fila de recogida",
  ["The pointer field, twice in a row. The while condition guards both hops."] = "El campo puntero, dos veces seguidas. La condición del while protege ambos saltos.",
  ["The pointer that walks the list. prev is the new head once it is nil."] = "El puntero que recorre la lista. prev es la nueva cabeza cuando llega a nil.",
  ["The pot is empty mid-loop. Which keyword leaves the loop at once?"] = "La olla se vacía a mitad de bucle. ¿Qué palabra clave sale del bucle de inmediato?",
  ["The prices are sorted. Find 45 in O(log n). Which slice method returns Result<usize, usize>?"] = "Los precios están ordenados. Encuentra 45 en O(log n). ¿Qué método de slice devuelve Result<usize, usize>?",
  ["The proxy and the private repo"] = "El proxy y el repo privado",
  ["The proxy is why go get is fast and why a deleted GitHub repo does not break the world: it keeps every version it ever served."] = "El proxy es la razón de que go get sea rápido y de que un repo de GitHub borrado no rompa el mundo: guarda cada versión que alguna vez sirvió.",
  ["The queue"] = "La cola",
  ["The queue at Lucky Mac Express"] = "La fila de Lucky Mac Express",
  ["The queue begins with one station. Which one?"] = "La cola empieza con una estación. ¿Cuál?",
  ["The queue counter"] = "El contador de la cola",
  ["The queue is a linked list. Reverse it without allocating, then find the loop."] = "La cola es una lista enlazada. Inviértela sin reservar memoria y luego encuentra el bucle.",
  ["The queue is a struct of orders. A method with a pointer receiver can change the order. The till only knows the Pay() interface, not the card type."] = "La fila es un struct de pedidos. Un método con receptor puntero puede cambiar el pedido. La caja solo conoce la interface Pay(), no el tipo de tarjeta.",
  ["The queue outside the shutter. To total everyone's bill you visit each person once. Bo draws the diagonal, and reminds Alex that a built-in like sum hides the loop, not its cost."] = "La cola fuera de la persiana. Para sumar la cuenta de todos visitas a cada persona una vez. Bo dibuja la diagonal y le recuerda a Alex que una integrada como sum esconde el bucle, no su coste.",
  ["The queue outside the shutter. To total everyone's bill you visit each person once. Mei draws the diagonal again, and Alex writes it as an iterator chain instead of a loop."] = "La cola fuera de la persiana. Para sumar la cuenta de todos visitas a cada persona una vez. Mei dibuja la diagonal otra vez, y Alex la escribe como una cadena de iteradores en vez de un bucle.",
  ["The queue outside the shutter. To total the bill of everyone in it you visit each person once. Mei draws the second line on the whiteboard: a straight diagonal. Double the queue, double the work."] = "La cola fuera de la persiana. Para sumar la cuenta de todos los que están en ella visitas a cada persona una vez. Mei dibuja la segunda línea en la pizarra: una diagonal recta. Duplica la cola, duplica el trabajo.",
  ["The race detector watches real memory accesses, so it only sees races the run actually hits. Run your tests with it in CI."] = "El detector de carreras observa accesos reales a memoria, así que solo ve las carreras que la ejecución llega a tocar. Ejecuta tus pruebas con él en CI.",
  ["The rack script lists trays. It drops the last one every time."] = "El script del estante lista las bandejas. Se le cae la última cada vez.",
  ["The receipt borrows your name. It must not outlive you. That is all a lifetime says."] = "El recibo toma prestado tu nombre. No debe vivir más que tú. Eso es todo lo que dice un lifetime.",
  ["The recursive call must shrink the problem. Fill: n * fact(___)"] = "La llamada recursiva debe encoger el problema. Completa: n * fact(___)",
  ["The recursive call must shrink the problem. Fill: return n * fact(___)"] = "La llamada recursiva debe reducir el problema. Completa: return n * fact(___)",
  ["The recursive flood written above, four letters. Takes &mut g and the cell."] = "La inundación recursiva escrita arriba, cuatro letras. Recibe &mut g y la celda.",
  ["The refund desk"] = "El mostrador de reembolsos",
  ["The repeat is gone: b[r] joins the window. Which HashSet method adds it?"] = "El repetido ya no está: b[r] entra en la ventana. ¿Qué método de HashSet lo añade?",
  ["The repeat sits at p, inside the window. The window must restart just after it. Fill."] = "El repetido está en p, dentro de la ventana. La ventana debe reiniciarse justo después. Completa.",
  ["The repo is private and the proxy answers 404. Which variable sends those paths straight to git?"] = "El repo es privado y el proxy responde 404. ¿Qué variable manda esas rutas directamente a git?",
  ["The rest of the chain, or nothing at the end. Which type wraps Box<ListNode> so it can be empty?"] = "El resto de la cadena, o nada al final. ¿Qué tipo envuelve Box<ListNode> para que pueda estar vacío?",
  ['The rider app sends JSON with "dish", our struct says "name". serde can bridge it.'] = 'La app de repartidores envía JSON con "dish", nuestro struct dice "name". serde puede tender el puente.',
  ["The rider app sends text. Parse it back into an Order. Which function?"] = "La app de repartidores envía texto. Vuelve a parsearlo en un Order. ¿Qué función?",
  ["The rider who gave up"] = "El repartidor que se rindió",
  ["The road value, as a one-character string. Sinking is the visited set for free."] = "El valor de la calle, como string de un carácter. Hundir es el set de visitados gratis.",
  ["The robot is a class. One Order per bowl. It forgot how to make itself."] = "El robot es una clase. Un Order por bol. Olvidó cómo construirse.",
  ["The rooftop"] = "La azotea",
  ["The root of a heap lives at the first index of the slice."] = "La raíz de un heap vive en el primer índice del slice.",
  ["The root of every request tree. Fill: ctx := context.___()"] = "La raíz de todo árbol de peticiones. Completa: ctx := context.___()",
  ["The round opener, as a rune literal in single quotes."] = "La apertura redonda, como literal rune entre comillas simples.",
  ["The run so far with x added. If that is worse than x alone, the old run was dead weight."] = "La racha hasta ahora con x sumado. Si eso es peor que x solo, la racha vieja era lastre.",
  ["The safe"] = "La caja fuerte",
  ["The safe behind the till holds the stock file. The script opens it, writes, and forgets to close when a line is bad. Alex knows defer f.Close(); Python puts the whole idea into one keyword."] = "La caja fuerte detrás de la caja guarda el archivo de stock. El script lo abre, escribe y olvida cerrar cuando una línea está mal. Alex conoce defer f.Close(); Python mete toda la idea en una palabra clave.",
  ["The same customer is in the queue list twice. Which built-in keeps each name once?"] = "El mismo cliente está dos veces en la lista de la cola. ¿Qué función integrada conserva cada nombre una sola vez?",
  ["The same function the right side of the == already uses. It takes a string and returns a list of characters."] = "La misma función que ya usa el lado derecho del ==. Recibe una cadena y devuelve una lista de caracteres.",
  ["The same keyword as for slices, now on an int. No i := 0; i < 3; i++."] = "La misma palabra clave que para slices, ahora sobre un int. Sin i := 0; i < 3; i++.",
  ["The same mark that ends a question."] = "El mismo signo que cierra una pregunta.",
  ["The same method that appends to any Vec. The top of the stack is the end of the Vec."] = "El mismo método que añade al final de cualquier Vec. La cima de la pila es el final del Vec.",
  ["The same shape as threading.Thread, one word, capitalised. What the operating system schedules."] = "La misma forma que threading.Thread, una palabra, en mayúscula inicial. Lo que planifica el sistema operativo.",
  ["The same three letters as the file next to go.mod. The proxy's sibling."] = "Las mismas tres letras que el fichero junto a go.mod. El hermano del proxy.",
  ["The same trait String::from comes from. Capital F, one generic parameter."] = "El mismo trait del que sale String::from. F mayúscula, un parámetro genérico.",
  ["The same word as a C-style counted loop."] = "La misma palabra que un bucle contado al estilo C.",
  ["The same word as in 'the ___ value of a struct is all fields blank'."] = "La misma palabra que en 'el valor ___ de un struct tiene todos los campos vacíos'.",
  ["The same word as the blank import above. Go 1.16."] = "La misma palabra que el import en blanco de arriba. Go 1.16.",
  ["The same word as the builtin, capitalised, living in sync."] = "La misma palabra que el tipo integrado, en mayúscula inicial, viviendo en sync.",
  ["The same word the till used to shut the drawer. It fires on the way out."] = "La misma palabra con la que la caja cerraba el cajón. Se dispara al salir.",
  ["The seating chart"] = "El plano de mesas",
  ["The seating chart for a banquet. Siu Ming's script checks every guest against every other for a duplicate. Bo draws the curve that leaves the board. Nested loops over the same list: the shape to avoid."] = "El plano de mesas de un banquete. El script de Siu Ming compara cada invitado con todos los demás buscando un duplicado. Bo dibuja la curva que se sale de la pizarra. Bucles anidados sobre la misma lista: la forma a evitar.",
  ["The seating chart for a banquet. Siu Ming's script checks every guest against every other for a duplicate. Mei draws a curve that bends upward and leaves the board. Nested loops over the same list: the shape to avoid."] = "El plano de mesas de un banquete. El script de Siu Ming compara cada invitado con todos los demás buscando un duplicado. Mei dibuja una curva que se dobla hacia arriba y se sale de la pizarra. Bucles anidados sobre la misma lista: la forma a evitar.",
  ["The seating chart for a banquet. Siu Ming's script checks every guest against every other for a duplicate. Mei draws the curve that leaves the board. Nested loops over the same Vec: the shape to avoid."] = "El plano de mesas de un banquete. El script de Siu Ming compara cada invitado con todos los demás buscando un duplicado. Mei dibuja la curva que se sale de la pizarra. Bucles anidados sobre el mismo Vec: la forma a evitar.",
  ["The second argument holds the URL, method and body. Fill its type: r *http.___"] = "El segundo argumento contiene la URL, el método y el cuerpo. Completa su tipo: r *http.___",
  ["The second argument to make is the buffer size."] = "El segundo argumento de make es el tamaño del búfer.",
  ["The second file guards against a tampered download. Name it."] = "El segundo fichero protege contra una descarga manipulada. Nómbralo.",
  ["The second return value is not optional: not calling cancel leaks the context and whatever the parent holds for it."] = "El segundo valor devuelto no es opcional: no llamar a cancel filtra el context y todo lo que el padre guarda por él.",
  ["The second value of the map lookup, the boolean that says the key was present."] = "El segundo valor de la búsqueda en el map, el booleano que dice que la clave estaba presente.",
  ["The sentinel is the poison pill. Go closes the channel once and every receiver wakes; Python has to send one pill per worker."] = "El centinela es la píldora envenenada. Go cierra el channel una vez y despiertan todos los receptores; Python tiene que mandar una píldora por worker.",
  ["The set method that takes one element out; it raises KeyError if the element is missing."] = "El método de set que saca un elemento; lanza KeyError si el elemento no está.",
  ["The seven-letter word from the second street of this quest."] = "La palabra de siete letras de la segunda calle de esta misión.",
  ["The shared till"] = "La caja compartida",
  ["The shared tray rack"] = "La estantería de bandejas compartida",
  ["The shutter queue"] = "La cola de la persiana",
  ["The side smaller values live on. The else branch already shows the other side."] = "El lado donde viven los valores menores. La rama else ya muestra el otro lado.",
  ["The side the larger values live on, visited last."] = "El lado donde viven los valores mayores, visitado el último.",
  ["The signboard"] = "El letrero",
  ["The slice built-in that grows. Mark visited when you enqueue, not when you pop."] = "El built-in de slice que crece. Marca visitado al encolar, no al sacar.",
  ["The smallest buffer that still holds something. One result, one slot."] = "El buffer más pequeño que aún guarda algo. Un resultado, un hueco.",
  ["The sorting hat"] = "El sombrero seleccionador",
  ["The sorting hat: a shoebox of receipts. Alex sorts them by splitting the pile in half, again and again, then merging back in order. Bo draws the line between linear and quadratic and labels it n log n."] = "El sombrero seleccionador: una caja de zapatos con recibos. Alex los ordena partiendo la pila por la mitad, una y otra vez, y luego mezclando de vuelta en orden. Bo dibuja la línea entre lo lineal y lo cuadrático y la etiqueta n log n.",
  ["The sorting hat: a shoebox of receipts. Alex sorts them by splitting the pile in half, again and again, then merging back in order. Mei draws the line between linear and quadratic and labels it n log n."] = "El sombrero seleccionador: una caja de zapatos con recibos. Alex los ordena partiendo la pila por la mitad, una y otra vez, y luego mezclando de vuelta en orden. Mei dibuja la línea entre lo lineal y lo cuadrático y la etiqueta n log n.",
  ["The sorting hat: a shoebox of the night's receipts. Alex sorts them by splitting the pile in half, again and again, then merging the piles back in order. Mei draws the line between linear and quadratic."] = "El sombrero seleccionador: una caja de zapatos con los recibos de la noche. Alex los ordena partiendo la pila por la mitad, una y otra vez, y luego mezclando las pilas de vuelta en orden. Mei dibuja la línea entre lo lineal y lo cuadrático.",
  ["The stamp desk"] = "El mostrador de sellos",
  ["The stamp desk. Bo wants every kitchen function timed and logged without touching its body. In Python a function is a value: wrap it in another and put the wrapper's name, with an @, on the line above."] = "El mostrador de sellos. Bo quiere que cada función de la cocina se cronometre y se registre sin tocar su cuerpo. En Python una función es un valor: envuélvela en otra y pon el nombre de la envoltura, con una @, en la línea de arriba.",
  ["The startup calls back. Seven whiteboard classics: stack, DP, window, heap, intervals, LRU, grid. Get the OFFER."] = "La startup vuelve a llamar. Siete clásicos de pizarra: stack, DP, ventana, heap, intervalos, LRU, cuadrícula. Consigue la OFFER.",
  ["The stock file is left open every night. Then the count is wrong in the morning."] = "El archivo de stock se queda abierto cada noche. Y por la mañana el recuento está mal.",
  ["The stock room"] = "El almacén",
  ["The stock room. A script counts eggs, trays and coffee beans, and it has been dividing with the wrong slash all year. Alex has typed := ten thousand times; here a plain = will do, and there is no type to write."] = "El almacén. Un script cuenta huevos, bandejas y granos de café, y lleva todo el año dividiendo con la barra equivocada. Alex ha escrito := diez mil veces; aquí basta un = simple, y no hay tipo que escribir.",
  ["The stock script counts trays. It says we have 4.1666 trays of eggs. We do not."] = "El script de stock cuenta bandejas. Dice que tenemos 4.1666 bandejas de huevos. No es así.",
  ["The storeroom"] = "El almacén",
  ["The storeroom is small. Sort the trays where they stand; do not build a second rack."] = "El almacén es pequeño. Ordena las bandejas donde están; no construyas un segundo estante.",
  ["The storeroom: every algorithm needs somewhere to put things. Sorting the trays where they stand costs no shelf; cloning them onto a new rack costs a rack the size of the input. Mei adds the second axis."] = "El almacén: todo algoritmo necesita un sitio donde poner cosas. Ordenar las bandejas donde están no cuesta ningún estante; clonarlas a un estante nuevo cuesta un estante del tamaño de la entrada. Mei añade el segundo eje.",
  ["The storeroom: every algorithm needs somewhere to put things. Sorting the trays where they stand costs no shelf; copying them onto a new rack costs a rack the size of the input. Mei adds the second axis to the board."] = "El almacén: todo algoritmo necesita un sitio donde poner cosas. Ordenar las bandejas donde están no cuesta ningún estante; copiarlas a un estante nuevo cuesta un estante del tamaño de la entrada. Mei añade el segundo eje a la pizarra.",
  ["The storeroom: every algorithm needs somewhere to put things. Sorting the trays where they stand costs no shelf; copying them onto a new rack costs a rack the size of the input. Mei adds the second axis to the last board of the night."] = "El almacén: todo algoritmo necesita un sitio donde poner cosas. Ordenar las bandejas donde están no cuesta ningún estante; copiarlas a un estante nuevo cuesta un estante del tamaño de la entrada. Mei añade el segundo eje a la última pizarra de la noche.",
  ["The table starts with what is already known. One way to stand at the bottom, and how many ways to reach step 1?"] = "La tabla empieza con lo que ya se sabe. Una forma de estar abajo, ¿y cuántas formas de llegar al escalón 1?",
  ["The tea table"] = "La mesa del té",
  ["The thread may outlive this scope. Which keyword gives the closure ownership of order?"] = "El thread puede vivir más que este scope. ¿Qué palabra clave da al closure el ownership de order?",
  ["The three biggest prices, biggest first, in one call. Which heapq helper?"] = "Los tres precios más altos, el mayor primero, en una sola llamada. ¿Qué ayudante de heapq?",
  ["The ticket printer skips dish zero and prints dish five twice. Fix the loop."] = "La impresora de tickets se salta el plato cero e imprime el plato cinco dos veces. Arregla el bucle.",
  ["The till"] = "La caja",
  ["The till returns (receipt, err). If err is not the zero value of error, stop. defer close() runs even if you return early."] = "La caja devuelve (receipt, err). Si err no es el valor cero de error, para. defer close() se ejecuta aunque retornes antes.",
  ["The till says Err and then just stops. Mei, does Rust not have nil?"] = "La caja dice Err y luego se para. Mei, ¿Rust no tiene nil?",
  ['The till sends "12" as text. Which built-in turns it into a whole number?'] = 'La caja envía "12" como texto. ¿Qué función integrada lo convierte en un número entero?',
  ["The till thinks every order is a tuple. Give it a struct with names."] = "La caja cree que cada pedido es una tupla. Dale un struct con nombres.",
  ["The trait behind {}. Debug is behind {:?}. You cannot derive this one."] = "El trait detrás de {}. Debug está detrás de {:?}. Este no se puede derivar.",
  ["The tray is on the table. One last lesson: a request has a context so the kitchen can stop if the guest walks out. And a test so the next morning still compiles."] = "La bandeja está en la mesa. Una última lección: una petición lleva un context para que la cocina pare si el cliente se va. Y un test para que la mañana siguiente aún compile.",
  ["The tray rack"] = "El estante de bandejas",
  ["The tray rack. Bo's rack script keeps trays in a list and reads the last one with index len minus one, off by one, every night. Python has a shorter way to say 'last'."] = "El estante de bandejas. El script del estante de Bo guarda las bandejas en una lista y lee la última con el índice len menos uno, desplazado en uno, cada noche. Python tiene una forma más corta de decir 'último'.",
  ["The tray rail"] = "El riel de bandejas",
  ["The tuple assignment does all three moves at once: Go evaluates the right side first."] = "La asignación en tupla hace los tres movimientos a la vez: Go evalúa primero el lado derecho.",
  ["The two seconds ran out. Which context error is that?"] = "Se acabaron los dos segundos. ¿Qué error de context es ese?",
  ["The type itself, used as a constructor. a[:] and a.copy() are the other two spellings."] = "El tipo en sí, usado como constructor. a[:] y a.copy() son las otras dos formas de escribirlo.",
  ["The type name works as the conversion. Floor and int never mix silently."] = "El nombre del tipo funciona como conversión. Floor e int nunca se mezclan en silencio.",
  ["The type name, inside the parentheses. The second line shows the safe two-value form."] = "El nombre del tipo, dentro del paréntesis. La segunda línea muestra la forma segura de dos valores.",
  ["The type of [] itself, with the item type in square brackets. Older code imported a capitalized one from typing."] = "El tipo de [] mismo, con el tipo del elemento entre corchetes. El código antiguo importaba uno con mayúscula desde typing.",
  ["The type of {} itself, lowercase, key type then value type inside the brackets."] = "El tipo de {} mismo, en minúsculas, tipo de la clave y luego tipo del valor entre corchetes.",
  ["The type whose empty value the append needs. Passed as a callable, no parentheses."] = "El tipo cuyo valor vacío necesita el append. Se pasa como invocable, sin paréntesis.",
  ["The typed-nil trap: return a plain nil error, never a nil *MyError."] = "La trampa del nil tipado: devuelve un error nil plano, nunca un *MyError nil.",
  ["The usual 'no answer' for a count: negative one."] = "El 'sin respuesta' habitual para un conteo: menos uno.",
  ["The usual 'not found' number, which is why the return type is i64 and not usize."] = "El número habitual de 'no encontrado', por eso el tipo de retorno es i64 y no usize.",
  ["The usual impossible marker: a negative one, since a real count is never below zero."] = "El marcador habitual de imposible: un menos uno, ya que un conteo real nunca es negativo.",
  ["The value a function without return gives back, capital letter, used as the type here."] = "El valor que devuelve una función sin return, con mayúscula, usado aquí como tipo.",
  ["The value of nothing, capital letter. Every function without a return statement gives it back."] = "El valor de la nada, con mayúscula. Toda función sin sentencia return lo devuelve.",
  ["The walk stops when the runner falls off the end. Fill the condition: ___ != nil"] = "El recorrido para cuando el corredor se sale del final. Completa la condición: ___ != nil",
  ["The water byte. Same shape as the land literal, other digit."] = "El byte del agua. La misma forma que el literal de tierra, con el otro dígito.",
  ["The web counter"] = "El mostrador web",
  ["The whiteboard again, the Rust column this time. Mei redraws the axes: n across, work up. First street: the operations whose line stays flat, written the Rust way."] = "La pizarra otra vez, esta vez la columna de Rust. Mei vuelve a dibujar los ejes: n a lo ancho, trabajo hacia arriba. Primera calle: las operaciones cuya línea se queda plana, escritas a la manera de Rust.",
  ["The whiteboard in the back office, wiped clean. Mei draws one axis: n, the size of the input. The other axis is work. First street: operations whose line stays flat however far n goes."] = "La pizarra de la oficina trasera, limpia. Mei dibuja un eje: n, el tamaño de la entrada. El otro eje es el trabajo. Primera calle: operaciones cuya línea se queda plana por lejos que vaya n.",
  ["The whiteboard one more time, the Python column. Chef Bo takes the marker: n across, work up. First street: the operations whose line stays flat, written the Python way."] = "La pizarra una vez más, la columna de Python. El chef Bo toma el rotulador: n a lo ancho, trabajo hacia arriba. Primera calle: las operaciones cuya línea se queda plana, escritas a la manera de Python.",
  ["The window is s[l..r], both ends included. Fill its length."] = "La ventana es s[l..r], ambos extremos incluidos. Completa su longitud.",
  ["The window is s[l:r+1]. Record its width if it is the widest yet. Fill the width."] = "La ventana es s[l:r+1]. Registra su ancho si es el más ancho hasta ahora. Completa el ancho.",
  ["The with block closes and joins the pool for you. Without it, a forgotten pool keeps eight interpreters resident."] = "El bloque with cierra y hace join del pool por ti. Sin él, un pool olvidado mantiene ocho intérpretes residentes.",
  ["The word package, capitalised, followed by the package's name. One comment per package, in one file."] = "La palabra package, en mayúscula, seguida del nombre del paquete. Un comentario por paquete, en un fichero.",
  ["The word that follows an if block, here in the middle of one line. Python has no ? : operator."] = "La palabra que sigue a un bloque if, aquí en medio de una línea. Python no tiene operador ? :.",
  ["The worker appended to my list and my list stayed empty. Every single time."] = "El worker hizo append en mi lista y mi lista siguió vacía. Todas las veces.",
  ["The worker has to attach to the same block. Which attribute do you send it?"] = "El worker tiene que engancharse al mismo bloque. ¿Qué atributo le envías?",
  ["The workers want a real dict everyone can see. Which class serves one over a proxy?"] = "Los workers quieren un dict de verdad que vean todos. ¿Qué clase lo sirve por un proxy?",
  ["The workshop"] = "El taller",
  ["The zero pointer. This is the base case of the tree recursion."] = "El puntero cero. Es el caso base de la recursión del árbol.",
  ["The zero value of a channel. Receiving on it blocks for ever, which select reads as 'never ready'."] = "El valor cero de un channel. Recibir de él bloquea para siempre, que select lee como 'nunca está listo'.",
  ["The zero value of a pointer, slice, map, chan, func, or error is ___."] = "El valor cero de un pointer, slice, map, chan, func o error es ___.",
  ["Then I owe him a tag. And a promise about what the number means."] = "Entonces le debo una etiqueta. Y una promesa sobre lo que significa el número.",
  ["There are no relative imports in Go, ever. An import path is always the full name of a package, so it means the same thing from every file in the world."] = "En Go no hay imports relativos, nunca. Una ruta de importación es siempre el nombre completo de un paquete, así que significa lo mismo desde cualquier fichero del mundo.",
  ["There is exactly one way to stand still, and one way to take a single step."] = "Hay exactamente una forma de quedarse quieto, y una de dar un solo paso.",
  ["They asked me this one too. A stack, Bo. Every closer looks at the top."] = "A mí también me preguntaron esta. Una pila, Bo. Cada cierre mira el tope.",
  ["They overlap: stretch the merged interval to whichever end is farther. Fill the builtin."] = "Se solapan: estira el intervalo fusionado hasta el fin más lejano. Completa la función integrada.",
  ["They overlap: the merged block ends at the later of the two ends. Which built-in?"] = "Se solapan: el bloque fusionado termina en el mayor de los dos finales. ¿Qué función integrada?",
  ["They overlap: the merged block ends at the later of the two ends. Which method picks the larger end?"] = "Se solapan: el bloque fusionado termina en el mayor de los dos finales. ¿Qué método elige el final mayor?",
  ["This cell is land and part of the island. Sink it before flooding onward, so it is never visited twice. What does the cell become?"] = "Esta celda es tierra y parte de la isla. Húndela antes de seguir inundando, para que nunca se visite dos veces. ¿En qué se convierte la celda?",
  ["This is the trap every threading programmer walks into once. Processes share nothing implicitly: results come back through a Queue, a return value, or shared memory."] = "Es la trampa en la que cae una vez todo programador venido de los hilos. Los procesos no comparten nada implícitamente: los resultados vuelven por una Queue, un valor devuelto o memoria compartida.",
  ["This scan is O(n): the honest cost of a VecDeque order. A doubly linked list with map-held nodes makes it O(1)."] = "Este recorrido es O(n): el coste honesto de un orden en VecDeque. Una lista doblemente enlazada con nodos en el map lo hace O(1).",
  ["Thread(target=fn, args=(...)) wraps a call. It is an OS thread, heavier than a goroutine, fine for I/O."] = "Thread(target=fn, args=(...)) envuelve una llamada. Es un hilo del SO, más pesado que una goroutine, suficiente para E/S.",
  ["Threads"] = "Threads",
  ["Threads and the GIL"] = "Hilos y el GIL",
  ["Threads do help downloads. What happens to the GIL around a socket read?"] = "Los hilos sí ayudan a las descargas. ¿Qué le pasa al GIL alrededor de una lectura de socket?",
  ["Threads that borrow menu and are all joined before the block ends. Which function?"] = "Threads que prestan menu y a los que se hace join antes de que acabe el bloque. ¿Qué función?",
  ["Three bowls left. If it says zero, we close."] = "Quedan tres boles. Si dice cero, cerramos.",
  ["Three cooks, one ticket rail, one lock on the rail. That is a worker pool."] = "Tres cocineros, un riel de tickets, un lock sobre el riel. Eso es un worker pool.",
  ["Three cooks, one ticket rail, one pass. That is a worker pool."] = "Tres cocineros, un riel de comandas, un pase. Eso es un worker pool.",
  ["Three cooks, three OS threads. Which thread function runs a closure and returns a JoinHandle?"] = "Tres cocineros, tres threads del sistema. ¿Qué función de thread corre un closure y devuelve un JoinHandle?",
  ["Three dots then the element type. Inside the function fares is a []int."] = "Tres puntos y luego el tipo del elemento. Dentro de la función fares es un []int.",
  ["Three letters for the chip, an underscore, then the verb for counting. os has the same one."] = "Tres letras del chip, un guion bajo y luego el verbo de contar. os tiene la misma.",
  ["Three letters from Ord, the twin of the one that picks the smaller."] = "Tres letras, de Ord, el gemelo del que elige el menor.",
  ["Three letters from Ord. A plain assignment of cur.1 would shrink a block that already reached further."] = "Tres letras, de Ord. Una asignación simple de cur.1 encogería un bloque que ya llegaba más lejos.",
  ["Three letters from Ord: the smaller of the current entry and the new candidate."] = "Tres letras, de Ord: el menor entre la entrada actual y el nuevo candidato.",
  ["Three letters in front of Lock, Go 1.18 and up. It attempts, it does not queue."] = "Tres letras delante de Lock, desde Go 1.18. Lo intenta, no hace cola.",
  ["Three letters, O(1) itself: the slice header stores it."] = "Tres letras, O(1) en sí misma: la cabecera del slice la guarda.",
  ["Three letters, a label on a commit. The v in front is not optional for Go."] = "Tres letras, una etiqueta sobre un commit. La v delante no es opcional para Go.",
  ["Three letters, a method with parentheses. Go has the same word as a builtin."] = "Tres letras, un método con paréntesis. Go tiene la misma palabra como builtin.",
  ["Three letters, a statement not a method. Go's delete(m, k), shortened."] = "Tres letras, una sentencia, no un método. El delete(m, k) de Go, acortado.",
  ["Three letters, a verb: attempt it. The except below only makes sense after this."] = "Tres letras, un verbo: inténtalo. El except de abajo solo tiene sentido después de esto.",
  ["Three letters, an underscore, and the four-letter word for a mutex."] = "Tres letras, un guion bajo y la palabra de cuatro letras para un mutex.",
  ["Three letters, as in checksum. Commit it next to go.mod, always."] = "Tres letras, como en checksum. Súbelo al repo junto a go.mod, siempre.",
  ["Three letters, capital N. Takes the message, returns an error."] = "Tres letras, N mayúscula. Recibe el mensaje, devuelve un error.",
  ["Three letters, from Ord. Its twin picks the larger one."] = "Tres letras, de Ord. Su gemelo elige el mayor.",
  ["Three letters, from the Ord trait. a.max(b) reads better than std::cmp::max(a, b)."] = "Tres letras, del trait Ord. a.max(b) se lee mejor que std::cmp::max(a, b).",
  ["Three letters, like the fastener that joins two sides tooth by tooth."] = "Tres letras, como el cierre que une dos lados diente a diente.",
  ["Three letters, no underscore. The opposite of push. Returns Option<T>."] = "Tres letras, sin guion bajo. Lo contrario de push. Devuelve Option<T>.",
  ["Three letters, same as the module behind println!. Runs rustfmt."] = "Tres letras, igual que el módulo detrás de println!. Ejecuta rustfmt.",
  ["Three letters, same name as on a Vec. It counts bytes, never characters."] = "Tres letras, el mismo nombre que en un Vec. Cuenta bytes, nunca caracteres.",
  ["Three letters, short for buffer."] = "Tres letras, abreviatura de buffer.",
  ["Three letters, short for command. A convention, not a rule, but one every Go repo follows."] = "Tres letras, abreviatura de command. Una convención, no una regla, pero la sigue todo repo Go.",
  ["Three letters, short for dynamic."] = "Tres letras, abreviatura de dynamic.",
  ["Three letters, short for module. The same word as in go.mod."] = "Tres letras, abreviatura de module. La misma palabra que en go.mod.",
  ["Three letters, short for module. Under GOPATH, read-only, shared by every project on the machine."] = "Tres letras, abreviatura de module. Bajo GOPATH, de solo lectura, compartida por todos los proyectos de la máquina.",
  ["Three letters, short for reverse. Only a DoubleEndedIterator has it, and Chars is one."] = "Tres letras, abreviatura de reverse en inglés. Solo un DoubleEndedIterator lo tiene, y Chars lo es.",
  ["Three letters, short for sequence. Seq2 yields pairs, like index and value."] = "Tres letras, abreviatura de sequence. Seq2 produce pares, como índice y valor.",
  ["Three letters, the abbreviation everybody uses. It is a convention, not a rule the compiler knows."] = "Tres letras, la abreviatura que usa todo el mundo. Es una convención, no una regla que el compilador conozca.",
  ["Three letters, the math word for a collection with no duplicates. Go has no built-in one; map[T]bool stands in."] = "Tres letras, la palabra matemática para una colección sin duplicados. Go no tiene una integrada; map[T]bool hace su papel.",
  ["Three letters, the name of the type itself. float() is its cousin."] = "Tres letras, el nombre del tipo mismo. float() es su primo.",
  ["Three letters, the opposite of min. Built in; Go only got it in 1.21."] = "Tres letras, lo contrario de min. Integrada; Go solo la tuvo en 1.21.",
  ["Three letters, the opposite of push. With no argument it takes the last item."] = "Tres letras, lo contrario de push. Sin argumento toma el último elemento.",
  ["Three letters, the opposite of put. Go's <-jobs."] = "Tres letras, lo contrario de put. El <-jobs de Go.",
  ["Three letters, the opposite of the last blank. None when the stack is already empty, and None != Some(open)."] = "Tres letras, lo contrario del último hueco. None cuando la pila ya está vacía, y None != Some(open).",
  ["Three letters, the opposite of the method a worker calls. Go's jobs <- order."] = "Tres letras, lo contrario del método que llama un worker. El jobs <- order de Go.",
  ["Three letters, the partner of Put."] = "Tres letras, la pareja de Put.",
  ["Three letters, the partner of put. Pass timeout= if you would rather not wait for ever."] = "Tres letras, la pareja de put. Pásale timeout= si prefieres no esperar para siempre.",
  ["Three letters, the plainest verb for starting a program. Once, at the top level."] = "Tres letras, el verbo más simple para arrancar un programa. Una vez, en el nivel superior.",
  ["Three letters, the plainest verb there is. go work use ./kiosk writes the same line."] = "Tres letras, el verbo más sencillo que hay. go work use ./kiosk escribe la misma línea.",
  ["Three letters, the same as Go. Not a method: it is a function that takes the list."] = "Tres letras, igual que en Go. No es un método: es una función que recibe la lista.",
  ["Three letters, the same builtin a slice uses for its capacity."] = "Tres letras, la misma función integrada que usa un slice para su capacidad.",
  ["Three letters, the same name as on a Vec, but here it returns the top of the heap in O(log k)."] = "Tres letras, el mismo nombre que en un Vec, pero aquí devuelve la cima del heap en O(log k).",
  ["Three letters, the same name as the builtin it replaces."] = "Tres letras, el mismo nombre que la función integrada a la que sustituye.",
  ["Three letters, the start of 'define'. Go's func, Rust's fn."] = "Tres letras, el inicio de 'define'. El func de Go, el fn de Rust.",
  ["Three letters, the text type's own name. An f-string would do the same without the call."] = "Tres letras, el nombre del tipo de texto. Una f-string haría lo mismo sin la llamada.",
  ["Three letters, what you do to fetch something. The @ picks the version; without it, latest."] = "Tres letras, lo que haces para traer algo. La @ elige la versión; sin ella, latest.",
  ["Three letters. A slice of pairs would need a scan, O(n); this hashes the key instead."] = "Tres letras. Un slice de pares necesitaría un barrido, O(n); este hashea la clave en su lugar.",
  ["Three letters. Bigger than any coin count, so the first real answer replaces it."] = "Tres letras. Mayor que cualquier conteo de monedas, así que la primera respuesta real lo reemplaza.",
  ["Three letters. Capacity, not length."] = "Tres letras. Capacidad, no longitud.",
  ["Three letters. Go has var and :=; Rust has one word for both."] = "Tres letras. Go tiene var y :=; Rust tiene una sola palabra para ambos.",
  ["Three letters. Heap pointer. dyn has no known size, so it must live behind one."] = "Tres letras. Puntero al heap. dyn no tiene tamaño conocido, así que debe vivir detrás de uno.",
  ["Three letters. Lists append; sets do this."] = "Tres letras. Las listas hacen append; los sets hacen esto.",
  ["Three letters. Plus. Built into cargo since 1.62; remove is its opposite."] = "Tres letras. Sumar. Integrado en cargo desde 1.62; remove es su opuesto.",
  ["Three letters. Rust's word for Go's import, one path at a time."] = "Tres letras. La palabra de Rust para el import de Go, una ruta a la vez.",
  ["Three letters. Same word as Vec::new. Add --lib for a library instead."] = "Tres letras. La misma palabra que Vec::new. Añade --lib para una biblioteca en su lugar.",
  ["Three letters. Short for mutable, the opposite of the default."] = "Tres letras. Abreviatura de mutable, lo contrario del valor por defecto.",
  ["Three letters. Takes a reference to the key, returns Option<&V>."] = "Tres letras. Recibe una referencia a la clave, devuelve Option<&V>.",
  ["Three letters. Takes a reference to the key, returns Option<&V>. The &v pattern copies the u64 out."] = "Tres letras. Toma una referencia a la clave y devuelve Option<&V>. El patrón &v copia el u64 fuera.",
  ["Three letters. The maths word for adding up. product() is its cousin."] = "Tres letras. La palabra matemática para sumar, en inglés. product() es su primo.",
  ["Three letters. The owned heap pointer: one owner, freed when dropped. Not Rc, nobody shares a child."] = "Tres letras. El puntero al heap con dueño: un solo dueño, liberado al soltarlo. No es Rc, nadie comparte un hijo.",
  ["Three letters. The type on the left, : i32, tells it what to produce."] = "Tres letras. El tipo a la izquierda, : i32, le dice qué producir.",
  ["Three letters. This is Python's await: the work started at apply_async."] = "Tres letras. Este es el await de Python: el trabajo empezó en apply_async.",
  ["Three letters. Works anywhere; := only works inside a function."] = "Tres letras. Funciona en cualquier parte; := solo funciona dentro de una función.",
  ["Three letters. impl Trait ___ Type."] = "Tres letras. impl Trait ___ Tipo.",
  ["Three letters. max is its twin. Both take any number of ordered values."] = "Tres letras. max es su gemelo. Ambos aceptan cualquier número de valores ordenados.",
  ["Three letters. menu[k] raises when k is missing; this one returns the default instead."] = "Tres letras. menu[k] lanza si falta k; este devuelve el valor por defecto en su lugar.",
  ["Three letters: Atomic Reference Counted."] = "Tres letras: Atomic Reference Counted.",
  ["Three letters: is there any element for which the closure is true. Vec::contains does the same for one value."] = "Tres letras: ¿hay algún elemento para el que la clausura sea verdadera? Vec::contains hace lo mismo para un solo valor.",
  ["Three letters: to examine. ./... means this package and everything under it."] = "Tres letras: examinar. ./... significa este paquete y todo lo que hay debajo.",
  ["Three letters; the loop calls .add on it. len(set(guests)) < len(guests) is the one-liner."] = "Tres letras; el bucle llama a .add sobre él. len(set(guests)) < len(guests) es la versión de una línea.",
  ["Three letters; the next line calls .add on it. Go's map[string]bool, Rust's HashSet."] = "Tres letras; la línea siguiente llama a .add sobre él. El map[string]bool de Go, el HashSet de Rust.",
  ["Three pairs, one match. '\\0' marks an opener; the rest of the loop branches on that."] = "Tres pares, un match. '\\0' marca una apertura; el resto del bucle se bifurca según eso.",
  ["Three parts: ampersand, the mutability word, the receiver. o must be let mut to call it."] = "Tres partes: ampersand, la palabra de mutabilidad, el receptor. o debe ser let mut para llamarlo.",
  ["Three riders, three radios. The script calls them one after another and the noodles go cold."] = "Tres repartidores, tres radios. El script los llama uno tras otro y los fideos se enfrían.",
  ["Three threads add to one counter. Which threading object guards it?"] = "Tres hilos suman a un contador. ¿Qué objeto de threading lo protege?",
  ["Three woks, one cook script. It fries one egg at a time while the other two woks sit cold."] = "Tres woks, un script de cocina. Fríe un huevo a la vez mientras los otros dos woks se enfrían.",
  ["Three words in one: check the old value, then put the new one. Everyone calls it CAS."] = "Tres palabras en una: comprueba el valor viejo y pon el nuevo. Todo el mundo lo llama CAS.",
  ["Three words joined: what the operating system schedules, a pool of them, and the thing that runs your calls."] = "Tres palabras unidas: lo que planifica el sistema operativo, un pool de ellos y lo que ejecuta tus llamadas.",
  ["Three words with underscores: relocate the key to the back of the order."] = "Tres palabras con guiones bajos: mover la clave al final del orden.",
  ["Three words with underscores: run, in, and the thing you built at the top of this street."] = "Tres palabras con guiones bajos: run, in y lo que construiste al principio de esta calle.",
  ["Three words with underscores: sort, by, and the thing the closure returns."] = "Tres palabras con guiones bajos: sort, by, y lo que devuelve la closure.",
  ["Three words, two underscores: skip, the verb for writing out, if. It names a predicate."] = "Tres palabras, dos guiones bajos: skip, el verbo de escribir hacia fuera, if. Nombra un predicado.",
  ["Throw away the bool, keep the error. What character discards?"] = "Descarta el bool, quédate con el error. ¿Qué carácter descarta?",
  ["Ticket five: the app needs a server. net/http is in the standard library: a handler is a function, a route is a string, the server is one call."] = "Ticket cinco: la app necesita un servidor. net/http está en la biblioteca estándar: un handler es una función, una ruta es un string, el servidor es una sola llamada.",
  ["Ticket four: orders arrive as JSON. The decoder only sees exported fields, and a tag on the field tells it which key to read."] = "Ticket cuatro: los pedidos llegan como JSON. El decodificador solo ve campos exportados, y un tag en el campo le dice qué clave leer.",
  ["Ticket one. The receipt cuts the shop name in half. Bytes, not characters."] = "Ticket uno. El recibo corta el nombre de la tienda por la mitad. Bytes, no caracteres.",
  ["Ticket seven, the rooftop. The app is live. Newer Go has generic helpers so the old hand-written loops can go: slices, maps, min, and iterators you can range over."] = "Ticket siete, la azotea. La app está en producción. El Go más reciente tiene ayudantes genéricos que jubilan los viejos bucles a mano: slices, maps, min e iteradores que puedes recorrer con range.",
  ["Ticket six: ship it. A module names the project, go.mod pins the dependencies, and the go tool formats, checks and builds. No Makefile needed."] = "Ticket seis: a producción. Un módulo nombra el proyecto, go.mod fija las dependencias, y la herramienta go formatea, revisa y compila. Sin Makefile.",
  ["Ticket three: the menu board takes any. Before the app can print a price it must ask what is inside. Go asks with an assertion or a type switch."] = "Ticket tres: la pizarra del menú acepta any. Antes de imprimir un precio, la app debe preguntar qué hay dentro. Go pregunta con una aserción o un type switch.",
  ["Ticket two: refunds. An error must say what went wrong, keep its cause, and let the caller ask which kind it was. All of that is in package errors."] = "Ticket dos: reembolsos. Un error debe decir qué falló, conservar su causa y dejar que quien llama pregunte de qué clase era. Todo eso está en el paquete errors.",
  ["Tilde. Without it, type Cents int would not satisfy Number."] = "La virgulilla ~. Sin ella, type Cents int no satisfaría Number.",
  ["Time is one axis. Memory is the other. Every cache you loved tonight paid rent here."] = "El tiempo es un eje. La memoria es el otro. Cada cache que te gustó esta noche pagó alquiler aquí.",
  ["Time is one axis. Memory is the other. Every memo you loved tonight paid rent here."] = "El tiempo es un eje. La memoria es el otro. Cada memo que te gustó esta noche pagó alquiler aquí.",
  ["Time is one axis. Memory is the other. Rust makes you see every allocation; that is the point."] = "El tiempo es un eje. La memoria es el otro. Rust te hace ver cada reserva; ese es el punto.",
  ["Time the grill. Fill the prefix: func ___Grill(b *testing.B)"] = "Cronometra la plancha. Completa el prefijo: func ___Grill(b *testing.B)",
  ["Times Square"] = "Times Square",
  ["Times Square atrium"] = "Atrio de Times Square",
  ["Times Square's LED cube is a slice of frames. An array has a fixed size in the type. A slice does not. append returns a (maybe new) slice."] = "El cubo LED de Times Square es un slice de frames. Un array tiene tamaño fijo en el tipo. Un slice no. append devuelve un slice (quizá nuevo).",
  ["Times Square's live coding show. Seven rounds of classic interview problems. Get HIRED."] = "El show de programación en vivo de Times Square. Siete rondas de problemas clásicos de entrevista. Consigue el CONTRATADO.",
  ["To then Upper. Strings are immutable, so it returns a new one."] = "To y luego Upper. Los strings son inmutables, así que devuelve uno nuevo.",
  ["Toast is off the menu tonight. Which statement removes the key?"] = "Esta noche la tostada sale de la carta. ¿Qué sentencia elimina la clave?",
  ["Top k frequent dishes: count first. Which HashMap method gives a slot for w, creating it with 0 if new?"] = "Top k platos más frecuentes: primero cuenta. ¿Qué método de HashMap da un hueco para w, creándolo con 0 si es nuevo?",
  ["Top k most ordered dishes. Count them, then take the k highest counts. Which Counter method?"] = "Los k platos más pedidos. Cuéntalos y toma los k conteos más altos. ¿Qué método de Counter?",
  ["Top-down instead: recurse, but remember every result. Which functools decorator?"] = "De arriba abajo, en cambio: recursión, pero recordando cada resultado. ¿Qué decorador de functools?",
  ["Traits"] = "Traits",
  ["Tram or walk? if the light is green, we go."] = "¿Tranvía o a pie? if el semáforo está en verde, vamos.",
  ["Tray::default() comes from the Default trait: 0 for numbers, empty String, empty Vec. Also ..Default::default() in struct literals."] = "Tray::default() viene del trait Default: 0 para números, String vacío, Vec vacío. También ..Default::default() en literales de struct.",
  ["True only when nothing is left on the stack: compare its length with zero."] = "Verdadero solo cuando no queda nada en la pila: compara su longitud con cero.",
  ["True when the stack is empty. An empty list is falsy; negate it."] = "True cuando la pila está vacía. Una lista vacía es falsy; niégala.",
  ["TryLock is for work you can skip, not for dodging a design problem. If you reach for it often, the shared state is wrong."] = "TryLock es para trabajo que puedes saltarte, no para esquivar un problema de diseño. Si recurres a él a menudo, el estado compartido está mal.",
  ["Turn an Option into a Result, with this message as the Err. Which method?"] = "Convierte un Option en Result, con este mensaje como Err. ¿Qué método?",
  ["Turn land into water: the byte for water."] = "Convierte tierra en agua: el byte del agua.",
  ["Turn the Order into JSON bytes. Fill: json.___(order)"] = "Convierte el Order en bytes JSON. Completa: json.___(order)",
  ["Turn the Order into a JSON String. Which serde_json function?"] = "Convierte el Order en un String JSON. ¿Qué función de serde_json?",
  ["Turn the lazy chain back into a Vec. Which method finishes it?"] = "Convierte la cadena perezosa de vuelta en un Vec. ¿Qué método la remata?",
  ["Twelve letters. Things the project depends on. dev-... is the variant for tests only."] = "Doce letras. Las cosas de las que depende el proyecto. dev-... es la variante solo para tests.",
  ["Twenty goroutines want the menu loaded; load it exactly once. Which method of sync.Once?"] = "Veinte goroutines quieren el menú cargado; cárgalo exactamente una vez. ¿Qué método de sync.Once?",
  ["Two ETAs at the same time, both results in one tuple. Which tokio macro?"] = "Dos ETA a la vez, ambos resultados en una tupla. ¿Qué macro de tokio?",
  ["Two English words glued together: this and the thing you are deriving. Not anyhow."] = "Dos palabras inglesas pegadas: this y lo que estás derivando. No es anyhow.",
  ["Two binaries, one repo. Which directory holds one main package per binary?"] = "Dos binarios, un repo. ¿Qué directorio guarda un paquete main por binario?",
  ["Two braces with nothing between. Note: this makes a dict, not a set; set() is spelled out."] = "Dos llaves sin nada entre ellas. Ojo: esto crea un dict, no un set; set se escribe set().",
  ["Two braces with nothing inside. Not %d, not %v."] = "Dos llaves sin nada dentro. Ni %d, ni %v.",
  ["Two characters: the receive operator, in front of the channel."] = "Dos caracteres: el operador de recepción, delante del channel.",
  ["Two choices per topping, multiplied n times. Two, a caret, n."] = "Dos opciones por ingrediente, multiplicadas n veces. Dos, un acento circunflejo, n.",
  ["Two colons, then the type in angle brackets. It looks like a fish."] = "Dos veces dos puntos, luego el tipo entre ángulos. Parece un pez.",
  ["Two cooks increment the same tray count. Without a lock that is a race. WaitGroup.Add, Done, Wait is how the pass knows both items are ready."] = "Dos cocineros incrementan el mismo contador de bandejas. Sin candado eso es una race. WaitGroup.Add, Done, Wait es como el pase sabe que ambos platos están listos.",
  ["Two dots and one more character that says the end counts too."] = "Dos puntos y un carácter más que dice que el final también cuenta.",
  ["Two dots, then the sign that says equal too."] = "Dos puntos seguidos y luego el signo que dice igual también.",
  ["Two goroutines touching one variable, one of them writing, is a data race: go test -race finds it. Share by sending on a channel instead, or protect the reference. A plain map crashes under concurrent writes; sync.Map is built for it. Closing a channel publishes everything written before the close."] = "Dos goroutines tocando una variable, y una de ellas escribiendo, es una carrera de datos: go test -race la encuentra. Comparte enviando por un channel, o protege la referencia. Un map normal revienta con escrituras concurrentes; sync.Map está hecho para eso. Cerrar un channel publica todo lo escrito antes del cierre.",
  ["Two hands, one tray counter. Lock it. Then wait for both cooks."] = "Dos manos, un contador de bandejas. Bloquéalo. Luego espera a ambos cocineros.",
  ["Two less than n. The base case handles 0 and 1, so this never goes negative."] = "Dos menos que n. El caso base maneja 0 y 1, así que esto nunca se vuelve negativo.",
  ["Two letters, the opposite of off. The empty default means the same thing now."] = "Dos letras, lo contrario de off. El valor vacío por defecto significa ahora lo mismo.",
  ["Two letters, the same name a map lookup and a type assertion use."] = "Dos letras, el mismo nombre que usan la consulta a un map y una aserción de tipo.",
  ["Two letters, the same word except and import use to bind a name."] = "Dos letras, la misma palabra que except e import usan para enlazar un nombre.",
  ["Two letters, the same word import and with use to give something a local name."] = "Dos letras, la misma palabra que import y with usan para darle a algo un nombre local.",
  ["Two letters, the same word the for loop uses between the name and the list."] = "Dos letras, la misma palabra que el bucle for usa entre el nombre y la lista.",
  ["Two letters, the shortest keyword in the language, and the name of the language."] = "Dos letras, la palabra clave más corta del lenguaje y también el nombre del lenguaje.",
  ["Two letters. == only checks the outer error; this unwraps."] = "Dos letras. == solo revisa el error externo; esto desenvuelve.",
  ["Two letters. Go's func with the middle taken out."] = "Dos letras. El func de Go sin el medio.",
  ["Two letters. In Rust it is an expression, so it can sit after =."] = "Dos letras. En Rust es una expresión, así que puede ir tras el =.",
  ["Two letters. Is matches a value; this matches a type and fills the pointer."] = "Dos letras. Is compara un valor; esto compara un tipo y rellena el puntero.",
  ["Two letters. Rust never converts numbers silently; you write the cast."] = "Dos letras. Rust nunca convierte números en silencio; tú escribes el cast.",
  ["Two letters. The other nineteen goroutines wait inside it until the first is finished."] = "Dos letras. Las otras diecinueve goroutines esperan dentro hasta que la primera termina.",
  ["Two letters. The same word the for loop uses. Its cost depends entirely on the type on the right."] = "Dos letras. La misma palabra que usa el bucle for. Su coste depende por completo del tipo de la derecha.",
  ["Two letters. Then a function call. The caller does not wait."] = "Dos letras. Luego una llamada a función. Quien llama no espera.",
  ["Two letters: the same object, not merely equal values. == would work here too, but this is the honest one."] = "Dos letras: el mismo objeto, no meramente valores iguales. == también funcionaría aquí, pero este es el honesto.",
  ["Two numbers that add up to target. Store value to index; for each x ask if target - x is already there. Which method?"] = "Dos números que suman target. Guarda valor a índice; para cada x pregunta si target - x ya está. ¿Qué método?",
  ["Two of the same character. One of them alone gives 4.1666, a float, every time."] = "Dos veces el mismo carácter. Uno solo da 4.1666, un float, siempre.",
  ["Two packages in one file. What keyword opens the grouped list?"] = "Dos paquetes en un archivo. ¿Qué palabra clave abre la lista agrupada?",
  ["Two pointers that only move right: O(n) time, O(alphabet) space. 'abcabcbb' gives 3."] = "Dos punteros que solo avanzan a la derecha: tiempo O(n), espacio O(alfabeto). 'abcabcbb' da 3.",
  ["Two pointers walk inward from both ends. Fill the step: i, j = i+1, ___"] = "Dos punteros avanzan hacia dentro desde ambos extremos. Completa el paso: i, j = i+1, ___",
  ["Two pointers: O(n) time, O(1) extra space. Same trick for sorted-array pair sums."] = "Dos punteros: tiempo O(n), espacio extra O(1). Mismo truco para sumas de pares en arrays ordenados.",
  ["Two processes, one conversation, no queue machinery. Which function?"] = "Dos procesos, una conversación, sin la maquinaria de una cola. ¿Qué función?",
  ["Two repos, one laptop"] = "Dos repos, un portátil",
  ["Two runners: slow hops one node a lap, fast two. hop turns Option<Box<T>> into Option<&T>. Which method?"] = "Dos corredores: slow salta un nodo por vuelta, fast dos. hop convierte Option<Box<T>> en Option<&T>. ¿Qué método?",
  ["Two separate loops over the same n items, one after the other: O(n) + O(n) simplifies to O(___)"] = "Dos bucles separados sobre los mismos n elementos, uno tras otro: O(n) + O(n) se simplifica a O(___)",
  ["Two separate passes over the same n items, one after the other: O(n) + O(n) simplifies to O(___)"] = "Dos pasadas separadas sobre los mismos n elementos, una tras otra: O(n) + O(n) se simplifica a O(___)",
  ["Two singles, or one double. Count them."] = "Dos simples, o un doble. Cuéntalos.",
  ["Two slashes. A single one makes a float, and a[3.5] raises TypeError."] = "Dos barras. Una sola produce un float, y a[3.5] lanza TypeError.",
  ["Two slashes. Same as Go, C and JavaScript."] = "Dos barras. Igual que Go, C y JavaScript.",
  ["Two slashes: floor division. A single slash would make 3.5 and the slice would raise TypeError."] = "Dos barras: división entera. Una sola barra daría 3.5 y la rebanada lanzaría TypeError.",
  ["Two sorted lists, two pointers: O(n log n). rooms peaks at the answer and never has to come down."] = "Dos listas ordenadas, dos punteros: O(n log n). rooms alcanza su pico en la respuesta y nunca tiene que bajar.",
  ["Two stars, then the name the body reads .items() from. Inside, it is a dict."] = "Dos asteriscos, y luego el nombre del que el cuerpo lee .items(). Dentro es un dict.",
  ["Two stars. Go has no operator for this; Python and Rust's pow() do."] = "Dos asteriscos. Go no tiene operador para esto; Python sí, y Rust usa pow().",
  ["Two steps below i. The loop starts at 2 so this index never goes negative."] = "Dos escalones por debajo de i. El bucle empieza en 2, así que este índice nunca es negativo.",
  ["Two steps below i. The same shape as fib, without the recursion."] = "Dos escalones por debajo de i. La misma forma que fib, sin la recursión.",
  ["Two tills need two senders into the same pipe. Which method makes the second?"] = "Dos cajas necesitan dos emisores hacia la misma tubería. ¿Qué método crea el segundo?",
  ["Two tills, both adding to sold. At 12:04 the screen says 311, the drawer says 317."] = "Dos cajas, las dos sumando a sold. A las 12:04 la pantalla dice 311 y el cajón dice 317.",
  ["Two tills, one counter"] = "Dos cajas, un contador",
  ["Two tills, one kitchen. Orders pile up on my side and never arrive."] = "Dos cajas, una cocina. Los pedidos se amontonan de mi lado y nunca llegan.",
  ["Two tills, six woks and forty riders touch the same numbers. Lock it, share it, cancel it. And find Go's await."] = "Dos cajas, seis woks y cuarenta repartidores tocan los mismos números. Bloquéalo, compártelo, cancélalo. Y encuentra el await de Go.",
  ["Two underscores, the name of the function above, two underscores. As a module the value would be the file name."] = "Dos guiones bajos, el nombre de la función de arriba, dos guiones bajos. Como módulo, el valor sería el nombre del archivo.",
  ["Two underscores, the start of initialize, two underscores. Dunder methods all look like this."] = "Dos guiones bajos, el inicio de initialize, dos guiones bajos. Todos los métodos dunder tienen este aspecto.",
  ["Two words are anagrams if their letters, put in order, match. Which built-in orders them?"] = "Dos palabras son anagramas si sus letras, puestas en orden, coinciden. ¿Qué función integrada las ordena?",
  ["Two words as one, camelCase: use this, instead of that. The ssh form replaces the https prefix."] = "Dos palabras en una, camelCase: usa esto en lugar de aquello. La forma ssh sustituye al prefijo https.",
  ["Two words glued: the verb you call to wait, and a thing you hold."] = "Dos palabras pegadas: el verbo que llamas para esperar, y algo que sujetas (handle).",
  ["Two words joined by an underscore: the ones that appear the most, the way people say it."] = "Dos palabras unidas por guion bajo: los que más aparecen, dicho como lo dice la gente.",
  ["Two words joined, CapWords: stop, and the thing generators do. A for loop catches it silently."] = "Dos palabras unidas, CapWords: detener, y lo que hacen los generadores. Un bucle for la captura en silencio.",
  ["Two words joined, lowercase. The first parameter is spelled cls by convention."] = "Dos palabras unidas, en minúsculas. El primer parámetro se escribe cls por convención.",
  ["Two words joined, lowercase: not moving, and what a def in a class is."] = "Dos palabras unidas, en minúsculas: que no se mueve, y lo que es un def en una clase.",
  ["Two words joined, lowercase: the thing a with statement needs, as one name."] = "Dos palabras unidas, en minúsculas: lo que necesita una sentencia with, como un solo nombre.",
  ["Two words joined, no underscore: how it left, as a number. None until it has."] = "Dos palabras juntas, sin guion bajo: cómo se fue, en forma de número. None hasta que se va.",
  ["Two words joined: the mod folder, and what kind of folder it is. Eight letters."] = "Dos palabras unidas: la carpeta mod y qué clase de carpeta es. Ocho letras.",
  ["Two words with an underscore: as, then the past participle of complete."] = "Dos palabras con un guion bajo: as y luego el participio de complete.",
  ["Two words with an underscore: make one of the things the loop schedules. tokio::spawn."] = "Dos palabras con guion bajo: crear una de las cosas que el bucle programa. tokio::spawn.",
  ["Two words with an underscore: the task, and the state it is now in."] = "Dos palabras con guion bajo: la tarea, y el estado en que está ahora.",
  ["Two words with an underscore: the unit of work, then the past tense of finish."] = "Dos palabras con un guion bajo: la unidad de trabajo y luego el pasado de terminar.",
  ["Two words, CamelCase: a dict with an order."] = "Dos palabras, en CamelCase: un dict con orden.",
  ["Two words: the moment you promised, and what the clock did to it. The other one is Canceled."] = "Dos palabras: el momento que prometiste y lo que el reloj le hizo. El otro es Canceled.",
  ["Two-sum in one pass: for each x, is target minus x already known? Which dict is checked?"] = "Two-sum en una pasada: para cada x, ¿ya se conoce target menos x? ¿Qué dict se consulta?",
  ["Two-sum on a sorted slice, no HashMap: i from the left, j from the right. The sum is too big: which way does j move?"] = "Two-sum en un slice ordenado, sin HashMap: i desde la izquierda, j desde la derecha. La suma es demasiado grande: ¿hacia dónde se mueve j?",
  ["Two-sum, anagrams, palindromes"] = "Two-sum, anagramas, palíndromos",
  ["Two-sum, palindrome, anagram"] = "Two-sum, palíndromo, anagrama",
  ["Two-sum: a dict of seen values, one pass. Anagram: sorted(a) == sorted(b), or a Counter. Palindrome: two pointers from both ends."] = "Two-sum: un dict de valores vistos, una pasada. Anagrama: sorted(a) == sorted(b), o un Counter. Palíndromo: dos punteros desde ambos extremos.",
  ["Type hints"] = "Anotaciones de tipo",
  ["Type name, two colons, the method that copies a handle."] = "Nombre del tipo, dos veces dos puntos, el método que copia un handle.",
  ["Type parameters go in [T any]. Embedding promotes methods. A closure captures nearby names."] = "Los parámetros de tipo van en [T any]. Embedding promueve métodos. Un closure captura nombres cercanos.",
  ["Type the answer, then ENTER."] = "Escribe la respuesta, luego ENTER.",
  ["Un + Marshal. It needs a pointer so it can fill your variable."] = "Un + Marshal. Necesita un puntero para poder rellenar tu variable.",
  ["Unchanged. That is the whole meaning of the 1 in O(1)."] = "Sin cambios. Ese es todo el significado del 1 en O(1).",
  ["Unexported fields are skipped silently. Capital letters or nothing."] = "Los campos no exportados se omiten en silencio. Mayúsculas o nada.",
  ["Unknown shape from the rider app. Which serde_json type holds any JSON?"] = "Forma desconocida desde la app de repartidores. ¿Qué tipo de serde_json guarda cualquier JSON?",
  ["Unmarshal(data, &v). Without & it decodes into a copy and you see nothing."] = "Unmarshal(data, &v). Sin & decodifica en una copia y no ves nada.",
  ["Unpack the Some or leave the function, no match block. Which keyword completes it?"] = "Desempaqueta el Some o sal de la función, sin bloque match. ¿Qué palabra clave lo completa?",
  ["Unseen neighbours go to the back of the queue. Fill: queue = ___(queue, nb)"] = "Los vecinos no vistos van al final de la cola. Completa: queue = ___(queue, nb)",
  ["Up, down, right, left. A dirs table {{1,0},{-1,0},{0,1},{0,-1}} is the same thing in a loop."] = "Arriba, abajo, derecha, izquierda. Una tabla dirs {{1,0},{-1,0},{0,1},{0,-1}} es lo mismo en un bucle.",
  ["Valid means matched and closed. O(n) time, O(n) stack in the worst case: a string of openers."] = "Válido significa emparejado y cerrado. Tiempo O(n), pila O(n) en el peor caso: una cadena de aperturas.",
  ["Valid parentheses and a min stack"] = "Paréntesis válidos y un min stack",
  ["Valid parentheses, min stack"] = "Paréntesis válidos, min stack",
  ["Value and Array are the small end of shared memory: a type code, a size, and a lock in the box. SharedMemory is the large end."] = "Value y Array son el extremo pequeño de la memoria compartida: un código de tipo, un tamaño y un bloqueo en la caja. SharedMemory es el extremo grande.",
  ["Value ships with a lock so you do not invent one. Read, add, write is three steps here exactly as it was in Go."] = "Value viene con un bloqueo para que no te inventes otro. Leer, sumar y escribir son tres pasos aquí igual que en Go.",
  ["Variables need no type. int() and str() convert. // divides down, ** is power. None is no value."] = "Las variables no necesitan tipo. int() y str() convierten. // divide hacia abajo, ** es potencia. None es ningún valor.",
  ["Variables, types, const"] = "Variables, tipos, const",
  ["Vec grows with push. Arrays have a fixed length in the type. HashMap stores key to value; get returns Option."] = "Vec crece con push. Los arrays tienen longitud fija en el tipo. HashMap guarda clave a valor; get devuelve Option.",
  ["Vec plus Deque, a double-ended queue. A ring buffer: O(1) at both ends. Vec::remove(0) would be O(n)."] = "Vec más Deque, una cola de doble extremo. Un búfer circular: O(1) en ambos extremos. Vec::remove(0) sería O(n).",
  ["Vec, arrays and HashMap"] = "Vec, arrays y HashMap",
  ["Vec::sort is a merge sort; sort_unstable is pattern-defeating quicksort. Both n log n."] = "Vec::sort es una ordenación por mezcla; sort_unstable es un quicksort pattern-defeating. Ambos n log n.",
  ["Vec<Box<dyn Cook>>: every Box is one pointer wide, so the Vec is happy. Dispatch happens at run time. The kiosk shows one list."] = "Vec<Box<dyn Cook>>: cada Box mide un puntero, así que el Vec está contento. El dispatch ocurre en ejecución. El kiosco muestra una sola lista.",
  ["VecDeque::from([start]) seeds the queue. seen starts with start too, so it is never queued twice."] = "VecDeque::from([start]) siembra la cola. seen empieza también con start, así que nunca se encola dos veces.",
  ["WHAT ALEX LEARNED: Go basics.   PRIZE: the morning set."] = "LO QUE ALEX APRENDIÓ: bases de Go.   PREMIO: el menú de desayuno.",
  ["WHAT ALEX LEARNED: Mutex and atomics, shared references, worker pools, pipelines, context, and that go plus a channel is await.   PRIZE: the SYNCED stamp."] = "LO QUE APRENDIÓ ALEX: Mutex y atómicos, referencias compartidas, pools de workers, tuberías, context, y que go más un channel es await.   PREMIO: el sello SYNCED.",
  ["WHAT ALEX LEARNED: O(1) to O(2^n), and how to read a loop.   PRIZE: the O(1) stamp."] = "LO QUE APRENDIÓ ALEX: de O(1) a O(2^n), y cómo leer un bucle.   PREMIO: el sello O(1).",
  ["WHAT ALEX LEARNED: O(1) to O(2^n), maps beat loops, sort then search.   PRIZE: the O(1) stamp."] = "LO QUE APRENDIÓ ALEX: de O(1) a O(2^n), los maps ganan a los bucles, ordenar y luego buscar.   PREMIO: el sello O(1).",
  ["WHAT ALEX LEARNED: Python basics, lists, dicts, classes.   PRIZE: the shutter comes down."] = "LO QUE APRENDIÓ ALEX: lo básico de Python, listas, dicts, clases.   PREMIO: baja la persiana.",
  ["WHAT ALEX LEARNED: Result, traits, lifetimes, threads, Arc<Mutex>.   PRIZE: milk tea and a pineapple bun."] = "LO QUE APRENDIÓ ALEX: Result, traits, lifetimes, hilos, Arc<Mutex>.   PREMIO: té con leche y un bollo de piña.",
  ["WHAT ALEX LEARNED: Rust basics, ownership.   PRIZE: the afternoon tea set."] = "LO QUE APRENDIÓ ALEX: bases de Rust, ownership.   PREMIO: la merienda.",
  ["WHAT ALEX LEARNED: String, errors, iterators, serde, async, cargo.   PRIZE: the service shipped."] = "LO QUE APRENDIÓ ALEX: String, errores, iteradores, serde, async, cargo.   PREMIO: el servicio está en producción.",
  ["WHAT ALEX LEARNED: exceptions, generators, decorators, with, asyncio, typing.   PRIZE: the midnight bowl."] = "LO QUE APRENDIÓ ALEX: excepciones, generadores, decoradores, with, asyncio, tipado.   PREMIO: el bol de medianoche.",
  ["WHAT ALEX LEARNED: goroutines, channels, sync.   PRIZE: the morning set."] = "LO QUE ALEX APRENDIÓ: goroutines, channels, sync.   PREMIO: el menú de desayuno.",
  ["WHAT ALEX LEARNED: recursion, trees, graphs, lists, sorting, hashing, workers.   PRIZE: HIRED."] = "LO QUE ALEX APRENDIÓ: recursión, árboles, grafos, listas, ordenación, hashing, workers.   PREMIO: CONTRATADO.",
  ["WHAT ALEX LEARNED: stacks, DP, sliding windows, heaps, intervals, LRU, grid DFS.   PRIZE: the OFFER."] = "LO QUE APRENDIÓ ALEX: pilas, DP, ventanas deslizantes, heaps, intervalos, LRU, DFS en cuadrícula.   PREMIO: la OFFER.",
  ["WHAT ALEX LEARNED: strings, errors, JSON, HTTP.   PRIZE: the app is live."] = "LO QUE ALEX APRENDIÓ: strings, errores, JSON, HTTP.   PREMIO: la app está en línea.",
  ["WHAT ALEX LEARNED: the module path is the import path, a folder is a package, go get and go.sum, internal and cmd, replace and go.work, semver tags and /v2, the proxy and GOPRIVATE.   PRIZE: the v1.0.0 tag."] = "LO QUE APRENDIÓ ALEX: la ruta del módulo es la ruta de importación, una carpeta es un paquete, go get y go.sum, internal y cmd, replace y go.work, etiquetas semver y /v2, el proxy y GOPRIVATE.   PREMIO: la etiqueta v1.0.0.",
  ["WHAT CHEF BO LEARNED: the GIL, Process and the main guard, Pool and chunksize, Queue and Pipe, locks and Value, shared_memory, ProcessPoolExecutor.   PRIZE: the SCALED stamp."] = "LO QUE APRENDIÓ EL CHEF BO: el GIL, Process y la guarda de main, Pool y chunksize, Queue y Pipe, bloqueos y Value, shared_memory, ProcessPoolExecutor.   PREMIO: el sello SCALED.",
  ["WHAT CHEF BO SHOWED: list stacks, DP, windows, heapq, intervals, OrderedDict LRU, grid DFS.   PRIZE: the OFFER."] = "LO QUE MOSTRÓ EL CHEF BO: pilas con listas, DP, ventanas, heapq, intervalos, LRU con OrderedDict, DFS en cuadrícula.   PREMIO: la OFFER.",
  ["WHAT CHEF BO SHOWED: recursion, trees, graphs, lists, sorting, hashing, workers, in Python.   PRIZE: HIRED."] = "LO QUE MOSTRÓ EL CHEF BO: recursión, árboles, grafos, listas, ordenación, hashing, workers, en Python.   PREMIO: CONTRATADO.",
  ["WHAT MEI SHOWED: O(1) to O(2^n), HashMap beats Vec::contains, sort then binary_search.   PRIZE: the O(1) stamp."] = "LO QUE MOSTRÓ MEI: de O(1) a O(2^n), HashMap gana a Vec::contains, ordenar y luego binary_search.   PREMIO: el sello O(1).",
  ["WHAT MEI SHOWED: Vec as a stack, DP tables, windows, BinaryHeap, intervals, an LRU, grid DFS.   PRIZE: the OFFER."] = "LO QUE MOSTRÓ MEI: Vec como pila, tablas DP, ventanas, BinaryHeap, intervalos, una LRU, DFS en cuadrícula.   PREMIO: la OFFER.",
  ["WHAT MEI SHOWED: recursion, trees, graphs, lists, sorting, hashing, workers, in Rust.   PRIZE: HIRED."] = "LO QUE MOSTRÓ MEI: recursión, árboles, grafos, listas, ordenación, hashing, workers, en Rust.   PREMIO: CONTRATADA.",
  ["WIND"] = "VENTANA",
  ["Wait for all three woks before printing the receipt. Which method blocks until a thread is done?"] = "Esperar a los tres woks antes de imprimir el recibo. ¿Qué método bloquea hasta que un hilo termina?",
  ["Wait for every cook to finish before closing the kitchen. Which JoinHandle method blocks until the thread ends?"] = "Espera a que cada cocinero termine antes de cerrar la cocina. ¿Qué método de JoinHandle bloquea hasta que el thread acaba?",
  ["Wait for the tea thread and take its result. Which method?"] = "Espera al thread del té y toma su resultado. ¿Qué método?",
  ["Wait on muffin or hash brown, whichever is ready. Which keyword?"] = "Espera al muffin o al hash brown, el que esté listo. ¿Qué palabra clave?",
  ["Wait one second without freezing the loop. Which asyncio function, never time.sleep?"] = "Esperar un segundo sin congelar el bucle. ¿Qué función de asyncio, nunca time.sleep?",
  ["Wait then close(results) in a goroutine: the receiver's range ends cleanly. No leaks."] = "Wait y luego close(results) en una goroutine: el range del receptor termina limpio. Sin fugas.",
  ["Wait until both cooks call Done. Fill: var wg sync.___"] = "Espera a que ambos cocineros llamen a Done. Completa: var wg sync.___",
  ["WaitGroup.Add(n), Done(), Wait(). The tray leaves when n hits zero."] = "WaitGroup.Add(n), Done(), Wait(). La bandeja sale cuando n llega a cero.",
  ["Waiting on the network or burning the CPU: which word changes for CPU work?"] = "Esperar a la red o quemar CPU: ¿qué palabra cambia para el trabajo de CPU?",
  ["Waiting overlaps under the GIL; computing does not. That one sentence chooses the executor every time."] = "La espera se solapa bajo el GIL; el cálculo no. Esa sola frase elige el executor cada vez.",
  ["Walk every cell. Each unsunk building starts a new island: sink it whole, then add one. Fill the operator."] = "Recorre cada celda. Cada edificio sin hundir inicia una isla nueva: húndela entera, luego suma uno. Completa el operador.",
  ["Walk every cell. Land that is still standing is a new island: count it and sink all of it. Which function does the sinking?"] = "Recorre cada celda. La tierra que sigue en pie es una isla nueva: cuéntala y húndela entera. ¿Qué función hace el hundimiento?",
  ["Walk every shop name in a slice. Fill: for _, name := ___ shops"] = "Recorre cada nombre de tienda en un slice. Completa: for _, name := ___ shops",
  ["Walk from the flat to Lucky Mac. Fix every Go bug on the way."] = "Camina del piso a Lucky Mac. Arregla cada bug de Go por el camino.",
  ["Walk names and quantities side by side. Which built-in pairs two lists?"] = "Recorrer nombres y cantidades lado a lado. ¿Qué función integrada empareja dos listas?",
  ["Walk over a Vec by reference, no index. Which method starts the iterator?"] = "Recorre un Vec por referencia, sin índice. ¿Qué método arranca el iterador?",
  ["Walk with Mei to Lucky Mac Express. Fix every Rust kiosk on the way."] = "Camina con Mei hasta Lucky Mac Express. Arregla cada kiosco de Rust por el camino.",
  ["Walking by reference: no clone, no take, nothing moves. node is &Box<ListNode>, auto-deref reaches next."] = "Recorrer por referencia: sin clone, sin take, nada se mueve. node es &Box<ListNode>, el auto-deref llega a next.",
  ["Warm the grill exactly once, however many cooks call it. Fill: var once sync.___"] = "Calienta la plancha exactamente una vez, por muchos cocineros que llamen. Completa: var once sync.___",
  ["Warm, fry and brew at once; stop all three on the first error. Which package?"] = "Calienta, fríe e infusiona a la vez; para los tres al primer error. ¿Qué paquete?",
  ["Was the key there? The second result is a bool named ___."] = "¿Estaba la clave? El segundo resultado es un bool llamado ___.",
  ["Water, or land already sunk, ends the flood. The grid holds bytes: which byte literal is land?"] = "Agua, o tierra ya hundida, termina la inundación. La cuadrícula guarda bytes: ¿qué literal de byte es tierra?",
  ["Ways to climb 0 steps and 1 step: one each. Fill the base cases."] = "Formas de subir 0 escalones y 1 escalón: una cada una. Completa los casos base.",
  ["We already checked mid, so skip past it. hi = mid keeps the half-open rule."] = "Ya comprobamos mid, así que sáltalo. hi = mid mantiene la regla semiabierta.",
  ["Welcome back, Alex. The callback is the whiteboard round. First: are these brackets balanced?"] = "Bienvenido de nuevo, Alex. El callback es la ronda de pizarra. Primero: ¿están equilibrados estos paréntesis?",
  ["Welcome to CODE RUSH! Round one: factorial, then fib without the exponential blowup. Buzzer's live!"] = "¡Bienvenido a CODE RUSH! Ronda uno: factorial, y luego fib sin la explosión exponencial. ¡El timbre está activo!",
  ["What a channel does. The -ing form of the verb in the first half of the line."] = "Lo que hace un channel. La forma en -ing del verbo de la primera mitad de la línea.",
  ["What goes between the parameter list and the return type u32?"] = "¿Qué va entre la lista de parámetros y el tipo de retorno u32?",
  ["What is __name__ equal to when the file is run directly, not imported?"] = "¿A qué equivale __name__ cuando el archivo se ejecuta directamente, no importado?",
  ["What is the lightweight thread go starts called?"] = "¿Cómo se llama el hilo ligero que go lanza?",
  ["What is the three-letter name of the lock that lets one thread run bytecode at a time?"] = "¿Cómo se llama, en tres letras, el bloqueo que deja ejecutar bytecode a un hilo a la vez?",
  ["What versions of everything is this build using? Fill the subcommand."] = "¿Qué versiones de todo usa esta compilación? Rellena el subcomando.",
  ["Whatever opened last must close first. That sentence is a stack."] = "Lo último que se abrió debe cerrarse primero. Esa frase es una pila.",
  ["When fast reaches the end, slow is halfway. One pass, no length count."] = "Cuando fast llega al final, slow está a mitad. Una pasada, sin contar la longitud.",
  ["When fast runs out, slow stands in the middle. O(n) time, O(1) space, and Option<&T> is Copy so the hops are free. Combo x4."] = "Cuando fast se acaba, slow queda en el medio. O(n) en tiempo, O(1) en espacio, y Option<&T> es Copy así que los saltos son gratis. Combo x4.",
  ["When you edit a library and its caller at the same time, replace points a module path at a folder on disk, and go.work does it for a whole workspace without touching any go.mod. cannot find module means the import path and go.mod disagree; go mod tidy repairs go.mod from the imports. go mod vendor copies every dependency into the repo for builds with no network."] = "Cuando editas una biblioteca y quien la llama a la vez, replace apunta una ruta de módulo a una carpeta del disco, y go.work lo hace para todo un espacio de trabajo sin tocar ningún go.mod. cannot find module significa que la ruta de importación y go.mod no coinciden; go mod tidy repara go.mod a partir de los imports. go mod vendor copia todas las dependencias al repo para compilar sin red.",
  ["Where did the download actually land? Fill the last directory of the cache."] = "¿Dónde aterrizó la descarga en realidad? Rellena el último directorio de la caché.",
  ["Where do cur and best start? Not at 0: a list of only losses still has a best hour."] = "¿Dónde empiezan cur y best? No en 0: una lista de puras pérdidas sigue teniendo una mejor hora.",
  ["Where does a context go? Name the first parameter every Go API uses."] = "¿Dónde va un context? Nombra el primer parámetro que usa toda API de Go.",
  ["Where does go get look first, and what does it fall back to? Fill the fallback."] = "¿Dónde mira primero go get, y a qué recurre después? Rellena la alternativa.",
  ["Where is await?"] = "¿Dónde está await?",
  ["Which Cargo.toml section lists the crates the project uses?"] = "¿Qué sección de Cargo.toml enumera los crates que usa el proyecto?",
  ["Which Go type finds a price by name in O(1), on average?"] = "¿Qué tipo de Go encuentra un precio por nombre en O(1), en promedio?",
  ["Which built-in reads a line typed at the terminal?"] = "¿Qué función integrada lee una línea escrita en la terminal?",
  ["Which built-in tells you what kind of value price is?"] = "¿Qué función integrada te dice qué clase de valor es price?",
  ["Which built-in type finds a price by name in O(1), on average?"] = "¿Qué tipo integrado encuentra un precio por nombre en O(1), en promedio?",
  ["Which built-in writes a line to the terminal?"] = "¿Qué función integrada escribe una línea en la terminal?",
  ["Which directory name makes a package importable only from inside this module?"] = "¿Qué nombre de directorio hace que un paquete solo se pueda importar desde dentro de este módulo?",
  ["Which go.mod is in charge here? Ask the tool for the file it found."] = "¿Qué go.mod manda aquí? Pregúntale a la herramienta qué fichero encontró.",
  ["Which keyword before def makes fetch a coroutine?"] = "¿Qué palabra clave antes de def convierte fetch en una corrutina?",
  ["Which keyword binds a name to a value in Rust?"] = "¿Qué palabra clave vincula un nombre a un valor en Rust?",
  ["Which keyword brings HashMap from the standard library into this file?"] = "¿Qué palabra clave trae HashMap de la biblioteca estándar a este archivo?",
  ["Which keyword brings the time module in?"] = "¿Qué palabra clave trae el módulo time?",
  ["Which keyword declares a function in Rust?"] = "¿Qué palabra clave declara una función en Rust?",
  ["Which keyword declares a set of methods that types can promise?"] = "¿Qué palabra clave declara un conjunto de métodos que los tipos pueden prometer?",
  ["Which keyword defines a new type?"] = "¿Qué palabra clave define un tipo nuevo?",
  ["Which keyword opens the block whose errors you want to catch?"] = "¿Qué palabra clave abre el bloque cuyos errores quieres capturar?",
  ["Which keyword starts a function definition?"] = "¿Qué palabra clave inicia la definición de una función?",
  ["Which letter before the quote lets {n} be replaced by the value of n?"] = "¿Qué letra delante de la comilla hace que {n} se sustituya por el valor de n?",
  ["Which method returns 9 for the three characters of 銅鑼灣?"] = "¿Qué método devuelve 9 para los tres caracteres de 銅鑼灣?",
  ["Which operator raises 2 to the tenth power?"] = "¿Qué operador eleva 2 a la décima potencia?",
  ["Which placeholder inside the string prints the value of n?"] = "¿Qué marcador dentro del string imprime el valor de n?",
  ["Which special method runs when Order('noodles') is created?"] = "¿Qué método especial corre cuando se crea Order('noodles')?",
  ["Which standard library module gives real parallelism for CPU work?"] = "¿Qué módulo de la biblioteca estándar da paralelismo real para trabajo de CPU?",
  ["Which standard package prints to the terminal?"] = "¿Qué paquete estándar imprime en la terminal?",
  ["Which std collection finds a price by name in O(1), on average?"] = "¿Qué colección de std encuentra un precio por nombre en O(1), en promedio?",
  ["Which std trait, with an empty body, makes OrderError a real error?"] = "¿Qué trait de std, con cuerpo vacío, convierte OrderError en un error de verdad?",
  ["Why do four threads not make four times the arithmetic? Name the lock, three letters."] = "¿Por qué cuatro hilos no hacen cuatro veces la aritmética? Nombra el cerrojo, tres letras.",
  ["Why does a second process escape the lock? Each one has its own ___."] = "¿Por qué un segundo proceso escapa del bloqueo? Cada uno tiene su propio ___.",
  ["Why threads do not go faster"] = "Por qué los hilos no van más rápido",
  ["With a JoinableQueue the parent waits for the work, not the workers. Which call acknowledges one item?"] = "Con una JoinableQueue el padre espera al trabajo, no a los workers. ¿Qué llamada confirma un elemento?",
  ["With a cache every fib(k) is computed once. The cost drops to O(___)"] = "Con una cache cada fib(k) se calcula una vez. El coste baja a O(___)",
  ["With a memo every fib(k) is computed once. The cost drops to O(___)"] = "Con un memo cada fib(k) se calcula una vez. El coste baja a O(___)",
  ["With a vendor directory present, go build uses it and never touches the network or the cache. It is the whole dependency set, checked in, reviewable in a diff."] = "Con un directorio vendor presente, go build lo usa y no toca la red ni la caché. Es el conjunto completo de dependencias, subido al repo, revisable en un diff.",
  ["With cap 1 the sender finishes even if the context won the select. With an unbuffered channel that goroutine would block for ever: a leak."] = "Con capacidad 1 el emisor termina aunque el context gane el select. Con un channel sin buffer esa goroutine se bloquearía para siempre: una fuga.",
  ["With, then a duration word. The twin that takes a time.Time is WithDeadline."] = "With y luego una palabra de duración. El gemelo que toma un time.Time es WithDeadline.",
  ["With, then the verb for stopping. Its siblings are WithTimeout and WithDeadline."] = "With y luego el verbo de detener. Sus hermanos son WithTimeout y WithDeadline.",
  ["With, then the word for a time limit. WithDeadline takes a clock time instead."] = "With, luego la palabra para un límite de tiempo. WithDeadline recibe en cambio una hora de reloj.",
  ["With, then the word for what is stored. The key is a private type so nobody can collide with it."] = "With y luego la palabra para lo que se guarda. La clave es un tipo privado para que nadie choque con ella.",
  ["WithTimeout returns a child that cancels itself. Always defer cancel() or you leak."] = "WithTimeout devuelve un hijo que se cancela solo. Siempre defer cancel() o habrá fugas.",
  ["WithValue is for request-scoped data that crosses API boundaries: a trace id, not the parameters of your function."] = "WithValue es para datos del ámbito de la petición que cruzan fronteras de API: un id de traza, no los parámetros de tu función.",
  ["Without a with block, what must always follow acquire()?"] = "Sin un bloque with, ¿qué tiene que seguir siempre a acquire()?",
  ["Without the guard, spawn re-imports the file, the import starts another Process, and that is the fork bomb you just wrote by accident."] = "Sin la guarda, spawn reimporta el fichero, la importación arranca otro Process y esa es la bomba fork que acabas de escribir sin querer.",
  ["Without with, which method must you remember to call on the file?"] = "Sin with, ¿qué método debes recordar llamar sobre el archivo?",
  ["Word count. New word: start at 0. Seen word: bump it. One entry call does both. Fill: entry(w).___(0)"] = "Conteo de palabras. Palabra nueva: empieza en 0. Palabra vista: súbela. Una llamada a entry hace las dos. Completa: entry(w).___(0)",
  ["Worker pool and pipeline"] = "Worker pool y pipeline",
  ["Worker pool with threads"] = "Worker pool con threads",
  ["Worker pool: N goroutines range over a jobs channel; close(jobs) ends them; WaitGroup then close(results)."] = "Worker pool: N goroutines hacen range sobre un channel jobs; close(jobs) las termina; WaitGroup y luego close(results).",
  ["Worker pool: an mpsc channel of jobs, the Receiver in Arc<Mutex<>>, N thread::spawn workers looping on recv. drop(tx) ends them, join waits."] = "Worker pool: un channel mpsc de trabajos, el Receiver en Arc<Mutex<>>, N workers thread::spawn en bucle sobre recv. drop(tx) los termina, join espera.",
  ["Worker pools and how many to start"] = "Pools de workers y cuántos arrancar",
  ["Workers are identical goroutines sharing one input channel. The channel is the queue."] = "Los workers son goroutines idénticas que comparten un channel de entrada. El channel es la cola.",
  ["Works on slices, strings, maps, channels. cap is the capacity."] = "Funciona con slices, strings, maps, channels. cap es la capacidad.",
  ["Wrap the bytes as an array without copying them. Which attribute is the memoryview?"] = "Envuelve los bytes como un array sin copiarlos. ¿Qué atributo es el memoryview?",
  ["Write the reply into w, not the terminal. Which fmt function?"] = "Escribe la respuesta en w, no en la terminal. ¿Qué función de fmt?",
  ["You can clone it. The proxy cannot. Tell the tool which paths to fetch itself."] = "Tú puedes clonarlo. El proxy no. Dile a la herramienta qué rutas debe traer por sí misma.",
  ["You did tokio this afternoon. asyncio is the same shape: one loop, many awaits."] = "Hiciste tokio esta tarde. asyncio tiene la misma forma: un bucle, muchos await.",
  ["You fixed Price in luckymac, but the cousin's shop still builds against v1.2.0 from the cache. Of course it does."] = "Arreglaste Price en luckymac, pero la tienda del primo sigue compilando contra la v1.2.0 de la caché. Claro que sí.",
  ["You got HIRED at seven. This is the OFFER round. A stack, Mei, it's always a stack."] = "A las siete saliste CONTRATADA. Esta es la ronda del OFFER. Una pila, Mei, siempre es una pila.",
  ["You imported rider and then deleted the call. Finish the error."] = "Importaste rider y luego borraste la llamada. Termina el error.",
  ["You made a menu folder and wrote package pricing inside it. Go accepts it. Every reader will hate it."] = "Hiciste una carpeta menu y escribiste package pricing dentro. Go lo acepta. Todo el que lo lea lo odiará.",
  ["You only need a bool: is the order in one of two states? Which macro?"] = "Solo necesitas un bool: ¿está el pedido en uno de dos estados? ¿Qué macro?",
  ["You reach step i from one below or two below. Fill the second term: dp[i - 1] + dp[___]"] = "Llegas al escalón i desde uno más abajo o desde dos más abajo. Completa el segundo término: dp[i - 1] + dp[___]",
  ["You reach step i from one step below or two steps below. Fill the second index."] = "Llegas al escalón i desde un escalón más abajo o desde dos más abajo. Rellena el segundo índice.",
  ["You still want the position of every dish on the ticket. Which adapter adds it?"] = "Aún quieres la posición de cada plato en el ticket. ¿Qué adaptador la añade?",
  ["Your workers each pickled two gigabytes of the same table. That is the whole runtime, right there."] = "Cada uno de tus workers serializó dos gigabytes de la misma tabla. Ahí está todo el tiempo de ejecución.",
  ["[0i32; 26] lives on the stack: no HashMap, no allocation. Add for a, subtract for b, all zero means anagram."] = "[0i32; 26] vive en la pila: sin HashMap, sin reservar memoria. Suma para a, resta para b, todo a cero significa anagrama.",
  ["[1,6] absorbs [2,4]: without the larger-end rule you would shrink it to [1,4]. last is a slice, so out sees the change."] = "[1,6] absorbe [2,4]: sin la regla del fin mayor lo encogerías a [1,4]. last es un slice, así que out ve el cambio.",
  ["[3]string is an array: a value, fixed length, copied on assignment. []string is a slice."] = "[3]string es un array: un valor, longitud fija, se copia al asignar. []string es un slice.",
  ["[T any] is the widest constraint. comparable is for map keys."] = "[T any] es la restricción más amplia. comparable es para claves de map.",
  ["[[9, 11], [10, 12], [13, 15]] becomes [[9, 12], [13, 15]]. Sort plus one pass: O(n log n)."] = "[[9, 11], [10, 12], [13, 15]] se convierte en [[9, 12], [13, 15]]. Sort más una pasada: O(n log n).",
  ["[]int is a slice. [3]int is an array of three. Slices are what you use."] = "[]int es un slice. [3]int es un array de tres. Los slices son lo que usas.",
  ["[]rune(s) once, then index freely. Interviewers check this in Go."] = "[]rune(s) una vez, y luego indexa libremente. Los entrevistadores comprueban esto en Go.",
  ["[dependencies] asks for versions; Cargo.lock records the exact ones. Commit the lock for binaries."] = "[dependencies] pide versiones; Cargo.lock registra las exactas. Haz commit del lock en los binarios.",
  ["[expr for x in xs if cond] is a list comprehension. Rust's iter().map().collect(), in one readable line."] = "[expr for x in xs if cond] es una comprensión de lista. El iter().map().collect() de Rust, en una línea legible.",
  ["[i32; 3] lives on the stack and never grows. Vec is for lists that change size."] = "[i32; 3] vive en el stack y nunca crece. Vec es para listas que cambian de tamaño.",
  ['[package]\nname = "delivery"\nedition = "2021"\n\n[___]\nserde = { version = "1", features = ["derive"] }\ntokio = { version = "1", features = ["full"] }\n'] = '[package]\nname = "delivery"\nedition = "2021"\n\n[___]\nserde = { version = "1", features = ["derive"] }\ntokio = { version = "1", features = ["full"] }\n',
  ["_ matches anything and binds nothing. Without it the match is not exhaustive and will not compile. The gate shows set."] = "_ coincide con todo y no vincula nada. Sin él, el match no es exhaustivo y no compila. La puerta muestra el menú.",
  ["_ means I know this exists and I am ignoring it on purpose."] = "_ significa: sé que esto existe y lo ignoro a propósito.",
  ['___ OPEN: u8 = 7;        // hour the Express opens\n\nfn main() {\n    println!("opens at {}", OPEN);\n}\n'] = '___ OPEN: u8 = 7;        // hora a la que abre el Express\n\nfn main() {\n    println!("opens at {}", OPEN);\n}\n',
  ['___ Order {\n    item: String,\n    qty: u32,\n}\nlet o = Order { item: "muffin".to_string(), qty: 2 };\n'] = '___ Order {\n    item: String,\n    qty: u32,\n}\nlet o = Order { item: "muffin".to_string(), qty: 2 };\n',
  ["___ Order:\n    pass\n\no = Order()\n"] = "___ Order:\n    pass\n\no = Order()\n",
  ["___ Size { Small, Large }\n\nlet size = Size::Large;\nlet extra = match size {\n    Size::Small => 0,\n    Size::Large => 5,       // every variant handled\n};\n"] = "___ Size { Small, Large }\n\nlet size = Size::Large;\nlet extra = match size {\n    Size::Small => 0,\n    Size::Large => 5,       // todas las variantes cubiertas\n};\n",
  ['___ fry("hashbrown")\n___ toast("muffin")\n'] = '___ fry("hashbrown")\n___ toast("muffin")\n',
  ['___ fry(item):\n    print("frying", item)\n\nfry("egg")\n'] = '___ fry(item):\n    print("frying", item)\n\nfry("egg")\n',
  ['___ greet() {\n    println!("welcome to Lucky Mac Express");\n}\n// no arrow: this one returns the unit type ()\n'] = '___ greet() {\n    println!("welcome to Lucky Mac Express");\n}\n// sin flecha: esta devuelve el tipo unidad ()\n',
  ["___ luckymac/delivery\n\ngo 1.22\n\nrequire github.com/lib/pq v1.10.9\n"] = "___ luckymac/delivery\n\ngo 1.22\n\nrequire github.com/lib/pq v1.10.9\n",
  ['___ night shift starts at 21:00\nprint("open")\n'] = '___ el turno de noche empieza a las 21:00\nprint("open")\n',
  ['___ open("stock.csv") as f:\n    for line in f:\n        count(line)\n# f is closed here\n'] = '___ open("stock.csv") as f:\n    for line in f:\n        count(line)\n# aquí f está cerrado\n',
  ['___ queue:\n    person = queue.pop(0)\n    print("bowl for", person)\n'] = '___ queue:\n    person = queue.pop(0)\n    print("bowl for", person)\n',
  ['___ std::collections::HashMap;\n\nfn main() {\n    let mut stock = HashMap::new();\n    stock.insert("muffin", 4);\n}\n'] = '___ std::collections::HashMap;\n\nfn main() {\n    let mut stock = HashMap::new();\n    stock.insert("muffin", 4);\n}\n',
  ["___ tap(card string) bool {\n    return true\n}\n"] = "___ tap(card string) bool {\n    return true\n}\n",
  ['___ time\ntime.sleep(1)     # let the wok heat\nprint("ready")\n'] = '___ time\ntime.sleep(1)     # deja que el wok se caliente\nprint("ready")\n',
  ["___ {\ncase m := <-muffin:\n    serve(m)\ncase h := <-hash:\n    serve(h)\n}\n"] = "___ {\ncase m := <-muffin:\n    serve(m)\ncase h := <-hash:\n    serve(h)\n}\n",
  ['___("Lucky Mac night shift")\n'] = '___("Lucky Mac night shift")\n',
  ["___(ch)\nx, ok := <-ch          // ok is false after\n"] = "___(ch)\nx, ok := <-ch          // ok es false después\n",
  ["___(floors)                  // len(floors) == 0 after\n"] = "___(floors)                  // len(floors) == 0 después\n",
  ['___(prices, "closed")\n'] = '___(prices, "closed")\n',
  ['___, err := tap("octopus")\n'] = '___, err := tap("octopus")\n',
  ["___:\n    qty = int(raw)\nexcept ValueError:\n    qty = 0\n"] = "___:\n    qty = int(raw)\nexcept ValueError:\n    qty = 0\n",
  ['___timer\ndef fry(item):\n    return f"fried {item}"\n'] = '___timer\ndef fry(item):\n    return f"fried {item}"\n',
  ["__enter__ runs at the with line. Return self or the resource. Rust would use Drop for the other half."] = "__enter__ corre en la línea del with. Devuelve self o el recurso. Rust usaría Drop para la otra mitad.",
  ["__exit__(self, exc_type, exc, tb) always runs. Return True to swallow the exception; return None to let it propagate."] = "__exit__(self, exc_type, exc, tb) siempre corre. Devuelve True para tragarte la excepción; None para dejarla propagarse.",
  ["__init__ is the constructor body; self.item = item makes an attribute. __new__ exists too, rarely needed."] = "__init__ es el cuerpo del constructor; self.item = item crea un atributo. __new__ también existe, raramente necesario.",
  ["__str__ is what print and str() use; __repr__ is the unambiguous form, used when __str__ is missing. Go's String()."] = "__str__ es lo que usan print y str(); __repr__ es la forma sin ambigüedad, usada cuando falta __str__. El String() de Go.",
  ["a + b with no semicolon is the value of the block. Go coders write return; Rust coders usually do not."] = "a + b sin punto y coma es el valor del bloque. En Go se escribe return; en Rust normalmente no.",
  ["a := []int{1, 2, 3}\nb := a[:2]\nb[0] = 9\nfmt.Println(a[0])       // prints ___\n"] = "a := []int{1, 2, 3}\nb := a[:2]\nb[0] = 9\nfmt.Println(a[0])       // imprime ___\n",
  ["a if cond else b reads left to right like English. The shutter sign flips to 'closed' at the last bowl."] = "a if cond else b se lee de izquierda a derecha como el inglés. El letrero de la persiana pasa a 'closed' con el último bol.",
  ["a lesson you can carry in a photo album"] = "una lección que llevas en el álbum de fotos",
  ["a to z. The array length is part of the type, so it must be a constant."] = "De la a a la z. La longitud del array es parte del tipo, así que debe ser una constante.",
  ["a.clone() allocates a second buffer. Cheap types derive Copy instead and never need it."] = "a.clone() reserva un segundo buffer. Los tipos baratos derivan Copy y nunca lo necesitan.",
  ["a.clone(). Allocation is where space complexity is paid; drop frees it at the end of scope, no collector needed."] = "a.clone(). La reserva es donde se paga la complejidad espacial; drop la libera al final del ámbito, sin recolector.",
  ["a.sort()                              # once: n log n\nfor x in queries:\n    i = bisect.bisect_left(a, x)      # each: O(___)\n"] = "a.sort()                              # una vez: n log n\nfor x in queries:\n    i = bisect.bisect_left(a, x)      # cada una: O(___)\n",
  ["a.sort()    # in place: O(___) extra space (Timsort's small buffer aside)\n"] = "a.sort()    # en el sitio: O(___) de espacio extra (aparte del pequeño búfer de Timsort)\n",
  ["a.sort() sorts the list where it is. Extra memory, in Big O: O(___)"] = "a.sort() ordena la lista donde está. Memoria extra, en Big O: O(___)",
  ["a.sort();                                  // once: n log n\nfor x in &queries {\n    let hit = a.binary_search(x).is_ok();  // each: O(___)\n}\n"] = "a.sort();                                  // una vez: n log n\nfor x in &queries {\n    let hit = a.binary_search(x).is_ok();  // cada una: O(___)\n}\n",
  ["a.sort_unstable();    // in place: O(___) extra space\n"] = "a.sort_unstable();    // en el sitio: O(___) de espacio extra\n",
  ["a[-1] is the last item, a[-2] the one before. Bo's off-by-one is gone."] = "a[-1] es el último elemento, a[-2] el anterior. El desplazamiento de Bo desapareció.",
  ["a[1:3] copies items 1 and 2 into a new list. a[:2], a[2:], a[::2] and a[::-1] (reversed) all work."] = "a[1:3] copia los elementos 1 y 2 en una lista nueva. a[:2], a[2:], a[::2] y a[::-1] (invertida) funcionan todos.",
  ["a[mid] is too small: the answer is to the right. Fill: lo = ___ + 1"] = "a[mid] es demasiado pequeño: la respuesta está a la derecha. Completa: lo = ___ + 1",
  ["add changes qty. Which receiver borrows the order with write access?"] = "add cambia qty. ¿Qué receptor presta el pedido con acceso de escritura?",
  ["amounts.___();     // pdqsort, no scratch buffer, O(n log n)\n"] = "amounts.___();     // pdqsort, sin búfer de trabajo, O(n log n)\n",
  ["amounts.sort();    // ___ : stable merge sort\n"] = "amounts.sort();    // ___ : ordenación por mezcla estable\n",
  ["append is amortized O(1). Python has no stack class; a list is the stack."] = "append es O(1) amortizado. Python no tiene clase stack; una lista es la pila.",
  ["apply_async returned a handle. Which method waits for the value?"] = "apply_async devolvió un manejador. ¿Qué método espera el valor?",
  ["arr writes straight into the shared block, so every process sees the change with no send at all. This is how big NumPy jobs go parallel."] = "arr escribe directamente en el bloque compartido, así que todos los procesos ven el cambio sin enviar nada. Así se paralelizan los trabajos grandes con NumPy.",
  ["arrows walk   ESC map"] = "flechas andar   ESC mapa",
  ["as f binds what __enter__ returned. with a() as x, b() as y: manages two at once."] = "as f enlaza lo que devolvió __enter__. with a() as x, b() as y: gestiona dos a la vez.",
  ["as usize widens the u8 for free. A u8 index would not compile: Rust never converts integers silently."] = "as usize amplía el u8 gratis. Un índice u8 no compilaría: Rust nunca convierte enteros en silencio.",
  ["as_ followed by the short word for reference. Its cousin as_deref goes one step further, to Option<&Node>."] = "as_ seguido de la palabra corta en inglés para referencia. Su primo as_deref va un paso más allá, hasta Option<&Node>.",
  ["as_completed is Go's select over many channels: whoever finishes first is served first, and a slow chunk never holds up the log."] = "as_completed es el select de Go sobre muchos channels: se atiende primero a quien termina antes, y un trozo lento nunca retiene el log.",
  ["as_ref would give Option<&Box<T>>. This one also derefs the Box. as_ plus deref."] = "as_ref daría Option<&Box<T>>. Este además hace deref del Box. as_ más deref.",
  ["async and tokio"] = "async y tokio",
  ["async def fetch(rider):\n    await asyncio.___(1)     # the radio takes a second\n    return rider\n"] = "async def fetch(rider):\n    await asyncio.___(1)     # la radio tarda un segundo\n    return rider\n",
  ['async def main():\n    riders = ["Ken", "Mei", "Bo"]\n    where = await asyncio.___(*(fetch(r) for r in riders))\n    print(where)     # one second total, not three\n'] = 'async def main():\n    riders = ["Ken", "Mei", "Bo"]\n    where = await asyncio.___(*(fetch(r) for r in riders))\n    print(where)     # un segundo en total, no tres\n',
  ['async def main():\n    t = asyncio.___(fetch("Ken"))\n    print("radio sent")\n    print(await t)\n'] = 'async def main():\n    t = asyncio.___(fetch("Ken"))\n    print("radio sent")\n    print(await t)\n',
  ['async def main():\n    where = ___ fetch("Ken")\n    print(where)\n'] = 'async def main():\n    where = ___ fetch("Ken")\n    print(where)\n',
  ["async def makes a coroutine; await pauses it until the result is in. asyncio.run starts the loop, gather runs several at once, sleep waits without blocking, create_task fires and forgets."] = "async def crea una corrutina; await la pausa hasta que llega el resultado. asyncio.run arranca el bucle, gather ejecuta varias a la vez, sleep espera sin bloquear, create_task lanza y olvida.",
  ["async def returns a coroutine object when called; nothing runs until it is awaited or scheduled."] = "async def devuelve un objeto corrutina al llamarse; nada corre hasta que se le hace await o se programa.",
  ["async fn eta(url: &str) -> Result<String, Box<dyn Error>> {\n    // GET, wait for headers, then wait for the body\n    let body = ___::get(url).await?.text().await?;\n    Ok(body)\n}\n"] = "async fn eta(url: &str) -> Result<String, Box<dyn Error>> {\n    // GET, espera las cabeceras, luego espera el cuerpo\n    let body = ___::get(url).await?.text().await?;\n    Ok(body)\n}\n",
  ["async fn fetch_eta(..) -> u32 really returns impl Future<Output = u32>. Nothing runs until polled."] = "async fn fetch_eta(..) -> u32 en realidad devuelve impl Future<Output = u32>. Nada corre hasta que se hace poll.",
  ['async fn plan() {\n    // suspends here; other tasks run while we wait\n    let eta = fetch_eta(7)___;\n    println!("rider back in {eta} min");\n}\n'] = 'async fn plan() {\n    // se suspende aquí; otras tareas corren mientras esperamos\n    let eta = fetch_eta(7)___;\n    println!("rider back in {eta} min");\n}\n',
  ["async fn returns a Future; .await drives it. tokio runs them; spawn and join! run them at once."] = "async fn devuelve un Future; .await lo impulsa. tokio los ejecuta; spawn y join! los corren a la vez.",
  ["asyncio"] = "asyncio",
  ["asyncio handles the waiting, processes handle the computing, and await joins them. Go does the same thing with one goroutine and no ceremony."] = "asyncio se encarga de esperar, los procesos de calcular, y await une las dos cosas. Go hace lo mismo con una goroutine y sin ceremonias.",
  ["asyncio.run(main()) creates the loop, runs the coroutine, closes the loop. Rust's #[tokio::main]."] = "asyncio.run(main()) crea el bucle, ejecuta la corrutina y cierra el bucle. El #[tokio::main] de Rust.",
  ["atomic.Int64 keeps its own value, so nobody can read it the unsafe way. The old atomic.AddInt64(&n, 1) still works, but the type is safer."] = "atomic.Int64 guarda su propio valor, así que nadie puede leerlo de forma insegura. El viejo atomic.AddInt64(&n, 1) sigue funcionando, pero el tipo es más seguro.",
  ["atomic.Pointer[Menu] gives copy-on-write config: build a new menu, Store it, and every reader after that sees the new one whole."] = "atomic.Pointer[Menu] te da configuración copy-on-write: construyes un menú nuevo, lo haces Store y cada lector posterior ve el nuevo entero.",
  ["await asyncio.sleep(1) yields to the loop; time.sleep(1) would freeze every task. Same trap as in tokio."] = "await asyncio.sleep(1) cede al bucle; time.sleep(1) congelaría todas las tareas. La misma trampa que en tokio.",
  ["await hands control to the event loop until the coroutine finishes. Only allowed inside async def."] = "await cede el control al bucle de eventos hasta que la corrutina termina. Solo permitido dentro de async def.",
  ["b := make([]int, ___(a))    // allocate n ints\ncopy(b, a)                  // O(n) time, O(n) space\n"] = "b := make([]int, ___(a))    // reservar n ints\ncopy(b, a)                  // O(n) de tiempo, O(n) de espacio\n",
  ["b := slices.Clone(a)    // a second slice of n ints: O(___)\nsort.Ints(b)\n"] = "b := slices.Clone(a)    // un segundo slice de n ints: O(___)\nsort.Ints(b)\n",
  ["b = ___(a)    # allocate n slots and copy: O(n) time, O(n) space\n"] = "b = ___(a)    # reservar n ranuras y copiar: O(n) de tiempo, O(n) de espacio\n",
  ["b = sorted(a)    # a second list of n items: O(___)\n"] = "b = sorted(a)    # una segunda lista de n elementos: O(___)\n",
  ["b shares a's array. After b[0] = 9, what does a[0] print?"] = "b comparte el array de a. Tras b[0] = 9, ¿qué imprime a[0]?",
  ["b'1' is 49u8, the ASCII byte. Vec<Vec<u8>> is what you get from lines of a text map via as_bytes()."] = "b'1' es 49u8, el byte ASCII. Vec<Vec<u8>> es lo que sale de las líneas de un mapa de texto con as_bytes().",
  ['b, err := json.___(order)   // []byte\nfmt.Println(string(b))      // {"dish":"set"}\n'] = 'b, err := json.___(order)   // []byte\nfmt.Println(string(b))      // {"dish":"set"}\n',
  ["binary, underscore, search. Takes a reference to the wanted value. Err carries the insertion point."] = "binary, guion bajo, search. Toma una referencia al valor buscado. Err lleva el punto de inserción.",
  ["binary_search has one precondition. The slice must be ___"] = "binary_search tiene una condición previa. El slice debe estar ___",
  ["bisect has one precondition. The list must be ___"] = "bisect tiene una condición previa. La lista debe estar ___",
  ["bisect_left returns the first index >= x; bisect_right the one after equals. insort inserts. Round five to Bo."] = "bisect_left devuelve el primer índice >= x; bisect_right el siguiente a los iguales. insort inserta. Quinta ronda para Bo.",
  ["break ends the loop; continue skips to the next item. A for loop may have an else: that runs only if no break happened."] = "break termina el bucle; continue salta al siguiente elemento. Un bucle for puede tener else: corre solo si no hubo break.",
  ["break leaves the innermost for, switch or select. A label breaks an outer one."] = "break sale del for, switch o select más interno. Una etiqueta rompe uno exterior.",
  ["brew takes a whole number of cups and returns text. Annotate the parameter."] = "brew recibe un número entero de tazas y devuelve texto. Anota el parámetro.",
  ["c - b'a' is a u8 from 0 to 25. Arrays are indexed by exactly one integer type. Cast to which?"] = "c - b'a' es un u8 de 0 a 25. Los arrays se indexan con exactamente un tipo entero. ¿A cuál conviertes?",
  ["cannot find module providing package. Which subcommand rebuilds go.mod from the imports?"] = "cannot find module providing package. ¿Qué subcomando reconstruye go.mod a partir de los imports?",
  ["cap is the room in the backing array. append doubles it when len reaches cap."] = "cap es el espacio del array subyacente. append lo duplica cuando len llega a cap.",
  ["cargo add serde --features derive writes the line for you and picks the newest version."] = "cargo add serde --features derive escribe la línea por ti y elige la versión más nueva.",
  ["cargo clippy is the linter; -- -D warnings makes CI fail on any lint. The crab approves."] = "cargo clippy es el linter; -- -D warnings hace fallar la CI con cualquier lint. El cangrejo aprueba.",
  ["cargo fmt rewrites in place; --check only reports. Build green, lint clean. Ticket six closed."] = "cargo fmt reescribe en el sitio; --check solo informa. Build en verde, lint limpio. Ticket seis cerrado.",
  ["cargo new makes Cargo.toml, src/main.rs and a git repo. cargo init does it in an existing folder."] = "cargo new crea Cargo.toml, src/main.rs y un repo git. cargo init lo hace en una carpeta existente.",
  ["cargo new, add, build --release, test, clippy, fmt. Cargo.toml asks, Cargo.lock pins."] = "cargo new, add, build --release, test, clippy, fmt. Cargo.toml pide, Cargo.lock fija.",
  ["cargo run. cargo new makes a project, cargo build compiles, cargo test runs tests. The kiosk boots."] = "cargo run. cargo new crea un proyecto, cargo build compila, cargo test corre los tests. El kiosco arranca.",
  ["cargo test builds a test binary and runs #[test] fns in parallel. cargo test name filters."] = "cargo test construye un binario de pruebas y ejecuta las fn #[test] en paralelo. cargo test nombre filtra.",
