  ["ch := make(chan Order, 8)\nch <- Order{id: 1}\nfmt.Println(len(ch), ___(ch))\n// 1 8\n"] = "ch := make(chan Order, 8)\nch <- Order{id: 1}\nfmt.Println(len(ch), ___(ch))\n// 1 8\n",
  ["ch := make(chan int)\nch <- 1                // nobody receives\nfmt.Println(<-ch)\n// fatal error: all goroutines are asleep - ___!\n"] = "ch := make(chan int)\nch <- 1                // nadie recibe\nfmt.Println(<-ch)\n// fatal error: all goroutines are asleep - ___!\n",
  ['ch := make(chan string)\nch ___ "muffin"        // send\n'] = 'ch := make(chan string)\nch ___ "muffin"        // envía\n',
  ['ch := make(chan string, ___)   // buffered\nch <- "muffin"                 // does not block yet\n'] = 'ch := make(chan string, ___)   // con búfer\nch <- "muffin"                 // aún no bloquea\n',
  ["ch <- x sends. x := <-ch receives. Same operator, different place."] = "ch <- x envía. x := <-ch recibe. Mismo operador, distinto lugar.",
  ["chan is a typed pipe. <- sends and receives. close tells receivers to stop."] = "chan es una tubería tipada. <- envía y recibe. close avisa a los receptores de que paren.",
  ["chan struct{} plus close is the cheapest done signal. context.Done() returns one."] = "chan struct{} más close es la señal de fin más barata. context.Done() devuelve una.",
  ["chars().count() walks the string and counts. The receipt prints 銅鑼灣 in full."] = "chars().count() recorre la cadena y cuenta. El recibo imprime 銅鑼灣 completo.",
  ["cheapest := ___(muffin, hash, coffee)   // built-in\n"] = "cheapest := ___(muffin, hash, coffee)   // integrada\n",
  ["class ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = ___\n"] = "class ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = ___\n",
  ["class MinStack:\n    def __init__(self):\n        self.st, self.lows = [], []\n    def push(self, x):\n        self.st.append(x)\n        m = self.lows[-1] if self.lows else x\n        self.lows.append(___(x, m))\n"] = "class MinStack:\n    def __init__(self):\n        self.st, self.lows = [], []\n    def push(self, x):\n        self.st.append(x)\n        m = self.lows[-1] if self.lows else x\n        self.lows.append(___(x, m))\n",
  ["class Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = ___\n        self.right = ___\n"] = "class Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = ___\n        self.right = ___\n",
  ["class Order:\n    @___\n    def from_line(cls, line):\n        qty, _, item = line.split()\n        return cls(item, int(qty))\n"] = "class Order:\n    @___\n    def from_line(cls, line):\n        qty, _, item = line.split()\n        return cls(item, int(qty))\n",
  ['class Order:\n    def ___(self, item):\n        self.item = item\n\no = Order("noodles")\nprint(o.item)\n'] = 'class Order:\n    def ___(self, item):\n        self.item = item\n\no = Order("noodles")\nprint(o.item)\n',
  ['class Order:\n    def __init__(self, item):\n        self.item = item\n\n    def ___(self):\n        return f"Order({self.item})"\n'] = 'class Order:\n    def __init__(self, item):\n        self.item = item\n\n    def ___(self):\n        return f"Order({self.item})"\n',
  ['class Order:\n    def __init__(self, item):\n        self.item = item\n\n    def label(___):\n        return f"1 x {___.item}"\n'] = 'class Order:\n    def __init__(self, item):\n        self.item = item\n\n    def label(___):\n        return f"1 x {___.item}"\n',
  ["class Order:\n    def __init__(self, qty, price):\n        self.qty, self.price = qty, price\n\n    @___\n    def total(self):\n        return self.qty * self.price\n"] = "class Order:\n    def __init__(self, qty, price):\n        self.qty, self.price = qty, price\n\n    @___\n    def total(self):\n        return self.qty * self.price\n",
  ["class Order: then the body. Order() calls it to make an instance. pass is the empty statement."] = "class Order: y luego el cuerpo. Order() la llama para crear una instancia. pass es la sentencia vacía.",
  ["class OutOfStock(Exception) is enough. Callers write except OutOfStock:. The refund desk stops crashing."] = "class OutOfStock(Exception) basta. Quien llama escribe except OutOfStock:. El mostrador de reembolsos deja de caerse.",
  ['class OutOfStock(___):\n    pass\n\nraise OutOfStock("egg")\n'] = 'class OutOfStock(___):\n    pass\n\nraise OutOfStock("egg")\n',
  ['class Safe:\n    def ___(self):\n        self.f = open("stock.csv")\n        return self.f\n'] = 'class Safe:\n    def ___(self):\n        self.f = open("stock.csv")\n        return self.f\n',
  ['class Safe:\n    def __enter__(self):\n        self.f = open("stock.csv")\n        return self.f\n\n    def ___(self, exc_type, exc, tb):\n        self.f.close()\n'] = 'class Safe:\n    def __enter__(self):\n        self.f = open("stock.csv")\n        return self.f\n\n    def ___(self, exc_type, exc, tb):\n        self.f.close()\n',
  ["class SetMeal(Order):\n    def __init__(self, item, drink):\n        ___().__init__(item)\n        self.drink = drink\n"] = "class SetMeal(Order):\n    def __init__(self, item, drink):\n        ___().__init__(item)\n        self.drink = drink\n",
  ["class Till:\n    @___\n    def round_up(cents):\n        return (cents + 9) // 10 * 10\n\nprint(Till.round_up(123))    # 130\n"] = "class Till:\n    @___\n    def round_up(cents):\n        return (cents + 9) // 10 * 10\n\nprint(Till.round_up(123))    # 130\n",
  ["class defines a type. __init__ runs on creation; self is the object, written explicitly. __str__ is the print form. super() reaches the parent. @dataclass writes the boilerplate."] = "class define un tipo. __init__ corre al crear; self es el objeto, escrito explícitamente. __str__ es la forma impresa. super() alcanza al padre. @dataclass escribe el código repetitivo.",
  ["class, __init__, self"] = "class, __init__, self",
  ["clear(m) deletes every key. Before 1.21 you looped with delete."] = "clear(m) borra todas las claves. Antes de 1.21 hacías un bucle con delete.",
  ["close() drops your view, unlink() destroys the block. Skip unlink and the memory is still there after the process ends, with a warning to match."] = "close() suelta tu vista, unlink() destruye el bloque. Sáltate unlink y la memoria seguirá ahí tras terminar el proceso, con aviso incluido.",
  ["close(ch). range ch stops when the channel is closed."] = "close(ch). range ch se detiene cuando el channel está cerrado.",
  ["close(jobs) is the shutdown signal: every worker's range loop drains and exits."] = "close(jobs) es la señal de apagado: el bucle range de cada worker se vacía y sale.",
  ["close(orders)\norders <- Order{id: 8}\n// fatal: send on closed channel, the program ___\n"] = "close(orders)\norders <- Order{id: 8}\n// fatal: send on closed channel, el programa ___\n",
  ["close(orders)\nv, ok := <-orders\n// ok is false and v is the ___ value of Order\n"] = "close(orders)\nv, ok := <-orders\n// ok es false y v es el valor ___ de Order\n",
  ["cmd, internal, _test"] = "cmd, internal, _test",
  ["collect::<Vec<_>>() or let v: Vec<_> = ...collect(). Iterators are lazy until then."] = "collect::<Vec<_>>() o let v: Vec<_> = ...collect(). Los iteradores son perezosos hasta entonces.",
  ["comparable for map keys and ==. any allows everything but promises nothing."] = "comparable para claves de map y ==. any permite todo pero no promete nada.",
  ["concurrent map writes killed the process. Which sync type is a map made for goroutines?"] = "concurrent map writes mató el proceso. ¿Qué tipo de sync es un map hecho para goroutines?",
  ["concurrent.futures is the one API for both: ThreadPoolExecutor for waiting, ProcessPoolExecutor for computing. submit returns a Future whose result() blocks and re-raises; as_completed yields futures as they finish; executor.map keeps the order. asyncio joins in through run_in_executor, so an event loop can hand CPU work to processes without blocking."] = "concurrent.futures es la única API para ambos casos: ThreadPoolExecutor para esperar, ProcessPoolExecutor para calcular. submit devuelve un Future cuyo result() bloquea y relanza la excepción; as_completed entrega los futures según terminan; executor.map mantiene el orden. asyncio se suma con run_in_executor, así que un bucle de eventos puede pasar trabajo de CPU a procesos sin bloquearse.",
  ["const (\n    Muffin = ___       // 0\n    Hash               // 1\n    Coffee             // 2\n)\n"] = "const (\n    Muffin = ___       // 0\n    Hash               // 1\n    Coffee             // 2\n)\n",
  ["const OPEN: u8 = 7; A const always has a type, never mut. u8 holds 0 to 255."] = "const OPEN: u8 = 7; Una const siempre tiene tipo, nunca mut. u8 guarda de 0 a 255.",
  ["const opens = 6. The lift knows when breakfast starts."] = "const opens = 6. El ascensor sabe cuándo empieza el desayuno.",
  ["container/heap needs Less. For a min-heap, when does i come before j?"] = "container/heap necesita Less. Para un min-heap, ¿cuándo va i antes que j?",
  ["container/heap wants Len, Less, Swap plus Push and Pop on a pointer. Less with < is a min-heap. Kth largest: push everything, pop whenever the heap holds more than k, the root is the answer."] = "container/heap pide Len, Less, Swap más Push y Pop sobre un puntero. Less con < es un min-heap. K-ésimo mayor: mete todo, extrae cuando el heap tenga más de k, la raíz es la respuesta.",
  ["container/heap, kth largest"] = "container/heap, k-ésimo mayor",
  ["contains, underscore, key. Returns bool. Its cousin get would return the index directly."] = "contains, guion bajo, key. Devuelve bool. Su primo get devolvería el índice directamente.",
  ["context carries deadlines and cancel. go test runs Test* in _test.go."] = "context lleva deadlines y cancel. go test ejecuta Test* en _test.go.",
  ["context.Background() then WithCancel. Always defer cancel()."] = "context.Background() y luego WithCancel. Siempre defer cancel().",
  ["context.Canceled means somebody called cancel; context.DeadlineExceeded means the clock did. Both arrive through ctx.Err() after Done closes."] = "context.Canceled significa que alguien llamó a cancel; context.DeadlineExceeded, que lo hizo el reloj. Los dos llegan por ctx.Err() después de que Done se cierre.",
  ["context: cancel, deadline, value"] = "context: cancelar, plazo, valor",
  ["continue skips one round; break ends the loop."] = "continue salta una vuelta; break termina el bucle.",
  ["count := 0\nfor r := range g {\n    for c := range g[r] {\n        if g[r][c] == '1' {\n            count++         // a new island\n            ___(g, r, c)    // sink all of it\n"] = "count := 0\nfor r := range g {\n    for c := range g[r] {\n        if g[r][c] == '1' {\n            count++         // una isla nueva\n            ___(g, r, c)    // húndela entera\n",
  ["count must go up. Which word after let allows the change?"] = "count debe subir. ¿Qué palabra tras let permite el cambio?",
  ["create_task schedules the coroutine now; await t later collects it. Keep a reference or it may be garbage-collected mid-flight."] = "create_task programa la corrutina ahora; await t después la recoge. Guarda una referencia o puede recogerla el recolector a medio vuelo.",
  ["ctx := context.___()\nctx, cancel := context.WithCancel(ctx)\ndefer cancel()\n"] = "ctx := context.___()\nctx, cancel := context.WithCancel(ctx)\ndefer cancel()\n",
  ["ctx, cancel := context.___(context.Background())\ndefer cancel()\ngo fetchETA(ctx, id)\n"] = "ctx, cancel := context.___(context.Background())\ndefer cancel()\ngo fetchETA(ctx, id)\n",
  ["ctx, cancel := context.___(ctx, 2*time.Second)\ndefer cancel()\nresp, err := fetchETA(ctx, id)\n"] = "ctx, cancel := context.___(ctx, 2*time.Second)\ndefer cancel()\nresp, err := fetchETA(ctx, id)\n",
  ["ctx, cancel := context.___(ctx, 2*time.Second)\ndefer cancel()          // always\n"] = "ctx, cancel := context.___(ctx, 2*time.Second)\ndefer cancel()          // siempre\n",
  ["ctx.Done() closes on cancel or deadline; ctx.Err() says which one."] = "ctx.Done() se cierra por cancel o deadline; ctx.Err() dice cuál.",
  ["ctx.Done() is a receive-only channel closed on cancel or deadline. Selecting on it is how a goroutine agrees to be stoppable."] = "ctx.Done() es un channel de solo recepción que se cierra al cancelar o al vencer el plazo. Hacerle select es como una goroutine acepta poder ser detenida.",
  ["cups: int is a hint, not a check: brew('two') still runs. mypy or pyright flags it before that."] = "cups: int es una anotación, no una comprobación: brew('two') sigue corriendo. mypy o pyright lo señalan antes.",
  ["cur = nxt: without saving it first, the flip would have cut the rest of the chain loose."] = "cur = nxt: sin guardarlo primero, el giro habría soltado el resto de la cadena.",
  ["cur overlaps the last merged interval when its start is no later than that interval's end. Fill the index of the end."] = "cur se solapa con el último intervalo fusionado cuando su inicio no es posterior al fin de ese intervalo. Completa el índice del fin.",
  ["cur, best := a[0], a[0]\nfor _, x := range a[1:] {\n    cur = max(___, cur+x)   // start over here, or extend\n    best = max(best, cur)\n}\nreturn best\n"] = "cur, best := a[0], a[0]\nfor _, x := range a[1:] {\n    cur = max(___, cur+x)   // empezar aquí, o extender\n    best = max(best, cur)\n}\nreturn best\n",
  ["d.get(k, default) never raises. Go's comma-ok, in one call. The board shows 0 instead of dying."] = "d.get(k, default) nunca lanza. El comma-ok de Go, en una sola llamada. La carta muestra 0 en vez de morir.",
  ["d.items() yields (key, value) tuples; d.keys() and d.values() the halves. Since 3.7 the order is insertion order."] = "d.items() produce tuplas (key, value); d.keys() y d.values() las mitades. Desde 3.7 el orden es el de inserción.",
  ["d.keys() is a live view; wrap it in list() for a copy. Go 1.21 gives you the same with maps.Keys. The board is fixed."] = "d.keys() es una vista viva; envuélvela en list() para una copia. Go 1.21 te da lo mismo con maps.Keys. La carta está arreglada.",
  ['def anagram(a, b):\n    return ___(a) == sorted(b)\n\nprint(anagram("listen", "silent"))   # True\n'] = 'def anagram(a, b):\n    return ___(a) == sorted(b)\n\nprint(anagram("listen", "silent"))   # True\n',
  ["def belt(orders):\n    for o in orders:\n        bowl = cook(o)\n        ___ bowl\n\nfor b in belt(orders):\n    serve(b)\n"] = "def belt(orders):\n    for o in orders:\n        bowl = cook(o)\n        ___ bowl\n\nfor b in belt(orders):\n    serve(b)\n",
  ["def best_k(a, k):\n    s = sum(a[:k])\n    best = s\n    for i in range(k, len(a)):\n        s += a[i] - ___        # one in, one out\n        best = max(best, s)\n    return best\n"] = "def best_k(a, k):\n    s = sum(a[:k])\n    best = s\n    for i in range(k, len(a)):\n        s += a[i] - ___        # uno entra, uno sale\n        best = max(best, s)\n    return best\n",
