  ["def, return, *args, lambda"] = "def, return, *args, lambda",
  ["default: runs when every channel would block. The till stays free."] = "default: se ejecuta cuando todos los channels bloquearían. La caja queda libre.",
  ["defaultdict(list) calls list() for a missing key. Go's map[string][]string with the nil-slice append trick, built in."] = "defaultdict(list) llama a list() para una clave ausente. El map[string][]string de Go con el truco del append sobre slice nil, integrado.",
  ["defer captures its arguments now, not later. What does this print?"] = "defer captura sus argumentos ahora, no después. ¿Qué imprime esto?",
  ["defer evaluates arguments immediately. defer func() { fmt.Println(x) }() would print 2."] = "defer evalúa los argumentos de inmediato. defer func() { fmt.Println(x) }() imprimiría 2.",
  ["defer f.Close(). The drawer shuts even if Pay fails."] = "defer f.Close(). El cajón se cierra aunque Pay falle.",
  ["defer func() {\n    if r := ___(); r != nil {\n        // saved the till\n    }\n}()\n"] = "defer func() {\n    if r := ___(); r != nil {\n        // caja salvada\n    }\n}()\n",
  ["del menu[k] raises if k is missing; menu.pop(k, None) removes quietly and returns the value."] = "del menu[k] lanza si falta k; menu.pop(k, None) elimina en silencio y devuelve el valor.",
  ["delete(m, k) removes it. Maps grow by assignment, shrink by this."] = "delete(m, k) la quita. Los maps crecen por asignación y encogen con esto.",
  ["delete(m, key). Safe if the key is already gone."] = "delete(m, key). Seguro aunque la clave ya no esté.",
  ["deque.popleft is O(1); that is why BFS uses a deque and never a list. Round two to Bo."] = "deque.popleft es O(1); por eso BFS usa un deque y nunca una lista. Segunda ronda para Bo.",
  ["derive Serialize and Deserialize, then serde_json::to_string and from_str. Attributes shape the JSON."] = "derive Serialize y Deserialize, luego serde_json::to_string y from_str. Los atributos dan forma al JSON.",
  ["derive(Serialize, Deserialize) needs the derive feature in Cargo.toml. serde_json does the format."] = "derive(Serialize, Deserialize) necesita la feature derive en Cargo.toml. serde_json se encarga del formato.",
  ["dict: hash, slot, compare. O(1) average, O(n) worst when everything collides. Go's map, Rust's HashMap."] = "dict: hash, ranura, comparación. O(1) en promedio, O(n) en el peor caso cuando todo colisiona. El map de Go, el HashMap de Rust.",
  ["dict[str, float]. Go's map[string]float64, Rust's HashMap<String, f64>. TypedDict names each key."] = "dict[str, float]. El map[string]float64 de Go, el HashMap<String, f64> de Rust. TypedDict nombra cada clave.",
  ["done := make(chan ___)   // zero bytes per value\ngo func() {\n    cook()\n    close(done)\n}()\n<-done\n"] = "done := make(chan ___)   // cero bytes por valor\ngo func() {\n    cook()\n    close(done)\n}()\n<-done\n",
  ['done = mp.Value("i", 0)\n\nwith done.___():\n    done.value += 1\n'] = 'done = mp.Value("i", 0)\n\nwith done.___():\n    done.value += 1\n',
