  ["fn fib(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {\n    if let Some(&v) = memo.___(&n) { return v; }\n    let v = if n < 2 { n } else { fib(n - 1, memo) + fib(n - 2, memo) };\n    memo.insert(n, v);\n    v\n}\n"] = "fn fib(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {\n    if let Some(&v) = memo.___(&n) { return v; }\n    let v = if n < 2 { n } else { fib(n - 1, memo) + fib(n - 2, memo) };\n    memo.insert(n, v);\n    v\n}\n",
