  ["is_some_and(|e| e < 10) beats map(..).unwrap_or(false). Review clean at 17:59. SHIPPED."] = "is_some_and(|e| e < 10) gana a map(..).unwrap_or(false). Revisión limpia a las 17:59. ENTREGADO.",
  ['it = iter([1])\nnext(it)      # 1\ntry:\n    next(it)\nexcept ___:\n    print("belt empty")\n'] = 'it = iter([1])\nnext(it)      # 1\ntry:\n    next(it)\nexcept ___:\n    print("belt empty")\n',
  ["items.last() is items.get(len - 1). O(1), and no panic on an empty Vec. push at the end is O(1) amortized."] = "items.last() es items.get(len - 1). O(1), y sin panic con un Vec vacío. El push al final es O(1) amortizado.",
  ["items[-1]. Python adds len for you. Constant time, like append at the end (amortized) and pop()."] = "items[-1]. Python suma len por ti. Tiempo constante, como el append al final (amortizado) y pop().",
  ["items[len(items)-1]. Python spells it items[-1]. Both constant time. So is append at the end, amortized."] = "items[len(items)-1]. Python lo escribe items[-1]. Ambos en tiempo constante. También el append al final, amortizado.",
  ["iter() borrows, into_iter() consumes. map, filter, collect, sum, fold: no index bugs."] = "iter() toma prestado, into_iter() consume. map, filter, collect, sum, fold: sin bugs de índice.",
  ["iter() yields &T. into_iter() yields T and eats the Vec. Dish zero prints again."] = "iter() produce &T. into_iter() produce T y se come el Vec. El plato cero vuelve a imprimirse.",
  ["iter().sum() needs the result type written down. map, filter, count and collect live on the same chain."] = "iter().sum() necesita el tipo del resultado escrito. map, filter, count y collect viven en la misma cadena.",
  ["iter(x) calls x.__iter__(); next(it) calls __next__. That pair is the whole iterator protocol."] = "iter(x) llama a x.__iter__(); next(it) llama a __next__. Ese par es todo el protocolo de iterador.",
  ["iter.Seq[T] is func(yield func(T) bool). for x := range Items() just works."] = "iter.Seq[T] es func(yield func(T) bool). for x := range Items() funciona sin más.",
  ["j moves left as i moves right. Stop when they meet."] = "j va a la izquierda mientras i va a la derecha. Para cuando se cruzan.",
  ["jobs := make(chan int, 10)\nresults := make(chan int, 10)\nvar wg sync.WaitGroup\nfor w := 1; w <= 3; w++ {\n    wg.___(1)\n    go worker(jobs, results, &wg)\n}\n"] = "jobs := make(chan int, 10)\nresults := make(chan int, 10)\nvar wg sync.WaitGroup\nfor w := 1; w <= 3; w++ {\n    wg.___(1)\n    go worker(jobs, results, &wg)\n}\n",
  ["jobs = [(p, 512) for p in photos]\nwith mp.Pool(8) as pool:\n    pool.___(resize, jobs)\n"] = "jobs = [(p, 512) for p in photos]\nwith mp.Pool(8) as pool:\n    pool.___(resize, jobs)\n",
  ["jobs.join() returns when every put has a matching task_done. daemon=True lets the idle cooks die with main. Seven rounds, no misses. HIRED, at midnight, in Python."] = "jobs.join() vuelve cuando cada put tiene su task_done correspondiente. daemon=True deja que los cocineros ociosos mueran con el principal. Siete rondas, sin fallos. CONTRATADO, a medianoche, en Python.",
  ["join! waits for all; select! returns on the first. 200 ms total instead of 400."] = "join! espera a todos; select! vuelve con el primero. 200 ms en total en vez de 400.",
  ["join() blocks until the child exits. Without it the parent can reach the end of the script and leave orphans behind."] = "join() bloquea hasta que el hijo termina. Sin él, el padre puede llegar al final del script y dejar huérfanos.",
  ["join() blocks until the thread ends and returns Result<T>; Err means the thread panicked. 180 seconds to steep."] = "join() bloquea hasta que el thread termina y devuelve Result<T>; Err significa que el thread hizo panic. 180 segundos de infusión.",
  ["json only sees exported fields. Name the item field: Item or item?"] = "json solo ve campos exportados. Nombra el campo del artículo: ¿Item o item?",
  ["json sees exported fields only. Tags pick the key. Marshal out, Unmarshal in."] = "json solo ve campos exportados. Los tags eligen la clave. Marshal saca, Unmarshal mete.",
  ["k contenders left; the smallest of them is the kth largest overall. Which index holds it?"] = "Quedan k candidatos; el menor de ellos es el k-ésimo mayor en total. ¿Qué índice lo guarda?",
  ["k positions behind the newest one."] = "k posiciones por detrás del más nuevo.",
  ["kb = 2 ___ 10\nprint(kb)          # 1024\n"] = "kb = 2 ___ 10\nprint(kb)          # 1024\n",
  ["key= is called once per item; sort by its result. sorted(words, key=str.lower) is the case-insensitive classic."] = "key= se llama una vez por elemento; se ordena por su resultado. sorted(words, key=str.lower) es el clásico sin distinguir mayúsculas.",
  ["kth largest: keep only the k biggest in a MIN-heap, so the smallest of them sits on top. BinaryHeap is a max-heap: which std::cmp wrapper flips the order?"] = "k-ésimo mayor: guarda solo los k mayores en un MIN-heap, para que el menor de ellos quede en la cima. BinaryHeap es un max-heap: ¿qué wrapper de std::cmp invierte el orden?",
  ["l only moves right, so each character enters and leaves once: O(n) despite the nested while."] = "l solo avanza a la derecha, así que cada carácter entra y sale una vez: O(n) pese al while anidado.",
  ["l[i] <= r[j] keeps the merge stable. The leftovers are appended with extend. O(n) per merge."] = "l[i] <= r[j] mantiene el merge estable. Los restos se añaden con extend. O(n) por merge.",
  ['label := fmt.___("%s $%d", item, price)   // "set $25"\n'] = 'label := fmt.___("%s $%d", item, price)   // "set $25"\n',
  ["lambda o: o[1] is an anonymous one-expression function. For anything longer, use def."] = "lambda o: o[1] es una función anónima de una sola expresión. Para algo más largo, usa def.",
  ["largest compares with >. Which trait must T promise?"] = "largest compara con >. ¿Qué trait debe prometer T?",
  ["last := items[len(items)___]    // still O(1): len is stored\n"] = "last := items[len(items)___]    // sigue siendo O(1): len está guardado\n",
  ["last := map[rune]int{}\nl, best := 0, 0\nfor r, c := range s {\n    if p, ok := last[c]; ok && p >= l {\n        l = p + 1           // jump past the repeat\n    }\n    last[c] = ___\n"] = "last := map[rune]int{}\nl, best := 0, 0\nfor r, c := range s {\n    if p, ok := last[c]; ok && p >= l {\n        l = p + 1           // salta más alla del repetido\n    }\n    last[c] = ___\n",
  ["last = items[___]    # still O(1): negative indexes count from the end\n"] = "last = items[___]    # sigue siendo O(1): los índices negativos cuentan desde el final\n",
  ["latest means the highest tagged release, never a pre-release and never main. Without any tag at all you get a pseudo-version like v0.0.0-20260904164500-abc123def456."] = "latest significa la release etiquetada más alta, nunca una prerelease y nunca main. Sin ninguna etiqueta obtienes una pseudoversión como v0.0.0-20260904164500-abc123def456.",
  ["len counts bytes. 灣 is one character. In UTF-8, how many bytes?"] = "len cuenta bytes. 灣 es un carácter. En UTF-8, ¿cuántos bytes?",
  ["len is how many you can see. cap is how many fit before a new array."] = "len es cuántos ves. cap es cuántos caben antes de un array nuevo.",
  ["len is what is waiting, cap is the buffer size. A buffer smooths bursts; it never removes the need to handle a slow consumer."] = "len es lo que está esperando, cap es el tamaño del buffer. Un buffer suaviza picos; nunca te quita la obligación de tratar con un consumidor lento.",
  ["len works on lists, strings, dicts, sets, anything with __len__. It is O(1): the length is stored."] = "len funciona con listas, cadenas, dicts, sets, cualquier cosa con __len__. Es O(1): la longitud está guardada.",
  ["len() is bytes. Slicing &s[0..4] in the middle of 鑼 panics: not a char boundary."] = "len() son bytes. Cortar &s[0..4] en medio de 鑼 hace panic: no es un límite de char.",
  ["len() returns usize. The second let shadows n with a new binding; the old one is gone. Next tram in 7."] = "len() devuelve usize. El segundo let hace shadowing de n con un binding nuevo; el viejo desaparece. Próximo tranvía en 7.",
  ["len(a) // 2 splits [3, 1, 2] into [3] and [1, 2]. Each level halves; log2(n) levels."] = "len(a) // 2 divide [3, 1, 2] en [3] y [1, 2]. Cada nivel parte a la mitad; log2(n) niveles.",
  ["len(s) - 1 is the last index. Two pointers meet in the middle: O(n) time, O(1) space. s == s[::-1] is the one-liner."] = "len(s) - 1 es el último índice. Dos punteros se encuentran en el medio: O(n) de tiempo, O(1) de espacio. s == s[::-1] es la versión de una línea.",
  ["len(s) is bytes, not characters. That is why the sign counted nine."] = "len(s) son bytes, no caracteres. Por eso el letrero contó nueve.",
  ["let (mut i, mut j) = (0, a.len() - 1);     // a is sorted\nwhile i < j {\n    match (a[i] + a[j]).cmp(&target) {\n        Ordering::Equal => return Some((i, j)),\n        Ordering::Less => i += 1,        // need more\n        Ordering::Greater => j ___ 1,    // need less\n    }\n"] = "let (mut i, mut j) = (0, a.len() - 1);     // a está ordenado\nwhile i < j {\n    match (a[i] + a[j]).cmp(&target) {\n        Ordering::Equal => return Some((i, j)),\n        Ordering::Less => i += 1,        // hace falta más\n        Ordering::Greater => j ___ 1,    // hace falta menos\n    }\n",
  ["let (mut lo, mut hi) = (0, a.len());\nwhile lo < hi {\n    let mid = lo + (hi - lo) ___ 2;   // integer division on usize\n    if a[mid] < x { lo = mid + 1 } else { hi = mid }\n}\n"] = "let (mut lo, mut hi) = (0, a.len());\nwhile lo < hi {\n    let mid = lo + (hi - lo) ___ 2;   // división entera sobre usize\n    if a[mid] < x { lo = mid + 1 } else { hi = mid }\n}\n",
  ['let (tx, rx) = mpsc::channel();\n// Two tills, one kitchen: each till needs its own sender.\nlet tx2 = tx.___();\nthread::spawn(move || tx.send("till 1").unwrap());\nthread::spawn(move || tx2.send("till 2").unwrap());\nfor msg in rx { println!("{msg}"); }\n'] = 'let (tx, rx) = mpsc::channel();\n// Dos cajas, una cocina: cada caja necesita su propio emisor.\nlet tx2 = tx.___();\nthread::spawn(move || tx.send("till 1").unwrap());\nthread::spawn(move || tx2.send("till 2").unwrap());\nfor msg in rx { println!("{msg}"); }\n',
  ['let (tx, rx) = mpsc::channel();\nlet tx2 = tx.clone();\nthread::spawn(move || tx2.send("bun").unwrap());\n___(tx);   // otherwise the loop below never ends\nfor msg in rx { println!("{msg}"); }\n'] = 'let (tx, rx) = mpsc::channel();\nlet tx2 = tx.clone();\nthread::spawn(move || tx2.send("bun").unwrap());\n___(tx);   // si no, el bucle de abajo nunca termina\nfor msg in rx { println!("{msg}"); }\n',
  ["let (tx, rx) = mpsc::channel();\ntx.send(7).unwrap();\n// The kitchen waits here until an order arrives.\nlet order: u32 = rx.___().unwrap();\n"] = "let (tx, rx) = mpsc::channel();\ntx.send(7).unwrap();\n// La cocina espera aquí hasta que llega un pedido.\nlet order: u32 = rx.___().unwrap();\n",
  ["let Reverse(kth) = ... destructures the wrapper in the pattern. peek is O(1)."] = "let Reverse(kth) = ... desestructura el wrapper en el patrón. peek es O(1).",
  ["let Some(x) = opt else { return }; binds x for the rest of the function. No nesting."] = "let Some(x) = opt else { return }; liga x para el resto de la función. Sin anidamiento.",
  ["let b = a.___();    // allocate n ints and copy: O(n) time, O(n) space\n"] = "let b = a.___();    // reservar n ints y copiar: O(n) de tiempo, O(n) de espacio\n",
  ["let b = s.as_bytes();\nlet mut seen = HashSet::new();\nlet (mut l, mut best) = (0, 0);\nfor r in 0..b.len() {\n    while seen.contains(&b[r]) {\n        seen.___(&b[l]);    // the left end leaves\n        l += 1;\n"] = "let b = s.as_bytes();\nlet mut seen = HashSet::new();\nlet (mut l, mut best) = (0, 0);\nfor r in 0..b.len() {\n    while seen.contains(&b[r]) {\n        seen.___(&b[l]);    // el extremo izquierdo sale\n        l += 1;\n",
  ["let bill = vec![18, 0, 42, 0, 25];\n// into_iter gives i32; the closure sees &i32\nlet ok: Vec<_> = bill.into_iter().___(|p| *p > 0).collect();\nassert_eq!(ok, vec![18, 42, 25]);\n"] = "let bill = vec![18, 0, 42, 0, 25];\n// into_iter da i32; el closure ve &i32\nlet ok: Vec<_> = bill.into_iter().___(|p| *p > 0).collect();\nassert_eq!(ok, vec![18, 42, 25]);\n",
  ["let binds. mut allows change. const needs a type. as converts. A new let can shadow an old name."] = "let vincula. mut permite cambiar. const necesita un tipo. as convierte. Un nuevo let puede hacer shadowing de un nombre viejo.",
  ['let dish = "curry rice";\nlet qty = 2;\n// like println! but it returns the String\nlet line = ___!("{qty} x {dish}");\n'] = 'let dish = "curry rice";\nlet qty = 2;\n// como println! pero devuelve el String\nlet line = ___!("{qty} x {dish}");\n',
  ['let dishes = ["curry rice", "noodles", "toast"];\n// nothing runs before this call; turbofish names the type\nlet lens = dishes.iter().map(|d| d.len()).___::<Vec<_>>();\nassert_eq!(lens, vec![10, 7, 5]);\n'] = 'let dishes = ["curry rice", "noodles", "toast"];\n// nada se ejecuta antes de esta llamada; el turbofish nombra el tipo\nlet lens = dishes.iter().map(|d| d.len()).___::<Vec<_>>();\nassert_eq!(lens, vec![10, 7, 5]);\n',
  ['let dishes = ["curry rice", "noodles", "toast"];\n// yields (usize, &&str) pairs, starting from 0\nfor (i, d) in dishes.iter().___() {\n    println!("{}. {d}", i + 1);\n}\n'] = 'let dishes = ["curry rice", "noodles", "toast"];\n// produce pares (usize, &&str), empezando en 0\nfor (i, d) in dishes.iter().___() {\n    println!("{}. {d}", i + 1);\n}\n',
  ['let dishes = vec!["curry rice", "noodles", "toast"];\n// borrows every element as &&str; dishes stays usable\nfor d in dishes.___() {\n    println!("ticket: {d}");\n}\n'] = 'let dishes = vec!["curry rice", "noodles", "toast"];\n// toma prestado cada elemento como &&str; dishes sigue usable\nfor d in dishes.___() {\n    println!("ticket: {d}");\n}\n',
  ['let district = "銅鑼灣";\nlet n = district.___().count();\nassert_eq!(n, 3);\n// the receipt now cuts at whole characters\n'] = 'let district = "銅鑼灣";\nlet n = district.___().count();\nassert_eq!(n, 3);\n// el recibo ahora corta en caracteres completos\n',
  ["let else, matches!, impl Trait, ..=, ? on Option, is_some_and: less nesting, same safety."] = "let else, matches!, impl Trait, ..=, ? en Option, is_some_and: menos anidamiento, la misma seguridad.",
  ['let eta: Option<u32> = fetch_eta_cached(order.id);\n// Rust 1.70: None -> false, Some(e) -> the closure result\nlet fast = eta.___(|e| e < 10);\nif fast { println!("promise the customer 10 minutes"); }\n'] = 'let eta: Option<u32> = fetch_eta_cached(order.id);\n// Rust 1.70: None -> false, Some(e) -> el resultado del closure\nlet fast = eta.___(|e| e < 10);\nif fast { println!("promise the customer 10 minutes"); }\n',
  ['let menu = vec!["bun", "egg tart", "milk tea"];\n// Borrow menu from threads; all end before the block does.\nthread::___(|s| {\n    s.spawn(|| println!("{}", menu[0]));\n    s.spawn(|| println!("{}", menu[1]));\n});\n'] = 'let menu = vec!["bun", "egg tart", "milk tea"];\n// Presta menu desde los threads; todos acaban antes que el bloque.\nthread::___(|s| {\n    s.spawn(|| println!("{}", menu[0]));\n    s.spawn(|| println!("{}", menu[1]));\n});\n',
  ["let mut b = a.clone();    // a second Vec of n ints: O(___)\nb.sort();\n"] = "let mut b = a.clone();    // un segundo Vec de n ints: O(___)\nb.sort();\n",
  ["let mut count = 0; Immutable by default is Rust's first safety rule. The sign counts again."] = "let mut count = 0; Inmutable por defecto es la primera regla de seguridad de Rust. El letrero vuelve a contar.",
  ['let mut counts: HashMap<&str, u32> = HashMap::new();\nfor w in "muffin coffee muffin".split(\' \') {\n    // start at 0 if w is new, then bump it either way\n    *counts.entry(w).___(0) += 1;\n}\nassert_eq!(counts["muffin"], 2);\n'] = 'let mut counts: HashMap<&str, u32> = HashMap::new();\nfor w in "muffin coffee muffin".split(\' \') {\n    // empieza en 0 si w es nueva, y súbelo en cualquier caso\n    *counts.entry(w).___(0) += 1;\n}\nassert_eq!(counts["muffin"], 2);\n',
  ["let mut handles = Vec::new();\nfor id in 0..3 {\n    let rx = Arc::clone(&rx);\n    // a new OS thread runs the closure; move hands over rx\n    handles.push(thread::___(move || worker(id, rx)));\n}\n"] = "let mut handles = Vec::new();\nfor id in 0..3 {\n    let rx = Arc::clone(&rx);\n    // un thread nuevo del sistema corre el closure; move pasa rx\n    handles.push(thread::___(move || worker(id, rx)));\n}\n",
  ["let mut ids = vec![9, 2, 7, 2, 5];\n// equal ids may swap places; nobody can tell\nids.___();\nassert_eq!(ids, [2, 2, 5, 7, 9]);\n"] = "let mut ids = vec![9, 2, 7, 2, 5];\n// los ids iguales pueden intercambiarse; nadie lo nota\nids.___();\nassert_eq!(ids, [2, 2, 5, 7, 9]);\n",
  ['let mut left = 3;\n___ left > 0 {\n    left -= 1;\n    if left == 1 { continue; }   // skip this round\n    println!("{}", left);\n}\n'] = 'let mut left = 3;\n___ left > 0 {\n    left -= 1;\n    if left == 1 { continue; }   // salta esta vuelta\n    println!("{}", left);\n}\n',
  ["let mut max = prices[0];\nfor &p in &prices[1..] {    // ___ comparisons\n    if p > max { max = p; }\n}\n"] = "let mut max = prices[0];\nfor &p in &prices[1..] {    // ___ comparaciones\n    if p > max { max = p; }\n}\n",
  ["let mut n = 0;\nfor r in 0..g.len() {\n    for c in 0..g[0].len() {\n        // land still standing: a new island, flood it\n        if g[r][c] == b'1' { n += 1; ___(&mut g, r, c); }\n    }\n}\n"] = "let mut n = 0;\nfor r in 0..g.len() {\n    for c in 0..g[0].len() {\n        // tierra aún en pie: una isla nueva, inúndala\n        if g[r][c] == b'1' { n += 1; ___(&mut g, r, c); }\n    }\n}\n",
  ['let mut order = String::new();\norder.___("curry rice");\norder.___(" + hash brown");\nlet loud = order.to_uppercase();\n'] = 'let mut order = String::new();\norder.___("curry rice");\norder.___(" + hash brown");\nlet loud = order.to_uppercase();\n',
  ["let mut seen = ___::new();\nfor g in &guests {               // one pass: O(n)\n    if !seen.insert(g) { dup = true; }   // false = already there\n}\n"] = "let mut seen = ___::new();\nfor g in &guests {               // una pasada: O(n)\n    if !seen.insert(g) { dup = true; }   // false = ya estaba\n}\n",
  ["let mut st: Vec<char> = Vec::new();\nfor c in s.chars() {\n    let open = closer_of(c);\n    if open == '\\0' {\n        st.___(c);          // wait here for the closer\n        continue;\n    }\n"] = "let mut st: Vec<char> = Vec::new();\nfor c in s.chars() {\n    let open = closer_of(c);\n    if open == '\\0' {\n        st.___(c);          // espera aquí al cierre\n        continue;\n    }\n",
  ['let mut tray = vec![7, 8];\n// pop returns an Option: a value, or None if empty.\nif let ___(id) = tray.pop() {\n    println!("serving order {id}");\n}\n'] = 'let mut tray = vec![7, 8];\n// pop devuelve un Option: un valor, o None si está vacío.\nif let ___(id) = tray.pop() {\n    println!("serving order {id}");\n}\n',
  ['let mut tries = 0;\nlet code = ___ {\n    tries += 1;\n    if tries == 3 { break tries * 10; }\n};\nprintln!("{}", code);   // 30\n'] = 'let mut tries = 0;\nlet code = ___ {\n    tries += 1;\n    if tries == 3 { break tries * 10; }\n};\nprintln!("{}", code);   // 30\n',
  ["let n = if a > b { a } else { b }; Both branches must have the same type. n is 22."] = "let n = if a > b { a } else { b }; Ambas ramas deben tener el mismo tipo. n es 22.",
  ['let order = Order { name: "toast".into(), qty: 2 };\n// takes a reference; returns Result<String, Error>\nlet text = serde_json::___(&order)?;\nassert_eq!(text, r#"{"name":"toast","qty":2}"#);\n'] = 'let order = Order { name: "toast".into(), qty: 2 };\n// recibe una referencia; devuelve Result<String, Error>\nlet text = serde_json::___(&order)?;\nassert_eq!(text, r#"{"name":"toast","qty":2}"#);\n',
  ['let order = String::from("pineapple bun");\n// The thread may outlive this block: give it the String.\nlet h = thread::spawn(___ || {\n    println!("toasting {order}");\n});\nh.join().unwrap();\n'] = 'let order = String::from("pineapple bun");\n// El thread puede vivir más que este bloque: dale el String.\nlet h = thread::spawn(___ || {\n    println!("toasting {order}");\n});\nh.join().unwrap();\n',
  ["let price = 28; The type is inferred as i32. Without mut it can never change."] = "let price = 28; El tipo se infiere como i32. Sin mut nunca puede cambiar.",
  ['let prices = [18, 22, 45, 60];       // already sorted\n// halve the range each step\nmatch prices.___(&45) {\n    Ok(i) => println!("found at {i}"),\n    Err(i) => println!("would insert at {i}"),\n}\n'] = 'let prices = [18, 22, 45, 60];       // ya ordenado\n// parte el rango a la mitad en cada paso\nmatch prices.___(&45) {\n    Ok(i) => println!("found at {i}"),\n    Err(i) => println!("would insert at {i}"),\n}\n',
  ["let prices = vec![18, 42, 25];\n// acc starts at 0; the closure returns the next acc\nlet total = prices.iter().___(0, |acc, p| acc + p);\nassert_eq!(total, 85);\n"] = "let prices = vec![18, 42, 25];\n// acc empieza en 0; el closure devuelve el siguiente acc\nlet total = prices.iter().___(0, |acc, p| acc + p);\nassert_eq!(total, 85);\n",
  ["let prices = vec![18, 42, 25];\n// the turbofish tells it which number type to add into\nlet total = prices.iter().___::<i32>();\nassert_eq!(total, 85);\n"] = "let prices = vec![18, 42, 25];\n// el turbofish le dice en qué tipo numérico acumular\nlet total = prices.iter().___::<i32>();\nassert_eq!(total, 85);\n",
  ["let qty = vec![1, 2, 3];\n// a closure: the parameter sits between two pipes\nlet doubled: Vec<i32> = qty.iter().map(___ x * 2).collect();\nassert_eq!(doubled, vec![2, 4, 6]);\n"] = "let qty = vec![1, 2, 3];\n// un closure: el parámetro va entre dos barras verticales\nlet doubled: Vec<i32> = qty.iter().map(___ x * 2).collect();\nassert_eq!(doubled, vec![2, 4, 6]);\n",
  ["let sold = Arc::new(Mutex::new(0u32));\n// Each thread needs its own handle to the same counter.\nlet mine = ___(&sold);\nthread::spawn(move || { *mine.lock().unwrap() += 1; });\n"] = "let sold = Arc::new(Mutex::new(0u32));\n// Cada thread necesita su propio handle al mismo contador.\nlet mine = ___(&sold);\nthread::spawn(move || { *mine.lock().unwrap() += 1; });\n",
  ["let sold = Arc::new(Mutex::new(0u32));\n// Take the guard; it opens again when it goes out of scope.\nlet mut n = sold.___().unwrap();\n*n += 1;\n"] = "let sold = Arc::new(Mutex::new(0u32));\n// Toma el guard; se abre de nuevo al salir del scope.\nlet mut n = sold.___().unwrap();\n*n += 1;\n",
  ["let tail = items.___();    // Some(&x) or None; still O(1)\n"] = "let tail = items.___();    // Some(&x) o None; sigue siendo O(1)\n",
  ['let text = r#"{"dish":"toast","tags":["hot","new"]}"#;\n// an enum: Null, Bool, Number, String, Array, Object\nlet v: serde_json::___ = serde_json::from_str(text)?;\nprintln!("{}", v["tags"][0]);   // "hot"\n'] = 'let text = r#"{"dish":"toast","tags":["hot","new"]}"#;\n// un enum: Null, Bool, Number, String, Array, Object\nlet v: serde_json::___ = serde_json::from_str(text)?;\nprintln!("{}", v["tags"][0]);   // "hot"\n',
  ['let text = r#"{"name":"noodles","qty":1}"#;\n// the type annotation tells serde what to build\nlet order: Order = serde_json::___(text)?;\nassert_eq!(order.qty, 1);\n'] = 'let text = r#"{"name":"noodles","qty":1}"#;\n// la anotación de tipo le dice a serde qué construir\nlet order: Order = serde_json::___(text)?;\nassert_eq!(order.qty, 1);\n',
  ["let total: i32 = prices.iter().sum();        // n steps\nlet max = prices.iter().max();                // n more\n// 2n steps, written O(___)\n"] = "let total: i32 = prices.iter().sum();        // n pasos\nlet max = prices.iter().max();                // n más\n// 2n pasos, escrito O(___)\n",
  ["let total: i32 = prices.iter().sum();   // ___ : n items, n adds\n"] = "let total: i32 = prices.iter().sum();   // ___ : n elementos, n sumas\n",
  ['let typed = "18";\n// FromStr does the work; the turbofish picks the type\nlet qty = typed.___::<i32>()?;\nprintln!("{qty} sets");\n'] = 'let typed = "18";\n// FromStr hace el trabajo; el turbofish elige el tipo\nlet qty = typed.___::<i32>()?;\nprintln!("{qty} sets");\n',
  ['light := "green"\n___ light {\ncase "green":\n    walk()\n}\n'] = 'light := "green"\n___ light {\ncase "green":\n    walk()\n}\n',
  ["list(a), a[:] or a.copy(): all shallow, all O(n). Allocation is where space complexity is paid."] = "list(a), a[:] o a.copy(): todas superficiales, todas O(n). La reserva es donde se paga la complejidad espacial.",
  ["list[str] since 3.9; typing.List[str] before. Go's []string, Rust's Vec<String>."] = "list[str] desde 3.9; typing.List[str] antes. El []string de Go, el Vec<String> de Rust.",
  ["lo = mid + 1 drops the left half. Each step halves the range: O(log n). The array must be sorted first."] = "lo = mid + 1 descarta la mitad izquierda. Cada paso parte el rango a la mitad: O(log n). El array debe estar ordenado primero.",
  ["lo, hi := 0, len(a)\nfor lo < hi {\n    mid := (lo + hi) ___ 2   // integer division in Go\n    if a[mid] < x { lo = mid + 1 } else { hi = mid }\n}\n"] = "lo, hi := 0, len(a)\nfor lo < hi {\n    mid := (lo + hi) ___ 2   // división entera en Go\n    if a[mid] < x { lo = mid + 1 } else { hi = mid }\n}\n",
  ["lo, hi := 0, len(a)         // [lo, hi)\nfor lo < hi {\n    mid := lo + (hi-lo)/___\n"] = "lo, hi := 0, len(a)         // [lo, hi)\nfor lo < hi {\n    mid := lo + (hi-lo)/___\n",
  ["lo, hi = 0, len(a)\nwhile lo < hi:\n    mid = (lo + hi) ___ 2    # floor division\n    if a[mid] < x: lo = mid + 1\n    else: hi = mid\n"] = "lo, hi = 0, len(a)\nwhile lo < hi:\n    mid = (lo + hi) ___ 2    # división entera\n    if a[mid] < x: lo = mid + 1\n    else: hi = mid\n",
  ["lock = threading.___()\nserved = 0\n\ndef serve():\n    global served\n    with lock:\n        served += 1\n"] = "lock = threading.___()\nserved = 0\n\ndef serve():\n    global served\n    with lock:\n        served += 1\n",
  ["lock() returns a MutexGuard; unwrap fails only if another thread panicked while holding it. The guard unlocks on drop."] = "lock() devuelve un MutexGuard; unwrap falla solo si otro thread hizo panic mientras lo tenía. El guard se desbloquea al hacer drop.",
  ["log n levels, n work per level: O(n log n). The base case is a slice of 0 or 1."] = "log n niveles, n de trabajo por nivel: O(n log n). El caso base es un slice de 0 o 1.",
  ["log prints and returns nothing. What goes after the arrow?"] = "log imprime y no devuelve nada. ¿Qué va después de la flecha?",
  ["log() prints but never returns. What does print(log('x')) show on its second line?"] = "log() imprime pero nunca devuelve. ¿Qué muestra print(log('x')) en su segunda línea?",
  ['log.Fatal(http.___(":8080", nil))   // nil = default mux\n'] = 'log.Fatal(http.___(":8080", nil))   // nil = mux por defecto\n',
  ["longest returns one of its inputs. Which lifetime does the return value carry?"] = "longest devuelve una de sus entradas. ¿Qué lifetime lleva el valor de retorno?",
  ["loop = asyncio.get_running_loop()\nsize = await loop.___(ex, resize, photo)\n"] = "loop = asyncio.get_running_loop()\nsize = await loop.___(ex, resize, photo)\n",
  ["loop { ... break value; } is an expression. code becomes 30. The gate stops spinning."] = "loop { ... break valor; } es una expresión. code pasa a ser 30. La puerta deja de girar.",
  ["low:high. Includes low, excludes high. Same backing array, no copy."] = "low:high. Incluye low, excluye high. Mismo array subyacente, sin copia.",
  ["lows[-1] is always the minimum of what is on st. pop both lists together. O(1) push, pop and get_min."] = "lows[-1] es siempre el mínimo de lo que hay en st. Haz pop en las dos listas a la vez. push, pop y get_min en O(1).",
  ["luckymac itself needs a JSON library you never import. How does go.mod mark it?"] = "luckymac necesita una biblioteca JSON que tú nunca importas. ¿Cómo la marca go.mod?",
  ["luckymac/\n  ___/luckymac/main.go   # go build ./___/luckymac\n  ___/kiosk/main.go      # go build ./___/kiosk\n  menu/  internal/\n"] = "luckymac/\n  ___/luckymac/main.go   # go build ./___/luckymac\n  ___/kiosk/main.go      # go build ./___/kiosk\n  menu/  internal/\n",
  ["luckymac/\n  ___/rider/rider.go     <- only luckymac/... may import\n  menu/price.go          <- anyone may import\n"] = "luckymac/\n  ___/rider/rider.go     <- solo luckymac/... puede importarlo\n  menu/price.go          <- cualquiera puede importarlo\n",
  ['luckymac/           module github.com/alex/luckymac\n  menu/price.go     import "github.com/alex/luckymac/___"\n  rider/eta.go      import "github.com/alex/luckymac/rider"\n'] = 'luckymac/           module github.com/alex/luckymac\n  menu/price.go     import "github.com/alex/luckymac/___"\n  rider/eta.go      import "github.com/alex/luckymac/rider"\n',
  ["m := <-res blocks this goroutine, not the program. That is exactly what await does, minus the keyword and minus the coloured functions."] = "m := <-res bloquea esta goroutine, no el programa. Eso es exactamente lo que hace await, menos la palabra clave y menos las funciones de colores.",
  ["macOS and Windows do not fork by default. Name their start method."] = "macOS y Windows no hacen fork por defecto. Nombra su método de arranque.",
  ["main calls menu.Price and the compiler says undefined. Fix the name."] = "main llama a menu.Price y el compilador dice undefined. Arregla el nombre.",
  ["main can fail in many ways. Which pointer type wraps any dyn Error?"] = "main puede fallar de muchas formas. ¿Qué tipo puntero envuelve cualquier dyn Error?",
  ["main sends on an unbuffered channel with nobody receiving. The runtime reports: all goroutines are asleep - ___!"] = "main envía por un channel sin búfer y nadie recibe. El runtime informa: all goroutines are asleep - ___!",
  ["make (or a {} literal) before the first write. Reading a nil map is safe."] = "make (o un literal {}) antes de la primera escritura. Leer un map nil es seguro.",
  ["make(T, len, cap) for slices, maps, channels. new(T) only gives a zeroed pointer."] = "make(T, len, cap) para slices, maps, channels. new(T) solo da un puntero a un valor cero.",
  ["make([]int, len(a)) then copy. Allocation is where space complexity is paid; the garbage collector collects the rent later."] = "make([]int, len(a)) y luego copy. La reserva es donde se paga la complejidad espacial; el recolector de basura cobra el alquiler después.",
  ["make(chan string). Unbuffered: send waits for receive."] = "make(chan string). Sin búfer: el envío espera a la recepción.",
  ["map with an i in front, as in iterator. There is an _unordered twin that is faster."] = "map con una i delante, de iterator. Hay un gemelo _unordered que es más rápido.",
  ["map, then [key type], then value type."] = "map, luego [tipo de clave], luego el tipo del valor.",
  ["map[K]bool is the everyday set. Missing keys read as false."] = "map[K]bool es el set de cada día. Las claves ausentes se leen como false.",
  ["map[string]bool as a set: one O(1) lookup per guest, O(n) total. Fifty million checks become ten thousand."] = "map[string]bool como set: una búsqueda O(1) por invitado, O(n) en total. Cincuenta millones de comprobaciones se vuelven diez mil.",
  ["map[string]int. make(map[string]int) if you start empty."] = "map[string]int. make(map[string]int) si empiezas vacío.",
  ["map[string]int: hash, bucket, compare. O(1) average, O(n) worst when everything collides. Python's dict, Rust's HashMap."] = "map[string]int: hash, bucket, comparación. O(1) en promedio, O(n) en el peor caso cuando todo colisiona. El dict de Python, el HashMap de Rust.",
  ["maps.Keys and maps.Values return iter.Seq, so range works on them directly."] = "maps.Keys y maps.Values devuelven iter.Seq, así que range funciona con ellos directamente.",
  ['match a.binary_search(&x) {     // ___\n    Ok(i) => println!("at {i}"),\n    Err(i) => println!("insert at {i}"),\n}\n'] = 'match a.binary_search(&x) {     // ___\n    Ok(i) => println!("at {i}"),\n    Err(i) => println!("insert at {i}"),\n}\n',
  ["match code { 1 => ..., _ => ... } Each arm is pattern => value. The compiler checks every case is covered."] = "match code { 1 => ..., _ => ... } Cada rama es patrón => valor. El compilador comprueba que todos los casos estén cubiertos.",
  ["matches!(v, Pat) expands to match v { Pat => true, _ => false }. Guards allowed: Some(n) if n > 3."] = "matches!(v, Pat) se expande a match v { Pat => true, _ => false }. Se permiten guardas: Some(n) if n > 3.",
  ["max := prices[0]\nfor _, p := range prices[1:] {   // ___ comparisons\n    if p > max {\n        max = p\n    }\n}\n"] = "max := prices[0]\nfor _, p := range prices[1:] {   // ___ comparaciones\n    if p > max {\n        max = p\n    }\n}\n",
  ["memo = {}\ndef fib(n):\n    if n in ___:\n        return memo[n]\n    v = n if n < 2 else fib(n - 1) + fib(n - 2)\n    memo[n] = v\n    return v\n"] = "memo = {}\ndef fib(n):\n    if n in ___:\n        return memo[n]\n    v = n if n < 2 else fib(n - 1) + fib(n - 2)\n    memo[n] = v\n    return v\n",
  ["memo.get(&n) is O(1). Hit: return it. Miss: compute it. That is memoization."] = "memo.get(&n) es O(1). Acierto: devuélvelo. Fallo: calcúlalo. Eso es memoización.",
  ["memo.get(&n) is O(1). Hit: return. Miss: compute and insert. Go spells this the comma-ok test; Python @functools.cache."] = "memo.get(&n) es O(1). Acierto: devolver. Fallo: calcular e insert. Go lo escribe con la prueba comma-ok; Python con @functools.cache.",
  ['menu = ___\nmenu["tea"] = 12\nmenu["noodles"] = 38\nprint(menu["tea"])     # 12\n'] = 'menu = ___\nmenu["tea"] = 12\nmenu["noodles"] = 38\nprint(menu["tea"])     # 12\n',
  ['menu = ___(tea=12, noodles=38)\nprice = menu["tea"]    # hash the key, jump to the slot\n'] = 'menu = ___(tea=12, noodles=38)\nprice = menu["tea"]    # hashea la clave, salta a la ranura\n',
  ["menu = {\"tea\": 12, \"noodles\": 38}\ndishes = list(menu.___())\nprint(dishes)     # ['tea', 'noodles']\n"] = "menu = {\"tea\": 12, \"noodles\": 38}\ndishes = list(menu.___())\nprint(dishes)     # ['tea', 'noodles']\n",
  ['menu = {"tea": 12, "noodles": 38}\nprint(menu.___("congee", 0))   # 0, no KeyError\n'] = 'menu = {"tea": 12, "noodles": 38}\nprint(menu.___("congee", 0))   # 0, sin KeyError\n',
  ['menu = {"tea": 12, "toast": 18}\n___ menu["toast"]\nprint(menu)     # {\'tea\': 12}\n'] = 'menu = {"tea": 12, "toast": 18}\n___ menu["toast"]\nprint(menu)     # {\'tea\': 12}\n',
  ['menu: ___[str, float] = {"tea": 12.0}\n'] = 'menu: ___[str, float] = {"tea": 12.0}\n',
  ["min, max and clear joined len, cap, append in Go 1.21."] = "min, max y clear se unieron a len, cap, append en Go 1.21.",
  ["module github.com/alex/luckymac\n\ngo 1.23\n\n___ v1.0.1 // wrong price for the tea set\n"] = "module github.com/alex/luckymac\n\ngo 1.23\n\n___ v1.0.1 // precio equivocado del tea set\n",
  ["module github.com/alex/luckymac\n\ngo ___\n"] = "module github.com/alex/luckymac\n\ngo ___\n",
  ['module github.com/alex/luckymac/___\n\n// callers: import "github.com/alex/luckymac/___/menu"\n'] = 'module github.com/alex/luckymac/___\n\n// quienes lo usan: import "github.com/alex/luckymac/___/menu"\n',
  ["module github.com/siuming/cousinshop\n\ngo 1.23\n\n___ github.com/alex/luckymac v1.2.0\n"] = "module github.com/siuming/cousinshop\n\ngo 1.23\n\n___ github.com/alex/luckymac v1.2.0\n",
  ["module, go, require. go.sum next to it holds the checksums."] = "module, go, require. go.sum, a su lado, guarda las sumas de verificación.",
  ["most_common uses heapq.nlargest inside when k is given. Count in O(n), pick in O(n log k). Round four to Bo."] = "most_common usa heapq.nlargest por dentro cuando se le da k. Contar en O(n), elegir en O(n log k). Cuarta ronda para Bo.",
  ["move || captures by value. Without it the closure would borrow order, and a borrow cannot be proven to outlive the thread."] = "move || captura por valor. Sin él, el closure prestaría order, y no se puede probar que un préstamo viva más que el thread.",
  ["mp.Process is a whole python interpreter of its own. It costs milliseconds to start, not microseconds: give it work worth the trip."] = "mp.Process es un intérprete de python entero. Arrancarlo cuesta milisegundos, no microsegundos: dale trabajo que valga el viaje.",
  ["mp.Queue is safe for many producers and many consumers. It must be created in the parent and passed in as an argument, never made inside the child."] = "mp.Queue es segura con muchos productores y muchos consumidores. Hay que crearla en el padre y pasarla como argumento, nunca hacerla dentro del hijo.",
  ["mp.Value('i', 0) is four bytes of shared memory with a type code. The object is shared; the number inside it is what you touch."] = "mp.Value('i', 0) son cuatro bytes de memoria compartida con un código de tipo. El objeto es lo compartido; el número de dentro es lo que tocas.",
  ["mp.cpu_count() is Go's runtime.NumCPU(). It counts logical cores, so on a laptop with hyper-threading it is twice the physical ones."] = "mp.cpu_count() es el runtime.NumCPU() de Go. Cuenta núcleos lógicos, así que en un portátil con hyper-threading es el doble de los físicos.",
  ["mpsc: multi-producer, single-consumer. Job is Send so it may cross to another thread; FnOnce because each ticket runs once."] = "mpsc: multi-productor, un solo consumidor. Job es Send para poder cruzar a otro thread; FnOnce porque cada ticket se ejecuta una vez.",
  ["mpsc::channel gives a Sender and a Receiver. Clone the Sender for many producers; the loop ends when all are dropped."] = "mpsc::channel da un Sender y un Receiver. Clona el Sender para muchos productores; el bucle termina cuando todos se sueltan.",
  ["mpsc::channel() returns (Sender<T>, Receiver<T>). mpsc: multi-producer, single-consumer. The pipe is unbounded."] = "mpsc::channel() devuelve (Sender<T>, Receiver<T>). mpsc: multi-producer, single-consumer. La tubería no tiene límite.",
  ["mu.Lock()\ndefer mu.___()          // even on panic\ncount++\n"] = "mu.Lock()\ndefer mu.___()          // incluso con panic\ncount++\n",
  ['mu.Lock()\nmenu["set"] = 42\nmu.Unlock()\n\nmu.___()\n'] = 'mu.Lock()\nmenu["set"] = 42\nmu.Unlock()\n\nmu.___()\n',
  ["multiprocessing copies the threading API onto processes, so the code looks the same and the cores actually fill up."] = "multiprocessing copia la API de threading sobre procesos, así que el código se parece y los núcleos se llenan de verdad.",
  ["multiprocessing.Process(target=f, args=(x,)) is threading's API on a real process: start() forks or spawns it, join() waits, exitcode says how it went and daemon=True lets it die with the parent. Under the spawn start method the child imports your file again, so everything that runs must sit behind if __name__ == '__main__'."] = "multiprocessing.Process(target=f, args=(x,)) es la API de threading sobre un proceso real: start() hace fork o spawn, join() espera, exitcode dice cómo fue y daemon=True lo deja morir con el padre. Con el método spawn el hijo vuelve a importar tu fichero, así que todo lo que se ejecuta debe ir detrás de if __name__ == '__main__'.",
  ["mypy runs no code; it reads the hints. Go and Rust do this in the compiler; Python does it on request. The labels print right."] = "mypy no ejecuta código; lee las anotaciones. Go y Rust lo hacen en el compilador; Python cuando se lo pides. Las etiquetas se imprimen bien.",
  ["n := 7\nhalf := ___(n) / 2      // 3.5, not 3\n"] = "n := 7\nhalf := ___(n) / 2      // 3.5, no 3\n",
  ["n := runtime.___()\nfor i := 0; i < n; i++ {\n    go worker(jobs, done)\n}\n"] = "n := runtime.___()\nfor i := 0; i < n; i++ {\n    go worker(jobs, done)\n}\n",
  ['n = 4\nprint(___"tables open: {n}")\n'] = 'n = 4\nprint(___"tables open: {n}")\n',
  ["n doubles from 1000 to 2000 items. An O(1) operation takes how long compared to before, in one word?"] = "n se duplica de 1000 a 2000 elementos. ¿Cuánto tarda una operación O(1) comparada con antes, en una palabra?",
  ["n in memo is O(1). Hit: return it. Miss: compute, store, return. That is memoization, spelled out."] = "n in memo es O(1). Acierto: devuélvelo. Fallo: calcula, guarda, devuelve. Eso es la memorización, escrita entera.",
  ["n is an int. Divide it as a floating point number. Fill: half := ___(n) / 2"] = "n es un int. Divídelo como número de punto flotante. Completa: half := ___(n) / 2",
  ["n pushes and pops on a heap of k: O(n log k) time, O(k) space. Sorting would be O(n log n) and O(n)."] = "n push y pop en un heap de k: O(n log k) tiempo, O(k) espacio. Ordenar sería O(n log n) y O(n).",
  ["n times the logarithm of n. No comparison sort can beat it in the worst case."] = "n veces el logaritmo de n. Ninguna ordenación por comparación puede vencerlo en el peor caso.",
  ["n+1 distinct inputs, each solved once. Linear, without the O( )."] = "n+1 entradas distintas, cada una resuelta una vez. Lineal, sin el O( ).",
  ['n, ___ := prices["hashbrown"]\nif !___ {\n    // missing\n}\n'] = 'n, ___ := prices["hashbrown"]\nif !___ {\n    // no existe\n}\n',
  ["n-1 comparisons, which is O(n): you cannot know the max without seeing every value. The diagonal is drawn."] = "n-1 comparaciones, que es O(n): no puedes conocer el máximo sin ver cada valor. La diagonal está dibujada.",
  ["n-1 comparisons, which is O(n): you cannot know the max without seeing every value. iter().max() does exactly this."] = "n-1 comparaciones, que es O(n): no puedes conocer el máximo sin ver cada valor. iter().max() hace exactamente esto.",
  ["n-1 comparisons, which is O(n): you cannot know the max without seeing every value. max() does exactly this."] = "n-1 comparaciones, que es O(n): no puedes conocer el máximo sin ver cada valor. max() hace exactamente esto.",
  ['name = ___("Order for: ")\nprint(f"one bowl for {name}")\n'] = 'name = ___("Order for: ")\nprint(f"one bowl for {name}")\n',
  ['names := []string{"Wing", "Bo", "Mei"}\nsort.___(names)          // O(n log n)\nfmt.Println(names)       // [Bo Mei Wing]\n'] = 'names := []string{"Wing", "Bo", "Mei"}\nsort.___(names)          // O(n log n)\nfmt.Println(names)       // [Bo Mei Wing]\n',
  ['names = ["Mei", "Alex", "Mei", "Ken"]\nunique = ___(names)\nprint(len(unique))     # 3\n'] = 'names = ["Mei", "Alex", "Mei", "Ken"]\nunique = ___(names)\nprint(len(unique))     # 3\n',
  ['names = ["egg", "tea"]\nqtys = [2, 1]\nfor name, qty in ___(names, qtys):\n    print(qty, "x", name)\n'] = 'names = ["egg", "tea"]\nqtys = [2, 1]\nfor name, qty in ___(names, qtys):\n    print(qty, "x", name)\n',
  ['names = ["noodles", "tea", "toast"]\nshort_first = ___(names, key=len)    # O(n log n)\n'] = 'names = ["noodles", "tea", "toast"]\nshort_first = ___(names, key=len)    # O(n log n)\n',
  ["net/http: handlers and a server"] = "net/http: handlers y un servidor",
  ["next() on an exhausted generator raises which exception?"] = "¿next() sobre un generador agotado lanza qué excepción?",
  ["next(gen) runs to the next yield. next(gen, None) returns None at the end instead of raising."] = "next(gen) corre hasta el siguiente yield. next(gen, None) devuelve None al final en vez de lanzar.",
  ["nil check first, then recurse. insert returns the (possibly new) subtree root."] = "Primero la comprobación de nil, luego recurre. insert devuelve la raíz (quizá nueva) del subárbol.",
  ["nlargest(n, xs, key=...) is O(n log k) and takes a key. sorted(xs)[-3:] would be O(n log n)."] = "nlargest(n, xs, key=...) es O(n log k) y acepta una key. sorted(xs)[-3:] sería O(n log n).",
  ["not st first: pop on an empty list raises IndexError. Then compare with the opener the dict expects."] = "Primero not st: pop en una lista vacía lanza IndexError. Luego compara con la apertura que espera el dict.",
  ['note = ___          # nothing yet\nif not note:\n    print("no note")\n'] = 'note = ___          # nada todavía\nif not note:\n    print("no note")\n',
  ['o := Order{Item: "set", Price: 25}\nfmt.Printf("___\\n", o)    // {Item:set Price:25}\n'] = 'o := Order{Item: "set", Price: 25}\nfmt.Printf("___\\n", o)    // {Item:set Price:25}\n',
  ["o.label() passes o as self automatically. Forgetting self is the most common TypeError in a beginner's class."] = "o.label() pasa o como self automáticamente. Olvidar self es el TypeError más común en la clase de un principiante.",
  ["ok is false only when the channel is closed and drained. It says nothing about the value: that one is always the zero value."] = "ok solo es false cuando el channel está cerrado y vacío. No dice nada del valor: ese siempre es el valor cero.",
  ["ok, an underscore, then the word you use to offer an alternative."] = "ok, un guion bajo, luego la palabra que usas para ofrecer una alternativa.",
  ["ok_or(err) maps Some(v) to Ok(v) and None to Err(err). Now ? works on it too."] = "ok_or(err) convierte Some(v) en Ok(v) y None en Err(err). Ahora ? también funciona con él.",
  ['omit + empty, one word, after the comma. json:"-" hides a field entirely.'] = 'omit + empty, una palabra, tras la coma. json:"-" oculta un campo por completo.',
  ['omitempty drops zero values. "-" drops the field always.'] = 'omitempty descarta valores cero. "-" descarta el campo siempre.',
  ["once.Do(f) runs f the first time and blocks the rest until it returns, so nobody sees a half-loaded menu."] = "once.Do(f) ejecuta f la primera vez y detiene al resto hasta que vuelve, así nadie ve un menú a medio cargar.",
  ["or, underscore, insert. Takes the starting value and returns &mut u32, which the * dereferences."] = "or, guion bajo, insert. Toma el valor inicial y devuelve &mut u32, que el * desreferencia.",
  ["or_ plus the word for Default::default(). An empty Vec is the default Vec."] = "or_ más la palabra de Default::default(). Un Vec vacío es el Vec por defecto.",
  ["or_insert returns &mut usize, so the * dereferences and += 1 bumps it in place. O(n) to count."] = "or_insert devuelve &mut usize, así que el * desreferencia y += 1 lo incrementa en el sitio. O(n) para contar.",
  ['order = ["noodles", "egg", "tea"]\nif "egg" ___ order:\n    print("fry one")\n'] = 'order = ["noodles", "egg", "tea"]\nif "egg" ___ order:\n    print("fry one")\n',
  ["order('noodles', spicy=True, egg=2): how is the parameter written to collect any keyword options?"] = "order('noodles', spicy=True, egg=2): ¿cómo se escribe el parámetro para recoger cualquier opción con nombre?",
  ["order.total should read like an attribute but be computed. Which built-in decorator?"] = "order.total debe leerse como un atributo pero calcularse. ¿Qué decorador integrado?",
  ["ordered = sorted(amounts)    # ___ : Timsort\n"] = "ordered = sorted(amounts)    # ___ : Timsort\n",
  ['orders = [("tea", 12), ("noodles", 38), ("egg", 6)]\ncheap = sorted(orders, key=___ o: o[1])\nprint(cheap[0])     # (\'egg\', 6)\n'] = 'orders = [("tea", 12), ("noodles", 38), ("egg", 6)]\ncheap = sorted(orders, key=___ o: o[1])\nprint(cheap[0])     # (\'egg\', 6)\n',
  ["orders = ___\nselect {\ncase o := <-orders:\n    cook(o)\ncase <-quit:\n    return\n}\n"] = "orders = ___\nselect {\ncase o := <-orders:\n    cook(o)\ncase <-quit:\n    return\n}\n",
  ["orders.push(18). pop() takes the last one back. The Vec reallocates when it runs out of room."] = "orders.push(18). pop() saca el último. El Vec se realoja cuando se queda sin espacio.",
  ['orders: ___[str] = []\norders.append("noodles")\n'] = 'orders: ___[str] = []\norders.append("noodles")\n',
  ["out := [][]int{iv[0]}\nfor _, cur := range iv[1:] {\n    last := out[len(out)-1]\n    if cur[0] <= last[___] {    // they touch or overlap\n"] = "out := [][]int{iv[0]}\nfor _, cur := range iv[1:] {\n    last := out[len(out)-1]\n    if cur[0] <= last[___] {    // se tocan o se solapan\n",
  ["out := make([]Dish, len(orders))\nfor i := range orders {\n    go func() {\n        out[___] = cook(orders[i])\n    }()\n}\n"] = "out := make([]Dish, len(orders))\nfor i := range orders {\n    go func() {\n        out[___] = cook(orders[i])\n    }()\n}\n",
  ["out = [[9, 12], [13, 15], [16, 18]]\n# the free slots between blocks: (12, 13), (15, 16)\nfree = [(a[1], b[0]) for a, b in zip(out, out[___])]\n"] = "out = [[9, 12], [13, 15], [16, 18]]\n# los huecos libres entre bloques: (12, 13), (15, 16)\nfree = [(a[1], b[0]) for a, b in zip(out, out[___])]\n",
  ["out[-1] is the last merged block, [1] its end. The sort guarantees s is never before the block's start."] = "out[-1] es el último bloque fusionado, [1] su final. El sort garantiza que s nunca va antes del inicio del bloque.",
  ['p := ___Order{Item: "set"}   // p is *Order\np.Price = 25                  // Go dereferences for you\n'] = 'p := ___Order{Item: "set"}   // p es *Order\np.Price = 25                  // Go desreferencia por ti\n',
  ["p = mp.Process(target=tail_log)\np.___ = True\np.start()\n"] = "p = mp.Process(target=tail_log)\np.___ = True\np.start()\n",
  ['p.join()\nif p.___ != 0:\n    print("the night batch died")\n'] = 'p.join()\nif p.___ != 0:\n    print("el lote nocturno murió")\n',
  ['p.start()\np.___()\nprint("child finished")\n'] = 'p.start()\np.___()\nprint("child finished")\n',
  ['package main\n___ (\n    "fmt"\n    "os"\n)\n'] = 'package main\n___ (\n    "fmt"\n    "os"\n)\n',
  ["package main\n___ opens = 6          // Lucky Mac hour, never changes\n"] = "package main\n___ opens = 6          // hora de Lucky Mac, nunca cambia\n",
  ['package main\n___ shop string = "Lucky Mac"   // package level: no :=\nfunc main() {\n    fmt.Println(shop)\n}\n'] = 'package main\n___ shop string = "Lucky Mac"   // nivel de paquete: sin :=\nfunc main() {\n    fmt.Println(shop)\n}\n',
  ["package main\nfunc main() {\n    floor ___ 8      // type inferred as int\n}\n"] = "package main\nfunc main() {\n    floor ___ 8      // tipo inferido como int\n}\n",
  ['package main\nimport "___"\nfunc main() {\n    Println("hash brown")\n}\n'] = 'package main\nimport "___"\nfunc main() {\n    Println("hash brown")\n}\n',
  ['package main\nimport "fmt"\nfunc main() {\n    fmt.___("morning set")   // capital P: exported\n}\n'] = 'package main\nimport "fmt"\nfunc main() {\n    fmt.___("morning set")   // P mayúscula: exportada\n}\n',
  ['package main\nvar menu map[string]int\nfunc ___() {                // before main\n    menu = map[string]int{"muffin": 18}\n}\nfunc main() {}\n'] = 'package main\nvar menu map[string]int\nfunc ___() {                // antes de main\n    menu = map[string]int{"muffin": 18}\n}\nfunc main() {}\n',
  ["package main is the entry. Other folders are libraries."] = "package main es la entrada. Las otras carpetas son bibliotecas.",
  ["package main plus func main is a program; anything else is a library. Nobody can import a main package, so keep it thin and put the logic in a package others can test."] = "package main más func main es un programa; cualquier otra cosa es una biblioteca. Nadie puede importar un paquete main, así que mantenlo fino y pon la lógica en un paquete que otros puedan probar.",
  ["package menu_test can only use the exported API, so the tests prove what callers can do. Plain package menu tests reach the unexported parts."] = "package menu_test solo puede usar la API exportada, así que las pruebas demuestran lo que pueden hacer los que llaman. Las pruebas en package menu a secas llegan a las partes no exportadas.",
  ["pairs := map[rune]rune{\n    ')': ___,           // closer -> opener\n    ']': '[',\n    '}': '{',\n}\n"] = "pairs := map[rune]rune{\n    ')': ___,           // cierre -> apertura\n    ']': '[',\n    '}': '{',\n}\n",
  ["panic stops the goroutine. recover() inside defer can save it. Rare in libraries."] = "panic detiene la goroutine. recover() dentro de defer puede salvarla. Raro en librerías.",
  ["panic unwinds the stack running every defer. recover in a defer can stop it."] = "panic desenrolla la pila ejecutando cada defer. recover en un defer puede detenerlo.",
  ["parent_conn, child_conn = mp.___()\nmp.Process(target=cook, args=(child_conn,)).start()\nprint(parent_conn.recv())\n"] = "parent_conn, child_conn = mp.___()\nmp.Process(target=cook, args=(child_conn,)).start()\nprint(parent_conn.recv())\n",
  ["parse::<i32>() names the generic explicitly. Same trick: collect::<Vec<_>>(). 12 x 18 = 216."] = "parse::<i32>() nombra el genérico explícitamente. Mismo truco: collect::<Vec<_>>(). 12 x 18 = 216.",
  ["pkg.go.dev shows the first sentence of the package comment. Start it properly."] = "pkg.go.dev muestra la primera frase del comentario del paquete. Empiézala bien.",
  ["plate only receives. Fill the parameter type: in ___ string"] = "plate solo recibe. Completa el tipo del parámetro: in ___ string",
  ["pool.map blocks until the last worker is done and returns a list in order. The function and its arguments have to be picklable, so no lambdas."] = "pool.map bloquea hasta que acaba el último worker y devuelve una lista en orden. La función y sus argumentos tienen que ser picklable, así que nada de lambdas.",
  ["pool.map keeps order; pool.submit returns a Future. ProcessPoolExecutor is the same API on processes, past the GIL."] = "pool.map mantiene el orden; pool.submit devuelve un Future. ProcessPoolExecutor es la misma API sobre procesos, más allá del GIL.",
  ["pool.map(scan, [(shm.___, i) for i in parts])\n\n# inside the worker:\n# SharedMemory(key) attaches here\n"] = "pool.map(scan, [(shm.___, i) for i in parts])\n\n# dentro del worker:\n# SharedMemory(key) se engancha aquí\n",
  ["pop pops both stacks, so the smallest is always on top of low. O(1) push, pop and get, O(n) space."] = "pop saca de ambas pilas, así que el mínimo siempre está en la cima de low. push, pop y get en O(1), O(n) espacio.",
  ["pop returns an Option. Which arm holds a value?"] = "pop devuelve un Option. ¿Qué variante contiene un valor?",
  ["pop the first node. We only have &mut head, so move the node out and leave None behind. Which Option method?"] = "Haz pop del primer nodo. Solo tenemos &mut head, así que saca el nodo y deja None detrás. ¿Qué método de Option?",
  ["pop, but from the left end, one word. list.pop(0) would be O(n)."] = "pop, pero por el extremo izquierdo, una sola palabra. list.pop(0) sería O(n).",
  ["pop, underscore, the end that is not back. The while let ends when it returns None."] = "pop, guion bajo, el extremo que no es back. El while let termina cuando devuelve None.",
  ["pop, underscore, the stale end. The mirror of the last blank."] = "pop, guion bajo, el extremo viejo. El espejo del último hueco.",
  ["pop_front is BFS, pop is DFS: the only difference is which end. Both O(V + E). Combo x3."] = "pop_front es BFS, pop es DFS: la única diferencia es qué extremo. Ambos O(V + E). Combo x3.",
  ["pop_front is O(1). Stations come out in rings: one hop, two hops, three. That is BFS."] = "pop_front es O(1). Las estaciones salen en anillos: un salto, dos saltos, tres. Eso es BFS.",
  ["price = 18.5\nprint(___(price))    # <class 'float'>\n"] = "price = 18.5\nprint(___(price))    # <class 'float'>\n",
  ['prices := ___{\n    "muffin": 18,\n}\n'] = 'prices := ___{\n    "muffin": 18,\n}\n',
  ["prices = [38, 6, 12]\ncheap = ___(prices)\nprint(cheap, prices)   # [6, 12, 38] [38, 6, 12]\n"] = "prices = [38, 6, 12]\ncheap = ___(prices)\nprint(cheap, prices)   # [6, 12, 38] [38, 6, 12]\n",
  ["prices = [6, 12, 38]\ndoubled = [p * 2 ___ p in prices]\nprint(doubled)     # [12, 24, 76]\n"] = "prices = [6, 12, 38]\ndoubled = [p * 2 ___ p in prices]\nprint(doubled)     # [12, 24, 76]\n",
  ["prices.len() is 3. is_empty() is the idiomatic way to ask for zero. The board counts to twelve."] = "prices.len() es 3. is_empty() es la forma idiomática de preguntar por cero. El tablero cuenta hasta doce.",
  ["print writes a line. # starts a comment. f-strings put values in text. import brings a module in."] = "print escribe una línea. # empieza un comentario. Las f-strings meten valores en el texto. import trae un módulo.",
  ["print() is a built-in: no import, no package. Python 3 needs the parentheses. The pass screen lights up."] = "print() es integrada: sin import, sin paquete. Python 3 necesita los paréntesis. La pantalla del pase se enciende.",
  ["print(o) shows <Order object at 0x...>. Which special method gives it a readable form?"] = "print(o) muestra <Order object at 0x...>. ¿Qué método especial le da una forma legible?",
  ["printer.acquire()\ntry:\n    print_label(order)\nfinally:\n    printer.___()\n"] = "printer.acquire()\ntry:\n    print_label(order)\nfinally:\n    printer.___()\n",
  ["println is a macro, not a function. Which character ends its name?"] = "println es una macro, no una función. ¿Qué carácter termina su nombre?",
  ["push adds one char. This one adds a whole str. Two words, underscore."] = "push añade un char. Este añade un str entero. Dos palabras, guion bajo.",
  ["push, underscore, the end that is not the front."] = "push, guion bajo, el extremo que no es el frente.",
  ["push_str borrows the &str and copies it in. to_uppercase() makes a new String."] = "push_str toma prestado el &str y lo copia dentro. to_uppercase() crea un String nuevo.",
  ["put blocks only when maxsize is reached. put_nowait raises queue.Full instead."] = "put solo bloquea cuando se alcanza maxsize. put_nowait lanza queue.Full en su lugar.",
  ["put made the cache one too big. Remove the oldest pair, at the front. Which method, with last=False?"] = "put dejó la caché con uno de más. Quita el par más viejo, al frente. ¿Qué método, con last=False?",
  ["put on a new key when the cache is full: the stale end goes first. Which VecDeque method removes the front as Option?"] = "put con una clave nueva y la caché llena: el extremo viejo se va primero. ¿Qué método de VecDeque quita el frente como Option?",
  ["q.get() blocks like <-ch in Go. get_nowait() raises queue.Empty instead, which is the select default case."] = "q.get() bloquea como <-ch en Go. get_nowait() lanza queue.Empty en su lugar, que es el caso default de select.",
  ['q.put(Order(7, "set"))\nq.put(open("menu.txt"))\n# TypeError: the file object is not ___\n'] = 'q.put(Order(7, "set"))\nq.put(open("menu.txt"))\n# TypeError: el objeto de fichero no es ___\n',
  ["queue.Queue is thread-safe: put adds a job, get takes one, task_done marks it finished, join waits until every job is done."] = "queue.Queue es seguro entre hilos: put añade un trabajo, get toma uno, task_done lo marca terminado, join espera hasta que todos los trabajos están hechos.",
  ["queue.Queue locks every operation. Queue(maxsize=3) blocks put when full: a buffered channel."] = "queue.Queue bloquea cada operación. Queue(maxsize=3) bloquea el put cuando está llena: un canal con búfer.",
  ["queue[0] then queue[1:] is the Go queue. For big queues use a ring or container/list."] = "queue[0] y luego queue[1:] es la cola en Go. Para colas grandes usa un ring o container/list.",
  ["r - l + 1 is the window's width. Grow on the right, shrink on the left: O(n) with at most 256 bytes in the set."] = "r - l + 1 es el ancho de la ventana. Crece por la derecha, encoge por la izquierda: O(n) con como mucho 256 bytes en el set.",
  ["r must be allowed to change a. Which two-part borrow gives write access?"] = "r debe poder cambiar a. ¿Qué préstamo de dos partes da acceso de escritura?",
  ["raise ValueError(...) throws an instance. A bare raise inside except re-throws the current one."] = "raise ValueError(...) lanza una instancia. Un raise a pelo dentro de except relanza la actual.",
  ["range 3 counts 0..2. Since 1.22 each iteration also gets its own i."] = "range 3 cuenta 0..2. Desde 1.22 cada iteración también tiene su propia i.",
  ["range decodes UTF-8 for you: byte index plus rune. string(r) turns it back."] = "range decodifica UTF-8 por ti: índice de byte más rune. string(r) lo revierte.",
  ["range over a channel ends when the sender calls close. Without close it blocks forever."] = "range sobre un channel termina cuando el emisor llama a close. Sin close bloquea para siempre.",
  ["range over a channel. Note the directional channel types in the signature."] = "range sobre un channel. Fíjate en los tipos de channel direccionales de la firma.",
  ["range over a string gives runes. Print each one as text: fill ___(r)"] = "range sobre un string da runes. Imprime cada uno como texto: completa ___(r)",
  ["range over an int, min and max, slices and maps packages, iter.Seq for range."] = "range sobre un int, min y max, los paquetes slices y maps, iter.Seq para range.",
  ["range(3) yields 0, 1, 2. range(1, 4) starts at 1; range(0, 10, 2) steps by two. It is lazy: nothing is built."] = "range(3) produce 0, 1, 2. range(1, 4) empieza en 1; range(0, 10, 2) va de dos en dos. Es perezoso: no construye nada.",
  ['raw = "12"\nqty = ___(raw)\nprint(qty + 1)     # 13, not "121"\n'] = 'raw = "12"\nqty = ___(raw)\nprint(qty + 1)     # 13, no "121"\n',
  ["ready := make(chan struct{})\ngo func() {\n    menu = loadMenu()\n    ___(ready)\n}()\n<-ready\nuse(menu)\n"] = "ready := make(chan struct{})\ngo func() {\n    menu = loadMenu()\n    ___(ready)\n}()\n<-ready\nuse(menu)\n",
  ["recv blocks with no busy loop. Not while let: its temporaries live for the whole body and would hold the lock during job()."] = "recv bloquea sin bucle de espera activa. No uses while let: sus temporales viven todo el cuerpo y mantendrían el lock durante job().",
  ["replace applies only in the main module: the cousin's users never see it. Keep the require line, and take the replace out before you commit."] = "replace solo se aplica en el módulo principal: los usuarios del primo nunca lo ven. Conserva la línea require y quita el replace antes de hacer commit.",
  ["replace, go.work, vendor"] = "replace, go.work, vendor",
  ["require (\n    github.com/alex/luckymac v1.2.0\n    github.com/goccy/go-json v0.10.3 // ___\n)\n"] = "require (\n    github.com/alex/luckymac v1.2.0\n    github.com/goccy/go-json v0.10.3 // ___\n)\n",
  ["require github.com/alex/luckymac v1.2.0\n\n___ github.com/alex/luckymac => ../luckymac\n"] = "require github.com/alex/luckymac v1.2.0\n\n___ github.com/alex/luckymac => ../luckymac\n",
  ["require is a minimum, not an exact pin: if another dependency needs v1.3.0, the build uses v1.3.0. Minimal version selection, no lock file solver."] = "require es un mínimo, no una fijación exacta: si otra dependencia necesita v1.3.0, la compilación usa v1.3.0. Selección de versión mínima, sin resolutor de lock file.",
  ["reqwest::get(url).await?.text().await? - two awaits, two places it can fail. Riders roll out."] = "reqwest::get(url).await?.text().await? - dos await, dos sitios donde puede fallar. Los repartidores salen.",
  ["res := make(chan Menu, 1)\n___ func() { res <- fetchMenu() }()\nprintReceipt()\n"] = "res := make(chan Menu, 1)\n___ func() { res <- fetchMenu() }()\nprintReceipt()\n",
  ["res := make(chan Menu, 1)\ngo func() { res <- fetchMenu() }()\nprintReceipt()\nm := ___\n"] = "res := make(chan Menu, 1)\ngo func() { res <- fetchMenu() }()\nprintReceipt()\nm := ___\n",
  ["res := make(chan Menu, ___)\ngo func() { res <- fetchMenu() }()\nselect {\ncase m := <-res:\n    use(m)\ncase <-ctx.Done():\n}\n"] = "res := make(chan Menu, ___)\ngo func() { res <- fetchMenu() }()\nselect {\ncase m := <-res:\n    use(m)\ncase <-ctx.Done():\n}\n",
  ["result() is await, and it re-raises the worker's exception in your process with the child's traceback attached."] = "result() es await, y relanza la excepción del worker en tu proceso con la traza del hijo incluida.",
  ["return 0; exits at once. The tail expression n * 18 - 5 handles every other case."] = "return 0; sale de inmediato. La expresión final n * 18 - 5 maneja todos los demás casos.",
  ["return s. A function that falls off the end returns None. return a, b hands back a tuple."] = "return s. Una función que llega al final devuelve None. return a, b devuelve una tupla.",
  ["return sends every result at once. The bool and the error travel together."] = "return envía todos los resultados a la vez. El bool y el error viajan juntos.",
  ["return wrapper, not wrapper(). The caller gets the wrapper and calls it later; *args, **kwargs pass anything through."] = "return wrapper, no wrapper(). Quien llama recibe la envoltura y la llama más tarde; *args, **kwargs dejan pasar cualquier cosa.",
  ["rune is one code point. 'x' literals are runes, \"x\" literals are strings."] = "rune es un punto de código. Los literales 'x' son runes; los literales \"x\" son strings.",
  ["runtime.NumCPU() is the usual pool size for CPU-bound work. For I/O-bound work the right number is higher and only a benchmark knows it."] = "runtime.NumCPU() es el tamaño habitual del pool para trabajo de CPU. Para trabajo de E/S el número correcto es mayor y solo lo sabe un benchmark.",
  ["rx.recv() blocks until a value arrives; Err when every Sender is gone. Order 7 hits the pass."] = "rx.recv() bloquea hasta que llega un valor; Err cuando ya no queda ningún Sender. El pedido 7 llega al pase.",
  ['s := "灣"\nfmt.Println(len(s))     // prints ___\n'] = 's := "灣"\nfmt.Println(len(s))     // imprime ___\n',
  ["s := ___{1, 2, 3}     // slice, length 3\n"] = "s := ___{1, 2, 3}     // slice, longitud 3\n",
  ["s[1:3] is a slice of a slice. Changing two[0] changes tray[1] too."] = "s[1:3] es un slice de un slice. Cambiar two[0] también cambia tray[1].",
  ["seats as f64. i32 / f64 does not compile in Rust; as makes the intent explicit."] = "seats as f64. i32 / f64 no compila en Rust; as hace explícita la intención.",
  ["seats is an i32 but the division needs a float. Which keyword converts it?"] = "seats es un i32 pero la división necesita un float. ¿Qué palabra clave lo convierte?",
  ["seen := map[int]int{}          // value -> index\nfor i, x := range nums {\n    if j, ok := seen[target-___]; ok {\n        return []int{j, i}\n    }\n    seen[x] = i\n}\n"] = "seen := map[int]int{}          // valor -> índice\nfor i, x := range nums {\n    if j, ok := seen[target-___]; ok {\n        return []int{j, i}\n    }\n    seen[x] = i\n}\n",
  ["seen := map[string]___{}\nfor _, g := range guests {        // one pass: O(n)\n    if seen[g] { dup = true }\n    seen[g] = true\n}\n"] = "seen := map[string]___{}\nfor _, g := range guests {        // una pasada: O(n)\n    if seen[g] { dup = true }\n    seen[g] = true\n}\n",
  ["seen = ___()\nfor g in guests:            # one pass: O(n)\n    if g in seen:\n        dup = True\n    seen.add(g)\n"] = "seen = ___()\nfor g in guests:            # una pasada: O(n)\n    if g in seen:\n        dup = True\n    seen.add(g)\n",
  ["seen.insert(m) is one lookup for check and mark. Without it, a loop in the map queues forever."] = "seen.insert(m) es una sola búsqueda para comprobar y marcar. Sin él, un ciclo en el mapa encola para siempre.",
  ["seen[x] = i maps value to position. Returning (seen[target - x], i) gives the pair of indexes the question wants."] = "seen[x] = i asocia valor a posición. Devolver (seen[target - x], i) da el par de índices que pide la pregunta.",
  ["select"] = "select",
  ["select waits on several channel ops. default is the non-blocking branch."] = "select espera varias operaciones de channel. default es la rama no bloqueante.",
  ["select {\ncase d := <-cooked:\n    return d, nil\ncase <-ctx.___():\n    return Dish{}, ctx.Err()\n}\n"] = "select {\ncase d := <-cooked:\n    return d, nil\ncase <-ctx.___():\n    return Dish{}, ctx.Err()\n}\n",
  ["select {\ncase m := <-muffin:\n    serve(m)\n___:\n    skip()\n}\n"] = "select {\ncase m := <-muffin:\n    serve(m)\n___:\n    skip()\n}\n",
  ["select {\ncase m := <-muffin:\n    serve(m)\ncase <-ctx.___():\n    return ctx.Err()\n}\n"] = "select {\ncase m := <-muffin:\n    serve(m)\ncase <-ctx.___():\n    return ctx.Err()\n}\n",
  ['select {\ncase m := <-muffin:\n    serve(m)\ncase <-time.___(time.Second):\n    fmt.Println("timeout")\n}\n'] = 'select {\ncase m := <-muffin:\n    serve(m)\ncase <-time.___(time.Second):\n    fmt.Println("timeout")\n}\n',
  ["select { case x := <-ch: ... }. Random choice if several are ready."] = "select { case x := <-ch: ... }. Elección aleatoria si hay varios listos.",
  ["sem := make(chan struct{}, 4)\nsem <- struct{}{}\ngo func() {\n    deliver(o)\n    ___\n}()\n"] = "sem := make(chan struct{}, 4)\nsem <- struct{}{}\ngo func() {\n    deliver(o)\n    ___\n}()\n",
  ["sem := make(chan struct{}, ___)\nfor _, u := range urls {\n    sem <- struct{}{}        // acquire (blocks when full)\n    go func(u string) {\n        defer func() { <-sem }()   // release\n        fetch(u) }(u)\n}\n"] = "sem := make(chan struct{}, ___)\nfor _, u := range urls {\n    sem <- struct{}{}        // adquirir (bloquea si está lleno)\n    go func(u string) {\n        defer func() { <-sem }()   // liberar\n        fetch(u) }(u)\n}\n",
  ["serde and JSON"] = "serde y JSON",
  ["serde_json::Value indexes with [] and returns Null when missing. Ticket four closed."] = "serde_json::Value se indexa con [] y devuelve Null cuando falta. Ticket cuatro cerrado.",
  ["serde_json::from_str::<Order>(text). from_slice for bytes, from_reader for files."] = "serde_json::from_str::<Order>(text). from_slice para bytes, from_reader para archivos.",
  ["serde_json::to_string(&order) -> compact JSON. to_vec gives bytes, to_writer streams."] = "serde_json::to_string(&order) -> JSON compacto. to_vec da bytes, to_writer escribe en un stream.",
  ["set(names) drops duplicates; x in s is O(1). {1, 2} is a set literal, but {} is a dict. Sets have no order."] = "set(names) elimina duplicados; x in s es O(1). {1, 2} es un literal de set, pero {} es un dict. Los sets no tienen orden.",
  ["set: one O(1) check per guest, O(n) total. Fifty million checks become ten thousand."] = "set: una comprobación O(1) por invitado, O(n) en total. Cincuenta millones de comprobaciones se vuelven diez mil.",
  ["shared_memory: no copy at all"] = "shared_memory: ni una copia",
  ["shifts = [[13, 15], [9, 11], [10, 12]]\n# sort by start so overlapping shifts sit side by side\nshifts.sort(key=lambda iv: iv[___])\nprint(shifts)    # [[9, 11], [10, 12], [13, 15]]\n"] = "shifts = [[13, 15], [9, 11], [10, 12]]\n# ordenar por inicio: los turnos solapados quedan juntos\nshifts.sort(key=lambda iv: iv[___])\nprint(shifts)    # [[9, 11], [10, 12], [13, 15]]\n",
  ["shm.close()\n\n# in the parent only, once:\nshm.___()\n"] = "shm.close()\n\n# solo en el padre, una vez:\nshm.___()\n",
  ['shops := []string{"Lucky Mac", "Sogo"}\nfor _, name := ___ shops {\n    fmt.Println(name)\n}\n'] = 'shops := []string{"Lucky Mac", "Sogo"}\nfor _, name := ___ shops {\n    fmt.Println(name)\n}\n',
  ['sign = "open" if bowls > 0 ___ "closed"\nprint(sign)\n'] = 'sign = "open" if bowls > 0 ___ "closed"\nprint(sign)\n',
  ["sink stops off the map. usize never goes below zero, so only the far edges need a test. Row r is outside when r is what, compared with the row count?"] = "sink se detiene fuera del mapa. usize nunca baja de cero, así que solo hay que probar los bordes lejanos. La fila r está fuera cuando r es ¿qué, comparada con el número de filas?",
  ['skip_serializing_if = "Option::is_none" drops empty fields. default fills them on the way in.'] = 'skip_serializing_if = "Option::is_none" omite los campos vacíos. default los rellena al entrar.',
  ["slices.Contains, Index, Reverse, Max: the loops you used to write by hand."] = "slices.Contains, Index, Reverse, Max: los bucles que antes escribías a mano.",
  ["slices.Sort is generic: no sort.Strings / sort.Ints per type any more."] = "slices.Sort es genérica: ya no hace falta sort.Strings / sort.Ints por tipo.",
  ["slow, fast := head, head\nfor fast != nil && fast.Next != nil {\n    slow = slow.Next\n    fast = fast.Next.___\n    if slow == fast { return true }   // cycle\n}\n"] = "slow, fast := head, head\nfor fast != nil && fast.Next != nil {\n    slow = slow.Next\n    fast = fast.Next.___\n    if slow == fast { return true }   // ciclo\n}\n",
  ["sold++ is three machine steps. Two goroutines can land between them. Put a lock around it."] = "sold++ son tres pasos de máquina. Dos goroutines pueden caer en medio. Ponle un lock alrededor.",
  ["sort, an underscore, and the word for 'may reorder equal items'."] = "sort, un guion bajo, y la palabra para 'puede reordenar elementos iguales'.",
  ["sort, by, key with underscores. The closure returns something Ord; here a u32."] = "sort, by, key con guiones bajos. El closure devuelve algo Ord; aquí un u32.",
  ["sort, underscore, the opposite of stable. A pattern-defeating quicksort inside."] = "sort, guion bajo, lo contrario de estable. Dentro, un quicksort que vence a los patrones.",
  ["sort.Ints on n receipts: what does it cost, in Big O?"] = "sort.Ints sobre n recibos: ¿qué cuesta, en Big O?",
  ["sort.Ints sorts the slice where it is. Extra memory, in Big O: O(___)"] = "sort.Ints ordena el slice donde está. Memoria extra, en Big O: O(___)",
  ["sort.Ints(a)                        // once: n log n\nfor _, x := range queries {\n    _, ok := slices.BinarySearch(a, x)   // each: O(___)\n}\n"] = "sort.Ints(a)                        // una vez: n log n\nfor _, x := range queries {\n    _, ok := slices.BinarySearch(a, x)   // cada una: O(___)\n}\n",
  ["sort.Ints(a)    // in place: O(___) extra space\n"] = "sort.Ints(a)    // en el sitio: O(___) de espacio extra\n",
  ["sort.Ints(amounts)    // ___ : pdqsort, comparison-based\n"] = "sort.Ints(amounts)    // ___ : pdqsort, basado en comparaciones\n",
  ["sort.Ints(starts); sort.Ints(ends)\nrooms, e := 0, 0\nfor _, s := range starts {\n    if s ___ ends[e] {      // one meeting already over\n        e++\n    } else {\n        rooms++\n"] = "sort.Ints(starts); sort.Ints(ends)\nrooms, e := 0, 0\nfor _, s := range starts {\n    if s ___ ends[e] {      // una reunión ya terminó\n        e++\n    } else {\n        rooms++\n",
  ["sort.Slice with a less function. slices.SortFunc is the generic Go 1.21 way."] = "sort.Slice con una función less. slices.SortFunc es la forma genérica de Go 1.21.",
  ["sort.Slice(iv, func(i, j int) bool {\n    return iv[i][0] ___ iv[j][0]    // earliest start first\n})\n"] = "sort.Slice(iv, func(i, j int) bool {\n    return iv[i][0] ___ iv[j][0]    // inicio más temprano primero\n})\n",
  ["sort.Strings(names). Go 1.21's slices.Sort(names) is generic and does the same. Both n log n."] = "sort.Strings(names). El slices.Sort(names) de Go 1.21 es genérico y hace lo mismo. Ambos n log n.",
  ["sort.___(orders, func(i, j int) bool {\n    return orders[i].Price < orders[j].Price\n})\n"] = "sort.___(orders, func(i, j int) bool {\n    return orders[i].Price < orders[j].Price\n})\n",
  ["sort_by_key is a stable merge sort, like the one you just wrote. sort_by takes a full comparator instead."] = "sort_by_key es un merge sort estable, como el que acabas de escribir. sort_by toma en cambio un comparador completo.",
  ["sort_unstable sorts the Vec where it is. Extra memory, in Big O: O(___)"] = "sort_unstable ordena el Vec donde está. Memoria extra, en Big O: O(___)",
  ["sort_unstable: O(n log n), in place, usually faster than sort. Use sort only when order among equals matters. Combo x5."] = "sort_unstable: O(n log n), en el sitio, normalmente más rápido que sort. Usa sort solo cuando importa el orden entre iguales. Combo x5.",
  ["sort_unstable: same O(n log n), less memory, usually faster. sort_by_key(|o| o.price) sorts by a field."] = "sort_unstable: el mismo O(n log n), menos memoria, normalmente más rápido. sort_by_key(|o| o.price) ordena por un campo.",
  ["sorted on n receipts: what does it cost, in Big O?"] = "sorted sobre n recibos: ¿qué cuesta, en Big O?",
  ["sorted() is Timsort: merge sort that notices runs already in order. Still n log n in the worst case."] = "sorted() es Timsort: una ordenación por mezcla que nota los tramos ya en orden. Sigue siendo n log n en el peor caso.",
  ["sorted(a) == sorted(b) is O(n log n) and one line. Counter(a) == Counter(b) is O(n) and just as short."] = "sorted(a) == sorted(b) es O(n log n) y una línea. Counter(a) == Counter(b) es O(n) e igual de corto.",
  ["sorted(names, key=len). The key is called n times, O(n), then Timsort. Both together: n log n."] = "sorted(names, key=len). La key se llama n veces, O(n), luego Timsort. Ambas juntas: n log n.",
  ["sorted(xs) returns a new list, xs.sort() sorts in place. Both take key= and reverse=True. The rack is in order."] = "sorted(xs) devuelve una lista nueva, xs.sort() ordena en el sitio. Ambos aceptan key= y reverse=True. El estante está en orden.",
  ["spawn returns a handle you can wait on. What is its type?"] = "spawn devuelve un handle al que puedes esperar. ¿Cuál es su tipo?",
  ["spawn starts a clean interpreter and pickles the target across, so nothing is silently inherited. fork is faster and shares everything, including locks held at the wrong moment."] = "spawn arranca un intérprete limpio y envía el target con pickle, así que no se hereda nada en silencio. fork es más rápido y lo comparte todo, incluidos los bloqueos tomados en mal momento.",
  ["split, underscore, at. Panics if mid is past the end; here it never is."] = "split, guion bajo, at. Hace panic si mid pasa del final; aquí nunca pasa.",
  ["split_at gives (&v[..mid], &v[mid..]) as one tuple. Two shared borrows of one slice are fine."] = "split_at da (&v[..mid], &v[mid..]) como una tupla. Dos préstamos compartidos de un slice están bien.",
  ["st := []rune{}\nfor _, c := range s {\n    if _, closer := pairs[c]; !closer {\n        st = ___(st, c)     // an opener waits here\n        continue\n    }\n}\n"] = "st := []rune{}\nfor _, c := range s {\n    if _, closer := pairs[c]; !closer {\n        st = ___(st, c)     // una apertura espera aquí\n        continue\n    }\n}\n",
  ['st = []\nst.append("(")\nst.append("[")\ntop = st[___]        # the most recent opener\nprint(top)           # [\n'] = 'st = []\nst.append("(")\nst.append("[")\ntop = st[___]        # la apertura más reciente\nprint(top)           # [\n',
  ["st[-1] is the peek. Guard it with if st: the same way as pop."] = "st[-1] es el peek. Protégelo con if st: igual que pop.",
  ["starmap(f, [(a, b), ...]) calls f(a, b). It is the difference between one argument and several, and the reason you rarely need a wrapper function."] = "starmap(f, [(a, b), ...]) llama a f(a, b). Es la diferencia entre un argumento y varios, y la razón de que rara vez necesites una función envoltorio.",
  ["start:stop, the stop is not included. Same rule as Go's a[1:3]."] = "start:stop, el stop no se incluye. La misma regla que a[1:3] en Go.",
  ['str(4) is "4". "Table " + 4 raises TypeError: Python never converts silently. The stock count comes out whole.'] = 'str(4) es "4". "Table " + 4 lanza TypeError: Python nunca convierte en silencio. El recuento de stock sale entero.',
  ["strconv.Atoi / Itoa for ints, ParseFloat and FormatFloat for floats."] = "strconv.Atoi / Itoa para ints, ParseFloat y FormatFloat para floats.",
  ["string is bytes, rune is a code point. utf8 counts characters, strconv converts."] = "string son bytes, rune es un punto de código. utf8 cuenta caracteres, strconv convierte.",
  ["strings has Split, Join, Contains, TrimSpace, ToUpper... all return new strings."] = "strings tiene Split, Join, Contains, TrimSpace, ToUpper... todas devuelven strings nuevos.",
  ['struct Grill;\n// Grill promises every method of Cook.\nimpl Cook ___ Grill {\n    fn name(&self) -> String {\n        "grill".to_string()\n    }\n}\n'] = 'struct Grill;\n// Grill promete todos los métodos de Cook.\nimpl Cook ___ Grill {\n    fn name(&self) -> String {\n        "grill".to_string()\n    }\n}\n',
  ["struct ListNode {\n    val: i32,\n    next: ___<Box<ListNode>>,   // the rest, or the end\n}\n"] = "struct ListNode {\n    val: i32,\n    next: ___<Box<ListNode>>,   // el resto, o el final\n}\n",
  ["struct Order { id: u32, price: u32 }\nlet mut orders = vec![\n    Order { id: 7, price: 45 },\n    Order { id: 3, price: 18 },\n];\n// cheapest first; equal prices keep their order (stable)\norders.___(|o| o.price);\n"] = "struct Order { id: u32, price: u32 }\nlet mut orders = vec![\n    Order { id: 7, price: 45 },\n    Order { id: 3, price: 18 },\n];\n// el más barato primero; a igual precio, mismo orden (estable)\norders.___(|o| o.price);\n",
  ["struct Order { item: String, qty: u32 } Fields are private to the module unless marked pub."] = "struct Order { item: String, qty: u32 } Los campos son privados del módulo salvo que se marquen pub.",
  ["struct Order { qty: u32 }\n\n___ Order {\n    fn total(&self) -> u32 {\n        self.qty * 18\n    }\n}\n"] = "struct Order { qty: u32 }\n\n___ Order {\n    fn total(&self) -> u32 {\n        self.qty * 18\n    }\n}\n",
  ["struct Receipt<'a> { name: &'a str }: a Receipt cannot outlive the name it borrows. The compiler now checks it for you."] = "struct Receipt<'a> { name: &'a str }: un Receipt no puede vivir más que el nombre que toma prestado. Ahora el compilador lo comprueba por ti.",
  ['struct Wok;\nimpl Cook for Wok {\n    fn name(&self) -> String { "wok".to_string() }\n}\n// Any Cook, decided at run time, behind a reference.\nfn call(c: &___ Cook) { println!("{}", c.greet()); }\ncall(&Grill); call(&Wok);\n'] = 'struct Wok;\nimpl Cook for Wok {\n    fn name(&self) -> String { "wok".to_string() }\n}\n// Cualquier Cook, decidido en ejecución, tras una referencia.\nfn call(c: &___ Cook) { println!("{}", c.greet()); }\ncall(&Grill); call(&Wok);\n',
  ["struct groups fields. *T is a pointer. Methods have a receiver. interface is a set of methods."] = "struct agrupa campos. *T es un puntero. Los métodos tienen receptor. interface es un conjunto de métodos.",
  ["struct groups fields. impl adds methods that take &self or &mut self. enum lists variants; match handles them all."] = "struct agrupa campos. impl añade métodos que reciben &self o &mut self. enum lista variantes; match las maneja todas.",
  ["struct, impl and enum"] = "struct, impl y enum",
  ["submit(f, *args) is go f(args): the call is already running somewhere else and you hold the receipt."] = "submit(f, *args) es go f(args): la llamada ya está corriendo en otra parte y tú tienes el resguardo.",
  ["sum := 0\nfor _, p := range prices {    // ___ : n items, n adds\n    sum += p\n}\n"] = "sum := 0\nfor _, p := range prices {    // ___ : n elementos, n sumas\n    sum += p\n}\n",
  ["sum over n prices: what is the cost in Big O?"] = "sum sobre n precios: ¿cuál es el coste en Big O?",
  ["sum takes any number of fares. Fill the parameter type: fares ___"] = "sum acepta cualquier cantidad de tarifas. Completa el tipo del parámetro: fares ___",
  ["sum.golang.org records the hash of every public version once, so two people who go get the same tag either get identical bytes or an error."] = "sum.golang.org registra una sola vez el hash de cada versión pública, así que dos personas que hagan go get de la misma etiqueta obtienen bytes idénticos o un error.",
  ["sum::<i32>() adds &i32 into an i32. Without the turbofish Rust cannot pick the type."] = "sum::<i32>() suma &i32 en un i32. Sin el turbofish, Rust no puede elegir el tipo.",
  ["super().__init__(item) runs the parent constructor. class SetMeal(Order) is inheritance; Go embeds instead."] = "super().__init__(item) ejecuta el constructor del padre. class SetMeal(Order) es herencia; Go incrusta en su lugar.",
  ['switch light { case "green": walk() }. No break: cases do not fall through.'] = 'switch light { case "green": walk() }. Sin break: los case no caen al siguiente.',
  ["switch v.(type) gives x the concrete type in every case."] = "switch v.(type) da a x el tipo concreto en cada case.",
  ['switch x := v.(___) {\ncase int:\n    fmt.Println(x + 1)      // x is an int here\ncase string:\n    fmt.Println(x + "!")    // and a string here\n}\n'] = 'switch x := v.(___) {\ncase int:\n    fmt.Println(x + 1)      // aquí x es un int\ncase string:\n    fmt.Println(x + "!")    // y aquí un string\n}\n',
  ["sync, underscore, then the word for the pipe itself."] = "sync, guion bajo, luego la palabra para la propia tubería (channel).",
  ["sync.Map pays off for keys written once and read often. For anything else a plain map behind a Mutex is faster and clearer."] = "sync.Map compensa con claves escritas una vez y leídas mucho. Para todo lo demás, un map normal detrás de un Mutex es más rápido y más claro.",
  ["sync.Mutex. Lock, change, Unlock. Prefer channels when you can."] = "sync.Mutex. Lock, cambia, Unlock. Prefiere channels cuando puedas.",
  ["sync.Mutex: one goroutine at a time"] = "sync.Mutex: una goroutine a la vez",
  ["sync.Once.Do runs the function once and blocks the others until it finishes. Go 1.21 adds sync.OnceValue."] = "sync.Once.Do ejecuta la función una vez y bloquea a los demás hasta que termina. Go 1.21 añade sync.OnceValue.",
  ["sync.OnceValue(f) returns a function: the first call runs f, every later call returns the cached value. sync.OnceValues does the (T, error) pair."] = "sync.OnceValue(f) devuelve una función: la primera llamada ejecuta f y todas las demás devuelven el valor guardado. El par (T, error) lo hace sync.OnceValues.",
  ["sync.Pool recycles short-lived allocations across goroutines. It is a garbage-collector optimisation, never a place to keep state."] = "sync.Pool recicla reservas de vida corta entre goroutines. Es una optimización para el recolector de basura, nunca un sitio donde guardar estado.",
  ["sync.RWMutex: any number of RLock holders, or exactly one Lock holder. Worth it when reads dominate."] = "sync.RWMutex: cualquier número de titulares de RLock, o exactamente uno de Lock. Vale la pena cuando dominan las lecturas.",
  ["sync/atomic is for single words: counters, flags. Anything bigger wants a Mutex."] = "sync/atomic es para palabras sueltas: contadores, flags. Cualquier cosa mayor pide un Mutex.",
  ["sync_channel(n) is bounded: send blocks when n values wait. Backpressure, like a buffered Go channel. The queue moves."] = "sync_channel(n) tiene límite: send bloquea cuando hay n valores esperando. Backpressure, como un channel de Go con buffer. La cola avanza.",
  ['t = threading.Thread(target=fry, args=("egg",))\nt.___()\nprint("frying in the background")\n'] = 't = threading.Thread(target=fry, args=("egg",))\nt.___()\nprint("frying in the background")\n',
  ["t.Errorf marks failure and continues; t.Fatalf stops. Table tests loop over cases with t.Run."] = "t.Errorf marca fallo y continúa; t.Fatalf para. Los table tests recorren casos con t.Run.",
  ["t.start() spawns the OS thread and returns at once. t.run() is the body; calling it yourself gains nothing."] = "t.start() crea el hilo del SO y vuelve de inmediato. t.run() es el cuerpo; llamarlo tú mismo no gana nada.",
  ['table = 4\nlabel = "Table " + ___(table)\nprint(label)       # Table 4\n'] = 'table = 4\nlabel = "Table " + ___(table)\nprint(label)       # Table 4\n',
  ["thiserror derives Display + Error; #[from] even writes the From impl. Ticket two closed."] = "thiserror deriva Display + Error; #[from] incluso escribe el impl de From. Ticket dos cerrado.",
  ["thread::scope(|s| ...) joins every s.spawn before returning, so the closures may borrow without move. Three cooks, one menu."] = "thread::scope(|s| ...) hace join de cada s.spawn antes de volver, así que los closures pueden prestar sin move. Tres cocineros, un menú.",
  ["thread::sleep(Duration) takes a Duration, never a bare number. Duration::from_secs and from_millis build one."] = "thread::sleep(Duration) recibe un Duration, nunca un número a secas. Duration::from_secs y from_millis construyen uno.",
  ["thread::spawn returns JoinHandle<T>. Keep them in a Vec, or the threads are detached and main may exit first."] = "thread::spawn devuelve JoinHandle<T>. Guárdalos en un Vec, o los threads quedan sueltos y main puede salir antes.",
  ["thread::spawn starts a thread; move gives it its data; join waits. thread::scope may borrow."] = "thread::spawn arranca un thread; move le da sus datos; join espera. thread::scope puede prestar.",
  ["thread::spawn(closure) returns a JoinHandle and runs at once on an OS thread. Rust has no green threads built in."] = "thread::spawn(closure) devuelve un JoinHandle y corre de inmediato en un thread del sistema. Rust no trae green threads incorporados.",
  ["threading.Thread(target=f).start() runs f beside the main thread; join waits. Lock guards shared state. ThreadPoolExecutor manages a pool. The GIL lets one thread run bytecode at a time."] = "threading.Thread(target=f).start() ejecuta f junto al hilo principal; join espera. Lock protege el estado compartido. ThreadPoolExecutor gestiona un pool. El GIL deja que un hilo ejecute bytecode a la vez.",
  ["tidy walks every import in the module, adds what is missing to go.mod and go.sum and drops what nothing uses. Run it before every commit."] = "tidy recorre cada import del módulo, añade lo que falta a go.mod y go.sum y quita lo que nada usa. Ejecútalo antes de cada commit.",
  ["time.After in a select is the classic timeout. In a loop prefer a time.Timer."] = "time.After en un select es el timeout clásico. En un bucle prefiere un time.Timer.",
  ["tokio::spawn needs a 'static + Send future. handle.await gives Result<T, JoinError>."] = "tokio::spawn necesita un future 'static + Send. handle.await da Result<T, JoinError>.",
  ["top = prices[0]\nfor p in prices[1:]:    # ___ comparisons\n    if p > top:\n        top = p\n"] = "top = prices[0]\nfor p in prices[1:]:    # ___ comparaciones\n    if p > top:\n        top = p\n",
  ["total = 0\n\ndef add(rows):\n    global total\n    total += sum(rows)\n# the child changed its own ___ of total\n"] = "total = 0\n\ndef add(rows):\n    global total\n    total += sum(rows)\n# el hijo cambió su propia ___ de total\n",
  ["total = sum(prices)    # ___ : n items, n adds, inside C\n"] = "total = sum(prices)    # ___ : n elementos, n sumas, dentro de C\n",
  ["total = sum(prices)    # n steps\ntop = max(prices)      # n more\n# 2n steps, written O(___)\n"] = "total = sum(prices)    # n pasos\ntop = max(prices)      # n más\n# 2n pasos, escrito O(___)\n",
  ["total only reads the order. Which receiver borrows it without change?"] = "total solo lee el pedido. ¿Qué receptor lo presta sin cambiarlo?",
  ["total(3, 5) and total(3, 5, 8) should both work. How is the parameter written to take any number of items?"] = "total(3, 5) y total(3, 5, 8) deben funcionar. ¿Cómo se escribe el parámetro para aceptar cualquier número de elementos?",
  ["trait Cook lists methods. One with a body is a default; implementors may keep it or override it."] = "trait Cook lista métodos. Uno con cuerpo es un valor por defecto; quien lo implementa puede conservarlo o sobrescribirlo.",
  ['tray := []string{"muffin", "hash", "coffee", "tea"}\ntwo := tray[___]         // {"hash", "coffee"}\n'] = 'tray := []string{"muffin", "hash", "coffee", "tea"}\ntwo := tray[___]         // {"hash", "coffee"}\n',
  ['tray := []string{"muffin", "hashbrown"}\nn := ___(tray)         // 2\n'] = 'tray := []string{"muffin", "hashbrown"}\nn := ___(tray)         // 2\n',
  ['tray := []string{"muffin"}\ntray = ___(tray, "hashbrown")\n'] = 'tray := []string{"muffin"}\ntray = ___(tray, "hashbrown")\n',
  ['tray := ___([]string, 0, 8)   // len 0, cap 8\ntray = append(tray, "muffin")\n'] = 'tray := ___([]string, 0, 8)   // len 0, cap 8\ntray = append(tray, "muffin")\n',
  ["tray := make([]string, 2, 8)\nfmt.Println(len(tray), ___(tray))   // 2 8\n"] = "tray := make([]string, 2, 8)\nfmt.Println(len(tray), ___(tray))   // 2 8\n",
  ["tray = append(tray, x). Never ignore the return."] = "tray = append(tray, x). Nunca ignores el retorno.",
  ['trays = ["egg", "tea", "toast", "rice"]\nprint(trays[___])     # [\'tea\', \'toast\']\n'] = 'trays = ["egg", "tea", "toast", "rice"]\nprint(trays[___])     # [\'tea\', \'toast\']\n',
  ['trays = ["egg", "tea", "toast", "rice"]\nprint(trays[___])     # rice\n'] = 'trays = ["egg", "tea", "toast", "rice"]\nprint(trays[___])     # rice\n',
  ['trays = ["egg", "tea", "toast"]\nit = ___(trays)\nprint(next(it))     # egg\nprint(next(it))     # tea\n'] = 'trays = ["egg", "tea", "toast"]\nit = ___(trays)\nprint(next(it))     # egg\nprint(next(it))     # tea\n',
  ['trays = ["egg", "tea", "toast"]\nprint(___(trays))     # 3\n'] = 'trays = ["egg", "tea", "toast"]\nprint(___(trays))     # 3\n',
  ["trays = [\"egg\", \"tea\"]\ntrays.___(\"toast\")\nprint(trays)     # ['egg', 'tea', 'toast']\n"] = "trays = [\"egg\", \"tea\"]\ntrays.___(\"toast\")\nprint(trays)     # ['egg', 'tea', 'toast']\n",
  ["trays.append(x) is amortized O(1). trays = trays.append(x) is the classic bug: it sets trays to None."] = "trays.append(x) es O(1) amortizado. trays = trays.append(x) es el bug clásico: pone trays a None.",
  ["tree.as_ref() turns &Option<T> into Option<&T>. Without it, map would try to move out of the borrow."] = "tree.as_ref() convierte &Option<T> en Option<&T>. Sin él, map intentaría mover fuera del préstamo.",
  ["try, except, raise"] = "try, except, raise",
  ["try, underscore, then the blocking method's name."] = "try, guion bajo, luego el nombre del método que bloquea.",
  ['try:\n    price = menu[dish]\nexcept KeyError ___ e:\n    print("unknown dish", e)\n'] = 'try:\n    price = menu[dish]\nexcept KeyError ___ e:\n    print("unknown dish", e)\n',
  ['try:\n    qty = int(raw)\n___ ValueError:\n    print("not a number:", raw)\n    qty = 0\n'] = 'try:\n    qty = int(raw)\n___ ValueError:\n    print("not a number:", raw)\n    qty = 0\n',
  ['try:\n    refund(receipt)\nexcept KeyError:\n    print("no such receipt")\n___:\n    printer.close()\n'] = 'try:\n    refund(receipt)\nexcept KeyError:\n    print("no such receipt")\n___:\n    printer.close()\n',
  ["try: guards the risky lines. Rust has Result and ?; Python unwinds the stack to the nearest except."] = "try: protege las líneas arriesgadas. Rust tiene Result y ?; Python desenrolla la pila hasta el except más cercano.",
  ["try_recv() returns at once: Ok(v), Err(Empty) or Err(Disconnected). Good for polling loops; recv_timeout is the middle road."] = "try_recv() vuelve al instante: Ok(v), Err(Empty) o Err(Disconnected). Bueno para bucles de sondeo; recv_timeout es el camino intermedio.",
  ["two-sum with a HashMap, palindrome with chars().rev(), anagram with a [0; 26] counter, word count with entry().or_insert(0)."] = "two-sum con un HashMap, palíndromo con chars().rev(), anagrama con un contador [0; 26], conteo de palabras con entry().or_insert(0).",
  ["type Floor int             // new type, underlying int\n\nf := ___(3)                // int -> Floor\n"] = "type Floor int             // tipo nuevo, subyacente int\n\nf := ___(3)                // int -> Floor\n",
  ["type Floor int is a new type: its own methods, no accidental mixing with int."] = "type Floor int es un tipo nuevo: sus propios métodos, sin mezclas accidentales con int.",
  ["type Future[T any] struct{ ch chan T }\n\nfunc (f Future[T]) Await() T {\n    return ___f.ch\n}\n"] = "type Future[T any] struct{ ch chan T }\n\nfunc (f Future[T]) Await() T {\n    return ___f.ch\n}\n",
  ["type IntHeap []int\n\nfunc (h IntHeap) Len() int { return len(h) }\nfunc (h IntHeap) Less(i, j int) bool {\n    return h[i] ___ h[j]    // the smallest rises to the top\n}\nfunc (h IntHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }\n"] = "type IntHeap []int\n\nfunc (h IntHeap) Len() int { return len(h) }\nfunc (h IntHeap) Less(i, j int) bool {\n    return h[i] ___ h[j]    // el menor sube a la cima\n}\nfunc (h IntHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }\n",
  ["type Kitchen struct {\n    ___                  // promoted methods\n}\n"] = "type Kitchen struct {\n    ___                  // métodos promovidos\n}\n",
  ["type Kitchen struct { Grill }. k.Toast() calls Grill.Toast."] = "type Kitchen struct { Grill }. k.Toast() llama a Grill.Toast.",
  ["type LRU struct {\n    cap int\n    m   map[int]___         // key -> its node in l\n    l   *list.List          // front = most recent\n}\n"] = "type LRU struct {\n    cap int\n    m   map[int]___         // clave -> su nodo en l\n    l   *list.List          // frente = más reciente\n}\n",
  ["type Link = Option<Box<ListNode>>;\nfn pop(head: &mut Link) -> Option<i32> {\n    // move the first node out, leave None in its place\n    let node = head.___()?;\n    *head = node.next;\n    Some(node.val)\n}\n"] = "type Link = Option<Box<ListNode>>;\nfn pop(head: &mut Link) -> Option<i32> {\n    // saca el primer nodo, deja None en su lugar\n    let node = head.___()?;\n    *head = node.next;\n    Some(node.val)\n}\n",
  ["type ListNode struct {\n    Val  int\n    Next ___             // nil at the tail\n}\n"] = "type ListNode struct {\n    Val  int\n    Next ___             // nil en la cola\n}\n",
  ["type Name ___, then curly braces with fields."] = "type Nombre ___, luego llaves con los campos.",
  ["type Node struct {\n    Val         int\n    Left, Right ___      // nil at the leaves\n}\n"] = "type Node struct {\n    Val         int\n    Left, Right ___      // nil en las hojas\n}\n",
  ["type Number interface {\n    ___int | ___float64      // underlying types\n}\nfunc Sum[T Number](xs []T) T\n"] = "type Number interface {\n    ___int | ___float64      // tipos subyacentes\n}\nfunc Sum[T Number](xs []T) T\n",
  ["type Order ___ {\n    Item  string\n    Price int\n}\n"] = "type Order ___ {\n    Item  string\n    Price int\n}\n",
  ['type Order struct {\n    Item string `json:"___"`\n}\n'] = 'type Order struct {\n    Item string `json:"___"`\n}\n',
  ['type Order struct {\n    Item string `json:"dish"`\n    Note string `json:"note,___"`   // skip when empty\n}\n'] = 'type Order struct {\n    Item string `json:"dish"`\n    Note string `json:"note,___"`   // omitir si está vacío\n}\n',
  ["type Order struct {\n    ___  string           // json needs a capital\n    Price int\n}\n"] = "type Order struct {\n    ___  string           // json necesita mayúscula\n    Price int\n}\n",
  ["type Order struct { Item string; Price int }. A value type."] = "type Order struct { Item string; Price int }. Un tipo valor.",
  ["type Payer ___ {\n    Pay(int) error\n}\n"] = "type Payer ___ {\n    Pay(int) error\n}\n",
  ['type RefundError struct{ Amount int }\n\nfunc (e *RefundError) ___() string {\n    return "refund " + strconv.Itoa(e.Amount)\n}\n'] = 'type RefundError struct{ Amount int }\n\nfunc (e *RefundError) ___() string {\n    return "refund " + strconv.Itoa(e.Amount)\n}\n',
  ["type names a type. v.(T) asserts, switch v.(type) branches. Sprintf formats."] = "type nombra un tipo. v.(T) afirma, switch v.(type) ramifica. Sprintf formatea.",
  ["type orderKey struct{}\n\nctx = context.___(ctx, orderKey{}, id)\n// five calls deeper:\nid, ok := ctx.Value(orderKey{}).(int)\n"] = "type orderKey struct{}\n\nctx = context.___(ctx, orderKey{}, id)\n// cinco llamadas más abajo:\nid, ok := ctx.Value(orderKey{}).(int)\n",
  ["type the answer"] = "escribe la respuesta",
  ["type(price) is float. Python is dynamically typed: the value carries the type, the name does not."] = "type(price) es float. Python es de tipado dinámico: el valor lleva el tipo, el nombre no.",
  ["u for unsigned, then the word for pointer size. Same type as len() returns."] = "u de unsigned, luego la palabra del tamaño de puntero. El mismo tipo que devuelve len().",
  ["u for unsigned, then the word size. It is also the type used to index a Vec."] = "u de unsigned, luego la palabra size. También es el tipo con el que se indexa un Vec.",
  ["unwrap, then an underscore, then a two-letter word."] = "unwrap, luego un guion bajo, luego una palabra de dos letras.",
  ["unwrap_or(default) returns the Ok value or your default. Sibling: unwrap_or_else(|e| ...). Zero coins, but no crash."] = "unwrap_or(default) devuelve el valor Ok o tu valor por defecto. Su hermano: unwrap_or_else(|e| ...). Cero monedas, pero sin crash.",
  ['use serde::{Deserialize, ___};\n// Cargo.toml: serde = {version="1", features=["derive"]}\n#[derive(Debug, ___, Deserialize)]\nstruct Order {\n    name: String,\n    qty: u32,\n}\n'] = 'use serde::{Deserialize, ___};\n// Cargo.toml: serde = {version="1", features=["derive"]}\n#[derive(Debug, ___, Deserialize)]\nstruct Order {\n    name: String,\n    qty: u32,\n}\n',
  ["use std::collections::HashMap;\n// station id -> the ids one hop away (an adjacency list)\ntype Graph = HashMap<u32, ___<u32>>;\nfn degree(g: &Graph, n: u32) -> usize {\n    g[&n].len()          // how many exits this station has\n}\n"] = "use std::collections::HashMap;\n// id de estación -> los ids a un salto (lista de adyacencia)\ntype Graph = HashMap<u32, ___<u32>>;\nfn degree(g: &Graph, n: u32) -> usize {\n    g[&n].len()          // cuántas salidas tiene la estación\n}\n",
  ['use std::collections::HashMap;\nfn main() {\n    let mut count = HashMap::new();\n    count.insert("t7", 2);\n    *count.___("t4").or_insert(0) += 1;   // t4 is 1\n    println!("{:?}", count.get("t9"));    // None\n}\n'] = 'use std::collections::HashMap;\nfn main() {\n    let mut count = HashMap::new();\n    count.insert("t7", 2);\n    *count.___("t4").or_insert(0) += 1;   // t4 es 1\n    println!("{:?}", count.get("t9"));    // None\n}\n',
  ["use std::collections::HashMap; The :: walks the path. std is always there, no Cargo.toml line needed."] = "use std::collections::HashMap; El :: recorre la ruta. std siempre está, sin línea en Cargo.toml.",
  ['use std::collections::___;\n\nlet mut menu = ___::new();\nmenu.insert("tea", 12);\nlet price = menu["tea"];    // hash, bucket, compare\n'] = 'use std::collections::___;\n\nlet mut menu = ___::new();\nmenu.insert("tea", 12);\nlet price = menu["tea"];    // hash, bucket, comparación\n',
  ['use std::error::Error;\nfn main() -> Result<(), ___<dyn Error>> {\n    let qty: i32 = "18".parse()?;   // ParseIntError fits\n    let text = std::fs::read_to_string("menu.txt")?;\n    println!("{qty} sets, {} bytes of menu", text.len());\n    Ok(())\n}\n'] = 'use std::error::Error;\nfn main() -> Result<(), ___<dyn Error>> {\n    let qty: i32 = "18".parse()?;   // ParseIntError cabe\n    let text = std::fs::read_to_string("menu.txt")?;\n    println!("{qty} sets, {} bytes of menu", text.len());\n    Ok(())\n}\n',
  ['use std::fmt;\n// Receipt carries a lifetime; fmt does not need its name.\nimpl fmt::Display for Receipt<___> {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} paid {}", self.name, self.total)\n    }\n}\n'] = 'use std::fmt;\n// Receipt lleva un lifetime; fmt no necesita su nombre.\nimpl fmt::Display for Receipt<___> {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} paid {}", self.name, self.total)\n    }\n}\n',
  ['use std::fmt;\n// Teach println!("{}") how to print an Order.\nimpl fmt::___ for Order {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} x{}", self.bun, self.qty)\n    }\n}\n'] = 'use std::fmt;\n// Enseña a println!("{}") a imprimir un Order.\nimpl fmt::___ for Order {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} x{}", self.bun, self.qty)\n    }\n}\n',
  ['use std::fmt;\nimpl fmt::___ for OrderError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "order failed")\n    }\n}\n'] = 'use std::fmt;\nimpl fmt::___ for OrderError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "order failed")\n    }\n}\n',
  ['use std::fs;\n// A missing menu file is a bug: stop with a message.\nlet menu = fs::read_to_string("menu.txt")\n    .___("menu.txt must exist");\n'] = 'use std::fs;\n// Que falte el archivo del menú es un bug: para con un mensaje.\nlet menu = fs::read_to_string("menu.txt")\n    .___("menu.txt must exist");\n',
  ["use std::num::ParseIntError;\n\n#[derive(Debug)]\n___ OrderError {\n    Empty,\n    BadQty(ParseIntError),\n}\n"] = "use std::num::ParseIntError;\n\n#[derive(Debug)]\n___ OrderError {\n    Empty,\n    BadQty(ParseIntError),\n}\n",
  ["use std::num::ParseIntError;\n// Hand any parse error straight back to the caller.\nfn cents(s: &str) -> Result<u32, ParseIntError> {\n    let n: u32 = s.parse()___;\n    Ok(n * 100)\n}\n"] = "use std::num::ParseIntError;\n// Devuelve cualquier error de parse directo a quien llama.\nfn cents(s: &str) -> Result<u32, ParseIntError> {\n    let n: u32 = s.parse()___;\n    Ok(n * 100)\n}\n",
  ["use std::sync::Arc;\n// Arc: one receiver, many owners across threads.\n// The lock: only one cook holds the rail at a time.\nlet rx = Arc::new(___::new(rx));\nlet rx2 = Arc::clone(&rx);       // one clone per cook\n"] = "use std::sync::Arc;\n// Arc: un receptor, muchos dueños entre threads.\n// El lock: solo un cocinero sostiene el riel a la vez.\nlet rx = Arc::new(___::new(rx));\nlet rx2 = Arc::clone(&rx);       // un clone por cocinero\n",
  ['use std::sync::RwLock;\nlet menu = RwLock::new(vec!["bun", "egg tart"]);\n// Many may look at once; only .write() has to wait.\nlet first = menu.___().unwrap()[0];\n'] = 'use std::sync::RwLock;\nlet menu = RwLock::new(vec!["bun", "egg tart"]);\n// Muchos pueden mirar a la vez; solo .write() tiene que esperar.\nlet first = menu.___().unwrap()[0];\n',
  ["use std::sync::atomic::{AtomicUsize, Ordering};\nstatic SERVED: AtomicUsize = AtomicUsize::new(0);\n// No lock needed: add one in a single hardware step.\nSERVED.___(1, Ordering::SeqCst);\n"] = "use std::sync::atomic::{AtomicUsize, Ordering};\nstatic SERVED: AtomicUsize = AtomicUsize::new(0);\n// Sin lock: suma uno en un solo paso de hardware.\nSERVED.___(1, Ordering::SeqCst);\n",
  ['use std::sync::mpsc;\n// One pipe from till to kitchen: a sender and a receiver.\nlet (tx, rx) = mpsc::___();\ntx.send("egg tart").unwrap();\n'] = 'use std::sync::mpsc;\n// Una tubería de la caja a la cocina: un emisor y un receptor.\nlet (tx, rx) = mpsc::___();\ntx.send("egg tart").unwrap();\n',
