  ["who returns a borrow of self. Write the return type with no lifetime at all."] = "who devuelve un préstamo de self. Escribe el tipo de retorno sin ningún lifetime.",
  ['with ProcessPoolExecutor(8) as ex:\n    fut = ex.___(total, rows)\n    log("still free to work")\n'] = 'with ProcessPoolExecutor(8) as ex:\n    fut = ex.___(total, rows)\n    log("still free to work")\n',
  ["with calls __enter__ on the way in and __exit__ on the way out, exception or not. Go's defer, scoped to a block."] = "with llama a __enter__ al entrar y a __exit__ al salir, con excepción o sin ella. El defer de Go, con alcance de bloque.",
  ["with lock: is acquire and release, even on error. served += 1 is not atomic, GIL or no GIL."] = "with lock: es acquire y release, incluso con error. served += 1 no es atómico, con GIL o sin él.",
  ["with lock: is the same thing with the finally written for you, which is why nobody writes acquire by hand any more."] = "with lock: es lo mismo con el finally ya escrito por ti, y por eso ya nadie escribe acquire a mano.",
  ["with mp.Pool(8) as pool:\n    for size in pool.___(resize, photos):\n        log(size)\n"] = "with mp.Pool(8) as pool:\n    for size in pool.___(resize, photos):\n        log(size)\n",
